# Supported language codes are kept in one place so selections can be
# validated before they are persisted or copied into the translation cache.
SUPPORTED_LANGUAGE_CODES = frozenset(
    TRANSLATION_STRINGS.get("lang_select_title", {}).keys()
) or frozenset({"en"})


def _user_language(user_id: str) -> str:
    """Return and synchronize the selected language for one player."""
    uid = str(user_id)
    profile = player_data.get(uid, {}) if isinstance(player_data, dict) else {}
    code = profile.get("language", "en") if isinstance(profile, dict) else "en"
    if code not in SUPPORTED_LANGUAGE_CODES:
        code = "en"
    set_user_lang(uid, code)
    return code


def _tr(user_id: str, key: str, **kwargs) -> str:
    """Translate a user-facing string using the persisted player preference."""
    return translate(str(user_id), key, **kwargs)


def _sync_translation_languages() -> None:
    """Warm the translation cache after loading persisted player data."""
    if not isinstance(player_data, dict):
        return
    for uid in player_data:
        _user_language(str(uid))


