def _format_coins(amount: float) -> str:
    """Format play-only coins as whole units with the casino coin icon."""
    return f"{_coin_emoji()} <b>{max(0, int(round(float(amount)))):,}</b>"

def _uses_coin_wallet_context() -> bool:
    return _wallet_context_cv.get() == "coins"

def _is_cash_only_update(update: Update) -> bool:
    """Keep financial/accounting handlers on the cash wallet.

    The selected wallet is a game preference only. Deposits, withdrawals,
    tips, rain, and cash bonus claims must never read or spend coins.
    """
    callback_data = getattr(getattr(update, "callback_query", None), "data", "") or ""
    if callback_data:
        if callback_data in {"bonus_coins", "coins_roll", "wallet_view",
                             "wallet_toggle", "wallet_select_real",
                             "wallet_select_coins"}:
            return False
        return callback_data.startswith((
            "crypto_", "withdraw_", "np_", "deposit", "cctip", "tip_",
            "rain_", "claim_", "bonus_", "rakeback", "weekly", "rank_",
            "referral",
        ))

    message = getattr(update, "message", None)
    text = (getattr(message, "text", "") or "").strip()
    if not text.startswith("/"):
        return False
    command = text.split()[0].split("@", 1)[0].lower()
    return command in {
        "/depo", "/deposit", "/depoinr", "/inrdeposit",
        "/withdraw", "/withdrawal", "/tip", "/tips", "/cctip",
        "/rain", "/startrain", "/weekly", "/rakeback", "/ref",
        "/spin", "/claim", "/bonuscode",
    }

async def _set_wallet_context(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Select the user's game wallet before any command or callback runs.

    PTB processes all handlers for one update in the same task, so the
    ContextVar is visible to the existing game balance primitives without
    changing every individual game handler.
    """
    user = update.effective_user
    if user:
        _handler_user_cv.set(str(user.id))
        selected = "real" if _is_cash_only_update(update) else get_wallet_mode(str(user.id))
        _wallet_context_cv.set(selected)

def _register_game_msg(msg_id, user_id: str) -> None:
    """Record that a game message belongs to user_id. Call after send/edit."""
    if not msg_id:
        return
    _game_msg_owners[int(msg_id)] = str(user_id)
    if len(_game_msg_owners) > _GAME_MSG_OWNER_LIMIT:
        oldest = list(_game_msg_owners.keys())[:200]
        for _k in oldest:
            _game_msg_owners.pop(_k, None)

