# ─── INR / UPI Deposit System ────────────────────────────────────────────────
UPI_ID        = "arshyy@ptyes"
UPI_NAME      = "Rollers Casino"
INR_PER_USDT  = 99.0   # 1 USDT = ₹99

def _make_upi_qr(amount_inr: float) -> BytesIO:
    """Generate a UPI deep-link QR code for the given INR amount."""
    upi_url = (
        f"upi://pay?pa={UPI_ID}"
        f"&am={amount_inr:.2f}&cu=INR"
    )
    qr = qrcode.QRCode(
        version=1,
        error_correction=qrcode.constants.ERROR_CORRECT_M,
        box_size=10,
        border=4,
    )
    qr.add_data(upi_url)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    buf = BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return buf

# pending_inr_deposits[user_id] = {amount_inr, usdt_amount, ts}
pending_inr_deposits: dict = {}

async def depoinr_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Entry point: /depoinr — ask user for INR amount."""
    msg = update.message or (update.callback_query.message if update.callback_query else None)
    user = update.effective_user
    if not user or not msg:
        return
    if update.callback_query:
        try:
            await update.callback_query.answer()
        except Exception:
            pass

    user_states[str(user.id)] = "inr_waiting_amount"
    kb = InlineKeyboardMarkup([[danger_btn("❌ Cancel", callback_data="inr_deposit_cancel")]])
    await msg.reply_text(
        "🇮🇳 <b>INR Deposit via UPI</b>\n\n"
        "Please enter the amount you wish to deposit in <b>₹ (INR)</b>:\n\n"
        f"<i>Rate: ₹{INR_PER_USDT:.0f} = 1.00 USDT</i>\n"
        "<i>Minimum: ₹100</i>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )

async def handle_inr_amount(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """User sent INR amount — generate QR and show payment details."""
    user = update.effective_user
    text = (update.message.text or "").strip()
    uid  = str(user.id)

    try:
        amount_inr = float(text.replace(",", "").replace("₹", "").strip())
    except ValueError:
        await update.message.reply_text(
            "❌ Invalid amount. Please enter a number, e.g. <b>500</b>",
            parse_mode=ParseMode.HTML,
        )
        return

    if amount_inr < 100:
        await update.message.reply_text(
            "❌ Minimum deposit is <b>₹100</b>. Please enter a higher amount.",
            parse_mode=ParseMode.HTML,
        )
        return

    usdt_amount = round(amount_inr / INR_PER_USDT, 4)
    ts          = int(time.time())
    pending_inr_deposits[uid] = {
        "amount_inr": amount_inr,
        "usdt_amount": usdt_amount,
        "ts": ts,
    }
    user_states[uid] = "inr_waiting_proof"

    # Generate QR
    try:
        qr_buf = _make_upi_qr(amount_inr)
    except Exception as e:
        logger.error(f"[INR] QR generation failed: {e}")
        await update.message.reply_text("❌ QR generation failed. Please try again.")
        return

    caption = (
        "🇮🇳 <b>UPI Payment Details</b>\n\n"
        f'<tg-emoji emoji-id="5807750375033278838">💰</tg-emoji> <b>Amount:</b>  ₹{amount_inr:,.2f}\n'
        f"🔄 <b>You receive:</b>  {usdt_amount:.4f} USDT\n"
        f"📲 <b>UPI ID:</b>  <code>{UPI_ID}</code>\n"
        f'<tg-emoji emoji-id="6303161581177937915">⏳</tg-emoji> <b>Valid for:</b>  1 hour\n\n'
        f'<tg-emoji emoji-id="6244295210390527866">1️⃣</tg-emoji> Scan the QR <i>or</i> pay to the UPI ID above\n'
        f'<tg-emoji emoji-id="6244583462825632927">2️⃣</tg-emoji> Complete payment of <b>exact amount</b>\n'
        f'<tg-emoji emoji-id="6246920985891577622">3️⃣</tg-emoji> Send <b>screenshot</b> with <b>UTR ref no.</b> as caption'
    )
    kb = InlineKeyboardMarkup([[danger_btn("❌ Cancel", callback_data="inr_deposit_cancel")]])
    await update.message.reply_photo(
        photo=qr_buf,
        caption=caption,
        parse_mode=ParseMode.HTML,
        reply_markup=kb,
    )

async def handle_inr_proof_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """User sent screenshot — forward to owner only if photo + big UTR number in caption."""
    import re as _re
    user = update.effective_user
    uid  = str(user.id)
    dep  = pending_inr_deposits.get(uid)

    if not dep:
        user_states[uid] = UserState.NONE
        await update.message.reply_text("⚠️ No pending INR deposit found. Use /depoinr to start.")
        return

    # ── 1-hour expiry check ──────────────────────────────────────────────────
    if time.time() - dep["ts"] > 3600:
        pending_inr_deposits.pop(uid, None)
        user_states[uid] = UserState.NONE
        await update.message.reply_text(
            "⏰ <b>Deposit session expired.</b>\n\nPlease use /depoinr to start a new deposit.",
            parse_mode=ParseMode.HTML,
        )
        return

    # ── Determine what was sent ──────────────────────────────────────────────
    is_photo   = bool(update.message.photo)
    msg_text   = (update.message.caption or update.message.text or "").strip()
    has_ref    = bool(_re.search(r'\d{9,}', msg_text))  # UTR/ref: ≥9 digit number

    # Must send EITHER a screenshot OR a reference number (≥9 digits)
    if not is_photo and not has_ref:
        await update.message.reply_text(
            "📸 Please send your <b>payment screenshot</b> <i>or</i> the <b>UTR / reference number</b> (e.g. 610267458376).",
            parse_mode=ParseMode.HTML,
        )
        return

    # ── Build owner notification ─────────────────────────────────────────────
    amount_inr  = dep["amount_inr"]
    usdt_amount = dep["usdt_amount"]
    uname       = f"@{user.username}" if user.username else user.full_name
    ref_display = msg_text if msg_text else "—"

    owner_caption = (
        "🇮🇳 <b>INR Deposit — Verify Payment</b>\n\n"
        f"👤 <b>Player:</b>  {uname}  (<code>{uid}</code>)\n"
        f"💰 <b>Amount:</b>  ₹{amount_inr:,.2f}\n"
        f"🔄 <b>Credit:</b>  {usdt_amount:.4f} USDT\n"
        f"📋 <b>Ref / UTR:</b>  <code>{ref_display}</code>\n\n"
        "Tap <b>✅ Confirm</b> once payment is verified."
    )
    confirm_kb = InlineKeyboardMarkup([[
        InlineKeyboardButton(
            f"✅ Confirm  ₹{amount_inr:,.0f}",
            callback_data=f"confirm_inr:{uid}:{dep['ts']}"
        ),
        InlineKeyboardButton("❌ Reject", callback_data=f"reject_inr:{uid}:{dep['ts']}"),
    ]])

    token = os.environ.get("TELEGRAM_BOT_TOKEN", "") or os.environ.get("BOT_TOKEN", "")
    try:
        if is_photo:
            file_id = update.message.photo[-1].file_id
            requests.post(
                f"https://api.telegram.org/bot{token}/sendPhoto",
                json={
                    "chat_id": OWNER_ID,
                    "photo": file_id,
                    "caption": owner_caption,
                    "parse_mode": "HTML",
                    "reply_markup": json.dumps(confirm_kb.to_dict()),
                },
                timeout=10,
            )
        else:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={
                    "chat_id": OWNER_ID,
                    "text": owner_caption,
                    "parse_mode": "HTML",
                    "reply_markup": json.dumps(confirm_kb.to_dict()),
                },
                timeout=10,
            )
        logger.info(f"[INR] Proof forwarded to owner — user {uid} ₹{amount_inr} ref:{ref_display}")
    except Exception as e:
        logger.error(f"[INR] Failed to forward proof to owner: {e}")

    user_states[uid] = UserState.NONE
    await update.message.reply_text(
        "📨 <b>Payment proof submitted!</b>\n\n"
        "Your payment details have been sent to the owner for verification.\n"
        "You will be notified once your balance is credited. ✅",
        parse_mode=ParseMode.HTML,
    )

async def handle_inr_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner confirms or rejects an INR deposit."""
    query = update.callback_query
    if not query:
        return

    # ── Admin check FIRST — before any query.answer() so the alert shows properly ──
    admin_id = str(query.from_user.id)
    if admin_id != str(OWNER_ID) and admin_id not in [str(m) for m in (context.bot_data.get("MANAGER_IDS") or [])]:
        try:
            await query.answer("⛔ Only the owner/admin can confirm deposits.", show_alert=True)
        except Exception:
            pass
        return

    try:
        await query.answer()
    except Exception:
        pass

    data   = query.data  # confirm_inr:<uid>:<ts>  or  reject_inr:<uid>:<ts>
    parts  = data.split(":")
    action = parts[0]    # confirm_inr / reject_inr
    uid    = parts[1]
    ts_str = parts[2]

    token = os.environ.get("TELEGRAM_BOT_TOKEN", "") or os.environ.get("BOT_TOKEN", "")

    if action == "confirm_inr":
        dep = pending_inr_deposits.get(uid)
        if not dep:
            # Try to reconstruct from callback data alone — shouldn't happen often
            await query.edit_message_caption(
                caption=query.message.caption + "\n\n⚠️ Deposit data not found (already processed?).",
                parse_mode=ParseMode.HTML,
            )
            return

        amount_inr  = dep["amount_inr"]
        usdt_amount = dep["usdt_amount"]
        pid         = f"inr_{uid}_{ts_str}"

        # Credit balance
        try:
            _process_confirmed_deposit(
                user_id       = uid,
                usd_amount    = usdt_amount,
                credited_amount = usdt_amount,
                fee_amount    = 0.0,
                pay_currency  = "INR",
                payment_id    = pid,
                source        = "inr_upi",
                coin_amount   = amount_inr,
                txid          = "",
            )
            save_data_critical()
            logger.info(f"[INR] ✅ Credited {usdt_amount} USDT to user {uid} (₹{amount_inr})")
        except Exception as e:
            logger.error(f"[INR] Credit failed for user {uid}: {e}")
            await query.edit_message_caption(
                caption=(query.message.caption or "") + f"\n\n❌ Credit error: {e}",
                parse_mode=ParseMode.HTML,
            )
            return

        # Remove pending entry
        pending_inr_deposits.pop(uid, None)

        # Notify user
        try:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={
                    "chat_id": uid,
                    "text": (
                        "✅ <b>INR Deposit Confirmed!</b>\n\n"
                        f"💰 <b>₹{amount_inr:,.2f}</b> received\n"
                        f"🎰 <b>{usdt_amount:.4f} USDT</b> has been credited to your account.\n\n"
                        "Good luck at Rollers Casino! 🎲"
                    ),
                    "parse_mode": "HTML",
                },
                timeout=8,
            )
        except Exception:
            pass

        # Update owner message
        new_caption = (
            f"✅ <b>INR Deposit CONFIRMED</b>\n"
            f"User <code>{uid}</code> credited {usdt_amount:.4f} USDT (₹{amount_inr:,.2f})\n"
            f"Confirmed by: {query.from_user.full_name}"
        )
        try:
            await query.edit_message_caption(caption=new_caption, parse_mode=ParseMode.HTML)
        except Exception:
            try:
                await query.edit_message_text(text=new_caption, parse_mode=ParseMode.HTML)
            except Exception:
                pass

    elif action == "reject_inr":
        pending_inr_deposits.pop(uid, None)
        try:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={
                    "chat_id": uid,
                    "text": (
                        "❌ <b>INR Deposit Rejected</b>\n\n"
                        "Your payment could not be verified.\n"
                        "Please contact support or try again with /depoinr."
                    ),
                    "parse_mode": "HTML",
                },
                timeout=8,
            )
        except Exception:
            pass

        rej_caption = (
            f"❌ <b>INR Deposit REJECTED</b>\n"
            f"User <code>{uid}</code>\n"
            f"Rejected by: {query.from_user.full_name}"
        )
        try:
            await query.edit_message_caption(caption=rej_caption, parse_mode=ParseMode.HTML)
        except Exception:
            try:
                await query.edit_message_text(text=rej_caption, parse_mode=ParseMode.HTML)
            except Exception:
                pass

async def handle_inr_cancel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """User cancels INR deposit."""
    query = update.callback_query
    if not query:
        return
    try:
        await query.answer("Deposit cancelled.")
    except Exception:
        pass
    uid = str(query.from_user.id)
    user_states[uid]  = UserState.NONE
    pending_inr_deposits.pop(uid, None)
    try:
        await query.edit_message_text("❌ INR deposit cancelled.")
    except Exception:
        try:
            await query.edit_message_caption(caption="❌ INR deposit cancelled.")
        except Exception:
            pass
