    import hashlib as _hlib
    ss = request.args.get('ss', '')
    cs = request.args.get('cs', '')
    n  = request.args.get('n', '')
    h  = request.args.get('h', '')
    t  = request.args.get('t', '')

    # Compute result server-side
    computed_hash = ''
    crash_point   = None
    result_label  = ''
    result_color  = '#8b949e'
    won           = None
    try:
        combined      = f"{ss}:{cs}:{n}"
        computed_hash = _hlib.sha256(combined.encode()).hexdigest()
        hash_int      = int(computed_hash[:8], 16)
        r           = (hash_int % 1_000_000) / 1_000_000.0
        crash_point = max(1.01, 0.99 / max(0.000001, 1.0 - r))
        if crash_point > 1000:
            crash_point = 1000.0
        if t:
            target = float(t)
            won = crash_point >= target
            result_label = f"{'✅ WIN' if won else '❌ LOSS'} — Crash: {crash_point:.2f}x | Target: {target:.2f}x"
            result_color = '#3fb950' if won else '#f85149'
        else:
            result_label = f"Crash Point: {crash_point:.2f}x"
            result_color = '#58a6ff'
    except Exception:
        result_label = 'Could not compute — check seeds above'
        result_color = '#f85149'

    hash_ok    = '✅ Hash matches' if (computed_hash and computed_hash == h) else ('⚠️ Hash mismatch!' if h else '')
    hash_color = '#3fb950' if computed_hash == h else '#f85149'

