def run_flask():
    # IPN-only internal server — intentionally avoids port 5000 so the public
    # Flask server started later in main() (after all routes are registered) can
    # claim it.  On Replit the public Flask binds 5000; on a VPS nginx proxies.
    for port in [7777, 8090, 9090]:
        try:
            app.run(host='0.0.0.0', port=port, use_reloader=False, threaded=True)
            break
        except Exception as e:
            logger.error(f"Flask IPN error on port {port}: {e}")

def start_flask_thread():
    """Start Flask in a background thread with error handling."""
    if not os.environ.get('WERKZEUG_RUN_MAIN'):
        flask_thread = threading.Thread(target=run_flask, daemon=True)
        flask_thread.start()
        logger.info("🔥 Flask IPN server thread started")

# In main() or at global scope
start_flask_thread()

# ── Startup configuration wizard ────────────────────────────────────────────
_CONFIG_FILE = ".bot_config"

def _load_config_file() -> dict:
    """Load saved config from .bot_config file."""
    if not os.path.exists(_CONFIG_FILE):
        return {}
    try:
        with open(_CONFIG_FILE, "r") as f:
            cfg = {}
            for line in f:
                line = line.strip()
                if "=" in line and not line.startswith("#"):
                    k, _, v = line.partition("=")
                    cfg[k.strip()] = v.strip()
            return cfg
    except Exception:
        return {}

def _save_config_file(cfg: dict):
    """Persist config to .bot_config file."""
    try:
        with open(_CONFIG_FILE, "w") as f:
            f.write("# Bot configuration — do not share this file\n")
            for k, v in cfg.items():
                f.write(f"{k}={v}\n")
    except Exception as e:
        print(f"⚠️  Could not save config file: {e}")

def _setup_config():
    """
    Check required env vars. If any are missing, prompt the operator
    interactively and save the answers so they persist across restarts.
    Config file stores keys under their env_key name for consistency.
    """
    # Bridge any alternate key name → NOWPAYMENTS_IPN_SECRET
    if not os.environ.get("NOWPAYMENTS_IPN_SECRET"):
        for _alt in ("NOW_PAYMENTS_IPN_SECRET", "NOWPAYMENTS_IPN_KEY", "IPN_SECRET", "NOWPAYMENTS_IPN"):
            if os.environ.get(_alt):
                os.environ["NOWPAYMENTS_IPN_SECRET"] = os.environ[_alt]
                break
    # Bridge NOW_PAYMENTS_API_KEY → NOWPAYMENTS_API_KEY
    if not os.environ.get("NOWPAYMENTS_API_KEY") and os.environ.get("NOW_PAYMENTS_API_KEY"):
        os.environ["NOWPAYMENTS_API_KEY"] = os.environ["NOW_PAYMENTS_API_KEY"]

    # Each entry: (env_key, label, optional)
    required = [
        ("TELEGRAM_BOT_TOKEN",    "🤖  Bot Token (from @BotFather)",      False),
        ("DEALER_BOT_TOKEN",      "🃏  Dealer Bot Token (from @BotFather)", True),
        ("NOWPAYMENTS_API_KEY",   "💳  NowPayments API Key",               True),
        ("NOWPAYMENTS_IPN_SECRET","🔒  NowPayments IPN Secret",            True),
    ]

    cfg = _load_config_file()

    # Bridge BOT_TOKEN → TELEGRAM_BOT_TOKEN if only the former is set
    if not os.environ.get("TELEGRAM_BOT_TOKEN") and os.environ.get("BOT_TOKEN"):
        os.environ["TELEGRAM_BOT_TOKEN"] = os.environ["BOT_TOKEN"]

    # Apply any saved values into os.environ (only if not already set)
    for env_key, _, _opt in required:
        saved = cfg.get(env_key, "")
        if saved and not os.environ.get(env_key):
            os.environ[env_key] = saved

    # Detect non-interactive mode (no stdin tty)
    import sys
    # Workflows and deployments do not have a human stdin. Never block a
    # long-running bot waiting for input; missing secrets must be reported
    # explicitly so the operator can add them through Replit Secrets.
    interactive = (
        sys.stdin.isatty()
        and not os.environ.get("CASINO_NON_INTERACTIVE")
        and not os.environ.get("REPL_ID")
        and not os.environ.get("PORT")
    )

    # Prompt for anything that is still missing
    changed = False
    for env_key, label, optional in required:
        if not os.environ.get(env_key):
            if not interactive or optional:
                print(f"  ⚠️  {env_key} not set — {'optional, skipping.' if optional else 'running without it.'}")
                continue
            print(f"\n{'─'*55}")
            print(f"  Missing: {label}")
            print(f"{'─'*55}")
            try:
                value = input(f"  Enter {label}: ").strip()
            except EOFError:
                value = ""
            if value:
                os.environ[env_key] = value
                cfg[env_key] = value
                changed = True
            else:
                print(f"  ⚠️  Skipped — {env_key} left unset.")

    if changed:
        _save_config_file(cfg)
        print("\n✅  Configuration saved to .bot_config\n")

_setup_config()
