def get_nowpayments_min_amount(pay_currency: str) -> float:
    """Fetch the minimum payment amount for a currency from NOWPayments."""
    try:
        resp = requests.get(
            f"https://api.nowpayments.io/v1/min-amount",
            headers={"x-api-key": NOWPAYMENTS_API_KEY},
            params={"currency_from": "usd", "currency_to": pay_currency},
            timeout=10
        )
        if resp.status_code == 200:
            data = resp.json()
            min_val = data.get("min_amount", 20.0)
            return max(float(min_val) * 1.05, 1.0)  # 5% buffer above minimum
    except Exception as e:
        logger.warning(f"Could not fetch min amount for {pay_currency}: {e}")
    return 20.0  # safe default fallback

def create_nowpayments_payment(amount_usd, pay_currency, user_id=None):
    """Create a payment via NOWPayments API. Auto-uses minimum amount if needed."""
    if not NOWPAYMENTS_API_KEY:
        logger.error("NOWPayments API Key missing")
        return None

    url = "https://api.nowpayments.io/v1/payment"
    headers = {
        "x-api-key": NOWPAYMENTS_API_KEY,
        "Content-Type": "application/json"
    }
    order_id = f"dep_{user_id}_{int(time.time())}" if user_id else f"dep_unknown_{int(time.time())}"

    def _attempt(price_amount):
        data = {
            "price_amount": price_amount,
            "price_currency": "usd",
            "pay_currency": pay_currency,
            "ipn_callback_url": IPN_CALLBACK_URL,
            "order_id": order_id,
            "order_description": "Casino Deposit"
        }
        return requests.post(url, headers=headers, json=data, timeout=20)

    def _json_or_empty(response):
        try:
            parsed = response.json()
            return parsed if isinstance(parsed, dict) else {}
        except (ValueError, TypeError):
            return {}

    try:
        response = _attempt(amount_usd)
        response_data = _json_or_empty(response)
        if response.status_code in (200, 201) and (
            response_data.get("payment_id") or response_data.get("pay_address")
        ):
            return response_data
        # If amount is too low, fetch the real minimum and retry once
        err_data = response_data
        if err_data.get("code") == "AMOUNT_MINIMAL_ERROR" or "minimal" in err_data.get("message", "").lower():
            min_amount = get_nowpayments_min_amount(pay_currency)
            logger.info(f"Retrying {pay_currency} with min amount ${min_amount:.2f}")
            response = _attempt(min_amount)
            response_data = _json_or_empty(response)
            if response.status_code in (200, 201) and (
                response_data.get("payment_id") or response_data.get("pay_address")
            ):
                return response_data
        provider_message = (
            response_data.get("message")
            or response_data.get("error")
            or response.text[:300]
            or "Payment creation failed"
        )
        logger.error(
            f"NOWPayments error: {response.status_code} - {provider_message}"
        )
        return None
    except Exception as e:
        logger.error(f"NOWPayments exception: {e}")
        return None

def format_remaining(sec: int) -> str:
    if sec < 0:
        sec = 0
    h = sec // 3600
    m = (sec % 3600) // 60
    s = sec % 60
    return f"{h:02d}:{m:02d}:{s:02d}"

