async def set_cf_sticker(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Admin command to set coinflip stickers."""
    if not update.message or update.message.from_user.id != OWNER_ID:
        return
    
    if not context.args:
        await update.message.reply_text(
            "✨ <b>Coinflip Sticker Setup</b>\n\n"
            "1. Send the sticker you want to use.\n"
            "2. Reply to that sticker with:\n"
            "   <code>/setcf heads</code> — for HEADS result\n"
            "   <code>/setcf tails</code> — for TAILS result\n"
            "   <code>/setcf btc</code> or <code>/setcf eth</code> — legacy options",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not update.message.reply_to_message or not update.message.reply_to_message.sticker:
        await update.message.reply_text("❌ Please reply to a <b>sticker</b> to set it as a coinflip animation.", parse_mode=ParseMode.HTML)
        return

    sticker_id = update.message.reply_to_message.sticker.file_id
    coin_type = context.args[0].lower()

    if coin_type not in ['btc', 'eth', 'heads', 'tails']:
        await update.message.reply_text(
            "❌ Usage: Reply to a sticker with <code>/setcf heads</code> or <code>/setcf tails</code>",
            parse_mode=ParseMode.HTML
        )
        return

    CF_STICKERS[coin_type] = sticker_id
    coinflip_stickers[coin_type] = sticker_id
    save_data()
    
    await update.message.reply_text(f"✅ <b>{coin_type.upper()}</b> coinflip sticker updated successfully!", parse_mode=ParseMode.HTML)

async def auto_save_sticker_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Unified sticker handler — owner sends sticker, bot asks what to use it for."""
    if not update.message or not update.message.sticker or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        return

    sticker = update.message.sticker
    sticker_id = sticker.file_id
    sticker_set_name = sticker.set_name or "unknown"

    # Save to user_states so callbacks can retrieve it
    user_id = str(update.message.from_user.id)
    user_states[f"{user_id}_pending_sticker"] = sticker_id
    user_states[f"{user_id}_pending_sticker_set"] = sticker_set_name

    keyboard = [
        [InlineKeyboardButton("🎰 Roulette Sticker Pack", callback_data="setsticker_roulette")],
        [InlineKeyboardButton("🔫 Rollers Roulette Sticker Pack", callback_data="setsticker_rollers_roulette")],
        [
            InlineKeyboardButton("🪙 Set as HEADS", callback_data="set_sticker:heads"),
            InlineKeyboardButton("🎲 Set as TAILS", callback_data="set_sticker:tails"),
        ],
        [
            InlineKeyboardButton("💰 Set as BTC Coinflip", callback_data="set_sticker:btc"),
            InlineKeyboardButton("💠 Set as ETH Coinflip", callback_data="set_sticker:eth"),
        ],
        [InlineKeyboardButton("❌ Cancel", callback_data="cancel_sticker")],
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    await update.message.reply_text(
        f"🎲 <b>Sticker Pack Detected!</b>\n\n"
        f"📦 Pack: <code>{sticker_set_name}</code>\n"
        f"🆔 File ID: <code>{sticker_id}</code>\n\n"
        f"What would you like to use this sticker pack for?",
        reply_markup=reply_markup,
        parse_mode=ParseMode.HTML,
    )

async def sticker_callback_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles BTC/ETH coinflip sticker selection from the unified sticker prompt."""
    query = update.callback_query
    # Auth check BEFORE query.answer() — show_alert must be the first and only answer
    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("Unauthorized", show_alert=True)
        except Exception:
            pass
        return
    # Answer normally for the success path (no alert needed)
    try:
        await query.answer()
    except Exception:
        pass

    user_id = str(query.from_user.id)
    data = query.data.split(':')
    coin_type = data[1]  # 'btc', 'eth', 'heads', or 'tails'

    sticker_id = user_states.get(f"{user_id}_pending_sticker")
    if not sticker_id:
        await query.edit_message_text("❌ Sticker session expired. Please send the sticker again.")
        return

    CF_STICKERS[coin_type] = sticker_id
    coinflip_stickers[coin_type] = sticker_id
    user_states.pop(f"{user_id}_pending_sticker", None)
    user_states.pop(f"{user_id}_pending_sticker_set", None)
    save_data()

    label = "HEADS 🪙" if coin_type == 'heads' else ("TAILS 🎲" if coin_type == 'tails' else coin_type.upper())
    await query.edit_message_text(
        f"✅ <b>{label} Coinflip sticker saved!</b>\n\n"
        f"The bot will now use this sticker for <b>{label}</b> results.",
        parse_mode=ParseMode.HTML,
    )

