def _ensure_permanent_casino_assets() -> None:
    """Ensure every UI image has a project-owned copy before handlers use it."""
    os.makedirs(CASINO_ASSET_DIR, exist_ok=True)
    project_dir = os.path.dirname(CASINO_ASSET_DIR)
    workspace_assets = os.path.join(project_dir, "attached_assets")
    # Older workspace exports kept permanent bot images at the project root
    # instead of in attached_assets. Search both locations for migration
    # compatibility, while the stable destination remains inside the project.
    source_dirs = (workspace_assets, project_dir)
    for destination_name, source_names in _PERMANENT_CASINO_ASSETS.items():
        destination = os.path.join(CASINO_ASSET_DIR, destination_name)
        if os.path.isfile(destination) and os.path.getsize(destination) > 0:
            continue
        restored = False
        for source_dir in source_dirs:
            for source_name in (destination_name, *source_names):
                source = os.path.join(source_dir, source_name)
                if os.path.isfile(source) and os.path.getsize(source) > 0:
                    shutil.copy2(source, destination)
                    logger.info("[ASSETS] Restored permanent banner: %s", destination_name)
                    restored = True
                    break
            if restored:
                break
        if not restored:
            logger.error("[ASSETS] Missing permanent banner recovery source: %s", destination_name)

_ensure_permanent_casino_assets()

async def crypto_deposit_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Start the crypto deposit flow."""
    query = update.callback_query

    if query:
        try:
            await query.answer()
        except Exception:
            pass
        # The banner is optional.  Do not let a missing local asset break the
        # actual deposit flow or leave the Telegram callback spinning forever.
        if os.path.isfile(DEPOSIT_BANNER_PATH):
            try:
                with open(DEPOSIT_BANNER_PATH, "rb") as img:
                    await query.edit_message_media(
                        media=InputMediaPhoto(media=img),
                        reply_markup=coin_keyboard()
                    )
                    return
            except Exception as exc:
                logger.warning("Could not update deposit banner: %s", exc)

        try:
            await query.edit_message_text(
                "💳 <b>Choose a cryptocurrency to deposit</b>\n\n"
                "Select a coin below to generate your payment address and QR code.",
                reply_markup=coin_keyboard(),
                parse_mode=ParseMode.HTML,
            )
        except Exception as exc:
            logger.warning("Could not show deposit menu in callback: %s", exc)
            await query.message.reply_text(
                "💳 <b>Choose a cryptocurrency to deposit</b>\n\n"
                "Select a coin below to generate your payment address and QR code.",
                reply_markup=coin_keyboard(),
                parse_mode=ParseMode.HTML,
            )
    else:
        if os.path.isfile(DEPOSIT_BANNER_PATH):
            try:
                with open(DEPOSIT_BANNER_PATH, "rb") as img:
                    await update.message.reply_photo(
                        photo=img,
                        reply_markup=coin_keyboard()
                    )
                    return
            except Exception as exc:
                logger.warning("Could not send deposit banner: %s", exc)

        await update.message.reply_text(
            "💳 <b>Choose a cryptocurrency to deposit</b>\n\n"
            "Select a coin below to generate your payment address and QR code.",
            reply_markup=coin_keyboard(),
            parse_mode=ParseMode.HTML,
        )


