def make_qr(data):
    qr = qrcode.QRCode(box_size=10, border=2)
    qr.add_data(data)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    bio = BytesIO()
    bio.name = "qr.png"
    img.save(bio, "PNG")
    bio.seek(0)
    return bio

def generate_crypto_logo(coin_name: str, size: int = 256):
    """Load official crypto logo from file, clipped to a circle with white border."""
    from PIL import Image, ImageDraw
    import os

    COIN_ICON_MAP = {
        # Bitcoin
        'btc': 'btc', 'bitcoin': 'btc',
        # Ethereum
        'eth': 'eth', 'ethereum': 'eth', 'ethbase': 'eth', 'etherc20': 'eth',
        # Litecoin
        'ltc': 'ltc', 'litecoin': 'ltc',
        # TON
        'ton': 'ton', 'toncoin': 'ton',
        # USDT (all networks → same usdt icon)
        'usdt': 'usdt', 'usdtton': 'usdt', 'usdttrc20': 'usdt', 'usdterc20': 'usdt',
        'usdtbsc': 'usdt', 'usdtsol': 'usdt', 'usdtmatic': 'usdt', 'usdtpol': 'usdt',
        # USDC (all networks → same usdc icon)
        'usdc': 'usdc', 'usdcerc20': 'usdc', 'usdcbsc': 'usdc', 'usdcsol': 'usdc',
        'usdcmatic': 'usdc', 'usdcpol': 'usdc',
        # DAI
        'dai': 'dai', 'daierc20': 'dai', 'daibsc': 'dai', 'daimatic': 'dai',
        # Solana
        'sol': 'sol', 'solana': 'sol',
        # BNB
        'bnb': 'bnb', 'bnbbsc': 'bnb',
        # TRON
        'trx': 'trx', 'tron': 'trx',
        # Polygon / MATIC (same coin, same icon)
        'pol': 'pol', 'polygon': 'pol', 'matic': 'pol', 'maticbsc': 'pol', 'maticpol': 'pol',
        # Dogecoin
        'doge': 'doge', 'dogecoin': 'doge',
        # XRP
        'xrp': 'xrp', 'ripple': 'xrp',
        # Monero
        'xmr': 'xmr', 'monero': 'xmr',
        # Cardano
        'ada': 'ada', 'cardano': 'ada',
        # Polkadot
        'dot': 'dot', 'polkadot': 'dot',
        # Shiba Inu
        'shib': 'shib', 'shibainu': 'shib',
        # Avalanche
        'avax': 'avax', 'avalanche': 'avax',
        # Chainlink
        'link': 'link', 'chainlink': 'link',
        # Stellar
        'xlm': 'xlm', 'stellar': 'xlm',
        # Cosmos
        'atom': 'atom', 'cosmos': 'atom',
        # NEAR
        'near': 'near',
    }

    coin_lower = coin_name.lower().strip()
    icon_name = COIN_ICON_MAP.get(coin_lower)
    if not icon_name:
        for key, val in COIN_ICON_MAP.items():
            if key in coin_lower:
                icon_name = val
                break
    # No BTC fallback — unknown coins get a colored circle with initials below

    # Try loading official icon
    base_dir = os.path.dirname(os.path.abspath(__file__))
    icon_path = os.path.join(base_dir, 'public', 'crypto_icons', f'{icon_name}.png') if icon_name else None

    def make_circle_logo(source_img, size):
        """Clip an image to a circle with white padded background."""
        padding = max(4, size // 16)
        total = size + padding * 2
        # White circle background
        bg = Image.new('RGBA', (total, total), (255, 255, 255, 0))
        mask_bg = Image.new('L', (total, total), 0)
        ImageDraw.Draw(mask_bg).ellipse([0, 0, total - 1, total - 1], fill=255)
        white_bg = Image.new('RGBA', (total, total), (255, 255, 255, 255))
        bg.paste(white_bg, mask=mask_bg)
        # Scale coin logo to fit inside the circle (inscribed square)
        inner = int(size * 0.82)
        logo = source_img.convert('RGBA').resize((inner, inner), Image.Resampling.LANCZOS)
        # Clip logo to circle
        logo_mask = Image.new('L', (inner, inner), 0)
        ImageDraw.Draw(logo_mask).ellipse([0, 0, inner - 1, inner - 1], fill=255)
        logo_circ = Image.new('RGBA', (inner, inner), (0, 0, 0, 0))
        logo_circ.paste(logo, mask=logo_mask)
        # Centre logo on background
        offset = (total - inner) // 2
        bg.paste(logo_circ, (offset, offset), logo_circ)
        return bg.resize((size, size), Image.Resampling.LANCZOS)

    try:
        if os.path.exists(icon_path):
            raw = Image.open(icon_path)
            return make_circle_logo(raw, size)
    except Exception as e:
        logger.warning(f"Failed to load crypto icon {icon_path}: {e}")

    # Fallback: brand-coloured circle with coin initials
    COIN_COLORS = {
        'btc': '#F7931A', 'eth': '#627EEA', 'ltc': '#345D9D', 'ton': '#0098EA',
        'usdt': '#26A69A', 'usdc': '#2775CA', 'dai': '#F5AC37', 'sol': '#9945FF',
        'bnb': '#F3BA2F', 'trx': '#EB0029', 'pol': '#8247E5', 'matic': '#8247E5',
        'doge': '#C2A633', 'xrp': '#346AA9', 'xmr': '#FF6600',
        'ada': '#0033AD', 'dot': '#E6007A', 'shib': '#FFA409',
        'avax': '#E84142', 'link': '#2A5ADA', 'xlm': '#14B6E7',
        'atom': '#2E3148', 'near': '#00C08B',
    }
    color_hex = COIN_COLORS.get(icon_name, '#6B7280')
    color_rgb = tuple(int(color_hex.lstrip('#')[i:i+2], 16) for i in (0, 2, 4))
    img = Image.new('RGBA', (size, size), (255, 255, 255, 0))
    draw = ImageDraw.Draw(img)
    draw.ellipse([2, 2, size - 3, size - 3], fill=color_rgb + (255,), outline=(255, 255, 255, 200), width=3)
    return img

def make_qr_with_logo(data, crypto_code: str = None):
    """Generate QR code. Overlays the coin logo ONLY if an actual icon file exists on disk.
    If no icon file is found, returns a clean scannable QR with no overlay."""
    from PIL import Image, ImageDraw
    import os

    # Maps every possible NOWPayments pay_currency code → icon filename (in public/crypto_icons/)
    # Same coin, different networks = same icon file
    logo_map = {
        # Bitcoin
        'btc': 'btc', 'bitcoin': 'btc',
        # Ethereum — all ETH networks (ERC20, BASE, Polygon, etc.) use eth icon
        'eth': 'eth', 'ethereum': 'eth',
        'ethbase': 'eth', 'etherc20': 'eth', 'etharb': 'eth', 'ethop': 'eth',
        'matic': 'eth',          # "ETH (POL)" in deposit options
        # Litecoin
        'ltc': 'ltc', 'litecoin': 'ltc',
        # Toncoin
        'ton': 'ton', 'toncoin': 'ton',
        # USDT — network-specific icons (show the chain, not just the token)
        'usdt': 'usdt',
        'usdtton': 'ton',    # USDT on TON  → TON icon
        'usdttrc20': 'trx',  # USDT on TRON → TRX icon
        'usdterc20': 'eth',  # USDT on ETH  → ETH icon
        'usdtbsc': 'bnb',    # USDT on BEP20 → BNB icon
        'usdtsol': 'sol',    # USDT on SOL  → SOL icon
        'usdtmatic': 'pol',  # USDT on POL  → POL icon
        'usdtpol': 'pol',
        # USDC — network-specific icons
        'usdc': 'usdc',
        'usdcerc20': 'eth',  'usdcbsc': 'bnb',
        'usdcsol': 'sol',    'usdcmatic': 'pol',  'usdcpol': 'pol',
        # DAI — network-specific icons
        'dai': 'dai',
        'daierc20': 'eth',   'daibsc': 'bnb',    'daimatic': 'pol',
        'maticusdce': 'pol',  # "DAI (POL)" in deposit options
        # Solana
        'sol': 'sol', 'solana': 'sol',
        # BNB
        'bnb': 'bnb', 'bnbbsc': 'bnb',
        # Tron
        'trx': 'trx', 'tron': 'trx',
        # Polygon / MATIC native token
        'pol': 'pol', 'polygon': 'pol',
        'maticbsc': 'pol', 'maticpol': 'pol',
        # Dogecoin
        'doge': 'doge', 'dogecoin': 'doge',
        # XRP
        'xrp': 'xrp', 'ripple': 'xrp',
        # Monero
        'xmr': 'xmr', 'monero': 'xmr',
        # Cardano
        'ada': 'ada', 'cardano': 'ada',
        # Polkadot
        'dot': 'dot', 'polkadot': 'dot',
        # Shiba Inu
        'shib': 'shib', 'shibainu': 'shib',
        # Avalanche
        'avax': 'avax', 'avalanche': 'avax',
        # Chainlink
        'link': 'link', 'chainlink': 'link',
        # Stellar
        'xlm': 'xlm', 'stellar': 'xlm',
        # Cosmos
        'atom': 'atom', 'cosmos': 'atom',
        # NEAR
        'near': 'near',
        # TRUMP coin (Solana)
        'trump': 'trump',
        # BONK (listed as "pepe" in NOWPayments code)
        'pepe': 'bonk', 'bonk': 'bonk',
    }

    # Resolve which icon file to look for
    crypto_code_lower = (crypto_code or '').lower().strip()
    icon_name = logo_map.get(crypto_code_lower)

    # Substring fallback for any unmapped variant codes
    if not icon_name:
        for base_coin in ['usdt', 'usdc', 'dai', 'eth', 'btc', 'ton',
                          'sol', 'bnb', 'trx', 'doge', 'xrp', 'xmr',
                          'ada', 'dot', 'shib', 'avax', 'link', 'xlm',
                          'atom', 'near', 'ltc', 'pol', 'trump', 'bonk']:
            if base_coin in crypto_code_lower:
                icon_name = logo_map.get(base_coin, base_coin)
                break

    base_dir = os.path.dirname(os.path.abspath(__file__))
    icon_path = os.path.join(base_dir, 'public', 'crypto_icons', f'{icon_name}.png') if icon_name else None
    icon_exists = icon_path and os.path.isfile(icon_path)

    # Use high error correction only when we'll place a logo on top
    # Map icon name → coin brand colour for the QR module fill
    QR_COIN_COLOURS = {
        'btc': '#F7931A', 'eth': '#627EEA', 'ltc': '#345D9D', 'ton': '#0098EA',
        'usdt': '#26A69A', 'usdc': '#2775CA', 'dai': '#F5AC37', 'sol': '#9945FF',
        'bnb': '#F3BA2F', 'trx': '#EB0029', 'pol': '#8247E5', 'matic': '#8247E5',
        'doge': '#C2A633', 'xrp': '#346AA9', 'xmr': '#FF6600',
        'ada': '#0033AD', 'dot': '#E6007A', 'shib': '#FFA409',
        'avax': '#E84142', 'link': '#2A5ADA', 'xlm': '#14B6E7',
        'atom': '#2E3148', 'near': '#00C08B', 'bonk': '#FFA409', 'trump': '#D4AF37',
    }
    fill_hex = QR_COIN_COLOURS.get(icon_name or '', QR_COIN_COLOURS.get(crypto_code_lower, '#000000'))

    ec = qrcode.constants.ERROR_CORRECT_H if icon_exists else qrcode.constants.ERROR_CORRECT_M
    qr = qrcode.QRCode(box_size=10, border=2, error_correction=ec)
    qr.add_data(data)
    qr.make(fit=True)
    qr_img = qr.make_image(fill_color=fill_hex, back_color="white").convert('RGB')

    if icon_exists:
        try:
            raw = Image.open(icon_path).convert('RGBA')
            width, height = qr_img.size
            center_size = int(width * 0.22)
            pad = max(5, center_size // 10)
            bg_size = center_size + pad * 2

            # Draw solid white circle background
            bg = Image.new('RGBA', (bg_size, bg_size), (0, 0, 0, 0))
            draw_bg = ImageDraw.Draw(bg)
            draw_bg.ellipse([0, 0, bg_size - 1, bg_size - 1], fill=(255, 255, 255, 255))

            # Resize coin logo to fit inside the circle
            logo = raw.resize((center_size, center_size), Image.Resampling.LANCZOS)

            # Clip logo to a circle
            lmask = Image.new('L', (center_size, center_size), 0)
            ImageDraw.Draw(lmask).ellipse([0, 0, center_size - 1, center_size - 1], fill=255)
            logo_circ = Image.new('RGBA', (center_size, center_size), (0, 0, 0, 0))
            logo_circ.paste(logo, (0, 0), mask=lmask)

            # Paste clipped logo centered on white circle bg
            bg.paste(logo_circ, (pad, pad), logo_circ)

            # Paste the badge onto the QR
            qr_rgba = qr_img.convert('RGBA')
            x_pos = (width - bg_size) // 2
            y_pos = (height - bg_size) // 2
            qr_rgba.paste(bg, (x_pos, y_pos), bg)
            qr_img = qr_rgba.convert('RGB')
        except Exception as e:
            logger.warning(f"Failed to overlay crypto icon {icon_path}: {e}")
            # Fall through with clean QR

    bio = BytesIO()
    bio.name = "qr.png"
    qr_img.save(bio, "PNG")
    bio.seek(0)
    return bio


def make_deposit_card_image(code: str, address: str, username: str = "") -> BytesIO:
    """
    Renders a single PIL image: text panel on top, QR code below.
    Matches the DiceGamble-style dark card layout.
    """
    from PIL import Image, ImageDraw, ImageFont
    import textwrap, os

    coin = COINS[code]
    coin_name_full = coin['name']
    coin_short = coin_name_full.split(' (')[0] if ' (' in coin_name_full else coin_name_full
    network_display = _coin_network_display(coin_name_full)
    pay_currency = coin.get('pay_currency', '').lower()

    # NowPayments fee per network
    FEE_MAP = {
        'btc': '1%', 'ltc': '1%', 'doge': '1%', 'xmr': '1%',
        'eth': '0.5%', 'ethbase': '0.5%', 'etherc20': '0.5%',
        'sol': '0.5%', 'ton': '0.5%', 'trx': '0.5%',
        'bnb': '0.5%', 'bnbbsc': '0.5%',
    }
    network_fee = FEE_MAP.get(pay_currency, '0.5%')

    # ── Colours ──────────────────────────────────────────────────────
    BG_COL     = (18, 18, 30)
    CARD_COL   = (28, 28, 48)
    ACCENT_COL = (80, 210, 150)
    TEXT_PRI   = (230, 230, 255)
    TEXT_SEC   = (140, 140, 190)
    ADDR_COL   = (255, 255, 255)
    USER_COL   = (100, 190, 255)
    FEE_COL    = (200, 170, 100)
    BORDER_COL = (55, 55, 95)
    DIVIDER    = (60, 60, 100)

    # ── Fonts ─────────────────────────────────────────────────────────
    def _font(size, bold=False):
        name = "DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf"
        for path in [
            f"/usr/share/fonts/truetype/dejavu/{name}",
            f"/usr/share/fonts/dejavu/{name}",
        ]:
            try:
                return ImageFont.truetype(path, size)
            except Exception:
                pass
        return ImageFont.load_default()

    def _mono(size):
        for path in [
            "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf",
            "/usr/share/fonts/dejavu/DejaVuSansMono.ttf",
        ]:
            try:
                return ImageFont.truetype(path, size)
            except Exception:
                pass
        return ImageFont.load_default()

    font_title = _font(24, bold=True)
    font_label = _font(16)
    font_bold  = _font(16, bold=True)
    font_addr  = _mono(14)
    font_small = _font(14)

    # ── QR code (coin-branded with logo in centre) ───────────────────
    qr_bio = make_qr_with_logo(address, code)
    qr_img = Image.open(qr_bio).convert('RGB')
    QR_SIZE = 340
    qr_img  = qr_img.resize((QR_SIZE, QR_SIZE), Image.Resampling.LANCZOS)

    PAD = 28
    W   = QR_SIZE + PAD * 2   # ≈ 396 px

    # ── Header coin icon ─────────────────────────────────────────────
    base_dir = os.path.dirname(os.path.abspath(__file__))
    HEADER_ICON_MAP = {
        'usdtton': 'usdt', 'usdttrc20': 'usdt', 'usdterc20': 'usdt',
        'usdtbsc': 'usdt', 'usdtsol': 'usdt', 'usdtmatic': 'usdt', 'usdtpol': 'usdt',
        'usdcerc20': 'usdc', 'usdcbsc': 'usdc', 'usdcsol': 'usdc',
        'usdcmatic': 'usdc', 'usdcpol': 'usdc',
        'daierc20': 'dai', 'daibsc': 'dai', 'daimatic': 'dai', 'maticusdce': 'dai',
        'ethbase': 'eth', 'etherc20': 'eth', 'etharb': 'eth', 'ethop': 'eth',
        'matic': 'eth', 'bnbbsc': 'bnb', 'maticpol': 'pol', 'maticbsc': 'pol',
        'pepe': 'bonk',
    }
    header_icon_name = HEADER_ICON_MAP.get(pay_currency, pay_currency)
    for base in ['usdt', 'usdc', 'dai', 'eth', 'btc', 'sol', 'bnb', 'trx', 'ltc', 'ton']:
        if not header_icon_name and base in pay_currency:
            header_icon_name = base
            break
    header_icon_path = os.path.join(base_dir, 'public', 'crypto_icons', f'{header_icon_name}.png')

    # ── Text layout calculations ─────────────────────────────────────
    chars_per_line = max(1, (W - PAD * 2) // 9)
    addr_lines  = textwrap.wrap(address, chars_per_line) or [address]
    LINE_H      = 24
    ADDR_LINE_H = 20
    ICON_SIZE   = 34

    n_rows = (
        PAD + 6
        + ICON_SIZE + 16          # title row
        + 1 + 12                  # divider + gap
        + LINE_H + 8              # address label
        + len(addr_lines) * ADDR_LINE_H + 6   # address lines
        + LINE_H + 6              # network row
        + LINE_H + 6              # fee row
        + (LINE_H + 4 if username else 0)  # owner line
        + PAD
    )
    text_panel_h = n_rows
    H = text_panel_h + 14 + QR_SIZE + PAD

    # ── Canvas ───────────────────────────────────────────────────────
    img  = Image.new('RGB', (W, H), BG_COL)
    draw = ImageDraw.Draw(img)

    # Dark rounded card for text section
    draw.rounded_rectangle(
        [6, 6, W - 6, text_panel_h - 6],
        radius=16, fill=CARD_COL, outline=BORDER_COL, width=1
    )

    y = PAD + 6

    # Coin icon + title
    x_title = PAD
    if os.path.isfile(header_icon_path):
        try:
            ci = Image.open(header_icon_path).convert('RGBA')
            ci = ci.resize((ICON_SIZE, ICON_SIZE), Image.Resampling.LANCZOS)
            img.paste(ci, (PAD, y), ci)
            x_title = PAD + ICON_SIZE + 10
        except Exception:
            pass
    draw.text((x_title, y + 4), f"{coin_short} deposit", font=font_title, fill=ACCENT_COL)
    y += ICON_SIZE + 16

    # Divider
    draw.line([PAD, y, W - PAD, y], fill=DIVIDER, width=1)
    y += 12

    # Address label + value
    draw.text((PAD, y), "Address:", font=font_label, fill=TEXT_SEC)
    y += LINE_H + 2
    for line in addr_lines:
        draw.text((PAD, y), line, font=font_addr, fill=ADDR_COL)
        y += ADDR_LINE_H
    y += 6

    # Network row
    net_lw = int(draw.textlength("Network: ", font=font_label))
    draw.text((PAD, y), "Network: ", font=font_label, fill=TEXT_SEC)
    draw.text((PAD + net_lw, y), network_display, font=font_bold, fill=TEXT_PRI)
    y += LINE_H + 6

    # Fee row
    fee_lw = int(draw.textlength("Network fee: ", font=font_label))
    draw.text((PAD, y), "Network fee: ", font=font_label, fill=TEXT_SEC)
    draw.text((PAD + fee_lw, y), network_fee, font=font_bold, fill=FEE_COL)
    y += LINE_H + 6

    # Owner line
    if username:
        draw.text((PAD, y), f"\U0001f512 This address belongs to @{username}", font=font_small, fill=USER_COL)

    # QR image (centred below text panel)
    qr_x = (W - QR_SIZE) // 2
    img.paste(qr_img, (qr_x, text_panel_h + 14))

    bio = BytesIO()
    bio.name = "deposit_card.png"
    img.save(bio, "PNG")
    bio.seek(0)
    return bio


