# ── NowPayments pay_currency code → canonical CURRENCY_RATES key ─────────────
# NowPayments returns codes like "usdcerc20", "pepe" (for BONK), "avaxc", etc.
# We normalise them here so rate lookups always succeed.
_NP_CODE_MAP: dict = {
    # USDT network variants — all stablecoins ≈ $1
    'USDTERC20': 'USDT', 'USDTTRC20': 'USDT', 'USDTBEP20': 'USDT',
    'USDTBSC':   'USDT', 'USDTSOL':   'USDT', 'USDTPOL':   'USDT',
    'USDTMATIC': 'USDT', 'USDTTON':   'USDT',
    # USDC network variants — all stablecoins ≈ $1
    'USDC':        'USDT', 'USDCERC20': 'USDT', 'USDCBSC':     'USDT',
    'USDCSOL':     'USDT', 'USDCMATIC': 'USDT', 'USDCTRC20':   'USDT',
    'USDCPOLYGON': 'USDT', 'USDCBEP20': 'USDT', 'USDCAVAX':    'USDT',
    'USDCARB':     'USDT', 'USDCOP':    'USDT',
    # DAI / BUSD
    'DAI': 'USDT', 'BUSD': 'USDT', 'DAIBSC': 'USDT', 'BUSDBSC': 'USDT',
    # BTC multi-chain
    'BTCBEP20': 'BTC', 'BTCBSC': 'BTC', 'WBTC': 'BTC', 'WBTCERC20': 'BTC',
    # ETH multi-chain
    'ETHBSC': 'ETH', 'ETHBEP20': 'ETH',
    # MATIC / POL
    'POL': 'MATIC', 'MATICMAINNET': 'MATIC', 'MATICBSC': 'MATIC',
    # AVAX variants
    'AVAXC': 'AVAX', 'AVAXBSC': 'AVAX',
    # LINK variants
    'LINKBSC': 'LINK', 'LINKERC20': 'LINK',
    # DOGE variants
    'DOGEBSC': 'DOGE', 'DOGEBEP20': 'DOGE',
    # XRP variants
    'XRPBSC': 'XRP', 'XRPBEP20': 'XRP',
    # BNB variants
    'BNBBSC': 'BNB', 'BNBBEP20': 'BNB',
    # SOL variants
    'SOLBSC': 'SOL',
    # SHIB variants
    'SHIBBSC': 'SHIB', 'SHIBETH': 'SHIB',
    # BONK — NowPayments internal code for BONK is "pepe"
    'PEPE': 'BONK', 'BONKSOL': 'BONK',
    # TRX variants
    'TRXBSC': 'TRX',
    # ADA variants
    'ADABSC': 'ADA',
    # DOT variants
    'DOTBSC': 'DOT',
    # TON variants
    'TONBSC': 'TON',
}

def _resolve_deposit_rate(pay_currency: str) -> float:
    """Resolve any NowPayments pay_currency code to a USD rate.

    Handles: standard codes (BTC, ETH…), network-variant codes (usdcerc20,
    avaxc…), NowPayments internal aliases (pepe → BONK), and falls back to
    the NOWPayments estimate API for any completely unknown currency.
    Returns 0.0 when we genuinely cannot determine the price.
    """
    cu = (pay_currency or '').strip().upper()
    # 1. Direct match in CURRENCY_RATES
    rate = CURRENCY_RATES.get(cu)
    if rate:
        return float(rate)
    # 2. Map via NowPayments alias table
    canonical = _NP_CODE_MAP.get(cu)
    if canonical:
        rate = CURRENCY_RATES.get(canonical)
        if rate:
            return float(rate)
    # 3. Prefix heuristics — e.g. "BTCARBITRUM" starts with "BTC"
    for prefix in ('USDT', 'USDC', 'BTC', 'ETH', 'SOL', 'DOGE', 'TRX',
                   'XRP', 'BNB', 'TON', 'ADA', 'DOT', 'LTC', 'AVAX',
                   'LINK', 'MATIC', 'POL', 'SHIB', 'BONK'):
        if cu.startswith(prefix):
            rate = CURRENCY_RATES.get(prefix)
            if rate:
                return float(rate)
    # 4. Live API fallback — ask NOWPayments how much 1 unit of this currency
    #    is worth in USD.  This handles brand-new or exotic coins not yet in
    #    CURRENCY_RATES without dropping the deposit.
    try:
        _np_key = (globals().get('NOWPAYMENTS_API_KEY') or
                   os.environ.get('NOWPAYMENTS_API_KEY') or
                   os.environ.get('NOWPAYMENTS_API', ''))
        if _np_key:
            _cu_lower = cu.lower()
            _resp = requests.get(
                f"https://api.nowpayments.io/v1/estimate"
                f"?amount=1&currency_from={_cu_lower}&currency_to=usd",
                headers={"x-api-key": _np_key},
                timeout=6,
            )
            if _resp.status_code == 200:
                _est = _resp.json()
                _est_usd = float(_est.get('estimated_amount') or 0)
                if _est_usd > 0:
                    # Cache in CURRENCY_RATES so subsequent calls are instant
                    CURRENCY_RATES[cu] = _est_usd
                    logger.info(f"[RATE] Live API fallback: 1 {cu} = ${_est_usd:.6f} USD (cached)")
                    return _est_usd
    except Exception as _rate_err:
        logger.warning(f"[RATE] Live API fallback failed for {cu}: {_rate_err}")
    return 0.0

# Timestamp of last live price fetch
_last_price_fetch: float = 0.0

def refresh_live_crypto_prices() -> None:
    """Fetch live crypto prices — tries CoinGecko first, falls back to Binance."""
    global _last_price_fetch

    # ── Map: CoinGecko id → CURRENCY_RATES key ──────────────────────────────
    CG_MAP = {
        "bitcoin": "BTC", "ethereum": "ETH", "litecoin": "LTC",
        "solana": "SOL", "dogecoin": "DOGE", "tron": "TRX",
        "ripple": "XRP", "binancecoin": "BNB", "the-open-network": "TON",
        "cardano": "ADA", "polkadot": "DOT", "avalanche-2": "AVAX",
        "chainlink": "LINK", "matic-network": "MATIC",
        "shiba-inu": "SHIB", "bonk": "BONK",
    }
    # ── Map: Binance symbol → CURRENCY_RATES key ────────────────────────────
    BINANCE_MAP = {
        "BTCUSDT": "BTC", "ETHUSDT": "ETH", "LTCUSDT": "LTC",
        "SOLUSDT": "SOL", "DOGEUSDT": "DOGE", "TRXUSDT": "TRX",
        "XRPUSDT": "XRP", "BNBUSDT": "BNB", "TONUSDT": "TON",
        "ADAUSDT": "ADA", "DOTUSDT": "DOT", "AVAXUSDT": "AVAX",
        "LINKUSDT": "LINK", "MATICUSDT": "MATIC",
        "SHIBUSDT": "SHIB", "BONKUSDT": "BONK",
    }

    updated = False

    # ── 1. Try CoinGecko ─────────────────────────────────────────────────────
    try:
        resp = requests.get(
            "https://api.coingecko.com/api/v3/simple/price",
            params={"ids": ",".join(CG_MAP.keys()), "vs_currencies": "usd"},
            timeout=8,
            headers={"Accept": "application/json"},
        )
        if resp.status_code == 200:
            data = resp.json()
            for cg_id, key in CG_MAP.items():
                price = (data.get(cg_id) or {}).get("usd")
                if price and price > 0:
                    CURRENCY_RATES[key] = float(price)
            _last_price_fetch = time.time()
            updated = True
    except Exception:
        pass

    # ── 2. Fallback to Binance if CoinGecko failed or was rate-limited ───────
    if not updated:
        try:
            symbols = "[" + ",".join(f'"{s}"' for s in BINANCE_MAP) + "]"
            resp = requests.get(
                "https://api.binance.com/api/v3/ticker/price",
                params={"symbols": symbols},
                timeout=8,
            )
            if resp.status_code == 200:
                for item in resp.json():
                    key = BINANCE_MAP.get(item.get("symbol"))
                    price = float(item.get("price", 0))
                    if key and price > 0:
                        CURRENCY_RATES[key] = price
                _last_price_fetch = time.time()
        except Exception:
            pass  # Keep using last known rates on error


    # ── 3. Fetch live fiat rates (INR and others) from Open Exchange Rates ───
    try:
        fiat_resp = requests.get(
            "https://open.er-api.com/v6/latest/USD",
            timeout=6,
            headers={"Accept": "application/json"},
        )
        if fiat_resp.status_code == 200:
            fiat_data = fiat_resp.json().get("rates", {})
            for fiat_key in ["INR", "EUR", "JPY", "GBP", "CNY", "KRW", "CAD",
                              "HKD", "BRL", "AUD", "TWD", "CHF", "RUB", "THB",
                              "SAR", "AED", "PLN", "VND", "IDR", "SEK", "TRY",
                              "PHP", "NOK", "CZK", "HUF", "UAH", "ARS"]:
                rate = fiat_data.get(fiat_key)
                if rate and float(rate) > 0:
                    CURRENCY_RATES[fiat_key] = float(rate)
    except Exception:
        pass  # Keep static rates on error


def get_telegram_username(update):
    """Helper to get safe username."""
    if not update or not update.effective_user:
        return "Player"
    return update.effective_user.username or update.effective_user.first_name or "Player"

