# Sessions older than this are considered abandoned/leaked and get purged the
# next time we see traffic (e.g. a dice sticker) tied to them, instead of
# silently continuing to process them forever.
STALE_GAME_TIMEOUT_SECS = 15 * 60

def is_active_game_stale(game_data: dict) -> bool:
    """True if a game_data entry has no/old '_created_at' stamp past the timeout."""
    created_at = game_data.get('_created_at')
    if not created_at:
        # Legacy entries created before this stamp existed — treat as stale.
        return True
    return (time.time() - created_at) > STALE_GAME_TIMEOUT_SECS

