def _utf16len(s: str) -> int:
    """Return the number of UTF-16 code units in s (Telegram entity offset unit)."""
    return len(s.encode('utf-16-le')) // 2

async def _send_game_result_msg(context, chat_id,
                                 player_won: bool,
                                 player_name: str, player_id,
                                 winner_pts: int, loser_pts: int,
                                 amount: float, user_currency: str,
                                 reply_markup,
                                 game_name: str = "dice"):
    """Send the compact Roller’s-style end-of-match result message."""
    bot_link_html = _rc_bot_link()

    player_label = f'@{player_name}' if player_name and not str(player_name).startswith('@') else (player_name or 'Player')
    player_link_html = _rc_player_link(player_id, player_label)

    if player_won:
        winner_html = player_link_html
        loser_html  = bot_link_html
        result_line = _rc_game_status(True, format_balance_in_currency(amount, user_currency))
    else:
        winner_html = bot_link_html
        loser_html  = player_link_html
        result_line = _rc_game_status(False, format_balance_in_currency(amount, user_currency))

    # Keep the outcome copy compact like the reference game messages. The bot
    # identity remains Rollers Game; only the message wording is styled here.
    html = (
        f'{_rc_tag("⬆️")} <b>The game has ended</b>\n\n'
        f'{_rc_tag("👑")} <b>Winner:</b> {winner_html} - <b>{winner_pts} points</b>\n'
        f'{_rc_tag("👎")} <b>Loser:</b> {loser_html} - <b>{loser_pts} points</b>\n\n'
        f'{result_line}'
    )

    await context.bot.send_message(
        chat_id=chat_id,
        text=html,
        parse_mode=ParseMode.HTML,
        reply_markup=reply_markup,
    )
