def _maintenance_blocks_player(user_id) -> bool:
    """Return True when maintenance should block a player action."""
    try:
        return casino_maintenance_mode and not is_owner_or_manager(int(user_id))
    except (TypeError, ValueError):
        return casino_maintenance_mode


def _maintenance_game_command(update: Update) -> str:
    """Extract a command name, including commands addressed to this bot."""
    text = getattr(getattr(update, "message", None), "text", "") or ""
    token = text.split(maxsplit=1)[0] if text else ""
    return token.split("@", 1)[0].lstrip("/").lower()


async def maintenance_command_gate(
    update: Update, context: ContextTypes.DEFAULT_TYPE
) -> None:
    """Stop player game commands before their game handlers can run."""
    message = update.message
    user = message.from_user if message else None
    if not message or not user:
        return
    if not _maintenance_blocks_player(user.id):
        return
    if _maintenance_game_command(update) not in MAINTENANCE_GAME_COMMANDS:
        return

    await message.reply_text(GAME_MAINTENANCE_MESSAGE, parse_mode=ParseMode.HTML)
    raise ApplicationHandlerStop


async def maintenance_callback_gate(
    update: Update, context: ContextTypes.DEFAULT_TYPE
) -> None:
    """Stop player game buttons before any game callback handler can run."""
    query = update.callback_query
    user = query.from_user if query else None
    data = (query.data or "") if query else ""
    if not query or not user or not _maintenance_blocks_player(user.id):
        return
    if not data.startswith(MAINTENANCE_GAME_CALLBACK_PREFIXES):
        return

    await query.answer(
        "🔧 Casino maintenance is active. Games are temporarily paused.",
        show_alert=True,
    )
    raise ApplicationHandlerStop


def payments_blocked_for(user_id) -> bool:
    """Return whether a player payment flow must be blocked by maintenance."""
    return _maintenance_blocks_player(user_id)

