def is_owner_or_manager(user_id) -> bool:
    """Return True if user_id is the owner or a registered manager."""
    try:
        uid = int(str(user_id).strip())
    except (TypeError, ValueError):
        return False
    return uid == OWNER_ID or uid in MANAGER_IDS

