PLISIO_CURRENCY_MAP = {
    'ltc': 'LTC',
    'eth': 'ETH',
    'ton': 'TON',
    'sol': 'SOL',
    'usdterc20': 'USDT_ETH',
    'usdttrc20': 'TRX_USDT',
    'usdtbsc': 'BUSD',
    'usdtsol': 'USDT_SOL',
    'btc': 'BTC',
    'trx': 'TRX',
    'bnb': 'BNB',
    'bnbbsc': 'BNB_BSC',
    'usdc': 'USDC',
    'doge': 'DOGE',
    'xrp': 'XRP',
    'ada': 'ADA',
    'matic': 'MATIC_POLYGON',
}


def _php_serialize(data) -> str:
    """Minimal PHP serialize implementation for Plisio webhook verification."""
    if isinstance(data, dict):
        parts = []
        for k, v in data.items():
            parts.append(_php_serialize(k))
            parts.append(_php_serialize(v))
        return "a:{}:{{{}}}".format(len(data), "".join(parts))
    elif isinstance(data, bool):
        return "b:{};".format(1 if data else 0)
    elif isinstance(data, int):
        return "i:{};".format(data)
    elif isinstance(data, float):
        return "d:{};".format(data)
    elif data is None:
        return "N;"
    else:
        s = str(data)
        encoded_len = len(s.encode('utf-8'))
        return 's:{}:"{}";'.format(encoded_len, s)


def plisio_verify_webhook(data: dict) -> bool:
    """Verify Plisio webhook HMAC-SHA1 signature."""
    if not PLISIO_SECRET_KEY:
        logger.warning("⚠️ PLISIO_SECRET_KEY not set — webhook is OPEN (insecure)")
        return True  # allow through but warn
    verify_hash = data.get("verify_hash", "")
    if not verify_hash:
        logger.warning("⚠️ Plisio webhook missing verify_hash — rejecting")
        return False
    payload = dict(sorted({k: v for k, v in data.items() if k != "verify_hash"}.items()))
    serialized = _php_serialize(payload)
    expected = hmac.new(PLISIO_SECRET_KEY.encode('utf-8'), serialized.encode('utf-8'), hashlib.sha1).hexdigest()
    return hmac.compare_digest(expected, verify_hash.lower())


def plisio_create_payout(address: str, currency: str, amount_usd: float, withdrawal_id: str):
    """Create a Plisio cash-out payout. Returns (result_dict, error_string)."""
    if not PLISIO_SECRET_KEY:
        return None, "PLISIO_SECRET_KEY not configured"
    plisio_currency = PLISIO_CURRENCY_MAP.get(currency.lower(), currency.upper())
    params = {
        'api_key': PLISIO_SECRET_KEY,
        'currency': plisio_currency,
        'to': address,
        'amount': str(round(amount_usd, 8)),
        'type': 'cash_out',
        'order_number': withdrawal_id,
        'order_name': f'Withdrawal {withdrawal_id}',
    }
    try:
        resp = requests.get(f"{PLISIO_API_BASE}/operations/withdraw", params=params, timeout=30)
        data = resp.json()
        logger.info(f"[Plisio] Payout response HTTP {resp.status_code}: {data}")
        if data.get('status') == 'success':
            return data.get('data', {}), None
        err_data = data.get('data', {})
        err_msg = (err_data.get('message') if isinstance(err_data, dict) else None) or str(data)
        logger.error(f"[Plisio] Payout failed: {err_msg}")
        return None, err_msg
    except Exception as e:
        logger.error(f"[Plisio] Payout exception: {e}")
        return None, str(e)


# ── Plisio webhook (early-binding on first Flask instance) ────────────────────
def _handle_plisio_webhook_sync():
    """Synchronous core of the Plisio webhook — called from both Flask instances."""
    try:
        data = request.form.to_dict() if request.form else (request.get_json(force=True) or {})
        order_number = data.get('order_number', '')
        status = data.get('status', '')
        txn_id = data.get('txn_id', '')
        logger.info(f"[Plisio Webhook] order={order_number} status={status} txn_id={txn_id} ip={request.remote_addr}")

        if not plisio_verify_webhook(data):
            logger.error(f"[Plisio Webhook] ❌ Invalid signature for order={order_number}")
            return jsonify({'status': 'invalid_signature'}), 200

        if not order_number:
            logger.warning("[Plisio Webhook] No order_number — ignoring")
            return jsonify({'status': 'ok'}), 200

        withdrawal = pending_withdrawals.get(order_number)
        if not withdrawal:
            logger.warning(f"[Plisio Webhook] Unknown order_number={order_number}")
            return jsonify({'status': 'ok'}), 200

        user_id = withdrawal.get('user_id', '')
        amount_usd = float(withdrawal.get('amount_usd', 0))
        display_name = withdrawal.get('display_name', 'Crypto')
        wallet_address = withdrawal.get('wallet_address', '')
        token = os.environ.get("TELEGRAM_BOT_TOKEN") or os.environ.get("BOT_TOKEN", "")

        if status == 'completed':
            if withdrawal.get('status') not in ('completed',):
                withdrawal['status'] = 'completed'
                withdrawal['txn_id'] = txn_id
                pending_withdrawals[order_number] = withdrawal
                try:
                    save_data_critical()
                except Exception:
                    pass
            logger.info(f"[Plisio Webhook] ✅ Completed: order={order_number} user={user_id} txn={txn_id}")
            if token and user_id:
                tx_url = data.get('tx_url', '')
                tx_line = (f"\n🔗 <a href=\"{tx_url}\">View Transaction</a>" if tx_url
                           else (f"\n🆔 TX: <code>{txn_id}</code>" if txn_id else ""))
                try:
                    requests.post(
                        f"https://api.telegram.org/bot{token}/sendMessage",
                        json={
                            "chat_id": user_id,
                            "text": (
                                f"✅ <b>Withdrawal Sent!</b>\n\n"
                                f"Amount: <b>${amount_usd:.2f}</b> ({display_name})\n"
                                f"Address: <code>{wallet_address}</code>"
                                f"{tx_line}\n\n"
                                f"Your crypto is on the way! 🚀"
                            ),
                            "parse_mode": "HTML",
                            "disable_web_page_preview": True,
                        },
                        timeout=8
                    )
                except Exception as e:
                    logger.error(f"[Plisio Webhook] Failed to notify user {user_id}: {e}")
            if token and OWNER_ID:
                try:
                    requests.post(
                        f"https://api.telegram.org/bot{token}/sendMessage",
                        json={
                            "chat_id": OWNER_ID,
                            "text": (
                                f"✅ <b>PLISIO WITHDRAWAL COMPLETED</b>\n\n"
                                f"Order: <code>{order_number}</code>\n"
                                f"User: <code>{user_id}</code>\n"
                                f"Amount: ${amount_usd:.2f} ({display_name})\n"
                                f"Address: <code>{wallet_address}</code>\n"
                                f"TXN: <code>{txn_id}</code>"
                            ),
                            "parse_mode": "HTML",
                        },
                        timeout=8
                    )
                except Exception:
                    pass

        elif status in ('error', 'cancelled', 'expired'):
            if withdrawal.get('status') not in ('refunded', 'completed'):
                withdrawal['status'] = 'refunded'
                pending_withdrawals[order_number] = withdrawal
                try:
                    ultra_secure_add_user_balance(user_id, amount_usd, "plisio_withdrawal_refund")
                    save_data_critical()
                    logger.info(f"[Plisio Webhook] 🔄 Refunded ${amount_usd:.2f} to user={user_id} (status={status})")
                except Exception as e:
                    logger.error(f"[Plisio Webhook] Refund error: {e}")
                if token and user_id:
                    try:
                        current_bal = get_user_balance(user_id)
                        requests.post(
                            f"https://api.telegram.org/bot{token}/sendMessage",
                            json={
                                "chat_id": user_id,
                                "text": (
                                    f"❌ <b>Withdrawal Failed</b>\n\n"
                                    f"Your {display_name} withdrawal of <b>${amount_usd:.2f}</b> "
                                    f"could not be processed.\n\n"
                                    f"💰 Balance refunded: <b>${current_bal:.2f}</b>\n\n"
                                    f"Please contact support if you need help."
                                ),
                                "parse_mode": "HTML",
                            },
                            timeout=8
                        )
                    except Exception as e:
                        logger.error(f"[Plisio Webhook] Notify failure error: {e}")
        else:
            logger.info(f"[Plisio Webhook] Intermediate status '{status}' for order={order_number} — no action")

        return jsonify({'status': 'ok'}), 200
    except Exception as e:
        logger.error(f"[Plisio Webhook] Unhandled error: {e}", exc_info=True)
        return jsonify({'status': 'error'}), 200  # always 200 to stop Plisio retries


def generate_qr_code_url(address: str, crypto: str, amount: float = None):
    """Generate a QR code URL for a crypto address using an external service."""
    qr_data = address
    if amount:
        if crypto.lower() == 'btc':
            qr_data = f"bitcoin:{address}?amount={amount}"
        elif crypto.lower() in ['eth', 'usdt', 'usdc']:
            qr_data = f"ethereum:{address}?value={amount}"
        else:
            qr_data = address
    
    encoded_data = requests.utils.quote(qr_data)
    return f"https://api.qrserver.com/v1/create-qr-code/?size=300x300&data={encoded_data}"

def get_blockchain_explorer_link(currency_code: str, tx_hash: str) -> str:
    """Get blockchain explorer link for a transaction."""
    base_url = BLOCKCHAIN_EXPLORERS.get(currency_code.lower(), "")
    if base_url and tx_hash:
        return f"{base_url}{tx_hash}"
    return ""

