def load_data():
    """Load data with embedded recovery - everything from one file!"""
    global user_balances, house_balance, deposit_counter, withdrawal_counter, OWNER_ID, casino_balance_usd
    global casino_maintenance_mode
    global user_states, pending_deposits, pending_withdrawals, pending_owner_payments, active_games
    global user_coins, user_coin_last_roll, user_wallet_mode
    global user_levels, user_boost_status, user_profiles, game_history, referral_data, referral_earnings, pending_referral_commissions
    global user_gift_profiles, processed_telegram_gifts, unattributed_telegram_gifts, gift_tracking_initialized
    global referral_wager_earnings, referral_deposit_earnings, referral_daily_earnings, referral_top_referred, referral_codes, referral_codes_reverse
    global pending_challenges, active_pvp_games, user_wagering_totals, user_losses_rakeback, user_streak_data
    global user_level_bonus_claimed
    global user_last_rakeback_claim, user_raffle_tickets, user_match_history, user_wagering_requirements, user_deposit_totals, user_deposit_history, user_tip_received, user_transfer_codes
    global coinflip_stickers, roulette_stickers, rollers_roulette_stickers
    global user_currency_preferences, crypto_house_balances, player_data
    global user_bonus_balances, user_bonus_wager_data, user_pending_bonus_claims

    import base64
    data = None

    # Try to load main file
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, 'r') as f:
                full_data = json.load(f)

            # Try current data first
            if 'current' in full_data:
                data = full_data['current']
                # CRITICAL: Verify data is not empty before accepting it
                if not (data and data.get('user_balances')) and 'backup_data' in full_data and full_data['backup_data'] and full_data['backup_data'].get('user_balances'):
                    data = full_data['backup_data']
                    print("⚠️ Current state was empty, recovered from embedded backup")
                else:
                    print("✅ Data loaded from current state")
            # Try embedded backup
            elif 'backup_data' in full_data and full_data['backup_data'] and full_data['backup_data'].get('user_balances'):
                data = full_data['backup_data']
                print("🔥 Data recovered from embedded backup")
            # Try emergency recovery
            elif 'emergency_recovery' in full_data:
                try:
                    decoded = base64.b64decode(full_data['emergency_recovery']).decode()
                    data = json.loads(decoded)
                    if data and data.get('user_balances'):
                        print("⚠️ Data recovered from emergency backup")
                    else:
                        data = None
                except:
                    data = None
            # Try old format
            elif 'user_balances' in full_data and full_data['user_balances']:
                data = full_data
                print("✅ Data loaded from legacy format")

        except Exception as e:
            print(f"❌ Error loading main file: {e}")

    # Try emergency files if main file failed
    if data is None:
        emergency_files = [f for f in os.listdir('.') if f.startswith('emergency_') and f.endswith('.json')]
        if emergency_files:
            latest = max(emergency_files)
            try:
                with open(latest, 'r') as f:
                    data = json.load(f)
                print(f"🔥 Data recovered from {latest}")
            except:
                pass

    # ALWAYS merge the dedicated balance backup — it may be newer than the main file
    # (written atomically after every balance change, survives main-file failures)
    if os.path.exists("balances_backup.json"):
        try:
            with open("balances_backup.json", 'r') as _bf:
                _bal_bk = json.load(_bf)
            _bk_balances = _bal_bk.get('user_balances', {})
            _bk_ts = float(_bal_bk.get('ts', 0))
            _main_ts = float(data.get('last_save_timestamp', 0)) if data else 0
            if _bk_balances:
                if data is None:
                    data = {}
                    data['user_balances'] = _bk_balances
                    print(f"🔥 Balances loaded from dedicated backup ({len(_bk_balances)} users)")
                elif _bk_ts >= _main_ts - 1:
                    # Backup is same-age or newer — merge balances: take the higher per user
                    _merged = dict(data.get('user_balances', {}))
                    for _uid, _bbal in _bk_balances.items():
                        _cur = float(_merged.get(_uid, 0))
                        _bbal = float(_bbal)
                        if _bbal > _cur:
                            _merged[_uid] = _bbal
                    data['user_balances'] = _merged
                    print(f"✅ Balances merged from dedicated backup (ts_diff={_bk_ts-_main_ts:.1f}s)")
                    # Also merge wagering data from backup (take higher totals, lower requirements)
                    _bk_wager_reqs = _bal_bk.get('user_wagering_requirements', {})
                    _bk_wager_tots = _bal_bk.get('user_wagering_totals', {})
                    if _bk_wager_reqs:
                        _merged_req = dict(data.get('user_wagering_requirements', {}))
                        for _uid, _wv in _bk_wager_reqs.items():
                            try:
                                _bk_w = float(_wv)
                                _cur_w = float(_merged_req.get(_uid, -1.0))
                                if _cur_w < 0:                    # user missing — insert
                                    _merged_req[_uid] = _bk_w
                                elif _bk_w < _cur_w:              # backup shows MORE progress (lower req)
                                    _merged_req[_uid] = _bk_w
                            except (TypeError, ValueError):
                                pass
                        data['user_wagering_requirements'] = _merged_req
                    if _bk_wager_tots:
                        _merged_tot = dict(data.get('user_wagering_totals', {}))
                        for _uid, _tv in _bk_wager_tots.items():
                            try:
                                _bk_t = float(_tv)
                                _cur_t = float(_merged_tot.get(_uid, 0))
                                if _bk_t > _cur_t:                # backup has higher total wagered
                                    _merged_tot[_uid] = _bk_t
                            except (TypeError, ValueError):
                                pass
                        data['user_wagering_totals'] = _merged_tot
                    print(f"✅ Wagering data merged from dedicated backup")
        except Exception as _bke:
            print(f"⚠️ Balance backup merge failed: {_bke}")

    if data:
        # Load all data - PRESERVE ALL USER DATA!
        # CRITICAL FIX: Update in-place — NEVER replace the dict object.
        # Replacing user_balances = new_dict breaks concurrent threads that hold
        # a reference to the old dict, causing their balance writes to be orphaned
        # and wiped on the next save.
        _loaded_balances = data.get('user_balances', {})
        for _k, _v in _loaded_balances.items():
            try:
                _fv = float(_v)
                # Only update if higher than current in-memory value (protects concurrent wins)
                if _fv > float(user_balances.get(_k, 0)):
                    user_balances[_k] = _fv
                elif _k not in user_balances:
                    user_balances[_k] = _fv
            except:
                pass
        # Sanitize: remove any key that is not a valid Telegram user ID
        _junk_keys = [_k for _k in list(user_balances.keys())
                      if not str(_k).isdigit() or len(str(_k)) < 6]
        for _jk in _junk_keys:
            del user_balances[_jk]
        if _junk_keys:
            print(f"🧹 Removed {len(_junk_keys)} junk balance entries: {_junk_keys}")
        # Load house balance from saved data, or use defaults
        # Load house balance in USD
        saved_hb = data.get('house_balance', data.get('casino_balance_usd', 1022.0))
        house_balance = saved_hb if saved_hb and saved_hb > 0 else 1022.0
        casino_balance_usd = house_balance
        user_currency_preferences = data.get('user_currency_preferences', {})
        deposit_counter = data.get('deposit_counter', 1)
        withdrawal_counter = data.get('withdrawal_counter', 1)
        # Keep the configured owner through reloads.  Older versions reset this
        # value to a hard-coded account, which made the approval buttons reject
        # the configured owner after a restart.
        OWNER_ID = int(os.environ.get("OWNER_ID", str(OWNER_ID)))
        # Restore owner-configurable limits (persisted so owner changes survive restart)
        global MIN_BET, MIN_DEPOSIT, MIN_WITHDRAWAL
        MIN_BET      = float(data.get('min_bet',      MIN_BET))
        MIN_DEPOSIT   = float(data.get('min_deposit',   MIN_DEPOSIT))
        MIN_WITHDRAWAL = float(data.get('min_withdrawal', MIN_WITHDRAWAL))
        user_states = data.get('user_states', {})
        # Clean up any temp_withdrawal data from previous sessions (should not persist)
