def add_user_balance(user_id: str, amount: float):
    """Securely add balance using ultra-secure system with full audit trail."""
    user_id_str = str(user_id)
    amount = float(amount)
    if amount <= 0: return 0.0
    
    # Use the ultra-secure version which has integrity checks
    result = ultra_secure_add_user_balance(user_id_str, amount, "credit")
    
    # NOTE: Do NOT reset wager_requirement here - that is only set on deposits.
    # Resetting it on every win/payout would be a glitch allowing early withdrawal.
    
    # CRITICAL: force synchronous save so balance survives any crash/restart instantly
    save_data_critical()
    return result

_COIN_GAME_CREDIT_TYPES = {
    "blackjack", "cashout", "crash_bet_refund", "dice_error_refund",
    "dice_match_win", "dr2_play_refund", "dr2_roll_cancel_refund",
    "dr_play_refund", "error_refund", "hilo_cashout", "mines_cashout",
    "push", "pvp_refund", "pvp_setup_refund", "pvp_win", "refund",
    "slot_emoji_win", "tie_refund", "tower_top_win", "win",
}
_COIN_GAME_DEBIT_TYPES = {"bet", "slot_emoji_bet"}

def parse_bet_amount(user_id: str, bet_arg: str) -> float:
    """Helper to parse bet amount, supporting 'all' and 'half' shortcuts."""
    balance = float(get_user_balance(user_id))
    user_currency = get_user_currency(user_id)
    
    bet_arg = str(bet_arg).lower().replace("$", "").replace(",", "").strip()
    if bet_arg in ["all", "full"]:
        return balance
    elif bet_arg == "half":
        return max(balance / 2, MIN_BET)
    else:
        try:
            # Parse numeric value
            # Remove symbols that might be present
            clean_arg = bet_arg.replace("$", "").replace("€", "").strip()
            val = float(clean_arg)
            
            # Real-money bets are entered in the user's display currency.
            # Coin bets are whole play-only units and must not be FX-converted.
            if _uses_coin_wallet_context():
                parsed = val
            else:
                target_rate = CURRENCY_RATES.get(user_currency, 1.0)
                parsed = val / target_rate if target_rate != 0 else val

            # Hard floor: never allow a bet below MIN_BET
            minimum_bet = 1.0 if _uses_coin_wallet_context() else MIN_BET
            if 0 < parsed < minimum_bet:
                return -1.0  # sentinel: caller must show "minimum bet" error
            return parsed
        except ValueError:
            return 0.0

def add_game_winnings(user_id: str, winnings: float, bet_amount: float = 0.0):
    """Add game winnings and track for profit system."""
    user_id = str(user_id)
    if _uses_coin_wallet_context():
        add_user_coins(user_id, winnings, "game_win")
        save_data_critical()
        return True
    track_win(user_id, winnings)

    # Credit win — immediately flushed to backup file inside ultra_secure_add_user_balance
    ultra_secure_add_user_balance(user_id, winnings, "win")

    # Auto-deduct from house balance when player wins - ONLY DEDUCT PROFIT, not full winnings
    profit = max(0, winnings - bet_amount)
    if profit > 0:
        deduct_house_balance(profit)

    # Critical save — win must survive any crash
    save_data_critical()
    return True

def is_game_actively_playing(game_data: dict) -> bool:
    """Return True only if the game is genuinely mid-play (not setup / pending / stale)."""
    if not game_data:
        return False
    gtype  = game_data.get('type', '')
    status = game_data.get('status', '')
    created_at = game_data.get('created_at', 0)
    # Stale games older than 2 minutes are never considered active
    if time.time() - created_at > 120:
        return False
    # Setup / pending states are NOT actively playing
    inactive_types = [
        'tower_setup', 'mines_setup',
    ]
    if gtype in inactive_types:
        return False
    inactive_statuses = ['waiting', 'setup', 'pending', 'waiting_for_emoji', 'WAITING_FOR_SETUP']
    if status in inactive_statuses:
        return False
    return True

def deduct_user_balance(user_id: str, amount: float) -> bool:
    """Securely deduct balance from user's account."""
    user_id_str = str(user_id)
    amount = float(amount)
    if amount <= 0: return False

    # ANTI-GLITCH: Block deduction ONLY if user has a genuinely active mid-play game
    if user_id_str in active_games:
        game_data = active_games[user_id_str]
        if is_game_actively_playing(game_data):
            logger.warning(f"🚫 DEDUCTION BLOCKED: {user_id_str} already has an active game ({game_data.get('type')})")
            return False
        else:
            # Stale / setup game — clean it up so new bet can proceed
            logger.info(f"🧹 Clearing stale/setup game for {user_id_str} ({game_data.get('type')})")
            del active_games[user_id_str]

    if _uses_coin_wallet_context():
        return deduct_user_coins(user_id_str, amount, "game_bet")

    # Check if this transaction was already processed in the last 3 seconds (debounce)
    # This PREVENTS double-deduction from rapid button clicks
    now = time.time()
    if not hasattr(deduct_user_balance, '_history'):
        deduct_user_balance._history = {}
        deduct_user_balance._last_cleanup = now

    # Periodically purge stale entries to prevent unbounded memory growth
    if now - deduct_user_balance._last_cleanup > 60:
        stale_keys = [k for k, t in deduct_user_balance._history.items() if now - t > 10]
        for k in stale_keys:
            del deduct_user_balance._history[k]
        deduct_user_balance._last_cleanup = now

    history_key = f"{user_id_str}_{round(amount, 2)}"
    last_time = deduct_user_balance._history.get(history_key, 0)

    if now - last_time < 0.8:
        logger.warning(f"🚫 DOUBLE DEDUCTION BLOCKED (debounce): {user_id_str} (amount: {amount})")
        return False  # CRITICAL: Return False - do NOT allow a free game

    # Record this deduction time so rapid re-clicks are blocked
    deduct_user_balance._history[history_key] = now

    # If user not in balances yet, initialize them (new user) instead of blocking
    if user_id_str not in user_balances:
        user_balances[user_id_str] = 0.0

    def _deduct_balance():
        global _balances_backup_mtime, _balances_backup_ts
        user_id_str = str(user_id)
        # Pull latest balance from disk before computing the new value — prevents
        # a stale in-memory copy from over- or under-deducting when another
        # instance has changed the balance.
        _refresh_balances_from_disk_if_changed()
        current = float(user_balances.get(user_id_str, 0.0))

        # Guard against zero or negative deductions
        if amount <= 0:
            return False

        # GUARD: Never deduct more than what exists
        if current >= amount:
            new_balance = round(current - amount, 2)
            user_balances[user_id_str] = new_balance
            try:
                log_transaction("bet", user_id, -amount, {'operation': 'deduct_balance', 'pre_balance': current, 'new_balance': new_balance})
            except Exception:
                pass
            # Flush the new balance to disk immediately so other instances pick it up.
            try:
                _tmp = "balances_backup.json.tmp"
                import time as _t
                _our_ts = _t.time()
                with open(_tmp, 'w') as _f:
                    import json as _j
                    _j.dump({
                        'user_balances': dict(user_balances),
                        'user_wagering_requirements': dict(user_wagering_requirements),
                        'user_wagering_totals': dict(user_wagering_totals),
                        'ts': _our_ts
                    }, _f)
                os.replace(_tmp, "balances_backup.json")
                # Update tracking so a later refresh doesn't re-pull our own write.
                try:
                    _st = os.stat("balances_backup.json")
                    _balances_backup_mtime = _st.st_mtime
                    _balances_backup_ts = _our_ts
                except Exception:
                    pass
            except Exception:
                pass
            return True
        return False

    return protected_balance_operation(_deduct_balance)

