# CRITICAL BALANCE PRIMITIVES
# These functions are called throughout the entire bot for every balance change.
# ═══════════════════════════════════════════════════════════════════════════════

_balance_op_lock = __import__('threading').Lock()

def protected_balance_operation(fn):
    """Run a balance-modifying callable under the global balance lock."""
    with _balance_op_lock:
        return fn()

def get_coin_balance(user_id: str) -> int:
    """Return the user's separate, non-withdrawable play-only balance."""
    return max(0, int(float(user_coins.get(str(user_id), 0) or 0)))

def get_wallet_mode(user_id: str) -> str:
    """Return the selected game wallet: real or coins."""
    return "coins" if user_wallet_mode.get(str(user_id)) == "coins" else "real"

def set_wallet_mode(user_id: str, mode: str) -> str:
    """Select the wallet used by games without changing either balance."""
    uid = str(user_id)
    selected = "coins" if mode == "coins" else "real"
    user_wallet_mode[uid] = selected
    save_data_critical()
    return selected

def coin_roll_seconds_remaining(user_id: str, now: float = None) -> int:
    """Seconds until the player's next daily coin roll is available."""
    current = time.time() if now is None else float(now)
    last_roll = float(user_coin_last_roll.get(str(user_id), 0) or 0)
    return max(0, int(COIN_COOLDOWN_SECONDS - (current - last_roll)))

def format_coin_cooldown(seconds: int) -> str:
    """Format a remaining daily-roll cooldown for Telegram."""
    seconds = max(0, int(seconds))
    hours, remainder = divmod(seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    if hours:
        return f"{hours}h {minutes}m"
    if minutes:
        return f"{minutes}m {secs}s"
    return f"{secs}s"

def claim_daily_coin_reward(user_id: str, die_value: int = None) -> dict:
    """Atomically claim the 24-hour die reward, returning its result.

    ``die_value`` comes from Telegram's live dice message when available.
    The optional fallback keeps this helper useful for non-Telegram callers.
    """
    uid = str(user_id)
    result = {"ok": False, "remaining": 0, "die": None, "reward": 0}

    def _claim():
        now = time.time()
        remaining = coin_roll_seconds_remaining(uid, now)
        if remaining:
            result["remaining"] = remaining
            return
        die = int(die_value) if die_value is not None else random.randint(1, 6)
        if die not in COIN_REWARDS_BY_DIE:
            return
        reward = COIN_REWARDS_BY_DIE[die]
        user_coins[uid] = get_coin_balance(uid) + reward
        user_coin_last_roll[uid] = now
        result.update({"ok": True, "die": die, "reward": reward})

    protected_balance_operation(_claim)
    if result["ok"]:
        save_data_critical()
    return result

def add_user_coins(user_id: str, amount: float, transaction_type: str = "coin_credit") -> int:
    """Credit only the play-only wallet; this function cannot touch cash."""
    uid = str(user_id)
    amount_int = int(round(float(amount)))
    if amount_int <= 0:
        return get_coin_balance(uid)

    def _credit():
        user_coins[uid] = get_coin_balance(uid) + amount_int
        try:
            log_transaction(
                "casino_coin_" + str(transaction_type),
                uid,
                amount_int,
                {"wallet": "coins", "coin_balance": user_coins[uid]},
            )
        except Exception:
            pass

    protected_balance_operation(_credit)
    save_data_critical()
    return get_coin_balance(uid)

def deduct_user_coins(user_id: str, amount: float, transaction_type: str = "coin_bet") -> bool:
    """Debit only the play-only wallet, rejecting overdrafts and decimals."""
    uid = str(user_id)
    amount_int = int(round(float(amount)))
    if amount_int <= 0:
        return False
    success = False

    def _debit():
        nonlocal success
        current = get_coin_balance(uid)
        if current < amount_int:
            return
        user_coins[uid] = current - amount_int
        success = True
        try:
            log_transaction(
                "casino_coin_" + str(transaction_type),
                uid,
                -amount_int,
                {"wallet": "coins", "coin_balance": user_coins[uid]},
            )
        except Exception:
            pass

    protected_balance_operation(_debit)
    if success:
        save_data_critical()
    return success

def log_transaction(transaction_type: str, user_id, amount: float, meta: dict = None):
    """Audit-log a balance transaction — writes to Python logger AND appends to transaction_log.json."""
    try:
        logger.info(
            f"💳 TXN [{transaction_type}] uid={user_id} "
            f"amount={amount:+.4f} meta={meta or {}}"
        )
    except Exception:
        pass
    # ── Persistent file audit trail ─────────────────────────────────────────
    try:
        import time as _t
        entry = {
            'ts': round(_t.time(), 3),
            'type': str(transaction_type),
            'uid': str(user_id),
            'amount': round(float(amount), 8),
            'meta': meta or {},
        }
        _txlog = "transaction_log.json"
        _tmp   = _txlog + ".tmp"
        # Load existing log (cap at MAX_TRANSACTION_LOGS entries)
        try:
            with open(_txlog, 'r') as _f:
                _data = json.load(_f)
            if not isinstance(_data, list):
                _data = []
        except Exception:
            _data = []
        _data.append(entry)
        # Keep only the most recent MAX_TRANSACTION_LOGS entries
        if len(_data) > MAX_TRANSACTION_LOGS:
            _data = _data[-MAX_TRANSACTION_LOGS:]
        with open(_tmp, 'w') as _f:
            json.dump(_data, _f, separators=(',', ':'))
        os.replace(_tmp, _txlog)
    except Exception:
        pass

def track_win(user_id: str, amount: float):
    """Record a win in player_data stats."""
    uid = str(user_id)
    if uid not in player_data:
        player_data[uid] = {}
    pd = player_data[uid]
    pd['total_wins'] = pd.get('total_wins', 0) + 1
    pd['total_won']  = pd.get('total_won',  0.0) + float(amount)

def add_balance(user_id: str, amount: float):
    """Convenience wrapper — add balance without a specific transaction label."""
    ultra_secure_add_user_balance(str(user_id), float(amount), "bonus")

def _flush_balances_backup():
    """Write in-memory balances atomically to balances_backup.json."""
    global _balances_backup_mtime, _balances_backup_ts
    try:
        import time as _t, json as _j
        _tmp = "balances_backup.json.tmp"
        _ts  = _t.time()
        with open(_tmp, 'w') as _f:
            _j.dump({
                'user_balances':              dict(user_balances),
                'user_wagering_requirements': dict(user_wagering_requirements),
                'user_wagering_totals':       dict(user_wagering_totals),
                'ts': _ts,
            }, _f)
        os.replace(_tmp, "balances_backup.json")
        try:
            _st = os.stat("balances_backup.json")
            _balances_backup_mtime = _st.st_mtime
            _balances_backup_ts    = _ts
        except Exception:
            pass
    except Exception as _fe:
        logger.error(f"_flush_balances_backup failed: {_fe}")

def ultra_secure_add_user_balance(
    user_id: str, amount: float, transaction_type: str = "credit"
) -> float:
    """
    Add *amount* to user_id's balance.
    Thread-safe, atomic, immediately flushed to backup file.
    Returns the new balance.
    """
    user_id = str(user_id)
    if _uses_coin_wallet_context() and transaction_type in _COIN_GAME_CREDIT_TYPES:
        return float(add_user_coins(user_id, amount, transaction_type))
    try:
        amount = float(amount)
    except (TypeError, ValueError):
        logger.error(f"ultra_secure_add_user_balance: bad amount={amount!r} uid={user_id}")
        return float(user_balances.get(user_id, 0.0))
    if amount <= 0:
        return float(user_balances.get(user_id, 0.0))

    def _add():
        _refresh_balances_from_disk_if_changed()
        current     = float(user_balances.get(user_id, 0.0))
        new_balance = round(current + amount, 8)
        user_balances[user_id] = new_balance
        log_transaction(transaction_type, user_id, +amount,
                        {'pre': current, 'post': new_balance})
        _flush_balances_backup()
        return new_balance

    result = protected_balance_operation(_add)
    return float(result) if result is not None else float(user_balances.get(user_id, 0.0))

def ultra_secure_deduct_user_balance(
    user_id: str, amount: float, transaction_type: str = "debit"
) -> bool:
    """
    Deduct *amount* from user_id's balance (only if sufficient funds exist).
    Thread-safe, atomic, immediately flushed to backup file.
    Returns True on success, False on insufficient balance or error.
    """
    user_id = str(user_id)
    if _uses_coin_wallet_context() and transaction_type in _COIN_GAME_DEBIT_TYPES:
        return deduct_user_coins(user_id, amount, transaction_type)
    try:
        amount = float(amount)
    except (TypeError, ValueError):
        logger.error(f"ultra_secure_deduct_user_balance: bad amount={amount!r} uid={user_id}")
        return False
    if amount <= 0:
        return False

    def _deduct():
        _refresh_balances_from_disk_if_changed()
        current = float(user_balances.get(user_id, 0.0))
        if current < amount:
            logger.warning(
                f"ultra_secure_deduct: insufficient for {user_id}: "
                f"has {current:.4f}, needs {amount:.4f}"
            )
            return False
        new_balance = round(current - amount, 8)
        user_balances[user_id] = new_balance
        log_transaction(transaction_type, user_id, -amount,
                        {'pre': current, 'post': new_balance})
        _flush_balances_backup()
        return True

    return bool(protected_balance_operation(_deduct))

# ═══════════════════════════════════════════════════════════════════════════════

def ultra_secure_crypto_operation(operation_type: str, crypto: str, amount: float, user_id: str = None):
    """Ultra-secure crypto operations with full audit trail."""
    def _crypto_operation():
        if operation_type == "add_house":
            log_transaction("crypto_house_credit", user_id or "system", amount, 
                          {'crypto': crypto, 'operation': 'add_house_balance'})
            crypto_house_balances[crypto] = crypto_house_balances.get(crypto, 0.0) + amount
        elif operation_type == "deduct_house":
            current = get_crypto_house_balance(crypto)
            if current >= amount:
                log_transaction("crypto_house_debit", user_id or "system", -amount, 
                              {'crypto': crypto, 'operation': 'deduct_house_balance', 'pre_balance': current})
                crypto_house_balances[crypto] = current - amount
                return True
            return False
        return amount

    return protected_balance_operation(_crypto_operation)

def handle_crypto_game_win(user_id: str, bet_amount: float, win_amount: float):
    """Handle crypto house balance when user wins a game."""
    user_id = str(user_id)

    # Determine which crypto to deduct from based on user's deposit history
    if user_id in user_crypto_deposits:
        total_crypto_deposited_usd = 0
        crypto_distribution = {}

        # Calculate distribution of user's crypto deposits
        for crypto, amount in user_crypto_deposits[user_id].items():
            usd_value = convert_crypto_to_usd(crypto, amount)
            total_crypto_deposited_usd += usd_value
            crypto_distribution[crypto] = usd_value

        if total_crypto_deposited_usd > 0:
            # Distribute the win amount across cryptocurrencies proportionally
            for crypto, usd_value in crypto_distribution.items():
                proportion = usd_value / total_crypto_deposited_usd
                crypto_win_amount = win_amount * proportion
                crypto_amount = convert_usd_to_crypto(crypto, crypto_win_amount)

                # Deduct from crypto house balance (house pays out real crypto)
                deduct_crypto_house_balance(crypto, crypto_amount)

def handle_crypto_game_loss(user_id: str, bet_amount: float):
    """Handle crypto house balance when user loses a game."""
    user_id = str(user_id)

    # Determine which crypto to add based on user's deposit history
    if user_id in user_crypto_deposits:
        total_crypto_deposited_usd = 0
        crypto_distribution = {}

        # Calculate distribution of user's crypto deposits
        for crypto, amount in user_crypto_deposits[user_id].items():
            usd_value = convert_crypto_to_usd(crypto, amount)
            total_crypto_deposited_usd += usd_value
            crypto_distribution[crypto] = usd_value

        if total_crypto_deposited_usd > 0:
            # Distribute the loss amount across cryptocurrencies proportionally
            for crypto, usd_value in crypto_distribution.items():
                proportion = usd_value / total_crypto_deposited_usd
                crypto_loss_amount = bet_amount * proportion
                crypto_amount = convert_usd_to_crypto(crypto, crypto_loss_amount)

                # Add to crypto house balance (house profits from real crypto)
                add_crypto_house_balance(crypto, crypto_amount)

# ============== CRYPTO SYSTEM IMPLEMENTATION ==============

class CryptoPaymentAPI:
    """Cryptomus API wrapper for cryptocurrency operations."""

    def __init__(self):
        self.api_url = "https://api.cryptomus.com/v1"
        self.payment_headers = {
            "merchant": os.getenv("CRYPTOMUS_MERCHANT_ID", ""),
            "sign": "",  # Will be calculated for each request
            "Content-Type": "application/json"
        }
        self.payout_headers = {
            "merchant": os.getenv("CRYPTOMUS_MERCHANT_ID", ""),
            "sign": "",  # Will be calculated for each request  
            "Content-Type": "application/json"
        }

    def _generate_sign(self, data, api_key):
        """Generate signature for Cryptomus API."""
        import base64
        import json
        data_string = base64.b64encode(json.dumps(data, separators=(',', ':')).encode()).decode()
        signature = hmac.new(api_key.encode(), data_string.encode(), hashlib.md5).hexdigest()
        return signature

    def get_available_currencies(self):
        """Get list of available currencies."""
        try:
            response = requests.get(f"{self.api_url}/currencies", headers=self.payment_headers)
            if response.status_code == 200:
                return response.json().get("currencies", [])
            return []
        except Exception as e:
            logger.error(f"Error getting currencies: {e}")
            return []

    def create_payment(self, amount, currency, order_id):
        """Create a new payment invoice."""
        # Check if payment API key is available
        api_key = os.getenv("CRYPTOMUS_PAYMENT_API_KEY")
        if not api_key:
            logger.warning("Payment API key not provided - deposits disabled")
            return {"error": "PAYMENT_KEY_MISSING", "message": "Crypto deposits coming soon! Payment API key not configured yet."}

        try:
            data = {
                "amount": str(amount),
                "currency": currency.upper(),
                "order_id": order_id,
                "url_return": "https://your-site.com/success",
                "url_callback": "https://your-site.com/callback",
                "is_subtract": 1,
                "lifetime": 3600,  # 1 hour validity
                "to_currency": currency.upper()
            }

            # Generate signature
            sign = self._generate_sign(data, api_key)
            headers = self.payment_headers.copy()
            headers["sign"] = sign

            response = requests.post(f"{self.api_url}/payment", headers=headers, json=data)

            if response.status_code == 200:
                result = response.json()
                if result.get("state") == 0:  # Success
                    return result.get("result")

            logger.error(f"Payment creation error: {response.status_code} - {response.text}")
            return None
        except Exception as e:
            logger.error(f"Error creating payment: {e}")
            return None

    def get_payment_status(self, uuid):
        """Get payment status by UUID."""
        try:
            api_key = os.getenv("CRYPTOMUS_PAYMENT_API_KEY", "")
            data = {"uuid": uuid}
            sign = self._generate_sign(data, api_key)
            headers = self.payment_headers.copy()
            headers["sign"] = sign

            response = requests.post(f"{self.api_url}/payment/info", headers=headers, json=data)
            if response.status_code == 200:
                result = response.json()
                if result.get("state") == 0:
                    return result.get("result")
            return None
        except Exception as e:
            logger.error(f"Error getting payment status: {e}")
            return None

    def create_payout(self, address, amount, currency, order_id):
        """Create cryptocurrency payout/withdrawal."""
        # Check if payout API key is available
        if not CRYPTOMUS_PAYOUT_API_KEY:
            logger.error("Payout API key not provided - withdrawals disabled")
            return {"error": "PAYOUT_KEY_MISSING", "message": "Crypto withdrawals unavailable! Payout API key not configured."}

        try:
            data = {
                "amount": str(amount),
                "currency": currency.upper(),
                "order_id": order_id,
                "address": address,
                "is_subtract": 1
            }

            sign = self._generate_sign(data, CRYPTOMUS_PAYOUT_API_KEY)
            headers = self.payout_headers.copy()
            headers["sign"] = sign

            response = requests.post(f"{self.api_url}/payout", headers=headers, json=data)

            if response.status_code == 200:
                result = response.json()
                if result.get("state") == 0:
                    return result.get("result")

            logger.error(f"Payout creation error: {response.status_code} - {response.text}")
            return None
        except Exception as e:
            logger.error(f"Error creating payout: {e}")
            return None

    def get_estimate(self, amount, currency_from, currency_to):
        """Get estimated conversion between currencies."""
        try:
            params = {
                "amount": amount,
                "currency_from": currency_from,
                "currency_to": currency_to
            }
            response = requests.get(f"{self.api_url}/estimate", headers=self.payment_headers, params=params)

            if response.status_code == 200:
                return response.json()
            return None
        except Exception as e:
            logger.error(f"Error getting estimate: {e}")
            return None

# Initialize crypto payment API
crypto_api = CryptoPaymentAPI()

def verify_crypto_transaction(address: str, currency: str, expected_amount: float) -> dict:
    """
    SECURITY: Auto-verification disabled.

    The previous implementation was a mock that returned "verified" 95% of the time
    without checking the blockchain — a critical exploit allowing free deposits.

    Real on-chain verification differs per coin/network and is not implemented here.
    Deposits must now be either:
      1. Confirmed by NOWPayments via the IPN webhook (/nowpayments_callback) — real,
         signed callback from the payment processor. This path is already secure.
      2. Manually approved by an owner/admin via the deposit approval handlers.

    Returning verified=False here ensures the auto-checker never auto-credits
    a manual deposit — the admin must explicitly approve it.
    """
    return {"verified": False}

async def check_pending_deposits():
    """Check for pending crypto deposits and verify them."""
    try:
        current_time = time.time()
        deposits_to_process = []

        # Check all pending deposits
        for deposit_id, deposit_data in list(pending_crypto_deposits.items()):
            address = deposit_data.get("address")
            currency = deposit_data.get("currency")
            expected_amount = deposit_data.get("expected_amount")
            user_id = deposit_data.get("user_id")

            if not all([address, currency, expected_amount, user_id]):
                continue

            # Check if deposit has expired (24 hours)
            if current_time - deposit_data.get("created_at", 0) > 86400:
                del pending_crypto_deposits[deposit_id]
                logger.info(f"🔥 Deposit {deposit_id} expired after 24 hours")
                continue

            # Verify transaction
            verification = verify_crypto_transaction(address, currency, expected_amount)

            if verification.get("verified"):
                # Process the deposit
                logger.info(f"✅ VERIFIED DEPOSIT: {deposit_id} | User: {user_id} | Amount: {expected_amount} {currency}")
                deposits_to_process.append({
                    "deposit_id": deposit_id,
                    "user_id": user_id,
                    "currency": currency,
                    "amount": verification.get("amount_received", expected_amount),
                    "transaction_id": verification.get("transaction_id"),
                    "verification": verification
                })

        # Process verified deposits
        for deposit in deposits_to_process:
            await process_crypto_deposit(deposit)

    except Exception as e:
        logger.error(f"Error checking pending deposits: {e}")

async def process_crypto_deposit(deposit_data: dict):
    """Process a verified crypto deposit — routes through _process_confirmed_deposit
    so ALL side-effects (history, wagering, rain eligibility, notification) are applied."""
    try:
        user_id = str(deposit_data["user_id"])
        currency = deposit_data["currency"]
        crypto_amount = deposit_data["amount"]
        transaction_id = str(deposit_data.get("transaction_id", ""))

        usd_value = convert_crypto_to_usd(currency, crypto_amount)
        if usd_value <= 0:
            logger.error(f"[process_crypto_deposit] zero usd_value for {currency} {crypto_amount}")
            return

        fee = round(usd_value * DEPOSIT_FEE_RATE, 2)
        credited = round(usd_value - fee, 2)

        # Dedup — skip if already processed
        if transaction_id and transaction_id in processed_payment_ids:
            logger.info(f"[process_crypto_deposit] tx {transaction_id} already processed — skipping")
            return

        # Remove from pending before crediting
        deposit_id = deposit_data.get("deposit_id", "")
        if deposit_id and deposit_id in pending_crypto_deposits:
            del pending_crypto_deposits[deposit_id]

        # Delegate to the single authoritative deposit handler.
        # Run in a thread — _process_confirmed_deposit makes blocking HTTP calls
        # (Telegram DM, notification) and must not stall the event loop.
        ok = await asyncio.to_thread(
            _process_confirmed_deposit,
            user_id=user_id,
            usd_amount=usd_value,
            credited_amount=credited,
            fee_amount=fee,
            pay_currency=currency.upper(),
            payment_id=transaction_id,
            source='blockchain_verify',
            coin_amount=float(crypto_amount),
        )
        if ok:
            logger.info(f"[process_crypto_deposit] ✅ user={user_id} {crypto_amount} {currency} = ${usd_value:.2f} tx={transaction_id}")
        else:
            logger.error(f"[process_crypto_deposit] ❌ _process_confirmed_deposit returned False for user={user_id} tx={transaction_id}")

        # Notify owner
        try:
            from telegram import Bot
            bot = Bot(token=BOT_TOKEN)
            await bot.send_message(
                chat_id=int(OWNER_ID),
                text=f"✅ <b>AUTO DEPOSIT PROCESSED</b>\n\n"
                     f"User: {user_id}\n"
                     f"Amount: ${usd_value:.2f} ({crypto_amount} {currency})\n"
                     f"TX: `{transaction_id}`\n"
                     f"New User Balance: ${get_user_balance(user_id):.2f}",
                parse_mode=ParseMode.HTML
            )
        except Exception as notify_error:
            logger.error(f"Error notifying owner: {notify_error}")

        # Notify user (this would be called from the main bot loop)
        return {
            "success": True,
            "user_id": user_id,
            "currency": currency,
            "crypto_amount": crypto_amount,
            "usd_value": usd_value,
            "transaction_id": transaction_id
        }

    except Exception as e:
        logger.error(f"Error processing crypto deposit: {e}")
        return {"success": False, "error": str(e)}

def create_crypto_withdrawal(user_id: str, currency: str, amount_usd: float, withdrawal_address: str) -> dict:
    """Create a cryptocurrency withdrawal."""
    try:
        # Check if user can withdraw
        can_withdraw_check, message = can_withdraw(user_id, amount_usd)
        if not can_withdraw_check:
            return {"success": False, "error": message}

        # Convert USD to crypto
        crypto_amount = convert_usd_to_crypto(currency, amount_usd)

        # Check if house has enough crypto
        if get_crypto_house_balance(currency) < crypto_amount:
            return {"success": False, "error": f"Insufficient {currency} in house balance"}

        # Create withdrawal order
        withdrawal_order = {
            "address": withdrawal_address,
            "currency": currency.lower(),
            "amount": crypto_amount,
            "order_id": f"withdrawal_{user_id}_{int(time.time())}"
        }

        # In production, create actual payout via NOWPayments
        if USE_SANDBOX:
            # Simulate successful withdrawal
            payout_result = {
                "id": f"payout_{secrets.token_hex(8)}",
                "withdrawals": [
                    {
                        "id": f"withdrawal_{secrets.token_hex(8)}",
                        "address": withdrawal_address,
                        "amount": crypto_amount,
                        "currency": currency.lower(),
                        "status": "confirmed",
                        "hash": f"0x{secrets.token_hex(32)}"
                    }
                ]
            }
        else:
            # Create actual payout
            payout_result = crypto_api.create_payout(
                withdrawal_address, 
                crypto_amount, 
                currency.upper(), 
                withdrawal_order["order_id"]
            )

        if payout_result and "id" in payout_result:
            # Deduct from user balance and house balance
            deduct_user_balance(user_id, amount_usd)
            deduct_crypto_house_balance(currency, crypto_amount)

            withdrawal_info = payout_result["withdrawals"][0] if "withdrawals" in payout_result else {}

            save_data_critical()

            return {
                "success": True,
                "payout_id": payout_result["id"],
                "withdrawal_id": withdrawal_info.get("id"),
                "transaction_hash": withdrawal_info.get("hash"),
                "amount_crypto": crypto_amount,
                "amount_usd": amount_usd,
                "currency": currency,
                "address": withdrawal_address
            }
        else:
            return {"success": False, "error": "Failed to create withdrawal"}

    except Exception as e:
        logger.error(f"Error creating crypto withdrawal: {e}")
        return {"success": False, "error": str(e)}

# Helper functions for new features
def track_wagering(user_id: str, amount: float, multiplier: float = 2.0):
    """Track total wagering for user and reduce wagering requirements.
    Only counts towards wagering requirement if multiplier >= 1.86."""
    global _active_race, _race_wagering, _race_usernames, user_raffle_wagering
    if _uses_coin_wallet_context():
        # Casino coins are promotional play credits, not cash wagering.
        return
    user_id = str(user_id)
    if user_id not in user_wagering_totals:
        user_wagering_totals[user_id] = 0.0
    user_wagering_totals[user_id] += amount

    # ── Race wagering tracking ────────────────────────────────────────────────
    if _active_race:
        race_end = _active_race.get('end_time', 0)
        if race_end == 0 or time.time() < race_end:
            _race_wagering[user_id] = _race_wagering.get(user_id, 0.0) + amount
            profile = user_profiles.get(user_id, {})
            _race_usernames[user_id] = (
                profile.get('username') or profile.get('first_name') or f"Player_{user_id[-4:]}"
            )

    # ── Raffle wagering tracking (resets per raffle period) ───────────────────
    user_raffle_wagering[user_id] = user_raffle_wagering.get(user_id, 0.0) + amount

    # Update bonus code wagering progress
    sync_check_bonus_wager(user_id, amount)

    # Reduce wagering requirements ($15 minimum wager rule) - only if multiplier >= 1.86
    # FIXED: Only reduce, NEVER increase requirements based on game outcomes
    # Wager requirement only comes from deposits and tips
    if multiplier >= 1.86:
        if user_id in user_wagering_requirements:
            if user_wagering_requirements[user_id] > 0:
                reduction = min(amount, user_wagering_requirements[user_id])
                user_wagering_requirements[user_id] -= reduction
                logger.info(f"📉 Wager reduced for {user_id} by {reduction}. Remaining: {user_wagering_requirements[user_id]}")
                # Sync player_data so withdrawal checks (which read player_data directly) stay consistent
                if user_id in player_data:
                    player_data[user_id]['wager_requirement'] = round(user_wagering_requirements[user_id], 2)

    # Calculate raffle tickets — based on wagering DURING the current raffle period only
    if _active_raffle:
        raffle_wager_start = _raffle_start_wager.get(user_id, 0.0)
        raffle_period_wagered = user_raffle_wagering.get(user_id, 0.0) - raffle_wager_start
        tickets_earned = int(max(0, raffle_period_wagered) / RAFFLE_TICKET_THRESHOLD)
        if user_id not in user_raffle_tickets:
            user_raffle_tickets[user_id] = 0
        user_raffle_tickets[user_id] = tickets_earned

    # Add to weekly rewards (0.1% of wagering amount)
    weekly_reward = amount * WEEKLY_REWARD_PERCENTAGE
    if user_id not in user_weekly_rewards:
        user_weekly_rewards[user_id] = 0.0
    user_weekly_rewards[user_id] += weekly_reward

    # ── Daily Streak tracking ──
    import datetime as _dt
    STREAK_WAGER_USD = 50.0  # $50 USDT daily wager threshold
    today_str = _dt.datetime.now().strftime('%Y-%m-%d')
    if user_id not in user_streak_data:
        user_streak_data[user_id] = {
            'streak': 0, 'last_checkin': '', 'today_wagered': 0.0, 'wager_date': today_str
        }
    sd = user_streak_data[user_id]
    # If new day: check for streak break, reset today counter
    if sd.get('wager_date') != today_str:
        yesterday = (_dt.datetime.now() - _dt.timedelta(days=1)).strftime('%Y-%m-%d')
        if sd.get('last_checkin') != yesterday and sd.get('last_checkin') != today_str:
            sd['streak'] = 0  # missed a day — streak breaks
        sd['today_wagered'] = 0.0
        sd['wager_date'] = today_str
    sd['today_wagered'] = sd.get('today_wagered', 0.0) + amount
    # Auto check-in when threshold crossed and not already checked in today
    if sd['today_wagered'] >= STREAK_WAGER_USD and sd.get('last_checkin') != today_str:
        sd['streak'] = sd.get('streak', 0) + 1
        if sd['streak'] > 7:
            sd['streak'] = 1  # restart cycle
        sd['last_checkin'] = today_str
        # Milestone rewards
        if sd['streak'] == 3:
            add_balance(user_id, 1.0)   # Day 3: $1 USDT
        if sd['streak'] == 7:
            add_balance(user_id, 3.0)  # Day 7: $3 USDT
            sd['streak'] = 0           # complete cycle, reset

    save_data()

def add_deposit_wagering_requirement(user_id: str, deposit_amount: float):
    """Add wagering requirement when user makes a deposit ($15 flat minimum wager).
    IMPORTANT: deposit_totals, deposit_history, and last_deposit_ts are ALL managed
    by _process_confirmed_deposit — this function ONLY touches wagering requirements."""
    user_id = str(user_id)
    # Flat $15 minimum wager requirement (not a multiplier) — only set once per user
    requirement = 15.0  # Must wager $15 total before withdrawal

    # Only apply the $15 requirement once — if user already has a requirement set
    # (from a prior deposit), do NOT stack/add another $15.  The $15 is a one-time
    # minimum wager gate, not a per-deposit multiplier.
    if user_wagering_requirements.get(user_id, 0.0) <= 0.0:
        user_wagering_requirements[user_id] = requirement

    # Sync player_data so withdrawal checks (which read player_data) stay consistent
    if user_id not in player_data:
        player_data[user_id] = {}
    # Only set once — do not accumulate per deposit
    if float(player_data[user_id].get('wager_requirement', 0.0)) <= 0.0:
        player_data[user_id]['wager_requirement'] = round(requirement, 2)
    # Caller always calls save_data_critical() — no need to save here.

def _process_confirmed_deposit(
    user_id: str,
    usd_amount: float,
    credited_amount: float,
    fee_amount: float,
    pay_currency: str,
    payment_id: str,
    source: str,
    coin_amount: float = 0.0,
    txid: str = "",
) -> bool:
    """Single authoritative function that applies ALL side-effects of a confirmed deposit.
    Call this from IPN handler, poll, secondary poll, and checkdeposit — never duplicate.
    Returns True on success."""
    user_id = str(user_id)
    try:
        # 0a. Internal dedup guard — prevents double-credit when IPN and poll
        #     race to call this function for the same payment simultaneously.
        #     Uses a SEPARATE in-flight set (not processed_payment_ids, which
        #     the IPN handler pre-populates before calling us).
        if payment_id:
            with _processed_payments_lock:
                if payment_id in _deposit_in_flight:
                    logger.info(f"[DEPOSIT] In-flight dedup: payment {payment_id} is already being processed — skipping")
                    return True
                _deposit_in_flight.add(payment_id)

        logger.info(f"[DEPOSIT] 🔄 Processing started: user={user_id} gross=${usd_amount:.2f} "
                    f"credited=${credited_amount:.2f} fee=${fee_amount:.2f} "
                    f"currency={pay_currency} source={source} payment_id={payment_id}")

        # 0b. Instantly send "Processing payment..." DM so user knows we received the tx
        try:
            _token = os.environ.get("TELEGRAM_BOT_TOKEN", "") or os.environ.get("BOT_TOKEN", "")
            if _token:
                # Normalise NowPayments codes (e.g. usdttrc20 → USDT) for display
                _NP_DISPLAY = {
                    "usdttrc20": "USDT", "usdterc20": "USDT", "usdtbsc": "USDT",
                    "usdtton": "USDT", "usdtsol": "USDT", "usdtmatic": "USDT",
                    "usdcerc20": "USDC", "usdcbsc": "USDC",
                    "bnbbsc": "BNB", "avaxc": "AVAX", "maticbsc": "MATIC",
                }
                _disp_cur = _NP_DISPLAY.get((pay_currency or "").lower(), (pay_currency or "").upper())
                _proc_text = (
                    "<tg-emoji emoji-id=\"5386367538735104399\">🔄</tg-emoji> "
                    "<b>Processing payment...</b>\n\n"
                    f"We've detected your <b>{_disp_cur}</b> transaction.\n"
                    "Waiting for blockchain confirmations — this usually takes <b>1–3 minutes</b>.\n\n"
                    "<i>Your balance will be credited automatically once confirmed.</i>"
                )
                requests.post(
                    f"https://api.telegram.org/bot{_token}/sendMessage",
                    json={"chat_id": user_id, "text": _proc_text, "parse_mode": "HTML"},
                    timeout=8,
                )
                logger.info(f"[DEPOSIT] ✉️ Processing message sent to user {user_id}")
        except Exception as _pm_err:
            logger.warning(f"[DEPOSIT] Processing message failed (non-fatal): {_pm_err}")

        # 1. Credit balance
        ultra_secure_add_user_balance(user_id, credited_amount, f"deposit_{pay_currency}")
        logger.info(f"[DEPOSIT] ✅ Balance credited ${credited_amount:.2f} to user {user_id}")

        # 1a. IMMEDIATELY persist payment_id to disk — this must happen as close as
        #     possible to the balance credit.  If the bot is killed between the credit
        #     above and save_data_critical() at step 11, balances_backup.json will
        #     have the credited balance but casino_data.json will not.  On restart the
        #     poll would find this payment still "unprocessed" and double-credit.
        #     Writing to processed_payments.json NOW (independent atomic file) closes
        #     that window: even a hard-kill cannot replay this payment.
        if payment_id:
            with _processed_payments_lock:
                processed_payment_ids.add(payment_id)
            _persist_payment_id(payment_id)
            logger.info(f"[DEPOSIT] 🔒 payment_id {payment_id} persisted to disk immediately after credit")

        # 1b. Apply active deposit-event bonuses (percentage, weekend, first-deposit)
        if _EVENTS_OK:
            try:
                _is_first_ev = not player_data.get(user_id, {}).get('deposited', False)
                _ev_uname    = (user_profiles.get(user_id) or {}).get('username', '')
                _ev_bonuses  = events.on_deposit(user_id, usd_amount, _is_first_ev, _ev_uname)
                if _ev_bonuses:
                    _ev_total = sum(b for b, _ in _ev_bonuses)
                    ultra_secure_add_user_balance(user_id, _ev_total, 'deposit_bonus_event')
                    _ev_lines = '\n'.join(f'  • {t}: +${b:.2f}' for b, t in _ev_bonuses)
                    _ev_dm    = (f'🎁 <b>Deposit Bonus Applied!</b>\n{_ev_lines}\n\n'
                                f'Bonus: <b>+${_ev_total:.2f}</b> credited!')
                    _tk_ev = os.environ.get('TELEGRAM_BOT_TOKEN','') or os.environ.get('BOT_TOKEN','')
                    if _tk_ev:
                        try:
                            requests.post(f'https://api.telegram.org/bot{_tk_ev}/sendMessage',
                                json={'chat_id': user_id, 'text': _ev_dm, 'parse_mode': 'HTML'}, timeout=8)
                        except Exception: pass
                    logger.info(f'[DEPOSIT] 🎁 Event bonuses +${_ev_total:.2f} to user {user_id}')
            except Exception as _ev_dep_err:
                logger.warning(f'[DEPOSIT] events.on_deposit error (non-fatal): {_ev_dep_err}')

        # 2. Track gross deposit total (what user actually sent)
        user_deposit_totals[user_id] = user_deposit_totals.get(user_id, 0.0) + usd_amount
        logger.info(f"[DEPOSIT] user_deposit_totals[{user_id}] = ${user_deposit_totals[user_id]:.2f}")

        # 3. Timestamped deposit history (for 30-day tip restriction check)
        if user_id not in user_deposit_history:
            user_deposit_history[user_id] = []
        user_deposit_history[user_id].append({
            'ts': time.time(), 'amount': usd_amount,
            'currency': pay_currency, 'source': source,
        })
        if len(user_deposit_history[user_id]) > 200:
            user_deposit_history[user_id] = user_deposit_history[user_id][-200:]

        # 4. Last deposit timestamp (for rain 24h eligibility)
        user_last_deposit_ts[user_id] = time.time()

        # 5. Mark player as deposited — clears tip-only and bonus restrictions
        if user_id not in player_data:
            player_data[user_id] = {}
        player_data[user_id]['deposited'] = True
        player_data[user_id]['total_deposited'] = round(
            float(player_data[user_id].get('total_deposited', 0.0)) + usd_amount, 2
        )
        # Clear tip-only flag — real depositors use normal wagering rules going forward
        if user_tip_received.pop(user_id, None):
            logger.info(f"[DEPOSIT] Cleared tip-received flag for {user_id} — now a real depositor")
        logger.info(f"[DEPOSIT] player_data[{user_id}]['deposited'] = True, "
                    f"total_deposited=${player_data[user_id]['total_deposited']:.2f}")

        # 6. House balance
        add_house_balance(usd_amount)

        # 7. Wagering requirement (ONLY wagering req — deposit_totals already updated above)
        add_deposit_wagering_requirement(user_id, credited_amount)

        # 8. payment_id already added to processed_payment_ids and persisted to disk
        #    at step 1a (immediately after balance credit).  This step only updates
        #    the nowpayments_pending_deposits status flag for tracking purposes.
        if payment_id and payment_id in nowpayments_pending_deposits:
            nowpayments_pending_deposits[payment_id]['status'] = 'credited'
            logger.info(f"[DEPOSIT] Marked nowpayments_pending_deposits[{payment_id}] = credited")

        # 9. Activate any pending bonus claim for this user
        bonus_activation_msg = None
        pending_claim = user_pending_bonus_claims.pop(user_id, None)
        if pending_claim:
            ba  = pending_claim['bonus_amount']
            wm  = pending_claim['wager_multiplier']
            wh  = pending_claim['wager_hours']
            wr  = ba * wm
            exp = time.time() + wh * 3600
            if user_id not in user_bonus_balances:
                user_bonus_balances[user_id] = 0.0
            user_bonus_balances[user_id] += ba
            user_bonus_wager_data[user_id] = {
                'code': pending_claim['code'],
                'bonus_amount': ba,
                'wager_required': wr,
                'wager_done': 0.0,
                'claimed_at': time.time(),
                'expires_at': exp,
            }
            bonus_activation_msg = (
                f"🎁 <b>Bonus Activated!</b>\n"
                f"${ba:.2f} added to your bonus balance.\n"
                f"Wager ${wr:.2f} within {wh:.0f}h to unlock it!"
            )
            logger.info(f"[DEPOSIT] Activated bonus ${ba:.2f} for user {user_id}")

        # 10. Belt-and-suspenders: ensure ALL deposit flags are consistent
        #     (_ensure_deposit_consistency is idempotent — safe to call after the above writes)
        _ensure_deposit_consistency(user_id)

        # 11. Atomic save — deposit credits MUST be persisted immediately
        save_data_critical()
        logger.info(f"[DEPOSIT] save_data_critical() done for user {user_id} payment {payment_id}")

        # 12. Send DM + group notification (sync HTTP — works from any thread)
        _tg_send_deposit_notification(
            user_id, credited_amount, pay_currency,
            bonus_msg=bonus_activation_msg,
            coin_amount=coin_amount,
            fee_amount=fee_amount,
            txid=txid,
        )
        logger.info(f"[DEPOSIT] Notification sent to user {user_id}")
        return True

    except Exception as e:
        logger.error(f"[DEPOSIT] _process_confirmed_deposit error user={user_id} "
                     f"payment={payment_id}: {e}", exc_info=True)
        return False

    finally:
        # Always release the in-flight slot so a retry can proceed
        if payment_id:
            _deposit_in_flight.discard(payment_id)


def add_wagering_requirement(user_id: str, amount: float):
    """Add to user's wagering requirement (both stores kept in sync)."""
    user_id = str(user_id)
    if user_id not in user_wagering_requirements:
        user_wagering_requirements[user_id] = 0.0
    user_wagering_requirements[user_id] += amount
    # Keep player_data in sync — withdrawal checks read from player_data directly
    if user_id not in player_data:
        player_data[user_id] = {}
    player_data[user_id]['wager_requirement'] = round(
        float(player_data[user_id].get('wager_requirement', 0.0)) + amount, 2
    )
    # Caller always saves — hot-path save removed to avoid races.

def get_wagering_requirement_remaining(user_id: str) -> float:
    """Get remaining wagering requirement for user."""
    user_id = str(user_id)
    return user_wagering_requirements.get(user_id, 0.0)

def can_withdraw(user_id: str, amount: float) -> tuple[bool, str]:
    """Check if user can withdraw the requested amount."""
    user_id = str(user_id)
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)
    remaining_requirement = get_wagering_requirement_remaining(user_id)

    # Check balance
    if balance < amount:
        return False, f"Insufficient balance! You have {format_balance_in_currency(balance, user_currency)}"

    # ── Tip withdrawal restriction ────────────────────────────────────────────
    # If user received a tip from a player with deposited balance:
    #   • No wagering requirement, minimum $0.01
    #   • Flag is NOT consumed here — only removed when user makes a real deposit
    #     or via admin panel. This prevents permanent loss if withdrawal fails.
    if user_tip_received.get(user_id):
        # If user has since made a real deposit, clear tip flag and use normal rules
        if player_data.get(user_id, {}).get('deposited'):
            user_tip_received.pop(user_id, None)
            logger.info(f"[CAN_WITHDRAW] {user_id} has real deposit — cleared tip flag, normal rules apply")
        else:
            if amount < 0.01:
                return False, "Minimum withdrawal is $0.01"
            logger.info(f"[CAN_WITHDRAW] tip recipient {user_id} — no wagering req, $0.01 min")
            return True, "Withdrawal allowed"
    # ─────────────────────────────────────────────────────────────────────────

    # Check minimum withdrawal ($5 for regular users)
    if amount < MIN_WITHDRAWAL:
        return False, f"Minimum withdrawal is {format_balance_in_currency(MIN_WITHDRAWAL, get_user_currency(user_id))}"

    # Check wagering requirement ($15 minimum wager rule)
    if remaining_requirement > 0:
        return False, f"You must wager {format_balance_in_currency(remaining_requirement, user_currency)} more before withdrawing (minimum $15 wager required)"

    logger.debug(f"[CAN_WITHDRAW] ✅ user={user_id} amount=${amount:.2f} — allowed")
    return True, "Withdrawal allowed"

def _ensure_deposit_consistency(user_id: str, usd_amount: float = 0.0) -> None:
    """Ensure all deposit-related flags are consistent for a user.

    Call this after any deposit credit to guarantee that EVERY feature gate
    (bonus codes, rain join, tip restriction, AI assistant) sees the deposit.

    Safe to call multiple times — all writes are idempotent.
    """
    uid = str(user_id)
    now = time.time()

    # 1. user_deposit_totals — authoritative gross deposit total
    if usd_amount > 0:
        user_deposit_totals[uid] = user_deposit_totals.get(uid, 0.0) + usd_amount

    dep_total = user_deposit_totals.get(uid, 0.0)
    if dep_total <= 0:
        return  # Nothing to fix for a user with no deposits at all

    # 2. player_data['deposited'] — used by AI assistant
    pd = player_data.setdefault(uid, {})
    pd['deposited'] = True
    if pd.get('total_deposited', 0.0) < dep_total:
        pd['total_deposited'] = dep_total

    # 3. user_last_deposit_ts — used by rain 24h eligibility check
    # Always refresh — ensures the timestamp reflects the most recent deposit
    user_last_deposit_ts[uid] = now

    # 4. user_deposit_history — used by 30-day tip restriction sum
    if not user_deposit_history.get(uid):
        user_deposit_history[uid] = [{
            'ts': now,
            'amount': dep_total,
            'currency': 'USDT',
            'source': 'consistency_repair',
        }]
        logger.info(f"[DEPOSIT_CONSISTENCY] synthetic history entry added for user {uid} "
                    f"(dep_total=${dep_total:.2f})")


def add_loss_to_rakeback(user_id: str, loss_amount: float):
    """Add loss amount to user's rakeback pool."""
    if _uses_coin_wallet_context():
        return
    user_id = str(user_id)
    rakeback_amount = loss_amount * RAKEBACK_PERCENTAGE
    if user_id not in user_losses_rakeback:
        user_losses_rakeback[user_id] = 0.0
    user_losses_rakeback[user_id] += rakeback_amount
    # Track losses for active cashback events
    if _EVENTS_OK:
        try: events.on_loss(user_id, loss_amount)
        except Exception: pass
    # No save_data() here — caller (game handler) always calls save_data_critical() after.
    # Calling it here creates extra background threads that race against the game's own save.

def add_match_history(user_id: str, game_type: str, bet_amount: float, result: str, winnings: float = 0.0, custom_id: str = None):
    """Add match to user's history and update permanent lifetime counters."""
    user_id = str(user_id)
    if user_id not in user_match_history:
        user_match_history[user_id] = []

    import time
    now_ts = int(time.time())
    match_data = {
        'timestamp': now_ts,
        'id': custom_id or str(int(time.time() * 1000))[-5:],
        'game': game_type,
        'bet': bet_amount,
        'result': result,  # 'win' or 'loss'
        'winnings': winnings,
        'profit': winnings - bet_amount if result == 'win' else -bet_amount
    }
    user_match_history[user_id].append(match_data)

    # Keep only last 200 matches in rolling history (was 50 — too few for proper casino records)
    if len(user_match_history[user_id]) > 200:
        user_match_history[user_id] = user_match_history[user_id][-200:]

    # ── Permanent lifetime counters (never trimmed) ───────────────────────
    if user_id not in user_profiles:
        user_profiles[user_id] = {}
    p = user_profiles[user_id]

    p['lt_games']  = p.get('lt_games', 0) + 1
    is_win = str(result).startswith('win')
    if is_win:
        p['lt_wins'] = p.get('lt_wins', 0) + 1
        p['lt_won']  = p.get('lt_won', 0.0) + float(winnings)
    else:
        p.setdefault('lt_wins', 0)
        p.setdefault('lt_won', 0.0)
    p['lt_wagered'] = p.get('lt_wagered', 0.0) + float(bet_amount)

    # Track first and last game timestamps
    if 'lt_first_game_ts' not in p or now_ts < p['lt_first_game_ts']:
        p['lt_first_game_ts'] = now_ts
    p['lt_last_game_ts'] = now_ts

    try:
        save_data_critical()
    except Exception as e:
        logger.error(f"add_match_history save_data error: {e}")


def get_next_level_requirement(user_id: str) -> float:
    """Get total wager threshold for the next rank."""
    user_id = str(user_id)
    current_level = get_user_level(user_id)
    if current_level >= len(CASINO_RANKS) - 1:
        return float(CASINO_RANKS[-1][2])
    return float(CASINO_RANKS[current_level + 1][2])

def get_current_level_base(user_id: str) -> float:
    """Get total wager threshold for the current rank."""
    user_id = str(user_id)
    current_level = get_user_level(user_id)
    return float(CASINO_RANKS[current_level][2])

def check_max_bet(amount: float) -> bool:
    """Check if bet amount exceeds maximum allowed."""
    return amount <= MAX_BET

def add_referral_commission(user_id: str, amount: float, commission_type: str = "wager") -> None:
    """Add referral commission to pending when a referred user deposits or wagers."""
    user_id = str(user_id)

    if user_id in referral_data:
        referrer_id = str(referral_data[user_id])

        # Determine commission rate based on type
        if commission_type == "deposit":
            commission = amount * REFERRAL_DEPOSIT_COMMISSION  # 8% on deposits
        else:
            commission = amount * REFERRAL_WAGER_COMMISSION  # 2% on wagers

        # Add to pending commissions instead of instant payout
        if referrer_id not in pending_referral_commissions:
            pending_referral_commissions[referrer_id] = 0.0
        pending_referral_commissions[referrer_id] += commission

        save_data()

