async def _load_custom_emoji_pack(bot) -> None:
    """Fetch every premium custom-emoji pack once at startup and merge them.
    Uses raw httpx to bypass PTB StickerSet de-serialisation issues
    (some Bot API fields changed in newer versions, breaking the PTB parser)."""
    global CUSTOM_EMOJI_MAP, CRYPTOCOINS_STICKERS, CRYPTOCOINS_DEFAULT_ID, _DC_MOJI_STICKERS, _DC_MOJI_BY_CODE, _PROGRESS_BAR_STICKERS
    merged: dict = {}
    import httpx as _hx
    for pack in CUSTOM_EMOJI_PACKS:
        try:
            async with _hx.AsyncClient(timeout=15) as _hc:
                _r = await _hc.get(
                    f"https://api.telegram.org/bot{bot.token}/getStickerSet",
                    params={"name": pack},
                )
            _data = _r.json()
            if not _data.get("ok"):
                raise RuntimeError(_data.get("description", "API error"))
            stickers_raw = _data["result"].get("stickers", [])
            added = 0
            for st in stickers_raw:
                ce_id = st.get("custom_emoji_id")
                alt   = st.get("emoji")
                if pack == "RollersProgressBar_by_CheakLeaksBot" and ce_id:
                    _PROGRESS_BAR_STICKERS.append(ce_id)
                if pack == "rollerscasino_by_rollersgamebot" and alt in _RC_MASCOT_EMOJI:
                    continue
                if ce_id and alt and alt not in merged:
                    merged[alt] = ce_id
                    added += 1
                if pack == "Cryptocoins_kotletovv" and ce_id:
                    CRYPTOCOINS_STICKERS.append(ce_id)
                    if not CRYPTOCOINS_DEFAULT_ID and alt == "🪙":
                        CRYPTOCOINS_DEFAULT_ID = ce_id
                if pack == "CasinoDCMoji_by_CheakLeaksBot" and ce_id:
                    _DC_MOJI_STICKERS.append((alt or "", ce_id))
            if pack == "CasinoDCMoji_by_CheakLeaksBot":
                # Log every sticker so we can build the emoji→coin mapping.
                for idx, (ch, cid) in enumerate(_DC_MOJI_STICKERS):
                    logger.info(f"[DCMoji] #{idx:02d}  emoji={repr(ch)}  id={cid}")
                # Auto-map known emoji characters to coin codes.
                for ch, cid in _DC_MOJI_STICKERS:
                    coin_code = _DC_EMOJI_CHAR_MAP.get(ch)
                    if coin_code and coin_code not in _DC_MOJI_BY_CODE:
                        _DC_MOJI_BY_CODE[coin_code] = cid
                logger.info(f"[DCMoji] Auto-mapped {len(_DC_MOJI_BY_CODE)} coins from pack: {list(_DC_MOJI_BY_CODE.keys())}")
            if pack == "bj_by_rollersgamebot":
                # Pack layout (verified from API):
                # #00-#08  → rank stickers: 2 3 4 5 6 7 8 9 10   (emoji: 2️⃣…🔟)
                # #09-#12  → suit stickers: ♠️ ♣️ ♥️ ♦️
                # #13-#16  → action stickers: 👍 👎 ❌ 🔄
                # #17      → hidden card sticker: 💳
                _bj_pack_rank_order = ['2','3','4','5','6','7','8','9','10']
                _bj_pack_suit_order = ['♠️','♣️','♥️','♦️']
                _bj_pack_ids = []
                for st in stickers_raw:
                    ce_id = st.get("custom_emoji_id")
                    if ce_id:
                        _bj_pack_ids.append(ce_id)
                for idx, cid in enumerate(_bj_pack_ids):
                    if idx < len(_bj_pack_rank_order):
                        label = _bj_pack_rank_order[idx]
                    elif idx < len(_bj_pack_rank_order) + len(_bj_pack_suit_order):
                        label = _bj_pack_suit_order[idx - len(_bj_pack_rank_order)]
                    else:
                        label = f"extra_{idx}"
                    logger.info(f"[BJ-Pack] #{idx:02d}  label={label}  id={cid}")
                # Rebuild _BJ_RANK_EMOJI — only ranks 2-10 have stickers in this pack.
                # J/Q/K/A have no rank sticker; they will render as bold text.
                for idx, cid in enumerate(_bj_pack_ids):
                    if idx < len(_bj_pack_rank_order):
                        _BJ_RANK_EMOJI[_bj_pack_rank_order[idx]] = cid
                # Remove any stale J/Q/K/A mappings (they were wrongly set before)
                for _face in ('J','Q','K','A'):
                    _BJ_RANK_EMOJI.pop(_face, None)
                logger.info(f"[BJ-Pack] Rebuilt _BJ_RANK_EMOJI with {min(len(_bj_pack_ids), len(_bj_pack_rank_order))} rank IDs (J/Q/K/A → bold text)")
                # Rebuild _BJ_SUIT_IDS from suit stickers (#09-#12)
                _suit_chars = ['♠','♣','♥','♦']
                for _si, _suit_char in enumerate(_suit_chars):
                    _suit_idx = len(_bj_pack_rank_order) + _si
                    if _suit_idx < len(_bj_pack_ids):
                        _BJ_SUIT_IDS[_suit_char] = _bj_pack_ids[_suit_idx]
                        logger.info(f"[BJ-Pack] Suit {_suit_char} → id={_bj_pack_ids[_suit_idx]}")
                # Hidden card sticker is #17 (last sticker)
                if len(_bj_pack_ids) >= 18:
                    global _BJ_HIDDEN_EMOJI_ID
                    _BJ_HIDDEN_EMOJI_ID = _bj_pack_ids[17]
                    logger.info(f"[BJ-Pack] Hidden card → id={_BJ_HIDDEN_EMOJI_ID}")
            logger.info(f"✅ Loaded {added} animated emoji from {pack}")
        except Exception as e:
            logger.warning(f"[premium-emoji] Could not load pack {pack}: {e}")
    CUSTOM_EMOJI_MAP = merged
    # Hard-pinned overrides — guarantee these win over whatever the auto-loader picked.
    # 🎲 dice is taken from the WelvurEmoji pack as requested.
    CUSTOM_EMOJI_MAP["🎲"] = "5972061723400605896"
    # 💰 money bag — used in CRYPTOCURRENCY DEPOSITS title and house-balance views.
