def _coin_sticker_id(coin_code: str) -> str:
    """Return the animated-coin custom_emoji_id for a given COINS code."""
    return CRYPTOCOINS_BY_CODE.get(coin_code) or CRYPTOCOINS_DEFAULT_ID


def _coin_network_display(coin_name: str) -> str:
    """Extract a pretty network name from a COINS["..."]["name"] like 'USDC (SOL)'."""
    if "(" in coin_name and coin_name.endswith(")"):
        net_code = coin_name.rsplit("(", 1)[1].rstrip(")").strip()
        return NETWORK_DISPLAY.get(net_code, net_code)
    return coin_name


def _deposit_qr_url(address: str) -> str:
    """Return a high-res QR code URL for the given address (used as send_photo source)."""
    import urllib.parse
    return f"https://api.qrserver.com/v1/create-qr-code/?size=512x512&margin=10&data={urllib.parse.quote(address)}"


def _get_deposit_coin_emoji_id(code: str) -> str:
    """Return the best coin-specific custom_emoji_id for a deposit screen title.
    Priority:
      1. DEPOSIT_COIN_EMOJI_ID (manually verified from CasinoDCMoji pack — always wins)
      2. CasinoDCMoji_by_CheakLeaksBot auto-mapper (fallback for any new coins)
      3. Cryptocoins_kotletovv animated coin logos
    """
    # Exact code match first (covers network variants like ERC20_USDT)
    eid = DEPOSIT_COIN_EMOJI_ID.get(code)
    if eid:
        return eid

    # Resolve base symbol for multi-network codes (e.g. BEP20_USDT → USDT)
    base = code
    for grp in ('USDT', 'USDC', 'DAI'):
        if grp in code:
            base = grp
            break
    else:
        if '_' in code:
            base = code.split('_')[-1]

    # 1) Verified static map (base symbol)
    eid = DEPOSIT_COIN_EMOJI_ID.get(base)
    if eid:
        return eid
    # 2) CasinoDCMoji auto-mapper fallback
    eid = _DC_MOJI_BY_CODE.get(base) or _DC_MOJI_BY_CODE.get(code)
    if eid:
        return eid
    # 3) Cryptocoins_kotletovv
    return CRYPTOCOINS_BY_CODE.get(code) or CRYPTOCOINS_BY_CODE.get(base, "")


def _build_deposit_caption(code: str, address: str, remaining_sec: int, username: str = ""):
    """
    Caption for the deposit QR photo.
    Uses the official per-coin emoji from CasinoDCMoji_by_CheakLeaksBot (or DEPOSIT_COIN_EMOJI_ID
    as fallback) on the title line; other lines use animated emoji from CUSTOM_EMOJI_MAP.
    NO QR URL in text — the photo itself is the QR.
    """
    coin = COINS[code]
    coin_name_full = coin['name']
    coin_short = coin_name_full.split(' (')[0] if ' (' in coin_name_full else coin_name_full
    network_display = _coin_network_display(coin_name_full)
    pay_currency = coin.get('pay_currency', '').lower()

    FEE_MAP = {
        'btc': '1%', 'ltc': '1%', 'doge': '1%', 'xmr': '1%',
        'eth': '0.5%', 'ethbase': '0.5%', 'etherc20': '0.5%',
        'sol': '0.5%', 'ton': '0.5%', 'trx': '0.5%',
        'bnb': '0.5%', 'bnbbsc': '0.5%',
    }
    network_fee = FEE_MAP.get(pay_currency, '0.5%')

    # Build the title with the coin-specific emoji (SOL logo, BTC logo, etc.)
    _coin_eid = _get_deposit_coin_emoji_id(code)
    if _coin_eid:
        # Use a coin-specific animated emoji — first char of coin_short as fallback glyph
        _fallback_char = coin_short[0] if coin_short else "🪙"
        title_line = f'<tg-emoji emoji-id="{_coin_eid}">{_fallback_char}</tg-emoji> <b>{coin_short} Deposit</b>'
    else:
        title_line = f"💎 <b>{coin_short} Deposit</b>"

    # 📥 address section, 🌟 network, ⌛ timer, 🔒 ownership
    parts = [
        title_line,
        "",
        "📥 Transfer the desired amount to this address:",
        "",
        f"<code>{address}</code>",
        "",
        f"🌟 <b>Network:</b> {network_display}",
        f"💳 <b>Network fee:</b> {network_fee}",
        "",
        f"⌛ <b>Expires in {format_remaining(remaining_sec)}</b>",
    ]
    if username:
        parts.append(f"🔒 <b>This address belongs to @{username}</b>")

    html_body = "\n".join(parts)
    # Return a 3-tuple: (plain_text, entities, raw_html)
    # raw_html is used for parse_mode=HTML sends (Telegram renders <tg-emoji> natively).
    # plain_text + entities are kept for any callers that still use caption_entities.
    plain_text, entities = _render_html_premium(html_body)
    return plain_text, entities, html_body


async def _run_deposit_countdown(context, chat_id: int, message_id: int,
                                  user_id: str, code: str, address: str,
                                  payment_id: str, expires_at: int, username: str = ""):
    """
    Background task: ticks once per minute, edits the deposit photo caption
    with the live countdown.  When the address expires, regenerates a fresh
    NOWPayments address, swaps the photo via edit_message_media, and resets
    the caption.
    message_id — the send_photo message (QR photo + caption + keyboard).
    """
    import asyncio
    from telegram import InputMediaPhoto
    last_minute_shown = -1
    if not username:
        username = user_profiles.get(user_id, {}).get('username', '')
    reply_markup = InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄", callback_data=f"refresh:{code}:{payment_id}")],
        [InlineKeyboardButton("⬅️ BACK", callback_data="back_to_deposit")]
    ])
    hard_deadline = int(time.time()) + 24 * 3600
    while int(time.time()) < hard_deadline:
        try:
            await asyncio.sleep(30)
        except asyncio.CancelledError:
            return
        now = int(time.time())
        remaining = expires_at - now
        if remaining > 0:
            cur_minute = remaining // 60
            if cur_minute == last_minute_shown:
                continue
            last_minute_shown = cur_minute
            try:
                new_plain, new_ents = _make_dep_caption(code, address, remaining, username)
                await context.bot.edit_message_caption(
                    chat_id=chat_id,
                    message_id=message_id,
                    caption=new_plain,
                    caption_entities=new_ents,
                    reply_markup=reply_markup,
                )
            except Exception as ex:
                msg = str(ex).lower()
                if 'not found' in msg or 'forbidden' in msg or 'message to edit' in msg:
                    return
                continue
        else:
            # Address expired — regenerate via NOWPayments
            try:
                coin = COINS[code]
                payment = create_nowpayments_payment(10, coin['pay_currency'], user_id=user_id)
                if not payment:
                    continue
                payment_id = str(payment['payment_id'])
                address = payment['pay_address']
                try:
                    save_deposit(payment_id, user_id, code, 10, address, int(time.time()))
                except Exception:
                    pass
                expires_at = int(time.time()) + EXP_SECONDS
                last_minute_shown = -1
                reply_markup = InlineKeyboardMarkup([
                    [InlineKeyboardButton("🔄", callback_data=f"refresh:{code}:{payment_id}")],
                    [InlineKeyboardButton("⬅️ BACK", callback_data="back_to_deposit")]
                ])
                new_qr_photo = make_qr_with_logo(address, coin.get('pay_currency', code).lower())
                new_plain, new_ents = _make_dep_caption(code, address, EXP_SECONDS, username)
                await context.bot.edit_message_media(
                    chat_id=chat_id,
                    message_id=message_id,
                    media=InputMediaPhoto(media=new_qr_photo),
                )
                await context.bot.edit_message_caption(
                    chat_id=chat_id,
                    message_id=message_id,
                    caption=new_plain,
                    caption_entities=new_ents if new_ents else None,
                    reply_markup=reply_markup,
                )
            except Exception as ex:
                msg = str(ex).lower()
                if 'not found' in msg or 'forbidden' in msg or 'message to edit' in msg:
                    return
                continue


def _prepend_coin_emoji(coin_code: str, html_text: str):
    """
    Render an HTML body via _render_html_premium, then prepend an animated
    coin sticker (CUSTOM_EMOJI entity) so the message starts with that coin's
    icon. Returns (text, entities) suitable for caption_entities/entities.
    """
    from telegram import MessageEntity

    body_text, body_entities = _render_html_premium(html_text)
    sid = _coin_sticker_id(coin_code)
    if not sid:
        return body_text, body_entities

    # 🪙 = 2 UTF-16 code units, plus a trailing space = total shift of 3.
    full_text = "🪙 " + body_text
    coin_ent = MessageEntity(
        type=MessageEntity.CUSTOM_EMOJI,
        offset=0,
        length=2,
        custom_emoji_id=sid,
    )
    shift = 3
    shifted = []
    for e in body_entities:
        kw = {}
        for f in ("url", "language", "custom_emoji_id", "user"):
            v = getattr(e, f, None)
            if v is not None:
                kw[f] = v
        shifted.append(MessageEntity(
            type=e.type,
            offset=e.offset + shift,
            length=e.length,
            **kw,
        ))
    return full_text, [coin_ent] + shifted


def _render_premium(template: str):
    """
    Walk through `template`, build UTF-16 offsets, and emit a custom_emoji
    entity for any character whose unicode emoji is in the pack.
    Returns (text, list[MessageEntity]).
    """
    entities = []
    if not template:
        return template, entities
    utf16_offset = 0
    for ch in template:
        ce_id = CUSTOM_EMOJI_MAP.get(ch) if CUSTOM_EMOJI_MAP else None
        ch_utf16 = len(ch.encode("utf-16-le")) // 2
        if ce_id:
            entities.append(MessageEntity(
                type=MessageEntity.CUSTOM_EMOJI,
                offset=utf16_offset,
                length=ch_utf16,
                custom_emoji_id=ce_id,
            ))
        utf16_offset += ch_utf16
    return template, entities


def _utf16_index(text: str, needle: str) -> int:
    """Return the UTF-16 offset of `needle` inside `text` (-1 if not found)."""
    idx = text.find(needle)
    if idx < 0:
        return -1
    return len(text[:idx].encode("utf-16-le")) // 2


_TG_HTML_TAG_RE = __import__("re").compile(
    r"<(/?)\s*([a-zA-Z][a-zA-Z0-9-]*)([^>]*)>"
)
_TG_HTML_HREF_RE = __import__("re").compile(
    r"""href\s*=\s*(?:"([^"]*)"|'([^']*)')"""
)
_TG_HTML_LANG_RE = __import__("re").compile(
    r"""(?:class|lang)\s*=\s*(?:"([^"]*)"|'([^']*)')"""
)
_TG_EMOJI_ID_RE = __import__("re").compile(
    r"""emoji-id\s*=\s*(?:"([^"]*)"|'([^']*)'|(\d+))"""
)
_TG_HTML_ENTITY_RE = __import__("re").compile(
    r"&(amp|lt|gt|quot|#39|nbsp);"
)
_TG_HTML_ENTITY_MAP = {
    "amp": "&", "lt": "<", "gt": ">",
    "quot": '"', "#39": "'", "nbsp": "\u00a0",
}

_TG_HTML_TYPE_MAP = {
    "b": MessageEntity.BOLD,
    "strong": MessageEntity.BOLD,
    "i": MessageEntity.ITALIC,
    "em": MessageEntity.ITALIC,
    "u": MessageEntity.UNDERLINE,
    "ins": MessageEntity.UNDERLINE,
    "s": MessageEntity.STRIKETHROUGH,
    "strike": MessageEntity.STRIKETHROUGH,
    "del": MessageEntity.STRIKETHROUGH,
    "code": MessageEntity.CODE,
    "pre": MessageEntity.PRE,
    "tg-spoiler": MessageEntity.SPOILER,
    "span": MessageEntity.SPOILER,        # only when class="tg-spoiler"
    "a": MessageEntity.TEXT_LINK,
    "blockquote": getattr(MessageEntity, "BLOCKQUOTE", "blockquote"),
}


def _render_html_premium(html: str):
    """
    Parse a Telegram-style HTML message into (text, entities) and add an
    animated custom-emoji entity for every character that exists in
    CUSTOM_EMOJI_MAP. Supports the common Telegram HTML subset:
      <b>/<strong>, <i>/<em>, <u>/<ins>, <s>/<strike>/<del>,
      <code>, <pre>, <a href="...">, <span class="tg-spoiler">,
      <tg-spoiler>, <blockquote>, <tg-emoji emoji-id="...">,
      plus &amp;/&lt;/&gt;/&quot;/&#39;/&nbsp;.
    Unknown tags are dropped (their text content is preserved).
    <tg-emoji> tags are honoured: their emoji-id is used directly and the
    fallback text inside is NOT re-mapped through CUSTOM_EMOJI_MAP.
    """
    if html is None:
        return None, []
    out_chars: list[str] = []
    entities: list = []
    stacks: dict = {}      # tag_name -> list[(utf16_off, attr_value)]
    tg_emoji_stack: list = []   # list of (utf16_off, emoji_id) for <tg-emoji> tags
    utf16_off = 0
    i = 0
    n = len(html)

    while i < n:
        ch = html[i]

        # Recognised opening/closing tag?
        if ch == "<":
            m = _TG_HTML_TAG_RE.match(html, i)
            if m:
                closing = m.group(1) == "/"
                tag = m.group(2).lower()
                attrs = m.group(3) or ""

                # ── <tg-emoji emoji-id="..."> — rank / custom animated emoji ──
                if tag == "tg-emoji":
                    if not closing:
                        em_m = _TG_EMOJI_ID_RE.search(attrs)
                        em_id = (em_m.group(1) or em_m.group(2) or em_m.group(3)) if em_m else None
                        tg_emoji_stack.append((utf16_off, em_id))
                    else:
                        if tg_emoji_stack:
                            start, em_id = tg_emoji_stack.pop()
                            length = utf16_off - start
                            if length > 0 and em_id:
                                entities.append(MessageEntity(
                                    type=MessageEntity.CUSTOM_EMOJI,
                                    offset=start,
                                    length=length,
                                    custom_emoji_id=em_id,
                                ))
                    i = m.end()
                    continue

                if tag in _TG_HTML_TYPE_MAP:
                    if not closing:
                        # span only counts when it's a spoiler
                        if tag == "span" and "tg-spoiler" not in attrs:
                            i = m.end()
                            continue
                        attr_val = None
                        if tag == "a":
                            hm = _TG_HTML_HREF_RE.search(attrs)
                            if hm:
                                attr_val = hm.group(1) or hm.group(2)
                        elif tag == "pre":
                            lm = _TG_HTML_LANG_RE.search(attrs)
                            if lm:
                                attr_val = lm.group(1) or lm.group(2)
                        stacks.setdefault(tag, []).append((utf16_off, attr_val))
                    else:
                        st = stacks.get(tag)
                        if st:
                            start, attr_val = st.pop()
                            length = utf16_off - start
                            if length > 0:
                                kw = {}
                                if tag == "a" and attr_val:
                                    kw["url"] = attr_val
                                if tag == "pre" and attr_val:
                                    kw["language"] = attr_val
                                entities.append(MessageEntity(
                                    type=_TG_HTML_TYPE_MAP[tag],
                                    offset=start,
                                    length=length,
                                    **kw,
                                ))
                    i = m.end()
                    continue
                # unknown tag → drop the tag, keep nothing
                i = m.end()
                continue
            # not a tag we recognise — fall through and emit '<' literally

        # HTML entity?
        if ch == "&":
            em = _TG_HTML_ENTITY_RE.match(html, i)
            if em:
                d = _TG_HTML_ENTITY_MAP[em.group(1)]
                d_utf16 = len(d.encode("utf-16-le")) // 2
                # Don't re-map inside a <tg-emoji> tag
                ce_id = (CUSTOM_EMOJI_MAP.get(d) if CUSTOM_EMOJI_MAP else None) if not tg_emoji_stack else None
                if ce_id:
                    entities.append(MessageEntity(
                        type=MessageEntity.CUSTOM_EMOJI,
                        offset=utf16_off,
                        length=d_utf16,
                        custom_emoji_id=ce_id,
                    ))
                out_chars.append(d)
                utf16_off += d_utf16
                i = em.end()
                continue

        ch_utf16 = len(ch.encode("utf-16-le")) // 2
        # Don't re-map fallback chars that are inside a <tg-emoji> tag
        ce_id = (CUSTOM_EMOJI_MAP.get(ch) if CUSTOM_EMOJI_MAP else None) if not tg_emoji_stack else None
        if ce_id:
            entities.append(MessageEntity(
                type=MessageEntity.CUSTOM_EMOJI,
                offset=utf16_off,
                length=ch_utf16,
                custom_emoji_id=ce_id,
            ))
        out_chars.append(ch)
        utf16_off += ch_utf16
        i += 1

    return "".join(out_chars), entities


def _has_premium_emoji(text: str) -> bool:
    """Cheap pre-check: is it worth rewriting this message?

    Returns False for HTML messages that already contain explicit <tg-emoji>
    tags — those should be sent with parse_mode=HTML and let Telegram render
    the custom emoji natively, without the interceptor touching them.
    """
    if not text or not CUSTOM_EMOJI_MAP:
        return False
    if '<tg-emoji' in text:
        return False  # already has explicit custom-emoji tags; send as HTML
    return any(ch in CUSTOM_EMOJI_MAP for ch in text)


def _render_plain_premium(text: str):
    """Plain-text emoji-to-custom-emoji entity converter (no HTML parsing).

    Walks the string char-by-char and emits a CUSTOM_EMOJI MessageEntity for
    every character present in CUSTOM_EMOJI_MAP. Returns (text_unchanged, entities).
    Safe for messages that may contain literal '<' or '&' (e.g. usernames).
    """
    if not text or not CUSTOM_EMOJI_MAP:
        return text, []
    entities = []
    utf16_off = 0
    for ch in text:
        ch_utf16 = len(ch.encode("utf-16-le")) // 2
        ce_id = CUSTOM_EMOJI_MAP.get(ch)
        if ce_id:
            entities.append(MessageEntity(
                type=MessageEntity.CUSTOM_EMOJI,
                offset=utf16_off,
                length=ch_utf16,
                custom_emoji_id=ce_id,
            ))
        utf16_off += ch_utf16
    return text, entities


def _install_premium_emoji_interceptor(bot) -> None:
    """
    Wrap the bot's send/edit methods so any HTML message/caption that contains
    an emoji available in CUSTOM_EMOJI_MAP is auto-rewritten to use animated
    custom-emoji entities. Messages without any premium emoji pass through
    untouched, preserving existing behaviour.

    PTB's ExtBot/Bot use __slots__, so we patch the *class* (not the instance)
    and walk up the MRO so subclasses inherit the wrapper too.
    """
    import inspect
    import functools

    HTML_VALUES = {ParseMode.HTML, "HTML", "html"}
    MARKDOWN_VALUES = {ParseMode.MARKDOWN, ParseMode.MARKDOWN_V2, "Markdown", "MarkdownV2", "markdown"}
    _PATCH_FLAG = "_premium_emoji_wrapped_"

    def _is_unset(value) -> bool:
        """True for None, PTB's DEFAULT_NONE sentinel, or any DefaultValue wrapper."""
        if value is None:
            return True
        # PTB's DefaultValue type — checked structurally so we don't depend on its import path
        cls_name = type(value).__name__
        if cls_name in ("DefaultValue", "_DefaultValue"):
            return True
        return False

    def _patch_class(cls, method_name: str, text_kwarg: str, entities_kwarg: str):
        if cls is object:
            return False
        if method_name not in cls.__dict__:
            return False
        original = cls.__dict__[method_name]
        if getattr(original, _PATCH_FLAG, False):
            return True
        try:
            sig = inspect.signature(original)
        except (TypeError, ValueError):
            sig = None

        @functools.wraps(original)
        async def wrapper(self, *args, **kwargs):
            try:
                txt = kwargs.get(text_kwarg)
                # Also handle positional text arg (some internal PTB paths pass it positionally)
                _txt_positional_idx = None
                if txt is None and args:
                    for _pi, a in enumerate(args):
                        if isinstance(a, str) and len(a) > 0:
                            txt = a
                            _txt_positional_idx = _pi
                            break
                pm = kwargs.get("parse_mode")
                # Unwrap PTB DefaultValue sentinel if needed
                if hasattr(pm, 'value'):
                    pm = pm.value
                already_ents = kwargs.get(entities_kwarg)
                has_ents = bool(already_ents) and not _is_unset(already_ents)
                if (
                    not has_ents
                    and isinstance(txt, str)
                    and _has_premium_emoji(txt)
                ):
                    if pm in HTML_VALUES:
                        new_text, ents = _render_html_premium(txt)
                    elif pm in MARKDOWN_VALUES:
                        new_text, ents = txt, []  # don't touch markdown
                    else:
                        new_text, ents = _render_plain_premium(txt)
                    if ents:
                        # ── Save originals before mutating kwargs ──
                        _orig_text  = kwargs.get(text_kwarg)
                        _orig_ents  = kwargs.get(entities_kwarg)
                        _orig_pm    = kwargs.get("parse_mode")
                        if _txt_positional_idx is not None:
                            args = list(args)
                            args[_txt_positional_idx] = new_text
                            args = tuple(args)
                        else:
                            kwargs[text_kwarg] = new_text
                        kwargs[entities_kwarg] = ents
                        kwargs["parse_mode"] = None
                        logger.debug(f"[premium-emoji] animated {len(ents)} entities in {method_name}")
                        try:
                            return await original(self, *args, **kwargs)
                        except Exception as _send_e:
                            logger.warning(f"[premium-emoji] interceptor {method_name}: {_send_e}")
                            # Restore original kwargs so the fallback send works correctly
                            if _txt_positional_idx is not None:
                                args = list(args)
                                args[_txt_positional_idx] = txt
                                args = tuple(args)
                            else:
                                kwargs[text_kwarg] = _orig_text
                            if _orig_ents is None:
                                kwargs.pop(entities_kwarg, None)
                            else:
                                kwargs[entities_kwarg] = _orig_ents
                            kwargs["parse_mode"] = _orig_pm
                            # Seek any file-like objects (BytesIO photos) back to start
                            for _v in list(kwargs.values()):
                                if hasattr(_v, 'seek'):
                                    try: _v.seek(0)
                                    except Exception: pass
                            for _a in args:
                                if hasattr(_a, 'seek'):
                                    try: _a.seek(0)
                                    except Exception: pass
            except Exception as _e:
                logger.warning(f"[premium-emoji] interceptor {method_name}: {_e}")
            return await original(self, *args, **kwargs)

        setattr(wrapper, _PATCH_FLAG, True)
        try:
            setattr(cls, method_name, wrapper)
            return True
        except Exception as _e:
            logger.warning(f"[premium-emoji] could not patch {cls.__name__}.{method_name}: {_e}")
            return False

    method_specs = [
        ("send_message",         "text",    "entities"),
        ("edit_message_text",    "text",    "entities"),
        ("send_photo",           "caption", "caption_entities"),
        ("send_animation",       "caption", "caption_entities"),
        ("send_video",           "caption", "caption_entities"),
        ("send_document",        "caption", "caption_entities"),
        ("send_audio",           "caption", "caption_entities"),
        ("send_voice",           "caption", "caption_entities"),
        ("send_video_note",      "caption", "caption_entities"),
        ("send_media_group",     "caption", "caption_entities"),
        ("edit_message_caption", "caption", "caption_entities"),
        ("copy_message",         "caption", "caption_entities"),
    ]

    patched = 0
    for mname, tkw, ekw in method_specs:
        # Patch every class in the MRO that defines the method (typically
        # both ExtBot and its Bot base class).
        for cls in type(bot).__mro__:
            if _patch_class(cls, mname, tkw, ekw):
                patched += 1
    logger.info(f"✅ Premium emoji interceptor installed ({patched} method patches)")


def _install_ownership_tracker(bot) -> None:
    """
    Wrap bot send methods so every message returned with an inline keyboard
    is auto-registered in _game_msg_owners under the user whose handler
    triggered the send (read from _handler_user_cv ContextVar).
    Must be called AFTER _install_premium_emoji_interceptor so we sit on top.
    """
    import functools
    _TRACK_FLAG = "_ownership_tracked_"

    SEND_METHODS = [
        "send_message", "send_photo", "send_animation", "send_video",
        "send_document", "send_audio", "send_voice", "send_sticker",
        "send_dice", "copy_message",
    ]

    def _patch(cls, method_name: str):
        if cls is object:
            return False
        if method_name not in cls.__dict__:
            return False
        original = cls.__dict__[method_name]
        if getattr(original, _TRACK_FLAG, False):
            return True

        @functools.wraps(original)
        async def wrapper(self, *args, **kwargs):
            result = await original(self, *args, **kwargs)
            try:
                uid = _handler_user_cv.get('')
                if uid and result and hasattr(result, 'message_id'):
                    # Only register messages that have an inline keyboard (clickable buttons)
                    if getattr(result, 'reply_markup', None) is not None:
                        _register_game_msg(result.message_id, uid)
            except Exception:
                pass
            return result

        setattr(wrapper, _TRACK_FLAG, True)
        try:
            setattr(cls, method_name, wrapper)
            return True
        except Exception:
            return False

    patched = 0
    for mname in SEND_METHODS:
        for cls in type(bot).__mro__:
            if _patch(cls, mname):
                patched += 1
                break
    logger.info(f"✅ Ownership tracker installed ({patched} method patches)")


def _build_game_menu_text():
    """Build the 'What games can I play?' list with animated custom emoji.

    Mirrors the requested layout: no buttons, just a clean text list where
    every leading emoji is an animated custom emoji and each /command is a
    clickable bot_command entity.
    """
    lines = [
        ("📢", "What games can I play?", None),
        ("🎲", "Dice", "/dice"),
        ("🎳", "Bowling", "/bowl"),
        ("🎯", "Darts", "/darts"),
        ("⚽", "Football", "/ball"),
        ("🏀", "Basketball", "/bask"),
        ("🪙", "Coinflip", "/coin"),
        ("🎰", "Slot machine", "/slots"),
        ("🎡", "Roulette", "/roulette"),
        ("🃏", "Blackjack", "/blackjack"),
        ("💣", "Mines", "/mines"),
        ("🐒", "Monkey Tower", "/tower"),
        ("🎡", "Wheel", "/wheel"),
        ("⚡", "Limbo", "/limbo"),
        ("🎯", "Plinko", "/plinko"),
        ("🎲", "Sic Bo", "/sicbo"),
        ("🕹", "Claw Machine", "/claw"),
        ("🏇", "Horse Race", "/horse"),
        ("🐸", "Crossy Road (Coming Soon)", None),
        ("🚌", "Coming Soon", None),
        ("🍀", "Enjoy the games!", None),
    ]

    parts: list[str] = []
    entities: list[MessageEntity] = []
    utf16_off = 0

    def _u16(s: str) -> int:
        return len(s.encode("utf-16-le")) // 2

    def _emit(s: str):
        nonlocal utf16_off
        parts.append(s)
        utf16_off += _u16(s)

    def _emit_emoji(ch: str):
        nonlocal utf16_off
        ce_id = CUSTOM_EMOJI_MAP.get(ch) if CUSTOM_EMOJI_MAP else None
        ln = _u16(ch)
        if ce_id:
            entities.append(MessageEntity(
                type=MessageEntity.CUSTOM_EMOJI,
                offset=utf16_off,
                length=ln,
                custom_emoji_id=ce_id,
            ))
        parts.append(ch)
        utf16_off += ln

    def _emit_bold(s: str):
        nonlocal utf16_off
        start = utf16_off
        parts.append(s)
        utf16_off += _u16(s)
        entities.append(MessageEntity(
            type=MessageEntity.BOLD,
            offset=start,
            length=utf16_off - start,
        ))

    def _emit_cmd(cmd: str):
        nonlocal utf16_off
        start = utf16_off
        parts.append(cmd)
        utf16_off += _u16(cmd)
        entities.append(MessageEntity(
            type=MessageEntity.BOT_COMMAND,
            offset=start,
            length=utf16_off - start,
        ))

    for idx, (emoji, label, cmd) in enumerate(lines):
        is_header = (idx == 0)
        is_footer = (idx == len(lines) - 1)
        if not is_header and not is_footer:
            _emit("• ")
        if emoji:
            _emit_emoji(emoji)
            _emit(" ")
        if is_header or is_footer:
            _emit_bold(label)
        else:
            _emit(label)
        if cmd:
            _emit(" - ")
            _emit_cmd(cmd)
        if not is_footer:
            _emit("\n")
        if is_header:
            _emit("\n")

    return "".join(parts), entities


