TRANSFER_CODE_TTL_SECONDS = 15 * 60  # 15 minutes
_transfer_claim_lock = threading.Lock()

def _generate_transfer_code() -> str:
    """Generate a short unique one-time transfer claim code."""
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # no 0/O/1/I ambiguity
    while True:
        code = "".join(secrets.choice(alphabet) for _ in range(8))
        if code not in user_transfer_codes:
            return code

def _prune_expired_transfer_codes() -> None:
    now = time.time()
    expired = [c for c, v in user_transfer_codes.items() if v.get('expires_ts', 0) < now]
    for c in expired:
        user_transfer_codes.pop(c, None)

async def transfer_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /transfer — generate a one-time code to move this whole account to another Telegram account."""
    if not update.message or not update.message.from_user:
        return
    await _send_transfer_code(update.message, context, str(update.message.from_user.id))

async def _send_transfer_code(message_or_query, context: ContextTypes.DEFAULT_TYPE, user_id: str) -> None:
    _prune_expired_transfer_codes()

    # Invalidate any previous unclaimed code from this user before issuing a new one
    for c in [c for c, v in user_transfer_codes.items() if v.get('source_uid') == user_id]:
        user_transfer_codes.pop(c, None)

    code = _generate_transfer_code()
    now = time.time()
    user_transfer_codes[code] = {
        'source_uid': user_id,
        'created_ts': now,
        'expires_ts': now + TRANSFER_CODE_TTL_SECONDS,
    }
    save_data_critical()

    text = (
        "💸 <b>Account Transfer</b>\n\n"
        f"Your one-time transfer code:\n<code>{code}</code>\n\n"
        "Give this code to the Telegram account you want to move your <b>entire casino account</b> to "
        "(balance, rank, wagered total, match history, biggest win, favorite game).\n\n"
        f"They must run <code>/accepttransfer {code}</code> within <b>15 minutes</b>.\n\n"
        "⚠️ <b>Once claimed, your current account is wiped and cannot be used again.</b> "
        "This cannot be undone."
    )
    reply_fn = getattr(message_or_query, "reply_text", None)
    if reply_fn:
        await reply_fn(text, parse_mode=ParseMode.HTML)
    else:
        await context.bot.send_message(chat_id=message_or_query, text=text, parse_mode=ParseMode.HTML)

async def accepttransfer_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /accepttransfer <code> — claim a transferred account, moving everything over and wiping the source."""
    if not update.message or not update.message.from_user:
        return
    target_uid = str(update.message.from_user.id)

    if not context.args:
        await update.message.reply_text(
            "Usage: <code>/accepttransfer CODE</code>\n\nAsk the sender for their transfer code (from /transfer).",
            parse_mode=ParseMode.HTML,
        )
        return

    code = context.args[0].strip().upper()

    # Atomic claim: validate + consume the code under a lock so concurrent/duplicate
    # claim attempts on the same code can only succeed once.
    with _transfer_claim_lock:
        _prune_expired_transfer_codes()
        entry = user_transfer_codes.get(code)
        if not entry:
            await update.message.reply_text("❌ Invalid or expired transfer code.", parse_mode=ParseMode.HTML)
            return

        source_uid = entry['source_uid']
        if source_uid == target_uid:
            await update.message.reply_text("❌ You can't transfer an account to itself.", parse_mode=ParseMode.HTML)
            return

        # Reject if the target account already has activity — prevents silently
        # clobbering an existing player's balance/stats.
        target_has_activity = (
            get_user_balance(target_uid) > 0
            or user_match_history.get(target_uid)
            or max(user_wagering_totals.get(target_uid, 0.0), user_wagered_amount.get(target_uid, 0.0)) > 0
        )
        if target_has_activity:
            await update.message.reply_text(
                "❌ This account already has balance or game activity — it can't receive a transfer. "
                "Use a fresh account to claim a transfer.",
                parse_mode=ParseMode.HTML,
            )
            return

        # Consume the code immediately so a duplicate claim can never see it again.
        user_transfer_codes.pop(code, None)
        save_data_critical()

        # ── Move everything from source → target ──────────────────────────
        source_balance = get_user_balance(source_uid)
        user_balances[target_uid] = source_balance
        user_balances[source_uid] = 0.0

        user_wagering_totals[target_uid] = user_wagering_totals.get(source_uid, 0.0)
        user_wagered_amount[target_uid]  = user_wagered_amount.get(source_uid, 0.0)
        user_match_history[target_uid]   = user_match_history.get(source_uid, [])
        user_wagering_requirements[target_uid] = user_wagering_requirements.get(source_uid, 0.0)

        src_profile = user_profiles.get(source_uid, {})
        tgt_profile = user_profiles.setdefault(target_uid, {})
        for fld in ('lt_games', 'lt_wins', 'lt_won', 'lt_wagered', 'lt_first_game_ts', 'lt_last_game_ts'):
            if fld in src_profile:
                tgt_profile[fld] = src_profile[fld]

        # Wipe the source account so it can't be reused
        user_wagering_totals[source_uid] = 0.0
        user_wagered_amount[source_uid]  = 0.0
        user_match_history[source_uid]   = []
        user_wagering_requirements[source_uid] = 0.0
        for fld in ('lt_games', 'lt_wins', 'lt_won', 'lt_wagered', 'lt_first_game_ts', 'lt_last_game_ts'):
            src_profile.pop(fld, None)

        save_data_critical()

    target_currency = get_user_currency(target_uid)
    await update.message.reply_text(
        "✅ <b>Transfer complete!</b>\n\n"
        f"Balance: {format_balance_in_currency(user_balances[target_uid], target_currency)}\n"
        f"Rank, match history, and stats have been moved to this account.\n\n"
        "Use /profile to see it.",
        parse_mode=ParseMode.HTML,
    )

    try:
        await context.bot.send_message(
            chat_id=int(source_uid),
            text="💸 Your account transfer was claimed. Your old account has been reset to zero and can no longer be used.",
        )
    except Exception:
        pass

async def claim_code_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /claim command - Claim a bonus code with wagering requirement."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"

    if not context.args:
        await update.message.reply_text(
            "🎁 <b>CLAIM BONUS CODE</b>\n\n"
            "Usage: /claim [CODE]\n\n"
            "Example: /claim WELCOME100\n\n"
            "Bonus funds are added to your bonus balance and convert to real balance once you complete the wagering requirement within the allowed time.",
            parse_mode=ParseMode.HTML
        )
        return

    code = context.args[0].upper()

    if code not in bonus_codes:
        await update.message.reply_text("❌ Invalid bonus code! Check the code and try again.")
        return

    code_data = bonus_codes[code]

    if code_data.get('expires') and time.time() > code_data['expires']:
        await update.message.reply_text("❌ This code has expired!")
        return

    if code_data['uses'] >= code_data['max_uses']:
        await update.message.reply_text("❌ This code has reached its maximum number of claims!")
        return

    # Check if code is restricted to a specific user
    specific_user = code_data.get('specific_user')
    if specific_user and str(specific_user) != user_id:
        await update.message.reply_text("❌ This code is not available for your account.")
        return

    if user_id not in user_claimed_codes:
        user_claimed_codes[user_id] = []
    if code in user_claimed_codes[user_id]:
        await update.message.reply_text("❌ You have already claimed this code!")
        return

    min_deposit = code_data.get('min_deposit', 0)
    user_deposits = user_deposit_totals.get(user_id, 0)
    logger.info(f"[BONUS_GATE] user={user_id} code={code} "
                f"user_deposits=${user_deposits:.2f} min_deposit=${min_deposit:.2f} "
                f"player_deposited={player_data.get(user_id, {}).get('deposited')} "
                f"hist_entries={len(user_deposit_history.get(user_id, []))}")
    if user_deposits < min_deposit:
        await update.message.reply_text(
            f"❌ You need at least ${min_deposit:.2f} in total deposits to claim this code.\n"
            f"Your total deposits: ${user_deposits:.2f}\n\n"
            f"💡 Make a deposit first, then try again."
        )
        return

    # Check if user already has an active bonus they haven't completed
    if user_id in user_bonus_wager_data:
        existing = user_bonus_wager_data[user_id]
        if time.time() < existing.get('expires_at', 0):
            remaining = existing['wager_required'] - existing['wager_done']
            hrs_left = (existing['expires_at'] - time.time()) / 3600
            await update.message.reply_text(
                f"❌ You already have an active bonus!\n\n"
                f"🎁 Bonus: ${existing['bonus_amount']:.2f}\n"
                f"🎰 Wager remaining: ${remaining:.2f}\n"
                f"⏰ Time left: {hrs_left:.1f}h\n\n"
                f"Complete or let the current bonus expire before claiming another.",
                parse_mode=ParseMode.HTML
            )
            return

    # Store as pending — bonus activates on next deposit
    bonus_amount = float(code_data.get('reward') or code_data.get('amount', 0))
    wager_multiplier = float(code_data.get('wager_multiplier', 3.0))
    wager_hours = float(code_data.get('wager_hours', 24.0))
    wager_required = bonus_amount * wager_multiplier

    user_pending_bonus_claims[user_id] = {
        'code': code,
        'bonus_amount': bonus_amount,
        'wager_multiplier': wager_multiplier,
        'wager_hours': wager_hours,
    }

    # Mark code as used
    bonus_codes[code]['uses'] += 1
    user_claimed_codes[user_id].append(code)
    logger.info(f"[BONUS_CLAIM] user={user_id} code={code} bonus=${bonus_amount:.2f} "
                f"wager_req=${bonus_amount * wager_multiplier:.2f} wager_hours={wager_hours}")
    save_data_critical()

    hrs_display = f"{wager_hours:.0f}h" if wager_hours == int(wager_hours) else f"{wager_hours:.1f}h"
    await update.message.reply_text(
        f"🎟️ <b>BONUS CODE RESERVED!</b>\n\n"
        f"🎁 Bonus: <b>${bonus_amount:.2f}</b>\n"
        f"🎰 Wager Requirement: <b>${wager_required:.2f}</b> ({wager_multiplier:.0f}x)\n"
        f"⏰ Wager Time Limit: <b>{hrs_display}</b> (starts on deposit)\n\n"
        f"📥 <b>Make a deposit to activate your bonus!</b>\n"
        f"The ${bonus_amount:.2f} will be added to your bonus balance automatically when your deposit confirms.",
        parse_mode=ParseMode.HTML
    )

async def create_code_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /createcode command - Owner creates bonus codes.
    
    Usage: /createcode CODE AMOUNT MAX_USES WAGER_MULTIPLIER WAGER_HOURS [EXPIRY_HOURS] [MIN_DEPOSIT] [USER_ID]
    
    Examples:
      /createcode WELCOME50 50 100 3 24
        → Code WELCOME50, $50 bonus, 100 max claims, 3x wager (=$150), 24h to complete
      /createcode VIP200 200 1 2 48 72 100 123456789
        → $200 bonus, 1 use only, 2x wager, 48h to complete, code expires in 72h, min $100 deposit, only user 123456789
    """
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)

    if not is_owner_or_manager(user_id):
        await update.message.reply_text("❌ Only the owner can create bonus codes!")
        return

    if len(context.args) < 5:
        await update.message.reply_text(
            "🎁 <b>CREATE BONUS CODE</b>\n\n"
            "<b>Usage:</b>\n"
            "<code>/createcode CODE AMOUNT MAX_USES WAGER_MULT WAGER_HOURS [EXPIRY_HOURS] [MIN_DEP] [USER_ID]</code>\n\n"
            "<b>Parameters:</b>\n"
            "• <b>CODE</b> — The code players will type (e.g. WELCOME50)\n"
            "• <b>AMOUNT</b> — Bonus $ amount (e.g. 50)\n"
            "• <b>MAX_USES</b> — How many users can claim it (e.g. 100)\n"
            "• <b>WAGER_MULT</b> — Wagering multiplier (e.g. 3 = must wager 3x the bonus)\n"
            "• <b>WAGER_HOURS</b> — Hours player has to complete wagering (e.g. 24)\n"
            "• <b>EXPIRY_HOURS</b> (optional) — Hours until code itself expires (e.g. 72)\n"
            "• <b>MIN_DEP</b> (optional) — Min total deposit to claim (e.g. 100)\n"
            "• <b>USER_ID</b> (optional) — Restrict to one specific user ID\n\n"
            "<b>Examples:</b>\n"
            "<code>/createcode WELCOME50 50 100 3 24</code>\n"
            "→ $50 bonus, 100 claims, 3x wager ($150), 24h to wager\n\n"
            "<code>/createcode VIP200 200 1 2 48 72 0 987654321</code>\n"
            "→ $200 bonus for user 987654321 only, 2x wager, 48h, expires in 72h",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        code = context.args[0].upper()
        bonus_amount = float(context.args[1])
        max_uses = int(context.args[2])
        wager_multiplier = float(context.args[3])
        wager_hours = float(context.args[4])
        expiry_hours = float(context.args[5]) if len(context.args) > 5 else None
        min_deposit = float(context.args[6]) if len(context.args) > 6 else 0.0
        specific_user = str(context.args[7]) if len(context.args) > 7 and context.args[7] != '0' else None

        if code in bonus_codes:
            await update.message.reply_text(f"❌ Code <code>{code}</code> already exists! Use /deletecode {code} first.", parse_mode=ParseMode.HTML)
            return

        if bonus_amount <= 0 or max_uses <= 0 or wager_multiplier <= 0 or wager_hours <= 0:
            await update.message.reply_text("❌ Amount, max uses, wager multiplier, and wager hours must all be positive numbers.")
            return

        expires_ts = time.time() + expiry_hours * 3600 if expiry_hours else None
        wager_required = bonus_amount * wager_multiplier

        bonus_codes[code] = {
            'reward': bonus_amount,
            'max_uses': max_uses,
            'uses': 0,
            'expires': expires_ts,
            'min_deposit': min_deposit,
            'wager_multiplier': wager_multiplier,
            'wager_hours': wager_hours,
            'specific_user': specific_user,
            'created_by': user_id,
            'created_at': time.time()
        }
        save_data()

        expiry_display = f"{expiry_hours:.0f}h" if expiry_hours else "Never"
        specific_display = f"User {specific_user}" if specific_user else "All players"
        await update.message.reply_text(
            f"✅ <b>BONUS CODE CREATED!</b>\n\n"
            f"📝 Code: <code>{code}</code>\n"
            f"💰 Bonus Amount: <b>${bonus_amount:.2f}</b>\n"
            f"🎰 Wager Required: <b>${wager_required:.2f}</b> ({wager_multiplier:.1f}x)\n"
            f"⏰ Wager Time Limit: <b>{wager_hours:.0f}h</b>\n"
            f"📊 Max Claims: <b>{max_uses}</b>\n"
            f"🕐 Code Expires: <b>{expiry_display}</b>\n"
            f"🔒 Min Deposit: <b>${min_deposit:.2f}</b>\n"
            f"👤 Claimable by: <b>{specific_display}</b>\n\n"
            f"Share this code with players! They use /claim {code}",
            parse_mode=ParseMode.HTML
        )

    except ValueError:
        await update.message.reply_text("❌ Invalid values! Make sure to use numbers for all numeric fields.")

async def list_codes_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /codes command - Owner lists all bonus codes."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)

    if not is_owner_or_manager(user_id):
        await update.message.reply_text("❌ Only the owner can view bonus codes!")
        return

    if not bonus_codes:
        await update.message.reply_text("📝 No bonus codes created yet.\n\nUse /createcode to create one!")
        return

    codes_msg = "🎁 <b>BONUS CODES</b>\n\n"

    for code, data in bonus_codes.items():
        reward = data.get('reward') or data.get('amount', 0)
        wager_mult = data.get('wager_multiplier', 3.0)
        wager_hrs = data.get('wager_hours', 24.0)
        expires = data.get('expires')
        specific = data.get('specific_user')
        min_dep = data.get('min_deposit', 0)

        status = "✅ Active"
        if expires and time.time() > expires:
            status = "❌ Expired"
        elif data['uses'] >= data['max_uses']:
            status = "🔴 Maxed"

        expiry_str = "Never"
        if expires:
            hrs_left = (expires - time.time()) / 3600
            if hrs_left > 0:
                expiry_str = f"{hrs_left:.1f}h left"
            else:
                expiry_str = "Expired"

        codes_msg += (
            f"<b>{code}</b> — {status}\n"
            f"  💰 ${reward:.2f} | 🎰 {wager_mult}x wager | ⏰ {wager_hrs:.0f}h limit\n"
            f"  📊 {data['uses']}/{data['max_uses']} claims | Expires: {expiry_str}\n"
        )
        if min_dep:
            codes_msg += f"  🔒 Min deposit: ${min_dep:.2f}\n"
        if specific:
            codes_msg += f"  👤 For user: {specific}\n"
        codes_msg += "\n"

    codes_msg += "Use /deletecode [CODE] to remove a code."
    await update.message.reply_text(codes_msg, parse_mode=ParseMode.HTML)

async def delete_code_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /deletecode command - Owner deletes a bonus code."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)

    if not is_owner_or_manager(user_id):
        await update.message.reply_text("❌ Only the owner can delete bonus codes!")
        return

    if not context.args:
        await update.message.reply_text("Usage: /deletecode [CODE]")
        return

    code = context.args[0].upper()

    if code not in bonus_codes:
        await update.message.reply_text(f"❌ Code '{code}' doesn't exist!")
        return

    del bonus_codes[code]
    save_data()

    await update.message.reply_text(f"✅ Code '{code}' has been deleted!")


user_pending_bonus_msgs = {}  # {user_id: str}  — bonus notifications waiting to be sent
owner_bonus_wizard = {}  # {owner_id: {step: int, code, amount, max_uses, wager_mult, wager_hours, min_deposit, expiry_hours, specific_user}}
user_pending_bonus_claims = {}  # {user_id: {code, bonus_amount, wager_multiplier, wager_hours}} — waiting for a deposit to activate
user_last_group_chat = {}  # {user_id: last_group_chat_id} — used to ping deposit confirmations in the group too
CASINO_GROUP_CHAT_ID = int(os.getenv("CASINO_GROUP_ID", "-1004222734406"))  # Rollers Open — every deposit confirmation is also pinged here

def sync_check_bonus_wager(user_id: str, bet_amount: float) -> None:
    """
    Synchronous version called from track_wagering.
    Updates bonus wagering data and stores any notification in user_pending_bonus_msgs.
    The notification must be sent by the async caller after it calls track_wagering.
    """
    user_id = str(user_id)
    if user_id not in user_bonus_wager_data:
        return

    bdata = user_bonus_wager_data[user_id]
    now = time.time()
    expires_at = bdata.get('expires_at', 0)

    # Only expire if expires_at is a valid future timestamp that has now passed
    if expires_at and expires_at > 0 and now > expires_at:
        forfeited = user_bonus_balances.pop(user_id, 0.0)
        user_bonus_wager_data.pop(user_id, None)
        if forfeited > 0:
            user_pending_bonus_msgs[user_id] = (
                f"⏰ <b>Bonus Expired!</b>\n\n"
                f"Your bonus of <b>${forfeited:.2f}</b> was forfeited — wagering time limit passed.\n"
                f"Better luck next time!"
            )
        return

    bdata['wager_done'] = bdata.get('wager_done', 0.0) + bet_amount
    remaining = bdata['wager_required'] - bdata['wager_done']

    if remaining <= 0:
        bonus_amt = user_bonus_balances.pop(user_id, bdata['bonus_amount'])
        user_bonus_wager_data.pop(user_id, None)
        ultra_secure_add_user_balance(user_id, bonus_amt, "bonus_wagering_unlock")
        save_data_critical()
        user_pending_bonus_msgs[user_id] = (
            f"🎉 <b>Bonus Unlocked!</b>\n\n"
            f"Wagering requirement completed!\n"
            f"<b>${bonus_amt:.2f}</b> has been added to your real balance automatically!\n\n"
            f"💰 Use /bal to check your balance."
        )


async def flush_bonus_notification(user_id: str, context) -> None:
    """Send any pending bonus notification for a user, then clear it."""
    msg = user_pending_bonus_msgs.pop(str(user_id), None)
    if msg:
        try:
            await context.bot.send_message(
                chat_id=int(user_id),
                text=msg,
                parse_mode='HTML'
            )
        except Exception as e:
            logger.warning(f"flush_bonus_notification failed for {user_id}: {e}")


