def _build_balance_view(user_id: str) -> tuple[str, InlineKeyboardMarkup]:
    """Build the balance screen with a single coin-wallet toggle.

    The coin row is always visible, but only the selected wallet is marked
    active.  Tapping the same coin toggle again returns the player to cash.
    Keeping both values in the message prevents a wallet switch from ever
    looking like a deposit or withdrawal.
    """
    uid = str(user_id)
    _sync_balance_from_disk(uid)
    currency = get_user_currency(uid)
    real_balance = get_real_user_balance(uid)
    coin_balance = get_coin_balance(uid)
    selected = get_wallet_mode(uid)

    real_active = f"  {_wallet_arrow()}" if selected == "real" else ""
    coin_active = f"  {_wallet_arrow()}" if selected == "coins" else ""

    text = (
        f"{_wallet_emoji()} <b>Current balance:</b> {_format_real_balance(real_balance, currency)}{real_active}\n"
        f"{_coin_emoji()} <b>Coins:</b> {coin_balance:,}{coin_active}\n"
    )

    bonus_bal = float(user_bonus_balances.get(uid, 0.0) or 0.0)
    bwdata = user_bonus_wager_data.get(uid)
    if bonus_bal > 0 and bwdata:
        now = time.time()
        wager_done = bwdata.get('wager_done', 0.0)
        wager_req = bwdata.get('wager_required', 0.0)
        expires_at = bwdata.get('expires_at', 0)
        hrs_left = max(0.0, (expires_at - now) / 3600)
        text += (
            f"\n\n🎁 <b>Bonus:</b> {_format_real_balance(bonus_bal, currency)}"
            f" | 🎰 ${wager_done:.2f}/${wager_req:.2f} wagered | ⏰ {hrs_left:.1f}h left"
        )
    elif bonus_bal > 0:
        text += f"\n\n🎁 <b>Bonus:</b> {_format_real_balance(bonus_bal, currency)}"

    keyboard = [
        [
            success_btn(
                "Deposit",
                callback_data="crypto_deposits",
                icon_custom_emoji_id="6305554908753959942",
            ),
            InlineKeyboardButton("💸 Withdraw", callback_data="crypto_withdrawals"),
        ],
        [
            primary_btn(
                f"Coin balance {'✅' if selected == 'coins' else '❌'}",
                callback_data="wallet_toggle",
                icon_custom_emoji_id=CASINO_COINS_EMOJI_ID,
            )
        ],
    ]
    return text, InlineKeyboardMarkup(keyboard)

