def _bonus_icon_id(symbol: str) -> str | None:
    """Resolve the best animated icon for a bonus screen symbol."""
    # The runtime-loaded pack takes priority, while the explicit IDs keep the
    # bonus menu animated even during a slow or unavailable sticker-pack load.
    return CUSTOM_EMOJI_MAP.get(symbol) or _BONUS_EMOJI_IDS.get(symbol)

def _bonus_icon_tag(symbol: str) -> str:
    """Render bonus copy with a consistent custom emoji and Unicode fallback."""
    emoji_id = _bonus_icon_id(symbol)
    return (
        f'<tg-emoji emoji-id="{emoji_id}">{symbol}</tg-emoji>'
        if emoji_id else symbol
    )

def _bonus_button(label: str, callback_data: str, symbol: str, kind: str = "primary"):
    """Build a compact bonus button with a pack icon."""
    factory = {
        "success": success_btn,
        "danger": danger_btn,
    }.get(kind, primary_btn)
    return factory(
        label,
        callback_data=callback_data,
        icon_custom_emoji_id=_bonus_icon_id(symbol),
    )

def _bonus_progress_bar(user_id: str) -> tuple[str, float, float]:
    """Return a connected rank progress bar plus current and next totals."""
    total = max(
        user_wagering_totals.get(str(user_id), 0.0),
        user_wagered_amount.get(str(user_id), 0.0),
    )
    current_idx = get_user_level(str(user_id))
    current_threshold = float(CASINO_RANKS[current_idx][2])
    next_threshold = (
        float(CASINO_RANKS[current_idx + 1][2])
        if current_idx < len(CASINO_RANKS) - 1 else current_threshold
    )
    span = max(1.0, next_threshold - current_threshold)
    progress = 1.0 if current_idx >= len(CASINO_RANKS) - 1 else max(
        0.0, min(1.0, (total - current_threshold) / span)
    )
    filled = int(round(progress * 10))
    if _PROGRESS_BAR_STICKERS:
        bar = "".join(
            f'<tg-emoji emoji-id="{_PROGRESS_BAR_STICKERS[min(i, len(_PROGRESS_BAR_STICKERS) - 1)]}">🟩</tg-emoji>'
            if i < filled else "▫️"
            for i in range(10)
        )
    else:
        bar = "🟩" * filled + "▫️" * (10 - filled)
    return bar, total, max(0.0, next_threshold - total)

