def get_user_level(user_id: str) -> int:
    """Get user's current rank index (0=Bronze I … 69=Top Tier V)."""
    user_id = str(user_id)
    wagered = max(
        user_wagering_totals.get(user_id, 0.0),
        user_wagered_amount.get(user_id, 0.0),
    )
    level = 0
    for i, (tier, sub, threshold, bonus, emoji) in enumerate(CASINO_RANKS):
        if wagered >= threshold:
            level = i
        else:
            break
    return level

def get_next_level_wager(user_id: str) -> float:
    """Get how much more user needs to wager to reach the next rank."""
    user_id = str(user_id)
    current_level = get_user_level(user_id)
    wagered = max(
        user_wagering_totals.get(user_id, 0.0),
        user_wagered_amount.get(user_id, 0.0),
    )
    if current_level >= len(CASINO_RANKS) - 1:
        return 0.0
    next_threshold = CASINO_RANKS[current_level + 1][2]
    return max(0.0, next_threshold - wagered)

async def handle_bonus_weekly(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show weekly bonus details with real calculation."""
    import datetime as _dt
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    # Get rank info
    current_level = get_user_level(user_id)
    cur_tier, cur_sub, cur_thresh, cur_bonus, cur_emoji = CASINO_RANKS[current_level]
    rank_name_w = f"{get_rank_custom_emoji_tag(current_level)} {cur_tier} {_CR_SUB[cur_sub-1]}"
    next_level = min(current_level + 1, len(CASINO_RANKS) - 1)
    next_tier_w, next_sub_w, next_thresh_w, _, next_emoji_w = CASINO_RANKS[next_level]
    next_rank_name_w = f"{get_rank_custom_emoji_tag(next_level)} {next_tier_w} {_CR_SUB[next_sub_w-1]}"

    # Real weekly bonus = 0.5% of total wagered
    total_wagered = user_wagering_totals.get(user_id, 0.0)
    estimated_weekly_bonus = total_wagered * 0.005

    # Check if user has rollers boost
    username = query.from_user.username or query.from_user.first_name or ""
    has_rollers = "rollers" in username.lower()
    if has_rollers:
        estimated_weekly_bonus *= 1.10

    # Weekly claim: Saturday at 11:00 PM
    now = _dt.datetime.now()
    is_saturday = now.weekday() == 5
    is_after_11pm = now.hour >= 23

    last_claim_time = user_last_weekly_claim.get(user_id, 0)
    already_claimed_this_week = False
    if last_claim_time > 0:
        last_claim_dt = _dt.datetime.fromtimestamp(last_claim_time)
        already_claimed_this_week = (now - last_claim_dt).days < 7

    can_claim = (_weekly_bonus_unlocked or (is_saturday and is_after_11pm)) and estimated_weekly_bonus > 0 and not already_claimed_this_week

    # Time until next Saturday 11 PM
    days_until_saturday = (5 - now.weekday()) % 7
    if days_until_saturday == 0 and now.hour >= 23:
        days_until_saturday = 7
    if is_saturday and now.hour < 23:
        hours_remaining = 23 - now.hour - 1
        mins_remaining = 60 - now.minute
        time_remaining = f"{hours_remaining}h {mins_remaining}m"
    elif days_until_saturday > 0:
        time_remaining = f"{days_until_saturday} days until Saturday 11:00 PM"
    else:
        time_remaining = "⚡ Available now!"

    bonus_formatted = format_balance_in_currency(estimated_weekly_bonus, user_currency)
    boost_status = "✅ Active (+10%)" if has_rollers else "❌ Inactive"

    wager_for_next = max(0, next_thresh_w - total_wagered)

    unlock_banner = "\n🔓 <b>WEEKLY BONUS UNLOCKED BY ADMIN — Claim now!</b>\n" if _weekly_bonus_unlocked else ""

    text = (
        f"💎 <b>Weekly Bonus</b>\n\n"
        f"Earn a percentage of your total wagers back every Saturday at 11:00 PM. "
        f"Claim within 24 hours or it burns!\n\n"
        f"❓ <b>Rules</b>\n"
        f"Take your bonus directly, or risk it on a dice roll for a multiplier:\n"
        f"🎲 1 → 0x  |  2 → 0.5x  |  3-4 → 1x  |  5 → 1.5x  |  6 → 2x\n\n"
        f"🏅 Your rank: <b>{rank_name_w}</b>\n"
        f"Rollers name boost: {boost_status}\n\n"
        f"🎖️ Next rank: <b>{next_rank_name_w}</b>\n"
        f"Wager ${wager_for_next:,.0f} more to upgrade!\n\n"
        f"⏳ Next claim: {time_remaining}\n"
        f"💰 <b>Your bonus: {bonus_formatted}</b>"
        + unlock_banner
    )

    if can_claim:
        keyboard = [
            [_bonus_button(f"Claim {bonus_formatted}", "bonus_weekly_claim", "🎁", "success")],
            [_bonus_button("Try To Double", "bonus_weekly_double", "🎲", "primary")],
            [_bonus_button("Back", "bonus_back", "⬅️", "danger")]
        ]
    elif already_claimed_this_week:
        keyboard = [
            [_bonus_button("Claimed This Week", "noop", "✅", "success")],
            [_bonus_button("Back", "bonus_back", "⬅️", "danger")]
        ]
    else:
        keyboard = [
            [_bonus_button("Claim opens Saturday 11 PM", "noop", "🔒", "primary")],
            [_bonus_button("Back", "bonus_back", "⬅️", "danger")]
        ]

    reply_markup = InlineKeyboardMarkup(keyboard)
    try:
        await query.edit_message_text(text, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query.message.delete()
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=text,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML,
        )

async def handle_bonus_levelup(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show level-up bonus with new rank system."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    current_idx = get_user_level(user_id)
    total_wagered = max(
        user_wagering_totals.get(user_id, 0.0),
        user_wagered_amount.get(user_id, 0.0),
    )

    tier, sub, curr_thresh, curr_bonus, emoji = CASINO_RANKS[current_idx]
    rank_name = f"{get_rank_custom_emoji_tag(current_idx)} {tier} {_CR_SUB[sub-1]}"

    is_max = current_idx >= len(CASINO_RANKS) - 1
    if not is_max:
        next_tier, next_sub, next_thresh, next_bonus, next_emoji = CASINO_RANKS[current_idx + 1]
        next_rank_name = f"{get_rank_custom_emoji_tag(current_idx + 1)} {next_tier} {_CR_SUB[next_sub-1]}"
        wager_needed = max(0.0, next_thresh - total_wagered)
    else:
        next_rank_name = rank_name
        next_thresh = curr_thresh
        wager_needed = 0.0

    ranking = sum(1 for uid, w in user_wagering_totals.items() if w > total_wagered) + 1

    last_claimed = user_level_bonus_claimed.get(user_id, -1)
    # User must have actually wagered >= the current rank's threshold before claiming its bonus
    can_claim = (current_idx > last_claimed) and not is_max and (total_wagered >= curr_thresh)

    bonus_amount = curr_bonus
    bonus_formatted = format_balance_in_currency(bonus_amount, user_currency)

    if is_max:
        next_level_line = f"\nNext Level:\n<b>{next_rank_name}</b> — Maximum reached!\n"
        wager_line = "👑 <b>You have reached the highest rank!</b>"
    else:
        next_level_line = f"\nNext Level:\n<b>{next_rank_name}</b> — ${next_thresh:,} wagered\n"
        wager_line = f"You are ranked <b>#{ranking}</b>.\nWager <b>${wager_needed:,.0f}</b> more to upgrade your level!"

    text = (
        f"🌲 <b>Level Up Bonus</b>\n\n"
        f"Play games, level up and get even more bonuses!\n\n"
        f"Your current level:\n"
        f"<b>{rank_name}</b> — ${total_wagered:,.0f} wagered"
        f"{next_level_line}\n"
        f"{wager_line}"
    )

    if can_claim:
        claim_btn = _bonus_button(
            f"Claim {bonus_formatted} Bonus",
            "bonus_levelup_claim",
            "🎁",
            "success",
        )
    else:
        claim_btn = _bonus_button(
            f"Claim {bonus_formatted} Bonus",
            "noop",
            "🔒",
            "primary",
        )

    keyboard = [
        [claim_btn],
        [_bonus_button("Levels List", "bonus_levels_list", "📈", "primary")],
        [_bonus_button("Back", "bonus_back", "⬅️", "danger")],
    ]

    reply_markup = InlineKeyboardMarkup(keyboard)
    try:
        await query.edit_message_text(text, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query.message.delete()
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=text,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML,
        )

def _build_rank_tier_page(tier_name: str, user_wagered: float) -> tuple:
    """Build the text + keyboard for a rank tier page.
    Returns (text, reply_markup).
    """
    tier_ranks = [
        (i, t, s, th, b, em)
        for i, (t, s, th, b, em) in enumerate(CASINO_RANKS)
        if t == tier_name
    ]

    text = f"✨ <b>Levels</b>\n\n"
    for idx, t, s, threshold, bonus, em in tier_ranks:
        sub_name = _CR_SUB[s - 1]
        rank_tag = get_rank_custom_emoji_tag(idx)
        text += f"{rank_tag} <b>{t} {sub_name}</b>\n"
        text += f"Wager to Reach: <b>${threshold:,}</b>\n"
        bonus_str = f"${bonus:,.2f}".rstrip('0').rstrip('.')
        text += f"Level Up Bonus: <b>{bonus_str}</b>\n\n"

    tier_idx = _TIER_ORDER.index(tier_name)
    prev_tier = _TIER_ORDER[tier_idx - 1] if tier_idx > 0 else None
    next_tier = _TIER_ORDER[tier_idx + 1] if tier_idx < len(_TIER_ORDER) - 1 else None

    nav_row = []
    if prev_tier:
        nav_row.append(InlineKeyboardButton(f"⬅️ {prev_tier}", callback_data=f"rank_tier_{prev_tier.replace(' ', '_')}"))
    if next_tier:
        nav_row.append(InlineKeyboardButton(f"{next_tier} ➡️", callback_data=f"rank_tier_{next_tier.replace(' ', '_')}"))

    keyboard = []
    if nav_row:
        keyboard.append(nav_row)
    keyboard.append([InlineKeyboardButton("⬅️ Back", callback_data="bonus_levelup")])

    return text, InlineKeyboardMarkup(keyboard)

async def handle_bonus_levels_list(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show rank levels list, starting at the user's current tier."""
    user_id = str(query.from_user.id)
    current_idx = get_user_level(user_id)
    current_tier = CASINO_RANKS[current_idx][0]
    total_wagered = max(
        user_wagering_totals.get(user_id, 0.0),
        user_wagered_amount.get(user_id, 0.0),
    )

    text, reply_markup = _build_rank_tier_page(current_tier, total_wagered)
    await query.edit_message_text(text, reply_markup=reply_markup, parse_mode=ParseMode.HTML)

async def cryptohouse_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /cryptohouse command - show crypto house balances."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)

    # Only owner can see crypto house balance
    if not is_owner_or_manager(user_id):
        await update.message.reply_text("❌ Access denied. Only the owner can view crypto house balance.")
        return

    # Calculate total crypto value in USDT
    total_crypto_usd = 0.0
    crypto_details = []

    for currency, balance in crypto_house_balances.items():
        if balance > 0:
            usd_value = convert_crypto_to_usd(currency, balance)
            total_crypto_usd += usd_value
            crypto_details.append(f"✅ <b>{currency}:</b> {balance:.6f} (✅{format_balance_in_currency(usd_value, user_currency)})")

    if not crypto_details:
        crypto_details.append("✅ No crypto holdings")

    crypto_message = (
        f"🔥 <b>CRYPTO HOUSE BALANCE</b>\n\n"
        f"🏦 <b>Total Crypto Value:</b> {format_balance_in_currency(total_crypto_usd, user_currency)}\n\n"
        f"<b>📊 Breakdown by Currency:</b>\n"
        + "\n".join(crypto_details) +
        f"\n\n🔥 <b>Real-time conversions</b>\n"
        f"🔥 <b>Multi-currency holdings</b>\n"
        f"✅ <b>Available for withdrawals</b>"
    )

    await update.message.reply_text(crypto_message, parse_mode=ParseMode.HTML)

