async def handle_crypto_deposit_amount(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle user entering the deposit amount in USD."""
    if not update.message or not update.message.from_user or not update.message.text:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"

    # Check if user is in the right state
    if user_states.get(user_id) != UserState.CRYPTO_WAITING_AMOUNT:
        return

    crypto = user_states.get(f"{user_id}_crypto")
    network = user_states.get(f"{user_id}_network")

    if not crypto or not network:
        await update.message.reply_text("❌ Session expired. Please start deposit process again.")
        user_states[user_id] = UserState.NONE
        save_data()
        return

    # Parse the amount
    try:
        amount_usd = float(update.message.text.strip().replace('$', '').replace(',', ''))
        if amount_usd <= 0:
            await update.message.reply_text("❌ Please enter a valid positive amount.")
            return
    except ValueError:
        await update.message.reply_text("❌ Please enter a valid number. Example: 5")
        return

    # Store amount and move to proof waiting state
    user_states[user_id] = UserState.CRYPTO_WAITING_PROOF
    user_states[f"{user_id}_amount_usd"] = amount_usd
    save_data()

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]
    network_name = NETWORK_INFO.get(network, network)
    proof_message = (
        f"🔥 <b>SEND DEPOSIT PROOF</b>\n\n"
        f"🔥ª <b>Cryptocurrency:</b> {crypto_info['name']}\n"
        f"🔥 <b>Network:</b> {network_name}\n"
        f"💰 <b>Amount:</b> ${amount_usd:.2f}\n\n"
        f"✅³ Your deposit will be confirmed after blockchain verification.\n\n"
        f"🔥 <b>Please send:</b>\n"
        f"✅ Transaction hash (TXID), OR\n"
        f"✅ Screenshot of your transaction\n\n"
        f"✅ Your proof will be reviewed and confirmed."
    )

    keyboard = [[InlineKeyboardButton("🔥 Cancel", callback_data=f"cancel_crypto_deposit_{crypto}_{network}")]]
    reply_markup = InlineKeyboardMarkup(keyboard)

    await update.message.reply_text(proof_message, reply_markup=reply_markup, parse_mode=ParseMode.HTML)

async def handle_crypto_deposit_proof_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle user sending proof (screenshot or hash) for crypto deposit."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"

    # Check if user is in the right state
    if user_states.get(user_id) != UserState.CRYPTO_WAITING_PROOF:
        return

    crypto = user_states.get(f"{user_id}_crypto")
    network = user_states.get(f"{user_id}_network")
    amount_usd = user_states.get(f"{user_id}_amount_usd")

    if not crypto or not network or not amount_usd:
        await update.message.reply_text("❌ Session expired. Please start deposit process again.")
        user_states[user_id] = UserState.NONE
        save_data()
        return

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]
    network_name = NETWORK_INFO.get(network, network)
    # Generate unique deposit ID
    import time
    deposit_id = f"{user_id}_{int(time.time())}"

    # Store pending crypto deposit with ALL required fields for auto-verification
    import secrets
    pending_crypto_deposits[deposit_id] = {
        'user_id': user_id,
        'username': username,
        'crypto': crypto,
        'currency': crypto,  # For auto-check compatibility
        'network': network,
        'amount_usd': amount_usd,
        'expected_amount': amount_usd,  # For auto-check compatibility
        'address': f"0x{secrets.token_hex(20)}",  # Dummy address for auto-verification
        'proof_type': 'photo' if update.message.photo else 'text',
        'timestamp': int(time.time()),
        'created_at': time.time(),
        'deposit_id': deposit_id
    }

    # Reset user state
    user_states[user_id] = UserState.NONE
    save_data()

    # Notify user
    await update.message.reply_text(
        f"✅ <b>Proof Received!</b>\n\n"
        f"Your {crypto_info['name']} deposit proof has been submitted.\n"
        f"💰 Amount: ${amount_usd:.2f}\n"
        f"🔥 Network: {network_name}\n\n"
        f"✅³ Your deposit is being reviewed and will be confirmed after blockchain verification.\n"
        f"🔥 You'll receive a notification once confirmed.",
        parse_mode=ParseMode.HTML
    )

    # Forward to owner with approval buttons
    keyboard = [
        [InlineKeyboardButton(" Confirm Payment", callback_data=f"approve_crypto_deposit_{deposit_id}")],
        [InlineKeyboardButton(" Reject", callback_data=f"reject_crypto_deposit_{deposit_id}")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    owner_message = (
        f"🔥 <b>NEW CRYPTO DEPOSIT PROOF</b>\n\n"
        f"🔥 <b>User:</b> {username} (ID: `{user_id}`)\n"
        f"🔥ª <b>Crypto:</b> {crypto_info['name']}\n"
        f"🔥 <b>Network:</b> {network_name}\n"
        f"💰 <b>User Claims Amount:</b> ${amount_usd:.2f}\n"
        f"🔥 <b>Deposit ID:</b> `{deposit_id}`\n\n"
        f"🔥 <b>Review the proof below and confirm or reject.</b>\n"
        f"✅ If you confirm, ${amount_usd:.2f} will be added to the user's balance automatically."
    )

    try:
        # Send message to owner
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=owner_message,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML
        )

        # Forward the proof (photo or text)
        if update.message.photo:
            await context.bot.send_photo(
                chat_id=OWNER_ID,
                photo=update.message.photo[-1].file_id,
                caption=f"Proof for deposit {deposit_id}"
            )
        elif update.message.text:
            await context.bot.send_message(
                chat_id=OWNER_ID,
                text=f"🔥 <b>Transaction Hash/Text:</b>\n`{update.message.text}`",
                parse_mode=ParseMode.HTML
            )
    except Exception as e:
        logger.error(f"Error forwarding to owner: {e}")

async def handle_owner_approve_crypto_deposit(query, context: ContextTypes.DEFAULT_TYPE, deposit_id: str) -> None:
    """Handle owner approving a crypto deposit - automatically add balance."""
    user_id_from_query = str(query.from_user.id)

    # Only owner can approve
    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("❌ Unauthorized", show_alert=True)
        except Exception:
            pass
        return

    # Check if deposit exists
    if deposit_id not in pending_crypto_deposits:
        try:
            await query.answer("❌ Deposit not found or already processed", show_alert=True)
        except Exception:
            pass
        return

    deposit_info = pending_crypto_deposits.pop(deposit_id)
    user_id = deposit_info['user_id']
    user_currency = get_user_currency(user_id)
    username = deposit_info['username']
    crypto = deposit_info['crypto']
    network = deposit_info['network']
    amount_usd = deposit_info['amount_usd']
    credit_amount = deposit_info.get('amount_usd', deposit_info.get('amount_inr', amount_usd))

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]
    network_name = NETWORK_INFO.get(network, network)

    # Add balance to user's account — must use critical save so credit survives crash
    ultra_secure_add_user_balance(user_id, credit_amount, "manual_deposit_approval")
    save_data_critical()

    # Notify owner
    await query.edit_message_text(
        f"✅ <b>DEPOSIT CONFIRMED</b> ✅\n\n"
        f"🔥 User: {username} (ID: {user_id})\n"
        f"🔥ª Crypto: {crypto_info['name']}\n"
        f"🔥 Network: {network_name}\n"
        f"💰 Amount: ${credit_amount:.2f}\n\n"
        f"✅ Balance added to user's account.\n"
        f"📊 User's new balance: {format_balance_in_currency(get_user_balance(user_id), user_currency)}",
        parse_mode=ParseMode.HTML
    )

    # Notify user
    try:
        keyboard = [
            [InlineKeyboardButton("⚠️ Report Stuck Deposit", callback_data="report_stuck_deposit")]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        await context.bot.send_message(
            chat_id=user_id,
            text=f"🔥 <b>Deposit Confirmed!</b>\n\n"
                 f"Your {crypto_info['name']} deposit has been confirmed!\n"
                 f"💰 Amount: ${credit_amount:.2f}\n"
                 f"🔥 Network: {network_name}\n\n"
                 f"✅ Your balance has been updated.\n"
                 f"📊 New Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>\n\n"
                 f"Thank you for your deposit!\n\n"
                 f"❓ Have a stuck deposit from an earlier transaction? Report it now!",
            parse_mode=ParseMode.HTML,
            reply_markup=reply_markup
        )
    except Exception as e:
        logger.error(f"Error notifying user: {e}")

async def handle_owner_reject_crypto_deposit(query, context: ContextTypes.DEFAULT_TYPE, deposit_id: str) -> None:
    """Handle owner rejecting a crypto deposit."""
    user_id_from_query = str(query.from_user.id)

    # Only owner can reject
    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("❌ Unauthorized", show_alert=True)
        except Exception:
            pass
        return

    # Check if deposit exists
    if deposit_id not in pending_crypto_deposits:
        try:
            await query.answer("❌ Deposit not found or already processed", show_alert=True)
        except Exception:
            pass
        return

    deposit_info = pending_crypto_deposits.pop(deposit_id)
    user_id = deposit_info['user_id']
    username = deposit_info['username']
    crypto = deposit_info['crypto']

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]
    save_data()

    # Notify owner
    await query.edit_message_text(
        f"❌ <b>DEPOSIT REJECTED</b> ❌\n\n"
        f"The deposit from {username} has been rejected.",
        parse_mode=ParseMode.HTML
    )

    # Notify user
    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=f"❌ <b>Deposit Rejected</b>\n\n"
                 f"Your {crypto_info['name']} deposit could not be verified.\n"
                 f"Please contact support if you believe this is an error.",
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"Error notifying user: {e}")

async def handle_crypto_withdrawal_selection(query, context: ContextTypes.DEFAULT_TYPE, crypto: str) -> None:
    """Handle crypto withdrawal currency selection - show network options if multiple networks available."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    if crypto not in SUPPORTED_CRYPTOCURRENCIES:
        await query.edit_message_text("Cryptocurrency not supported")
        return

    # ── Eligibility gate (same rules as handle_nowpayments_withdrawal) ────────
    _cs_has_dep = bool(player_data.get(user_id, {}).get('deposited'))
    _cs_is_tip  = bool(user_tip_received.get(user_id))
    if not _cs_has_dep and not _cs_is_tip:
        await query.edit_message_text(
            "⚠️ <b>Withdrawable Balance Unavailable</b>\n\n"
            "Only deposited funds and eligible tipped deposited balances can be withdrawn.\n"
            "Bonus or promotional balances may require wagering before withdrawal.\n\n"
            "Make a real deposit to unlock withdrawals.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Back", callback_data="back_to_menu")]]),
            parse_mode=ParseMode.HTML
        )
        return
    _cs_wager = get_wagering_requirement_remaining(user_id)
    if _cs_wager > 0 and not _cs_is_tip:
        await query.edit_message_text(
            "⚠️ <b>Withdrawable Balance Unavailable</b>\n\n"
            "Only deposited funds and eligible tipped deposited balances can be withdrawn. "
            "Bonus or promotional balances may require wagering before withdrawal.\n\n"
            f"📊 Wagering remaining: <b>{format_balance_in_currency(_cs_wager, user_currency)}</b>\n\n"
            "Play games to fulfill the requirement and unlock your withdrawal.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Back", callback_data="back_to_menu")]]),
            parse_mode=ParseMode.HTML
        )
        return
    # ─────────────────────────────────────────────────────────────────────────

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]
    user_balance = get_user_balance(user_id)
    
    # Check if this crypto has multiple networks available
    available_networks = NOWPAYMENTS_CURRENCY_MAP.get(crypto, {})
    
    if len(available_networks) > 1:
        # Show network selection buttons
        keyboard = []
        for network_code in available_networks.keys():
            network_name = NETWORK_INFO.get(network_code, network_code)
            keyboard.append([InlineKeyboardButton(
                f"🔗 {network_name}", 
                callback_data=f"withdraw_network_{crypto}_{network_code}"
            )])
        keyboard.append([InlineKeyboardButton("❌ Cancel", callback_data="crypto_withdrawals")])
        
        await query.edit_message_text(
            f"💸 *{crypto_info['name']} WITHDRAWAL* 💸\n\n"
            f"💳 Current balance: <b>{format_balance_in_currency(user_balance, user_currency)}</b>\n\n"
            f"🔗 *Select Network:*\n"
            f"Choose the network you want to receive your {crypto} on:\n\n"
            f"⚠️ *Important:* Make sure your wallet supports the selected network!",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
    # SINGLE NETWORK WITHDRAWAL
    else:
        # Single network - go directly to amount entry
        network = list(available_networks.keys())[0] if available_networks else crypto
        network_name = NETWORK_INFO.get(network, network)
        
        user_states[user_id] = UserState.CRYPTO_WITHDRAWAL_AMOUNT
        user_states[f"{user_id}_crypto"] = crypto
        user_states[f"{user_id}_network"] = network
        save_data()

        _wa_kb1 = InlineKeyboardMarkup([[
            InlineKeyboardButton(
                f"💰 Withdraw All (${user_balance:.2f})",
                callback_data=f"withdraw_all_{user_id}_{crypto}_{network}"
            )
        ]])
        await query.edit_message_text(
            f"💸 *{crypto_info['name']} WITHDRAWAL* 💸\n\n"
            f"🔗 *Network:* {network_name}\n"
            f"💳 Current balance: <b>{format_balance_in_currency(user_balance, user_currency)}</b>\n"
            f"Min Withdrawal: ${MIN_WITHDRAWAL:.2f}\n\n"
            f"*Enter withdrawal amount in USD:*\n"
            f"Example: 10\n\n"
            f"Your withdrawal will be processed automatically.\n"
            f"Or tap <b>Withdraw All</b> below.",
            parse_mode=ParseMode.HTML,
            reply_markup=_wa_kb1
        )

