_WR_REASONS = [
    ("🎁 Bonus balance", "Your balance was bonus/promotional credit given to play games. Bonus balance cannot be withdrawn — only winnings from real deposits are withdrawable."),
    ("🎮 Test balance", "Your balance was added for testing purposes only and is not withdrawable. Please make a real deposit to play and withdraw."),
    ("📋 Wagering incomplete", "You have not completed the required wagering requirement yet. Please continue playing to unlock your withdrawal."),
    ("🔧 API error", "We encountered a payment gateway error while processing your withdrawal. Please try again in a few minutes."),
    ("🚧 Maintenance", "Withdrawals are currently under maintenance. Please try again later — we apologise for the inconvenience."),
    ("📍 Wrong address", "The wallet address provided appears to be incorrect or unsupported. Please submit a new withdrawal with a valid address."),
    ("⚠️ Min not met", "Your withdrawal amount does not meet the minimum withdrawal requirement. Please check the minimum and try again."),
    ("🔍 Under review", "Your account is currently under review by our team. Withdrawals are temporarily paused. Please contact support for more information."),
]

async def show_withdrawal_reject_reasons(query, withdrawal_id: str, wtype: str) -> None:
    """Show owner a reason-selection menu before confirming rejection. wtype: 'np' or 'cr'."""
    keyboard = []
    for idx, (label, _) in enumerate(_WR_REASONS):
        keyboard.append([InlineKeyboardButton(label, callback_data=f"wr_reason_{wtype}_{withdrawal_id}_{idx}")])
    keyboard.append([InlineKeyboardButton("✏️ Custom / Other", callback_data=f"wr_reason_{wtype}_{withdrawal_id}_custom")])
    keyboard.append([InlineKeyboardButton("🔙 Cancel", callback_data=f"wr_reason_{wtype}_{withdrawal_id}_cancel")])
    try:
        await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(keyboard))
        await query.answer("Select a rejection reason to send to the player.", show_alert=False)
    except Exception:
        try:
            await query.answer("Select a rejection reason.", show_alert=True)
        except Exception:
            pass

async def handle_owner_reject_crypto_withdrawal(query, context: ContextTypes.DEFAULT_TYPE, withdrawal_id: str, reason: str = "") -> None:
    """Handle owner rejecting a crypto withdrawal - refund user."""
    user_id_from_query = str(query.from_user.id)

    # Only owner can reject
    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("❌ Unauthorized", show_alert=True)
        except Exception:
            pass
        return

    # Block double-reject: status 'approved' (was sent) or 'rejected' (already refunded)
    if withdrawal_id not in pending_crypto_withdrawals or \
       pending_crypto_withdrawals[withdrawal_id].get('status') in ('approved', 'rejected'):
        try:
            await query.answer("❌ Withdrawal not found or already processed", show_alert=True)
        except Exception:
            pass
        return

    # Mark rejected BEFORE popping — crash between pop and refund-save can't cause double-refund
    pending_crypto_withdrawals[withdrawal_id]['status'] = 'rejected'
    save_data_critical()
    withdrawal_info = pending_crypto_withdrawals.pop(withdrawal_id)
    user_id = withdrawal_info['user_id']
    user_currency = get_user_currency(user_id)
    username = withdrawal_info['username']
    crypto = withdrawal_info['crypto']
    amount_usd = withdrawal_info.get('amount_usd', withdrawal_info.get('amount_inr', 0))

    crypto_info = SUPPORTED_CRYPTOCURRENCIES[crypto]

    # Refund the user — critical save so refund survives crash
    ultra_secure_add_user_balance(user_id, amount_usd, "withdrawal_reject_refund")
    log_transaction("withdrawal_rejected_refund", user_id, +amount_usd,
                    {"crypto": crypto if 'crypto' in dir() else "unknown", "reason": "rejected_by_admin"})
    save_data_critical()

    # Notify owner
    _reason_display = f"\n\n📋 <b>Reason sent:</b> {reason}" if reason else ""
    await query.edit_message_text(
        f"❌ <b>WITHDRAWAL REJECTED</b> ❌\n\n"
        f"The withdrawal from {username} has been rejected.\n"
        f"💰 Amount ${amount_usd:.2f} has been refunded.{_reason_display}",
        parse_mode=ParseMode.HTML
    )

    # Notify user
    _reason_line = f"\n\n📋 <b>Reason:</b> {reason}" if reason else ""
    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=f"❌ <b>Withdrawal Rejected</b>\n\n"
                 f"Your {crypto_info['name']} withdrawal could not be processed.\n"
                 f"💰 Amount: ${amount_usd:.2f}{_reason_line}\n\n"
                 f"✅ Your balance has been refunded.\n"
                 f"📊 Current Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>\n\n"
                 f"Please contact support if you have any questions.",
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"Error notifying user: {e}")

async def handle_owner_approve_np_withdrawal(query, context: ContextTypes.DEFAULT_TYPE, withdrawal_id: str) -> None:
    """Handle owner approving a NOWPayments crypto withdrawal - notify player."""
    user_id_from_query = str(query.from_user.id)

    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("Unauthorized", show_alert=True)
        except Exception:
            pass
        return

    if withdrawal_id not in pending_withdrawals:
        try:
            await query.answer("Withdrawal not found or already processed", show_alert=True)
        except Exception:
            pass
        return

    # Mark as approved BEFORE popping — if bot crashes between pop and save,
    # the record reloads from disk as 'approved' so a restart + double-tap
    # is blocked by the status check at the top.
    pending_withdrawals[withdrawal_id]['status'] = 'approved'
    save_data_critical()
    withdrawal_info = pending_withdrawals.pop(withdrawal_id)
    user_id = withdrawal_info['user_id']
    username = withdrawal_info['username']
    amount_usd = withdrawal_info['amount_usd']
    display_name = withdrawal_info['display_name']
    wallet_address = withdrawal_info['wallet_address']

    logger.info(f"[WITHDRAWAL APPROVED] id={withdrawal_id} user={user_id} amount=${amount_usd:.2f} {display_name} → {wallet_address}")
    log_transaction("withdrawal_approved", user_id, -amount_usd,
                    {"withdrawal_id": withdrawal_id, "currency": display_name, "address": wallet_address})
    save_data_critical()

    await query.edit_message_text(
        f"<b>WITHDRAWAL APPROVED</b>\n\n"
        f"User: {username} (ID: <code>{user_id}</code>)\n"
        f"Currency: {display_name}\n"
        f"Amount: <b>${amount_usd:.2f}</b>\n"
        f"Address: <code>{wallet_address}</code>\n\n"
        f"Payment marked as sent. Player notified.",
        parse_mode=ParseMode.HTML
    )

    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=f"<b>WITHDRAWAL SENT!</b>\n\n"
                 f"Your {display_name} withdrawal has been processed!\n\n"
                 f"Amount: <b>${amount_usd:.2f}</b>\n"
                 f"Address: <code>{wallet_address}</code>\n\n"
                 f"Your crypto is on the way!",
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"Error notifying user: {e}")

async def handle_owner_reject_np_withdrawal(query, context: ContextTypes.DEFAULT_TYPE, withdrawal_id: str, reason: str = "") -> None:
    """Handle owner rejecting a NOWPayments crypto withdrawal - refund user."""
    user_id_from_query = str(query.from_user.id)

    if not is_owner_or_manager(query.from_user.id):
        try:
            await query.answer("Unauthorized", show_alert=True)
        except Exception:
            pass
        return

    if withdrawal_id not in pending_withdrawals or pending_withdrawals[withdrawal_id].get('status') == 'approved':
        try:
            await query.answer("Withdrawal not found or already processed", show_alert=True)
        except Exception:
            pass
        return

    withdrawal_info = pending_withdrawals.pop(withdrawal_id)
    user_id = withdrawal_info['user_id']
    username = withdrawal_info['username']
    amount_usd = withdrawal_info.get('amount_usd', withdrawal_info.get('amount_inr', 0))
    display_name = withdrawal_info['display_name']

    # Refund user — use hardened wrapper + critical save
    ultra_secure_add_user_balance(user_id, amount_usd, "withdrawal_refund")
    logger.info(f"[WITHDRAWAL REJECTED+REFUND] id={withdrawal_id} user={user_id} refunded=${amount_usd:.2f}")
    log_transaction("withdrawal_rejected_refund", user_id, +amount_usd,
                    {"withdrawal_id": withdrawal_id, "currency": display_name, "reason": "rejected_by_admin"})
    save_data_critical()

    _np_reason_display = f"\n\n📋 <b>Reason sent:</b> {reason}" if reason else ""
    await query.edit_message_text(
        f"❌ <b>WITHDRAWAL REJECTED</b>\n\n"
        f"User: {username}\n"
        f"Amount ${amount_usd:.2f} refunded to user's balance.{_np_reason_display}",
        parse_mode=ParseMode.HTML
    )

    _np_reason_line = f"\n\n📋 <b>Reason:</b> {reason}" if reason else ""
    try:
        await context.bot.send_message(
            chat_id=user_id,
            text=(
                f"❌ <b>Withdrawal Rejected</b>\n\n"
                f"Your {display_name} withdrawal request has been rejected.{_np_reason_line}\n\n"
                f"💰 Your balance has been refunded: "
                f"<b>{format_balance_in_currency(get_user_balance(user_id), get_user_currency(user_id))}</b>\n\n"
                f"Please contact support if you have any questions."
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"Error notifying user: {e}")

# Storage for pending tip confirmations: key = "tip_{sender_id}_{token}"
_pending_tips = {}
# Storage for pending admin addbal/setbal type selections: key = "adminbal_{admin_id}_{ts}"
_pending_admin_addbal = {}

# ── CC Tip Withdraw command ──────────────────────────────────────────────────
async def cctip_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /cctip AMOUNT COIN — CC tip withdrawal via owner's account."""
    global pending_cctip_requests
    if not update.message or not update.message.from_user:
        return
    user_id = str(update.message.from_user.id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"
    user_currency = get_user_currency(user_id)

    # Usage validation
    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "💸 <b>CC Tip Withdrawal</b>\n\n"
            "Usage: <code>/cctip AMOUNT COIN</code>\n"
            "Example: <code>/cctip 36 usdt</code>\n\n"
            "⚠️ Only <b>deposited balance</b> can be withdrawn via CC tip.\n"
            f"📌 Minimum: ${CC_TIP_MIN_USD:.0f}  |  Fee: {int(CC_TIP_FEE_RATE*100)}%",
            parse_mode=ParseMode.HTML
        )
        return

    # Parse amount and coin
    try:
        amount_usd = float(args[0].replace("$", "").replace(",", ""))
    except ValueError:
        await update.message.reply_text("❌ Invalid amount. Use: <code>/cctip 36 usdt</code>", parse_mode=ParseMode.HTML)
        return
    coin = args[1].upper().strip()

    # Min amount check
    if amount_usd < CC_TIP_MIN_USD:
        await update.message.reply_text(
            f"❌ Minimum CC tip withdrawal is <b>${CC_TIP_MIN_USD:.2f}</b>.",
            parse_mode=ParseMode.HTML
        )
        return

    # Wagering requirement check — tip recipients bypass (tipped funds are instantly withdrawable)
    _cctip_is_tip = bool(user_tip_received.get(user_id))
    wager_req = get_wagering_requirement_remaining(user_id)
    if wager_req > 0 and not _cctip_is_tip:
        await update.message.reply_text(
            "⚠️ <b>Withdrawable Balance Unavailable</b>\n\n"
            "Only deposited funds and eligible tipped deposited balances can be withdrawn. "
            "Bonus or promotional balances may require wagering before withdrawal.\n\n"
            f"📊 Wagering remaining: <b>{format_balance_in_currency(wager_req, user_currency)}</b>",
            parse_mode=ParseMode.HTML
        )
        return

    # Balance check
    balance = get_user_balance(user_id)
    if balance < amount_usd:
        await update.message.reply_text(
            f"❌ <b>Insufficient balance</b>\n\n"
            f"Required: <b>${amount_usd:.2f}</b>\n"
            f"Available: <b>{format_balance_in_currency(balance, user_currency)}</b>",
            parse_mode=ParseMode.HTML
        )
        return

    # Only deposited (non-bonus) balance can be CC-tipped
    total_deposited = user_deposit_totals.get(user_id, 0.0)
    if total_deposited <= 0 or not player_data.get(user_id, {}).get('deposited'):
        await update.message.reply_text(
            "❌ <b>No deposited balance</b>\n\n"
            "CC tip withdrawals require a real deposit first.\n"
            "Bonus balance cannot be withdrawn this way.",
            parse_mode=ParseMode.HTML
        )
        return

    # In-flight guard — prevents two concurrent /cctip messages both passing the
    # pending-check before either has reached the balance deduction step.
    if user_id in _cctip_submitting:
        await update.message.reply_text(
            "⏳ Your CC tip request is already being submitted. Please wait.",
            parse_mode=ParseMode.HTML
        )
        return
    _cctip_submitting.add(user_id)
    try:
        # Anti-spam: no duplicate pending requests per user
        for _req in pending_cctip_requests.values():
            if _req.get('user_id') == user_id and _req.get('status') == 'pending':
                await update.message.reply_text(
                    "⚠️ You already have a pending CC tip request.\n"
                    "Please wait for it to be processed.",
                    parse_mode=ParseMode.HTML
                )
                return

        # Calculate fee and receive amount
        fee = round(amount_usd * CC_TIP_FEE_RATE, 2)
        receive = round(amount_usd - fee, 2)
        total_deduct = amount_usd  # deduct full amount from balance

        # Deduct balance immediately (hold funds while pending)
        if not ultra_secure_deduct_user_balance(user_id, total_deduct, "cctip_hold"):
            await update.message.reply_text("❌ Balance deduction failed. Please try again.")
            return
        save_data_critical()

        # Create pending request INSIDE the guard — eliminates the race window where a
        # concurrent /cctip could pass both the in-flight check and the pending-request
        # check in the gap between guard release and request creation.
        req_id = f"CC{user_id}_{int(time.time())}"
        pending_cctip_requests[req_id] = {
            'user_id': user_id,
            'username': username,
            'amount_usd': amount_usd,
            'coin': coin,
            'fee': fee,
            'receive': receive,
            'created_at': time.time(),
            'status': 'pending',
            'chat_id': update.message.chat_id,
            'message_id': update.message.message_id,
        }
        save_data_critical()
    finally:
        _cctip_submitting.discard(user_id)

    # Confirmation to player
    await update.message.reply_text(
        f"✅ <b>CC Tip Withdrawal Requested</b>\n\n"
        f"💵 Amount: <b>${amount_usd:.2f}</b>\n"
        f"⚠️ Fee ({int(CC_TIP_FEE_RATE*100)}%): <b>${fee:.2f}</b>\n"
        f"✅ You Receive: <b>${receive:.2f} {coin}</b>\n\n"
        f"⏳ Your request is being processed by our team.\n"
        f"You will receive a DM when it's sent.",
        parse_mode=ParseMode.HTML
    )

    # Notify owner
    owner_kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Sent", callback_data=f"cctip_done_{req_id}"),
        InlineKeyboardButton("❌ Reject", callback_data=f"cctip_reject_{req_id}"),
    ]])
    try:
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=(
                f"💸 <b>New CC Tip Request</b>\n\n"
                f"👤 User: @{username} (ID: <code>{user_id}</code>)\n"
                f"💰 Amount: <b>${amount_usd:.2f}</b>\n"
                f"⚠️ Fee: <b>${fee:.2f}</b>\n"
                f"✅ Send: <b>${receive:.2f} {coin}</b>\n\n"
                f"🆔 Request ID: <code>{req_id}</code>\n\n"
                f"Tap ✅ Sent after your account sends the CC tip.\n"
                f"Tap ❌ Reject to refund the user."
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=owner_kb
        )
    except Exception as e:
        logger.error(f"[CCTIP] Failed to notify owner: {e}")

    log_transaction("cctip_request", user_id, -total_deduct,
                    {'req_id': req_id, 'coin': coin, 'receive': receive})

async def tip_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /tip command to send tips to other users — shows confirmation first."""
    if not update.message or not update.message.from_user:
        return

    user_id_str = str(update.message.from_user.id)
    sender_currency = get_user_currency(user_id_str)

    recipient_id = None
    amount_val = None
    tip_amount_usd = 0.0
    reply_tg_user = None  # Telegram User object from replied message (for name fallback)

    try:
        try:
            from tip_system import set_user_pref
            set_user_pref(update.effective_user.id, update.effective_user.username, None)
        except:
            pass

        # Case 1: /tip <amount> @username  OR  /tip @username <amount>
        if context.args and len(context.args) >= 2:
            arg1 = context.args[0]
            arg2 = context.args[1]
            arg1_low = arg1.lower()
            arg2_low = arg2.lower()
            arg1_clean = arg1_low.replace("$", "").replace(",", "")
            arg2_clean = arg2_low.replace("$", "").replace(",", "")

            target_str = None

            if arg1_low == "all":
                amount_val = convert_usd_to_currency(get_user_balance(user_id_str), sender_currency)
                target_str = arg2_low
            elif arg2_low == "all":
                amount_val = convert_usd_to_currency(get_user_balance(user_id_str), sender_currency)
                target_str = arg1_low
            else:
                try:
                    amount_val = float(arg1_clean)
                    target_str = arg2_low
                except ValueError:
                    try:
                        amount_val = float(arg2_clean)
                        target_str = arg1_low
                    except ValueError:
                        pass

            if amount_val is not None and target_str:
                tip_amount_usd = convert_currency_to_usd(amount_val, sender_currency)
                target_username = target_str.replace("@", "").strip().lower()
                for uid, profile in user_profiles.items():
                    p_uname = str(profile.get('username', '')).lower().replace("@", "").strip()
                    if p_uname == target_username:
                        recipient_id = str(uid)
                        break

        # Case 2: /tip <amount>  replying to a message
        elif context.args and len(context.args) == 1 and update.message.reply_to_message and update.message.reply_to_message.from_user:
            reply_tg_user = update.message.reply_to_message.from_user
            recipient_id = str(reply_tg_user.id)
            arg1_low = context.args[0].lower()
            arg1_clean = arg1_low.replace("$", "").replace(",", "")
            if arg1_low == "all":
                amount_val = convert_usd_to_currency(get_user_balance(user_id_str), sender_currency)
                tip_amount_usd = get_user_balance(user_id_str)
            else:
                try:
                    amount_val = float(arg1_clean)
                    tip_amount_usd = convert_currency_to_usd(amount_val, sender_currency)
                except ValueError:
                    pass

    except Exception as e:
        logger.error(f"Tip command parse error: {e}")
        return

    # Validate
    if not recipient_id:
        await update.message.reply_text("❌ Could not find that user. They must start the bot first.")
        return
    if amount_val is None or tip_amount_usd <= 0:
        await update.message.reply_text("❌ Please specify a valid amount.\nUsage: /tip <amount> @username")
        return

    # Self-tip check
    if recipient_id == user_id_str:
        await update.message.reply_text("❌ You can't tip yourself.")
        return

    # Deposited-balance-only rule: bonus balance cannot be tipped
    _sender_deposited = player_data.get(user_id_str, {}).get('deposited', False)
    _sender_deposit_total = user_deposit_totals.get(user_id_str, 0.0)
    if not _sender_deposited or _sender_deposit_total <= 0:
        await update.message.reply_text(
            "❌ <b>Cannot send tip</b>\n\n"
            "Only <b>deposited balance</b> can be tipped.\n"
            "Bonus balance is not tippable — make a real deposit first.",
            parse_mode=ParseMode.HTML
        )
        return

    # Balance check
    sender_balance_usd = get_user_balance(user_id_str)
    if sender_balance_usd < tip_amount_usd:
        current_bal = convert_usd_to_currency(sender_balance_usd, sender_currency)
        symbol = CURRENCY_SYMBOLS.get(sender_currency, '$')
        await update.message.reply_text(
            f"❌ <b>Insufficient balance!</b>\n\n"
            f"<b>Required:</b> {symbol}{amount_val:,.2f}\n"
            f"<b>Available:</b> {symbol}{current_bal:,.2f}",
            parse_mode=ParseMode.HTML
        )
        return

    # Build recipient display name:
    # Priority: @username from profile → first_name from profile →
    #           @username from Telegram obj → first_name from Telegram obj
    recipient_profile = user_profiles.get(recipient_id, {})
    r_uname = str(recipient_profile.get('username', '')).strip().lstrip('@')
    r_fname = str(recipient_profile.get('first_name', '')).strip()

    # If profile is missing, fall back directly to the Telegram user object (reply case)
    if not r_uname and not r_fname and reply_tg_user:
        r_uname = str(reply_tg_user.username or '').strip()
        r_fname = str(reply_tg_user.first_name or '').strip()

    if r_uname:
        recipient_display = f"@{r_uname}"
    elif r_fname:
        recipient_display = r_fname
    else:
        # Absolute last resort — never show a raw user ID
        recipient_display = "this user"

    # Amount display for confirmation
    symbol = CURRENCY_SYMBOLS.get(sender_currency, '$')
    tip_display = format_balance_in_currency(tip_amount_usd, sender_currency)

    # Store pending tip
    import uuid
    token = uuid.uuid4().hex[:12]
    pending_key = f"tip_{user_id_str}_{token}"
    _pending_tips[pending_key] = {
        'sender_id': user_id_str,
        'recipient_id': recipient_id,
        'tip_amount_usd': tip_amount_usd,
        'sender_currency': sender_currency,
        'recipient_display': recipient_display,
        'created_at': time.time(),
    }
    # Persist immediately so the pending tip survives restarts and is
    # visible to any other bot instance sharing the same data file.
    try:
        save_data_critical()
    except Exception as _e:
        logger.error(f"Failed to persist pending tip {pending_key}: {_e}")
        save_data()

    keyboard = InlineKeyboardMarkup([
        [
            success_btn("Confirm", callback_data=f"tip_confirm:{pending_key}"),
            danger_btn("Cancel", callback_data=f"tip_cancel:{pending_key}"),
        ]
    ])

    await update.message.reply_text(
        f"⚠️ <b>Confirm Tip</b>\n\n"
        f"Are you sure you want to tip <b>{tip_display}</b> to {recipient_display}?",
        parse_mode=ParseMode.HTML,
        reply_markup=keyboard
    )


async def tip_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle tip confirmation / cancellation button presses."""
    query = update.callback_query

    data = query.data
    action, pending_key = data.split(":", 1)
    caller_id = str(query.from_user.id)

    # ATOMIC POP before any await — guarantees only ONE handler ever processes
    # this tip, even if Telegram delivers the callback twice simultaneously.
    tip_data = _pending_tips.pop(pending_key, None)

    # DEDUP GUARD: If this key was already processed (even via disk recovery), reject immediately.
    # This prevents a second concurrent tap from recovering from disk after the first tap already
    # popped from memory and marked it processed.
    if pending_key in _processed_tip_keys:
        try:
            await query.answer("⏰ This tip was already processed.", show_alert=True)
        except Exception:
            pass
        return

    # FALLBACK: If tip not in memory (e.g., bot restarted between create and confirm),
    # try to recover from disk before declaring expired.
    if not tip_data:
        try:
            if os.path.exists(DATA_FILE):
                with open(DATA_FILE, 'r') as _df:
                    _disk = json.load(_df)
                _disk_tips = (_disk.get('current') or _disk).get('_pending_tips', {}) or {}
                _candidate = _disk_tips.get(pending_key)
                # Only accept if not older than 24 hours
                if _candidate and (time.time() - float(_candidate.get('created_at', 0))) < 86400:
                    tip_data = _candidate
                    logger.info(f"♻️ Recovered tip {pending_key} from disk after restart")
        except Exception as _e:
            logger.warning(f"Tip disk-recovery failed: {_e}")

    # Mark this key as processed NOW (before any await) so concurrent taps are blocked
    if tip_data:
        _processed_tip_keys.add(pending_key)

    try:
        await query.answer()
    except Exception:
        pass

    if not tip_data:
        await query.edit_message_text("⏰ This tip request has expired.")
        return

    # Only the original sender can press the buttons
    if caller_id != tip_data['sender_id']:
        # Put it back so they can still use it
        _pending_tips[pending_key] = tip_data
        try:
            await query.answer("❌ This is not your tip request.", show_alert=True)
        except Exception:
            pass
        return

    if action == "tip_cancel":
        await query.edit_message_text("❌ Tip cancelled.")
        return

    # --- Confirm ---
    sender_id = tip_data['sender_id']
    recipient_id = tip_data['recipient_id']
    tip_amount_usd = tip_data['tip_amount_usd']
    sender_currency = tip_data['sender_currency']
    recipient_display = tip_data['recipient_display']

    # Re-check balance (race condition guard)
    sender_balance_before = get_user_balance(sender_id)
    if sender_balance_before < tip_amount_usd:
        await query.edit_message_text("❌ Insufficient balance. Tip cancelled.")
        return

    # STEP 1: Deduct from sender.
    # Tips are player-to-player transfers — they must NEVER be blocked by
    # the active-game guard or the bet-debounce in deduct_user_balance.
    # Call ultra_secure_deduct_user_balance directly with type "tip" so
    # neither the game-block nor the 3-second debounce applies.
    deducted = ultra_secure_deduct_user_balance(sender_id, tip_amount_usd, "tip")
    if not deducted:
        await query.edit_message_text("❌ Could not process tip — insufficient balance.")
        return
    # Flush sender deduction to disk immediately — prevents balance reappearing
    # if the bot crashes before the recipient credit + full save below.
    save_data_critical()

    # STEP 2: Add to recipient — NO wagering requirement.
    # Tips are player-to-player transfers and must hit the wallet fully and instantly.
    try:
        # Ensure recipient exists in user_profiles so /bal and /profile work
        if recipient_id not in user_profiles:
            user_profiles[recipient_id] = {
                'first_name': tip_data.get('recipient_display', 'Player'),
                'username': '',
                'joined': int(time.time()),
            }
        if recipient_id not in user_balances:
            user_balances[recipient_id] = 0.0

        # Directly credit recipient balance using ultra-secure system
        ultra_secure_add_user_balance(recipient_id, tip_amount_usd, "tip_credit")
        # Mark recipient as having received a tip (triggers withdrawal restrictions)
        user_tip_received[recipient_id] = True
        # Force synchronous disk save so balance is never lost
        save_data_critical()
    except Exception as e:
        # If adding fails, refund sender immediately
        logger.error(f"Tip credit failed for {recipient_id}: {e} — refunding sender {sender_id}")
        ultra_secure_add_user_balance(sender_id, tip_amount_usd, "tip_refund")
        save_data_critical()
        await query.edit_message_text("❌ Tip failed due to an error. Your balance has been refunded.")
        return

    # Log balances after transfer for audit trail
    sender_balance_after = get_user_balance(sender_id)
    recipient_balance_after = get_user_balance(recipient_id)
    logger.info(
        f"✅ TIP TRANSFER: {sender_id} → {recipient_id} | "
        f"Amount: {tip_amount_usd:.2f} | "
        f"Sender: {sender_balance_before:.2f} → {sender_balance_after:.2f} | "
        f"Recipient balance now: {recipient_balance_after:.2f}"
    )

    tip_display = format_balance_in_currency(tip_amount_usd, sender_currency)

    # Build blue inline mention for recipient
    recipient_name = recipient_display.lstrip('@') or "Player"
    recipient_mention = f'<a href="tg://user?id={recipient_id}"><b>{recipient_name}</b></a>'

    # Edit the confirmation message with success
    await query.edit_message_text(
        f'<tg-emoji emoji-id="5127902823542948533">💲</tg-emoji> Transfer <b>{tip_display}</b> sent to {recipient_mention}',
        parse_mode=ParseMode.HTML
    )

    # Notify recipient privately — non-critical, tip is already saved
    try:
        rec_currency = get_user_currency(recipient_id)
        rec_display = format_balance_in_currency(tip_amount_usd, rec_currency)
        sender_profile = user_profiles.get(sender_id, {})
        sender_uname = sender_profile.get('username', '')
        sender_fname = sender_profile.get('first_name', 'Someone')
        sender_name = sender_fname or sender_uname or 'Someone'
        sender_mention = f'<a href="tg://user?id={sender_id}"><b>{sender_name}</b></a>'
        await context.bot.send_message(
            chat_id=int(recipient_id),
            text=f"🎁 <b>You received a tip!</b>\n\n"
                 f"{sender_mention} tipped you <b>{rec_display}</b>! 🎉\n"
                 f"Check your balance with /bal",
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.warning(f"Could not notify tip recipient {recipient_id}: {e}")

