def get_favorite_game(user_id: str) -> str:
    """Return the game the player has played the most, or 'None' if they haven't played any."""
    user_id = str(user_id)
    matches = user_match_history.get(user_id, [])
    if not matches:
        return "None"
    counts: dict = {}
    for m in matches:
        g = m.get('game')
        if g:
            counts[g] = counts.get(g, 0) + 1
    if not counts:
        return "None"
    top_game = max(counts.items(), key=lambda kv: kv[1])[0]
    emoji, name = GAME_DISPLAY_MAP.get(top_game, ('🎮', top_game.replace('_', ' ').title()))
    return f"{emoji} {name}"

def get_biggest_win(user_id: str, currency: str) -> str:
    """Return the player's single largest winning amount from match history, formatted."""
    user_id = str(user_id)
    matches = user_match_history.get(user_id, [])
    wins = [m.get('winnings', 0.0) for m in matches if str(m.get('result', '')).startswith('win')]
    biggest = max(wins) if wins else 0.0
    return format_balance_in_currency(biggest, currency)

