async def profile_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /profile command — text profile card with stats and action buttons."""
    if not update.message or not update.message.from_user:
        return

    tg_user       = update.message.from_user
    user_id       = str(tg_user.id)
    user_currency = get_user_currency(user_id)
    username      = tg_user.username or tg_user.first_name or "Player"

    balance       = get_user_balance(user_id)
    user_level    = get_user_level(user_id)
    current_rank, _ = get_rank_info(user_level)
    rank_tag      = get_rank_custom_emoji_tag(user_level)

    matches      = user_match_history.get(user_id, [])
    total_games  = len(matches)
    total_bets   = sum(m.get('bet', 0.0) for m in matches)
    total_wins   = sum(m.get('winnings', 0.0) for m in matches if str(m.get('result', '')).startswith('win'))
    favorite_game = get_favorite_game(user_id)
    biggest_win   = get_biggest_win(user_id, user_currency)

    profile_data = user_profiles.get(user_id, {})
    joined_ts    = profile_data.get('joined_at', time.time())
    reg_date     = datetime.fromtimestamp(joined_ts).strftime('%d.%m.%Y')

    caption = (
        f"ℹ️ User: <b>@{username}</b> (<code>{user_id}</code>)\n"
        f'<tg-emoji emoji-id="5393544377547104675">🏅</tg-emoji> Rank: <b>{rank_tag} {current_rank}</b>\n'
        f"💰 Balance: <b>{format_balance_in_currency(balance, user_currency)}</b>\n\n"
        f"⚡ Total games: <b>{total_games}</b>\n"
        f'<tg-emoji emoji-id="6233433019055612021">🎯</tg-emoji> Total bets: <b>{format_balance_in_currency(total_bets, user_currency)}</b>\n'
        f'<tg-emoji emoji-id="5415738595279394616">🏆</tg-emoji> Total wins: <b>{format_balance_in_currency(total_wins, user_currency)}</b>\n\n'
        f'<tg-emoji emoji-id="5447615395873716643">🎮</tg-emoji> Favorite game: <b>{favorite_game}</b>\n'
        f'<tg-emoji emoji-id="5442857362383714805">💎</tg-emoji> Biggest win: <b>{biggest_win}</b>\n\n'
        f'<tg-emoji emoji-id="5438384802484998938">🕒</tg-emoji> Registration date: <b>{reg_date}</b>'
    )

    try:
        with open(_DR_PROFILE_PHOTO_PATH, "rb") as photo_f:
            await update.message.reply_photo(
                photo       = photo_f,
                caption     = caption,
                parse_mode  = ParseMode.HTML,
                reply_markup= _profile_action_keyboard(),
            )
    except Exception:
        # Fall back to text-only if the image can't be loaded
        await update.message.reply_text(
            caption, parse_mode=ParseMode.HTML, reply_markup=_profile_action_keyboard()
        )

async def mydeposits_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the player their own deposit history."""
    if not update.message or not update.message.from_user:
        return
    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    history = user_deposit_history.get(user_id, [])
    if not history:
        await update.message.reply_text(
            "📋 <b>Your Deposit History</b>\n\nNo deposits found.\n\nUse /deposit to make your first deposit!",
            parse_mode=ParseMode.HTML
        )
        return
    total = sum(e.get('amount', 0) for e in history)
    lines = []
    for i, e in enumerate(reversed(history[-20:]), 1):
        ts = e.get('ts', 0)
        dt = datetime.fromtimestamp(ts).strftime('%Y-%m-%d %H:%M') if ts else '—'
        amt = e.get('amount', 0)
        cur = e.get('currency', 'USD')
        lines.append(f"{i}. <b>{format_balance_in_currency(amt, user_currency)}</b> ({cur}) — {dt}")
    msg = (
        f"📋 <b>Your Deposit History</b>\n\n"
        + "\n".join(lines)
        + f"\n\n💰 <b>Total deposited:</b> {format_balance_in_currency(total, user_currency)}"
        + (f"\n<i>Showing last 20 of {len(history)} deposits</i>" if len(history) > 20 else "")
    )
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def rakeback_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /rakeback command to view and claim rakeback."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    user = update.message.from_user
    username = user.username or user.first_name or "Unknown"
    full_name = f"{user.first_name or ''} {user.last_name or ''}".strip().lower()

    # Check if user has "rollers" in their name for boosted bonus
    has_rollers = "rollers" in username.lower() or "rollers" in full_name

    # Rakeback is based on accumulated losses (stored in user_losses_rakeback)
    rakeback_bonus = user_losses_rakeback.get(user_id, 0.0)
    
    # Apply 10% boost if user has rollers in name
    if has_rollers:
        rakeback_bonus *= 1.10

    # Check cooldown (24 hours for rakeback)
    import time
    current_time = time.time()
    last_claim_time = user_last_rakeback_claim.get(user_id, 0)
    cooldown_seconds = RAKEBACK_COOLDOWN_HOURS * 3600
    
    remaining_seconds = max(0, cooldown_seconds - (current_time - last_claim_time))
    can_claim = remaining_seconds == 0 and rakeback_bonus > 0

    # Format remaining time as "X hours, Y minutes" (no 0/00 format)
    hours = int(remaining_seconds // 3600)
    minutes = int((remaining_seconds % 3600) // 60)
    
    if hours > 0 and minutes > 0:
        time_remaining = f"{hours} hours, {minutes} minutes"
    elif hours > 0:
        time_remaining = f"{hours} hours"
    elif minutes > 0:
        time_remaining = f"{minutes} minutes"
    else:
        time_remaining = "Available now!"

    # Format bonus amount in user's preferred currency
    bonus_formatted = format_balance_in_currency(rakeback_bonus, user_currency)

    # Show boosted message if user has rollers in name
    if has_rollers:
        rakeback_message = (
            f"<b>Your rakeback is BOOSTED!</b>\n\n"
            f"Next rakeback bonus redeem available in {time_remaining}\n\n"
            f"Next rakeback bonus: <b>{bonus_formatted}</b> (10% boosted!)\n\n"
            f"<b>Thank you for adding Rollers to your name!</b>"
        )
    else:
        rakeback_message = (
            f"Next rakeback bonus redeem available in {time_remaining}\n\n"
            f"Next rakeback bonus: <b>{bonus_formatted}</b>\n\n"
            f"<b>Add 'Rollers' or 'RollersGamble' to your display name (beside your username) to boost rakeback &amp; weekly!</b>"
        )

    # Add claim button if eligible
    keyboard = []
    if can_claim:
        keyboard.append([InlineKeyboardButton("Claim Rakeback", callback_data="claim_rakeback")])

    if keyboard:
        reply_markup = InlineKeyboardMarkup(keyboard)
        await update.message.reply_text(rakeback_message, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(rakeback_message, parse_mode=ParseMode.HTML)

async def raffle_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show active raffle info and player's ticket count."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    username = get_telegram_username(update)

    if not _active_raffle:
        await update.message.reply_text(
            "🎟️ <b>Raffle</b>\n\n"
            "No active raffle right now.\n"
            "Stay tuned — the owner will announce the next one!",
            parse_mode=ParseMode.HTML
        )
        return

    import datetime as _dt
    end_time = _active_raffle.get('end_time', 0)
    title = _active_raffle.get('title', 'Rollers Exclusive Raffle')
    prize_per_winner = _active_raffle.get('prize_per_winner', 100)
    num_winners = _active_raffle.get('num_winners', 1)
    custom_text = _active_raffle.get('custom_text', '')
    total_prize = prize_per_winner * num_winners

    now = time.time()
    if end_time > 0:
        remaining_secs = max(0, int(end_time - now))
        days_r = remaining_secs // 86400
        hrs_r  = (remaining_secs % 86400) // 3600
        mins_r = (remaining_secs % 3600) // 60
        if days_r > 0:
            time_left = f"{days_r}d {hrs_r}h {mins_r}m"
        elif hrs_r > 0:
            time_left = f"{hrs_r}h {mins_r}m"
        else:
            time_left = f"{mins_r}m"
        end_str = _dt.datetime.utcfromtimestamp(end_time).strftime("%b %d, %Y %H:%M UTC")
    else:
        time_left = "Until owner ends it"
        end_str = "TBD"

    my_tickets = user_raffle_tickets.get(user_id, 0)
    raffle_wager_start = _raffle_start_wager.get(user_id, 0.0)
    my_period_wagered = max(0.0, user_raffle_wagering.get(user_id, 0.0) - raffle_wager_start)
    progress = my_period_wagered % RAFFLE_TICKET_THRESHOLD if RAFFLE_TICKET_THRESHOLD > 0 else 0
    remaining_for_ticket = max(0, RAFFLE_TICKET_THRESHOLD - progress)

    # Total tickets in pool
    total_tickets = sum(user_raffle_tickets.get(uid, 0) for uid in user_raffle_tickets)
    win_chance = f"{(my_tickets / total_tickets * 100):.1f}%" if total_tickets > 0 and my_tickets > 0 else "0%"

    text = (
        f"🎟️ <b>{title}</b>\n"
        f"<b>💰 Prize Pool: ${total_prize:,.0f} USDT</b>\n"
        f"<b>🏆 Winners: {num_winners}</b>  |  <b>${prize_per_winner:,.0f} each</b>\n"
        f"<b>⏳ Ends in: {time_left}</b> ({end_str})\n\n"
    )
    if custom_text:
        text += f"{custom_text}\n\n"

    text += (
        f"👤 <b>Player:</b> {username}\n"
        f"🎫 <b>Your Tickets: {my_tickets}</b>\n"
        f"📊 <b>Win Chance: {win_chance}</b>\n\n"
        f"<b>📈 Next Ticket Progress</b>\n"
        f"<b>${progress:,.1f} / ${RAFFLE_TICKET_THRESHOLD:,.0f}</b>\n"
        f"<i>Wager <b>${remaining_for_ticket:,.0f}</b> more for another ticket!</i>\n\n"
        f"<b>💎 How it Works:</b>\n"
        f"✅ Earn <b>1 ticket</b> every <b>${RAFFLE_TICKET_THRESHOLD:,.0f}</b> wagered\n"
        f"✅ More tickets = Higher win chance\n"
        f"✅ All games count — every wager matters\n"
        f"✅ Winners picked randomly at draw time\n\n"
        f"🚀 <i>Play now to earn more tickets!</i>"
    )

    keyboard = [[InlineKeyboardButton("🔄 Refresh", callback_data="raffle_refresh"),
                 InlineKeyboardButton("❌ Close", callback_data="close")]]
    await update.message.reply_text(text=text, parse_mode=ParseMode.HTML,
                                    reply_markup=InlineKeyboardMarkup(keyboard))

