async def _ensure_cf_sticker_set_loaded(context: ContextTypes.DEFAULT_TYPE) -> None:
    """Lazily fetch the Coinflipbyarshxyy sticker pack and cache heads/tails file_ids.

    Only fills in slots that an admin hasn't already set manually via /setcf.
    """
    global _cf_sticker_set_loaded
    if _cf_sticker_set_loaded:
        return
    _cf_sticker_set_loaded = True  # attempt only once per process, even on failure
    try:
        sticker_set = await context.bot.get_sticker_set(_CF_STICKER_SET_NAME)
        stickers = sticker_set.stickers or []
        if not stickers:
            return
        if not CF_STICKERS.get('heads'):
            CF_STICKERS['heads'] = stickers[0].file_id
            coinflip_stickers['heads'] = stickers[0].file_id
        if not CF_STICKERS.get('tails'):
            CF_STICKERS['tails'] = stickers[1].file_id if len(stickers) > 1 else stickers[0].file_id
            coinflip_stickers['tails'] = CF_STICKERS['tails']
        save_data()
        logger.info(f"[CF] Loaded {len(stickers)} sticker(s) from pack '{_CF_STICKER_SET_NAME}'")
    except Exception as e:
        logger.error(f"[CF] Failed to load sticker pack '{_CF_STICKER_SET_NAME}': {e}")


def _cf_build_accept_keyboard(cf_id: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton("✅ Flip the coin", callback_data=f"cf_flip_{cf_id}")]])


async def coinflip_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /cf [heads/tails] [amount] OR /cf [amount] [heads/tails] command."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    if user_id not in user_balances:
        user_balances[user_id] = 0.0
    if user_id not in user_profiles:
        user_profiles[user_id] = {
            'username': update.message.from_user.username or '',
            'first_name': update.message.from_user.first_name or 'Player',
            'currency': 'USD',
            'joined_at': time.time()
        }

    username = update.message.from_user.username or update.message.from_user.first_name or "Player"
    balance = get_user_balance(user_id)
    user_currency = get_user_currency(user_id)

    VALID_SIDES = {'heads', 'tails', 'h', 't', 'btc', 'eth', 'bitcoin', 'ethereum'}

    def usage_msg():
        return (
            "🪙 <b>COIN FLIP</b>\n\n"
            "<b>Usage:</b>\n"
            "  <code>/cf heads [amount]</code>\n"
            "  <code>/cf tails [amount]</code>\n"
            "  <code>/cf [amount] heads</code>\n"
            "  <code>/cf [amount] tails</code>\n\n"
            "<b>Examples:</b>\n"
            "  ✅ <code>/cf heads 50</code>\n"
            "  ✅ <code>/cf 100 tails</code>\n\n"
            f"Minimum bet: <b>{format_balance_in_currency(MIN_BET, user_currency)}</b>\n"
            f"Your balance: <b>{format_balance_in_currency(balance, user_currency)}</b>\n\n"
            "🪙 Pick <b>HEADS</b> or <b>TAILS</b> — win <b>1.88x</b> your bet!"
        )

    if not context.args or len(context.args) < 2:
        await update.message.reply_text(usage_msg(), parse_mode=ParseMode.HTML)
        return

    try:
        arg0, arg1 = context.args[0].lower(), context.args[1].lower()

        # Detect which arg is the side and which is the amount
        # Format 1: /cf heads 50  → arg0 is side, arg1 is amount
        # Format 2: /cf 50 heads  → arg0 is amount, arg1 is side
        if arg0 in VALID_SIDES:
            choice_raw, bet_input = arg0, float(arg1)
        elif arg1 in VALID_SIDES:
            bet_input, choice_raw = float(arg0), arg1
        else:
            await update.message.reply_text(
                "❌ Please specify <b>heads</b> or <b>tails</b>.\n\n" + usage_msg(),
                parse_mode=ParseMode.HTML
            )
            return

        # Normalise choice to 'heads' or 'tails'
        if choice_raw in ('heads', 'h', 'btc', 'bitcoin'):
            user_choice = 'heads'
        else:
            user_choice = 'tails'

        bet_amount = convert_currency_to_usd(bet_input, user_currency)
        min_bet_in_currency = convert_usd_to_currency(MIN_BET, user_currency)
        max_bet_in_currency = convert_usd_to_currency(MAX_BET, user_currency)

        if bet_input < min_bet_in_currency:
            await update.message.reply_text(
                f"❌ Minimum bet is <b>{format_balance_in_currency(MIN_BET, user_currency)}</b>",
                parse_mode=ParseMode.HTML
            )
            return

        if bet_input > max_bet_in_currency:
            await update.message.reply_text(
                f"❌ Maximum bet is <b>{format_balance_in_currency(MAX_BET, user_currency)}</b>",
                parse_mode=ParseMode.HTML
            )
            return

        if bet_amount > balance:
            keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
            await update.message.reply_text(
                "❌ <b>Insufficient balance.</b>\nPlease deposit to continue.",
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )
            return

        if not deduct_user_balance(user_id, bet_amount):
            await update.message.reply_text("❌ Failed to place bet. Please try again.")
            return

        # Match accepted — bet is locked in. Player must tap "Flip the coin" to play it out.
        await _ensure_cf_sticker_set_loaded(context)

        cf_id = f"{user_id}_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        pending_coinflips[cf_id] = {
            'user_id': user_id,
            'username': username,
            'chat_id': update.effective_chat.id,
            'bet_amount': bet_amount,
            'user_choice': user_choice,
            'currency': user_currency,
            'created_at': time.time(),
        }
        save_data_critical()

        side_emoji = {'heads': '🪙', 'tails': '🎲'}
        accept_msg = (
            f"🪙 <b>Match accepted!</b>\n\n"
            f"Player: <b>{username}</b>  vs  <b>Bot</b>\n"
            f"Bet: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
            f"Your call: {side_emoji[user_choice]} <b>{user_choice.upper()}</b>\n\n"
            f"<b>{username}</b>, your turn! Tap below to flip the coin."
        )
        await update.message.reply_text(
            accept_msg,
            parse_mode=ParseMode.HTML,
            reply_markup=_cf_build_accept_keyboard(cf_id)
        )

    except ValueError:
        await update.message.reply_text(
            "❌ Invalid amount. Please enter a number.\n\n" + usage_msg(),
            parse_mode=ParseMode.HTML
        )


async def handle_coinflip_flip(query, context: ContextTypes.DEFAULT_TYPE, cf_id: str) -> None:
    """Handle the 'Flip the coin' button tap — resolves the pending coinflip match."""
    pending = pending_coinflips.get(cf_id)
    if not pending:
        try:
            await query.answer("❌ This match has already been played or expired.", show_alert=True)
        except Exception:
            pass
        return

    user_id = str(query.from_user.id)
    if user_id != pending['user_id']:
        try:
            await query.answer("❌ This isn't your match!", show_alert=True)
        except Exception:
            pass
        return

    # Remove immediately so a double-tap can't replay the same match
    del pending_coinflips[cf_id]

    try:
        await query.answer()
    except Exception:
        pass

    username      = pending['username']
    bet_amount    = pending['bet_amount']
    user_choice   = pending['user_choice']
    user_currency = pending['currency']
    chat_id       = pending['chat_id']

    # House edge: bot wins 58% — player wins 42% at 1.88x
    CF_BOT_WIN_CHANCE = 0.58
    CF_WIN_MULTIPLIER = 1.88
    CF_BOT_WIN_PCT    = int(round(CF_BOT_WIN_CHANCE * 100))

    track_wagering(user_id, bet_amount, CF_WIN_MULTIPLIER)

    # Provably fair: SHA-256(server_seed:client_seed:nonce)
    import secrets as _cf_sec, hashlib as _cf_hm
    _cf_ss    = _cf_sec.token_hex(32)
    _cf_nonce = random.randint(100000, 999999)
    _cf_cs    = f"{user_id}_{_cf_nonce}"
    _cf_raw   = f"{_cf_ss}:{_cf_cs}:{_cf_nonce}"
    _cf_hash  = _cf_hm.sha256(_cf_raw.encode()).hexdigest()
    _cf_int   = int(_cf_hash[:8], 16)
    # 0..(CF_BOT_WIN_PCT-1) → house wins, rest → player wins
    bot_result = user_choice if (_cf_int % 100) >= CF_BOT_WIN_PCT else (
        'tails' if user_choice == 'heads' else 'heads'
    )
    _cf_pf_url = (f"{_pf_base}/cf_verify?ss={_cf_ss}&cs={_cf_cs}&n={_cf_nonce}&h={_cf_hash}"
                  if _pf_base else "")

    side_emoji = {'heads': '🪙', 'tails': '🎲'}

    try:
        await query.edit_message_text(
            f"{_rc_tag('🪙')} <b>Flipping...</b>\n\n"
            f"{_rc_tag('👤')} {username} called <b>{user_choice.upper()}</b>!",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass

    if bot_result == user_choice:
        winnings = round(bet_amount * CF_WIN_MULTIPLIER, 2)
        ultra_secure_add_user_balance(user_id, winnings, "win")
        track_win(user_id, winnings)
        deduct_house_balance(winnings - bet_amount)
        add_match_history(user_id, 'coinflip', bet_amount, 'win', winnings)
        try:
            await announce_win_to_channel(context, username, winnings, "Coinflip", multiplier=CF_WIN_MULTIPLIER, bet=bet_amount, user_id=user_id)
        except Exception as e:
            logger.error(f"Failed to announce win: {e}")
        _pf_line = f'\n<a href="{_cf_pf_url}">🔍 Verify result</a>' if _cf_pf_url else ""
        result_msg = (
            f"{_rc_tag('🎉')} <b>YOU WON</b>\n\n"
            f"{_rc_tag('🪙')} Result: <b>{bot_result.upper()}</b>  |  "
            f"You picked: <b>{user_choice.upper()}</b>\n\n"
            f"{_rc_tag('💰')} Won: <b>{format_balance_in_currency(winnings, user_currency)}</b> "
            f"({CF_WIN_MULTIPLIER}x)\n"
            f"{_rc_tag('📈')} Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>"
            f"{_pf_line}"
        )
    else:
        add_house_balance(bet_amount)
        try:
            add_loss_to_rakeback(user_id, bet_amount)
        except Exception:
            pass
        add_match_history(user_id, 'coinflip', bet_amount, 'loss')
        _pf_line = f'\n<a href="{_cf_pf_url}">🔍 Verify result</a>' if _cf_pf_url else ""
        result_msg = (
            f"{_rc_tag('❌')} <b>YOU LOST</b>\n\n"
            f"{_rc_tag('🪙')} Result: <b>{bot_result.upper()}</b>  |  "
            f"You picked: <b>{user_choice.upper()}</b>\n\n"
            f"Lost: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
            f"{_rc_tag('📈')} Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>"
            f"{_pf_line}"
        )

    # Send animated coin flip sticker/GIF before revealing the result
    sent_gif = False
    sticker_id = CF_STICKERS.get(bot_result)
    if sticker_id:
        try:
            await context.bot.send_sticker(chat_id=chat_id, sticker=sticker_id)
            await asyncio.sleep(3)
            sent_gif = True
        except Exception as e:
            logger.error(f"Failed to send sticker: {e}")

    if not sent_gif and CF_GIF_ENABLED:
        try:
            gif_buf = await asyncio.get_event_loop().run_in_executor(
                None, generate_cf_gif, bot_result
            )
            await context.bot.send_animation(
                chat_id=chat_id,
                animation=gif_buf,
                filename="coinflip.gif",
                caption=f"{'🪙' if bot_result == 'heads' else '🎲'} Flipping..."
            )
            await asyncio.sleep(3)
            sent_gif = True
        except Exception as e:
            logger.error(f"CF GIF send failed: {e}")

    if not sent_gif:
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"{_rc_tag('🪙')} <b>Result:</b> {bot_result.upper()}",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass

    # Save before any Telegram sends — balance is already credited above;
    # if a message send raises, the balance is still persisted to disk.
    save_data_critical()

    _cf_pf_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔐 Provably Fair", url=_cf_pf_url)]]) if _cf_pf_url else None
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=result_msg,
            parse_mode=ParseMode.HTML,
            disable_web_page_preview=True,
            reply_markup=_cf_pf_kb
        )
    except Exception as e:
        logger.error(f"Failed to send coinflip result: {e}")

    if bot_result == user_choice:
        await _send_player_win_sticker(context.bot, chat_id)

def _roulette_build_keyboard(selection: str = "") -> InlineKeyboardMarkup:
    """Build the roulette betting keyboard, with checkmark on the selected option."""
    def btn(label: str, val: str) -> InlineKeyboardButton:
        text = f"✅ {label}" if selection == val else label
        return InlineKeyboardButton(text, callback_data=f"roulette_bet:{val}")

    keyboard = [
        [InlineKeyboardButton("🎮 Play", callback_data="roulette_start")],
        [InlineKeyboardButton("🔢 Bet On Number", callback_data="roulette_number_hint")],
        [btn("1 to 12", "1-12"), btn("13 to 24", "13-24"), btn("25 to 36", "25-36")],
        [btn("1 to 18", "1-18"), btn("19 to 36", "19-36")],
        [btn("Even", "even"), btn("Odd", "odd")],
        [btn("🔴", "red"), btn("⚫", "black")],
        [InlineKeyboardButton("🔎 Verify", callback_data="roulette_verify")],
    ]
    return InlineKeyboardMarkup(keyboard)


def _roulette_caption(bet_amount: float, balance: float, currency: str, selection: str = "") -> str:
    """Build the Rollers roulette message caption."""
    sel_display = selection.replace("-", " to ").title() if selection else "None — pick below"
    multiplier = {
        "red": 2.0, "black": 2.0, "even": 2.0, "odd": 2.0,
        "1-18": 2.0, "19-36": 2.0,
        "1-12": 3.0, "13-24": 3.0, "25-36": 3.0,
    }.get(selection)
    multiplier_line = (
        f'{_rc_tag("📈")} Multiplier: <b>x{multiplier:.2f}</b>\n'
        if multiplier else
        f'{_rc_tag("📈")} Multiplier: <b>—</b>\n'
    )
    return (
        f'{_rc_tag("🎡")} <b>Roulette</b>\n\n'
        f'{_rc_tag("💵")} Bet: <b>{format_balance_in_currency(bet_amount, currency)}</b>\n'
        f'{multiplier_line}'
        f'{_rc_tag("📈")} Current balance: <b>{format_balance_in_currency(balance, currency)}</b>\n\n'
        f'{_rc_tag("⚡")} Selected outcome: <b>{sel_display}</b>\n\n'
        f'<i>Choose an outcome, then tap Play.</i>'
    )


async def roulette_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /roulette [amount] — send table image + interactive betting UI."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)

    if not context.args:
        await update.message.reply_text(
            "🎡 <b>ROULETTE</b>\n\n"
            f"Usage: <code>/roulette [amount]</code>\n\n"
            f"Example: <code>/roulette 10</code>\n\n"
            f"Minimum bet: <b>{format_balance_in_currency(MIN_BET, user_currency)}</b>\n"
            f"Your balance: <b>{format_balance_in_currency(balance, user_currency)}</b>",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        bet_amount = parse_bet_amount(user_id, context.args[0].lower())
    except (ValueError, Exception):
        await update.message.reply_text("❌ Please enter a valid amount.")
        return

    if bet_amount < MIN_BET:
        await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}")
        return
    if not check_max_bet(bet_amount):
        await update.message.reply_text(f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, user_currency)}")
        return
    if bet_amount > balance:
        keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
        await update.message.reply_text("❌ Insufficient balance!", reply_markup=InlineKeyboardMarkup(keyboard))
        return

    # Store game state (bet not deducted yet — deducted on Start Game)
    if 'user_games' not in context.user_data:
        context.user_data['user_games'] = {}
    context.user_data['user_games']['roulette'] = {
        'bet_amount': bet_amount,
        'selection': '',
        'chat_id': update.effective_chat.id,
        'thread_id': update.message.message_thread_id if update.message.is_topic_message else None,
    }

    caption = _roulette_caption(bet_amount, balance, user_currency)
    keyboard = _roulette_build_keyboard()

    try:
        with open("roulette_table.jpeg", "rb") as f:
            await update.message.reply_photo(
                photo=f,
                caption=caption,
                reply_markup=keyboard,
                parse_mode=ParseMode.HTML
            )
    except Exception:
        await update.message.reply_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Roulette error: {e}")
        await update.message.reply_text("❌ An error occurred during the game")
        return

RR_CHAMBER_MULTIPLIERS = {1: 1.08, 2: 1.35, 3: 1.80, 4: 2.70, 5: 5.40}

def _rroulette_build_keyboard(selected: int = 0, bet_amount: float = 1.0, currency: str = "USDT") -> InlineKeyboardMarkup:
    """Build the Rollers Roulette number selection keyboard."""
    def nbtn(n: int) -> InlineKeyboardButton:
        mult = RR_CHAMBER_MULTIPLIERS[n]
        label = f"✅ {n} ({mult}x)" if selected == n else f"{n} ({mult}x)"
        return InlineKeyboardButton(label, callback_data=f"rroulette_pick:{n}")

    bet_display = format_balance_in_currency(bet_amount, currency)
    half = bet_amount / 2
    double = bet_amount * 2
    return InlineKeyboardMarkup([
        [nbtn(1), nbtn(2), nbtn(3), nbtn(4), nbtn(5)],
        [
            InlineKeyboardButton("Half Bet", callback_data="rroulette_half"),
            InlineKeyboardButton(f"Bet: {bet_display}", callback_data="rroulette_noop"),
            InlineKeyboardButton("Double Bet", callback_data="rroulette_double"),
        ],
        [
            InlineKeyboardButton("◀️ Back", callback_data="back_to_lobby"),
            InlineKeyboardButton("🎯 Start Game", callback_data="rroulette_start"),
        ],
    ])


def _rroulette_caption(bet_amount: float, balance: float, currency: str, selected: int = 0, result_text: str = "") -> str:
    """Build the Rollers Roulette message caption."""
    mult = RR_CHAMBER_MULTIPLIERS.get(selected, 1.90)
    if selected:
        sel_display = f"Chamber {selected} — <b>{mult}x</b> payout"
        risk_map = {1: "low risk 🟢", 2: "medium risk 🟡", 3: "medium risk 🟡", 4: "high risk 🔴", 5: "max risk 💀"}
        risk = risk_map.get(selected, "")
        survive_chance = ["", "5/6", "4/6", "3/6", "2/6", "1/6"][selected]
        sel_display += f"\n<i>Survive if bullet fires past chamber {selected} ({survive_chance} chance, {risk})</i>"
    else:
        sel_display = "None — pick 1-5 below"
    base = (
        f"🔫 <b>Rollers Roulette</b>\n\n"
        f"Balance: <b>{format_balance_in_currency(balance, currency)}</b>\n\n"
    )
    if result_text:
        base += f"{result_text}\n\n"
    else:
        base += f"Selected: <b>{sel_display}</b>\n\n<i>🔫 6 chambers, 1 bullet — pick how many shots you dare to survive!</i>"
    return base


async def rr_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /rr [amount] or /rr [number] [amount] — Rollers Roulette (Revolver)."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)

    args = context.args or []

    # No args — open the interactive betting UI with default $1 bet so the
    # player can adjust the amount with Half/Double and pick a chamber.
    if not args:
        default_bet = max(1.0, MIN_BET)
        if 'user_games' not in context.user_data:
            context.user_data['user_games'] = {}
        context.user_data['user_games']['rroulette'] = {
            'bet_amount': default_bet,
            'selected': 0,
            'chat_id': update.effective_chat.id,
            'thread_id': update.message.message_thread_id if update.message.is_topic_message else None,
        }
        caption = _rroulette_caption(default_bet, balance, user_currency)
        keyboard = _rroulette_build_keyboard(0, default_bet, user_currency)
        await update.message.reply_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)
        return

    # Parse args: /rr amount  OR  /rr number amount
    try:
        if len(args) >= 2:
            chamber = int(args[0])
            if chamber < 1 or chamber > 5:
                await update.message.reply_text("❌ Chamber number must be between 1 and 5.")
                return
            bet_amount = parse_bet_amount(user_id, args[1].lower())
        else:
            chamber = 0
            bet_amount = parse_bet_amount(user_id, args[0].lower())
    except (ValueError, Exception):
        await update.message.reply_text("❌ Invalid amount. Usage: <code>/rr [amount]</code> or <code>/rr [1-5] [amount]</code>", parse_mode=ParseMode.HTML)
        return

    if bet_amount < MIN_BET:
        await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}")
        return
    if not check_max_bet(bet_amount):
        await update.message.reply_text(f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, user_currency)}")
        return
    if bet_amount > balance:
        logger.warning(f"⚠️ RR INSUF BAL: user={user_id} balance={balance:.4f} bet={bet_amount:.4f} currency={user_currency} chat={update.effective_chat.id}")
        keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
        await update.message.reply_text("❌ Insufficient balance!", reply_markup=InlineKeyboardMarkup(keyboard))
        return

    # Store game state
    if 'user_games' not in context.user_data:
        context.user_data['user_games'] = {}
    context.user_data['user_games']['rroulette'] = {
        'bet_amount': bet_amount,
        'selected': chamber,
        'chat_id': update.effective_chat.id,
        'thread_id': update.message.message_thread_id if update.message.is_topic_message else None,
    }

    # Direct bet: number provided — play immediately
    if chamber > 0:
        if bet_amount > balance:
            await update.message.reply_text("❌ Insufficient balance!")
            return
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            await update.message.reply_text("❌ Insufficient balance!")
            return

        import random
        MULTIPLIER = RR_CHAMBER_MULTIPLIERS.get(chamber, 1.90)
        bullet_chamber = random.randint(1, 6)
        # Sequential logic: survive if bullet fires PAST your chosen chamber
        won = bullet_chamber > chamber

        if won:
            winnings = bet_amount * MULTIPLIER
            ultra_secure_add_user_balance(user_id, winnings, "win")
            net_profit = winnings - bet_amount
            add_house_balance(-net_profit)
            track_wagering(user_id, bet_amount, MULTIPLIER)
            track_bet(user_id, bet_amount)
            add_match_history(user_id, 'rr', bet_amount, 'win', winnings)
            new_balance = get_user_balance(user_id)
            result = (
                f"🟢 <b>You survived!</b>\n"
                f"💥 Bullet fired at chamber <b>{bullet_chamber}</b> — past your stop point!\n"
                f"You pulled through <b>{chamber}</b> shots safely.\n"
                f"Won: <b>+{format_balance_in_currency(net_profit, user_currency)}</b>"
            )
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            track_wagering(user_id, bet_amount, 0)
            track_bet(user_id, bet_amount)
            add_match_history(user_id, 'rr', bet_amount, 'loss', 0)
            new_balance = get_user_balance(user_id)
            result = (
                f"💀 <b>You got shot!</b>\n"
                f"💥 Bullet was in chamber <b>{bullet_chamber}</b> — hit before your stop point!\n"
                f"Lost: <b>-{format_balance_in_currency(bet_amount, user_currency)}</b>"
            )
        save_data_critical()

        keyboard_after = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("◀️ Back", callback_data="back_to_lobby"),
                success_btn("🔄 Play Again", callback_data=f"rroulette_again:{bet_amount}"),
            ]
        ])
        stickers = rollers_roulette_stickers.get('stickers', [])
        if stickers:
            chosen = random.choice(stickers)
            sticker_file_id = chosen['file_id'] if isinstance(chosen, dict) else chosen
            try:
                await update.message.reply_sticker(sticker_file_id)
                await asyncio.sleep(4)
            except Exception as e:
                logger.error(f"RR sticker send error: {e}")

        caption = _rroulette_caption(bet_amount, new_balance, user_currency, chamber, result)
        await update.message.reply_text(caption, reply_markup=keyboard_after, parse_mode=ParseMode.HTML)
        if won:
            await _send_player_win_sticker(context.bot, update.message.chat_id)
        return

    # No chamber selected — show the interactive UI
    caption = _rroulette_caption(bet_amount, balance, user_currency)
    keyboard = _rroulette_build_keyboard(0, bet_amount, user_currency)
    await update.message.reply_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)


async def handle_rroulette_callbacks(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle all rroulette_* callback queries."""
    query = update.callback_query
    # NOTE: query.answer() is called per-branch below so that show_alert=True
    # error popups are never silenced by an earlier unconditional answer.
    user_id = str(query.from_user.id)
    data = query.data
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)
    MULTIPLIER = 1.90

    if 'user_games' not in context.user_data:
        context.user_data['user_games'] = {}
    game = context.user_data['user_games'].get('rroulette', {})
    bet_amount = game.get('bet_amount', 1.0)
    selected = game.get('selected', 0)

    if data.startswith("rroulette_pick:"):
        try:
            await query.answer()
        except Exception:
            pass
        n = int(data.split(":")[1])
        context.user_data['user_games']['rroulette'] = {**game, 'selected': n}
        caption = _rroulette_caption(bet_amount, balance, user_currency, n)
        keyboard = _rroulette_build_keyboard(n, bet_amount, user_currency)
        await query.edit_message_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)

    elif data == "rroulette_half":
        try:
            await query.answer()
        except Exception:
            pass
        new_bet = max(MIN_BET, bet_amount / 2)
        context.user_data['user_games']['rroulette'] = {**game, 'bet_amount': new_bet}
        caption = _rroulette_caption(new_bet, balance, user_currency, selected)
        keyboard = _rroulette_build_keyboard(selected, new_bet, user_currency)
        await query.edit_message_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)

    elif data == "rroulette_double":
        new_bet = min(MAX_BET, bet_amount * 2)
        if new_bet > balance:
            try:
                await query.answer("❌ Insufficient balance for double bet!", show_alert=True)
            except Exception:
                pass
            return
        try:
            await query.answer()
        except Exception:
            pass
        context.user_data['user_games']['rroulette'] = {**game, 'bet_amount': new_bet}
        caption = _rroulette_caption(new_bet, balance, user_currency, selected)
        keyboard = _rroulette_build_keyboard(selected, new_bet, user_currency)
        await query.edit_message_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)

    elif data == "rroulette_noop":
        try:
            await query.answer()
        except Exception:
            pass

    elif data == "rroulette_start":
        if not selected:
            try:
                await query.answer("⚠️ Pick a chamber (1-5) first!", show_alert=True)
            except Exception:
                pass
            return
        if bet_amount > balance:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        try:
            await query.answer()
        except Exception:
            pass

        import random
        MULTIPLIER = RR_CHAMBER_MULTIPLIERS.get(selected, 1.90)
        bullet_chamber = random.randint(1, 6)
        # Sequential logic: survive if bullet fires PAST your chosen chamber
        won = bullet_chamber > selected

        new_balance = get_user_balance(user_id)

        if won:
            winnings = bet_amount * MULTIPLIER
            ultra_secure_add_user_balance(user_id, winnings, "win")
            net_profit = winnings - bet_amount
            add_house_balance(-net_profit)
            track_wagering(user_id, bet_amount, MULTIPLIER)
            track_bet(user_id, bet_amount)
            add_match_history(user_id, 'rr', bet_amount, 'win', winnings)
            new_balance = get_user_balance(user_id)
            result = (
                f"🟢 <b>You survived!</b>\n"
                f"💥 Bullet fired at chamber <b>{bullet_chamber}</b> — past your stop point!\n"
                f"You pulled through <b>{selected}</b> shots safely.\n"
                f"Won: <b>+{format_balance_in_currency(net_profit, user_currency)}</b>"
            )
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            track_wagering(user_id, bet_amount, 0)
            track_bet(user_id, bet_amount)
            add_match_history(user_id, 'rr', bet_amount, 'loss', 0)
            new_balance = get_user_balance(user_id)
            result = (
                f"💀 <b>You got shot!</b>\n"
                f"💥 Bullet was in chamber <b>{bullet_chamber}</b> — hit before chamber {selected}!\n"
                f"Lost: <b>-{format_balance_in_currency(bet_amount, user_currency)}</b>"
            )
        save_data_critical()

        chat_id = query.message.chat_id

        # 1. Delete the betting interface so it disappears
        try:
            await query.message.delete()
        except Exception:
            pass

        # 2. Send the sticker first, then wait for it to finish animating
        stickers = rollers_roulette_stickers.get('stickers', [])
        if stickers:
            chosen = random.choice(stickers)
            sticker_file_id = chosen['file_id'] if isinstance(chosen, dict) else chosen
            try:
                await context.bot.send_sticker(chat_id=chat_id, sticker=sticker_file_id)
                await asyncio.sleep(4)
            except Exception as e:
                logger.error(f"RR sticker send error: {e}")

        # 3. Send outcome message below the sticker
        keyboard_after = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("◀️ Back", callback_data="back_to_lobby"),
                success_btn("🔄 Play Again", callback_data=f"rroulette_again:{bet_amount}"),
            ]
        ])
        caption = _rroulette_caption(bet_amount, new_balance, user_currency, selected, result)
        await context.bot.send_message(
            chat_id=chat_id,
            text=caption,
            reply_markup=keyboard_after,
            parse_mode=ParseMode.HTML
        )
        if won:
            await _send_player_win_sticker(context.bot, chat_id)

    elif data.startswith("rroulette_again:"):
        try:
            await query.answer()
        except Exception:
            pass
        try:
            prev_bet = float(data.split(":")[1])
        except Exception:
            prev_bet = 1.0
        new_balance = get_user_balance(user_id)
        context.user_data['user_games']['rroulette'] = {
            'bet_amount': prev_bet,
            'selected': 0,
        }
        caption = _rroulette_caption(prev_bet, new_balance, user_currency)
        keyboard = _rroulette_build_keyboard(0, prev_bet, user_currency)
        await query.edit_message_text(caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)


async def scratch_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /scratch command - scratch card game."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"
    balance = get_user_balance(user_id)

    if not context.args:
        await update.message.reply_text(
            "🔥 <b>SCRATCH CARD GAME</b>\n\n"
            f"Usage: /scratch [amount]\n"
            f"Example: /scratch 10\n\n"
            f"Minimum bet: {format_balance_in_currency(MIN_BET, get_user_currency(user_id))}\n"
            f"Your balance: {format_balance_in_currency(balance, user_currency)}\n\n"
            "🎰 Scratch virtual cards for instant wins!\n"
            "🔥 Match 3 symbols to win prizes!",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        bet_amount_input = float(context.args[0])
        bet_amount = convert_currency_to_usd(bet_amount_input, user_currency)

        if bet_amount < MIN_BET:
            await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, get_user_currency(user_id))}")
            return

        if not check_max_bet(bet_amount):
            await update.message.reply_text(f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, get_user_currency(user_id))}")
            return

        if bet_amount > balance:
            keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
            reply_markup = InlineKeyboardMarkup(keyboard)
            await update.message.reply_text(
                "❌ Balance is too low",
                reply_markup=reply_markup
            )
            return

        # Deduct bet amount
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            await update.message.reply_text("❌ Insufficient balance!")
            return

        track_wagering(user_id, bet_amount, 2.0)  # Scratch has 2x+ multipliers

        # Generate scratch card symbols
        symbols = ['🍒', '🍋', '🍇', '⭐', '🔔', '💎', '🎰', '7️⃣', '💰']

        # Track the bet
        track_bet(user_id, bet_amount)

        # Generate rigged result
        bot_win_chance = get_dynamic_bot_win_chance(user_id, 'scratch')
        if random.random() < bot_win_chance:
            # Player loses - generate non-matching symbols
            card = [random.choice(symbols) for _ in range(9)]
            # Ensure no 3 in a row
            for i in range(7):
                if card[i] == card[i+1] == card[i+2]:
                    card[i+2] = random.choice([s for s in symbols if s != card[i]])
        else:
            # Player wins - generate matching symbols
            winning_symbol = random.choice(symbols)
            card = [random.choice(symbols) for _ in range(9)]
            # Place 3 matching symbols
            positions = random.sample(range(9), 3)
            for pos in positions:
                card[pos] = winning_symbol

        # Check for wins
        wins = []
        # Check rows
        for i in [0, 3, 6]:
            if card[i] == card[i+1] == card[i+2]:
                wins.append(card[i])
        # Check columns
        for i in [0, 1, 2]:
            if card[i] == card[i+3] == card[i+6]:
                wins.append(card[i])
        # Check diagonals
        if card[0] == card[4] == card[8]:
            wins.append(card[0])
        if card[2] == card[4] == card[6]:
            wins.append(card[2])

        # Display card
        card_display = (
            f"┌─────────────┐\n"
            f"│ {card[0]} │ {card[1]} │ {card[2]} │\n"
            f"├───┼───┼───┤\n"
            f"│ {card[3]} │ {card[4]} │ {card[5]} │\n"
            f"├───┼───┼───┤\n"
            f"│ {card[6]} │ {card[7]} │ {card[8]} │\n"
            f"└─────────────┘"
        )

        global crypto_house_balances

        if wins:
            multiplier = len(wins) * 2.0  # More matches = higher multiplier
            winnings = bet_amount * multiplier
            ultra_secure_add_user_balance(user_id, winnings, "win")
            deduct_house_balance(winnings - bet_amount)
            add_match_history(user_id, 'scratch', bet_amount, 'win', winnings)
            save_data_critical()

            await announce_win_to_channel(context, get_telegram_username(update), winnings, "Scratch Card", multiplier=multiplier, bet=bet_amount, user_id=user_id)

            await update.message.reply_text(
                f"🔥 <b>SCRATCH CARD WIN!</b>\n\n"
                f"```\n{card_display}\n```\n"
                f"🔥 <b>Matches:</b> {len(wins)} lines\n"
                f"🔥 <b>Winning Symbol:</b> {wins[0]}\n"
                f"💰 <b>Multiplier:</b> {multiplier}x\n"
                f"💰 <b>Winnings:</b> {format_balance_in_currency(winnings, user_currency)}\n"
                f"Balance: {format_balance_in_currency(get_user_balance(user_id), user_currency)}",
                parse_mode=ParseMode.HTML
            )
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            add_match_history(user_id, 'scratch', bet_amount, 'loss')
            save_data_critical()

            await update.message.reply_text(
                f"💸 <b>NO MATCHES</b> 💸\n\n"
                f"```\n{card_display}\n```\n"
                f"🔥 <b>Result:</b> No matching lines\n"
                f"{_GAME_OVER_EMOJI} Game over\n\n"
                f"📊 <b>Remaining Balance:</b> {format_balance_in_currency(get_user_balance(user_id), user_currency)}",
                parse_mode=ParseMode.HTML
            )

    except ValueError:
        await update.message.reply_text("❌ Please enter a valid amount")

_rps_active: dict = {}

_RPS_EMOJI = {
    'rock':     ('<tg-emoji emoji-id="6221886815524102983">✊</tg-emoji>', '✊'),
    'scissors': ('<tg-emoji emoji-id="6222265687474185813">✌️</tg-emoji>', '✌️'),
    'paper':    ('<tg-emoji emoji-id="6222065894185508259">✋</tg-emoji>', '✋'),
}

def _rps_reply_keyboard(user_id: str, bet_input: float) -> ReplyKeyboardMarkup:
    return ReplyKeyboardMarkup(
        [[KeyboardButton('✊'), KeyboardButton('✌️'), KeyboardButton('✋')]],
        resize_keyboard=True, one_time_keyboard=True, selective=True,
        input_field_placeholder='Tap to make your choice…'
    )

async def handle_rps_text_choice(update, context) -> bool:
    """Called early in message handling to intercept ✊/✌️/✋ from active RPS sessions."""
    if not update.message or not update.message.from_user:
        return False
    raw = (update.message.text or '').strip()
    # Normalize: strip variation selectors so ✌️ (U+270C U+FE0F) == ✌ (U+270C)
    text = raw.replace('\ufe0f', '').replace('\ufe0e', '').strip()
    emoji_to_choice = {
        '\u270a': 'rock',      # ✊
        '\u270c': 'scissors',  # ✌
        '\u270b': 'paper',     # ✋
    }
    # Use first char only — iOS skin-tone variants send base_emoji + modifier (e.g. ✊🏼)
    base = text[0] if text else ''
    if base not in emoji_to_choice:
        return False
    text = base  # normalise for the lookup below
    user_id = str(update.message.from_user.id)
    if user_id not in _rps_active:
        return False
    session = _rps_active.pop(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or 'Player'
    choice = emoji_to_choice[text]
    await _rps_play(context, update.message.chat_id, user_id, username,
                    session['bet_input'], choice, is_text_msg=True)
    return True

async def _rps_play(context, chat_id: int, user_id: str, username: str,
                    bet_amount_input: float, choice: str,
                    reply_to=None, query=None, is_text_msg: bool = False) -> None:
    """Core RPS logic — shared by command and callback."""
    user_currency = get_user_currency(user_id)
    balance       = get_user_balance(user_id)
    bet_amount    = convert_currency_to_usd(bet_amount_input, user_currency)

    if bet_amount < MIN_BET:
        msg = f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}"
        if query:
            try:
                await query.answer(msg, show_alert=True)
            except Exception:
                pass
        else:
            await context.bot.send_message(chat_id, msg)
        return
    if not check_max_bet(bet_amount):
        msg = f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, user_currency)}"
        if query:
            try:
                await query.answer(msg, show_alert=True)
            except Exception:
                pass
        else:
            await context.bot.send_message(chat_id, msg)
        return
    if bet_amount > balance:
        kb = InlineKeyboardMarkup([[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]])
        if query:
            try:
                await query.answer("❌ Insufficient balance.", show_alert=True)
            except Exception:
                pass
        else:
            await context.bot.send_message(chat_id, "❌ Insufficient balance.", reply_markup=kb)
        return
    if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
        if query:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
        else:
            await context.bot.send_message(chat_id, "❌ Insufficient balance!")
        return

    track_wagering(user_id, bet_amount, 2.0)
    track_bet(user_id, bet_amount)

    # Bot choice (house edge)
    bot_win_chance = get_dynamic_bot_win_chance(user_id, 'rps')
    if random.random() < bot_win_chance:
        bot_choice = {'rock': 'paper', 'paper': 'scissors', 'scissors': 'rock'}[choice]
    else:
        bot_choice = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}[choice]

    beats = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}
    if choice == bot_choice:
        result = 'tie'
    elif beats[choice] == bot_choice:
        result = 'win'
    else:
        result = 'lose'

    if result == 'win':
        jackpot_roll = random.random()
        if   jackpot_roll < 0.00001: multiplier, jackpot_tag = 100.0, "🎰 MEGA JACKPOT!!!"
        elif jackpot_roll < 0.0001:  multiplier, jackpot_tag = 50.0,  "🎰 SUPER JACKPOT!"
        elif jackpot_roll < 0.001:   multiplier, jackpot_tag = 10.0,  "🎰 JACKPOT!"
        else:                        multiplier, jackpot_tag = 2.0,   ""
        winnings = round(bet_amount * multiplier, 2)
        net_profit = round(winnings - bet_amount, 2)
        pre_bal = get_user_balance(user_id)
        ultra_secure_add_user_balance(user_id, winnings, "win")
        post_bal = get_user_balance(user_id)
        logger.info(f"💰 RPS WIN: user={user_id} bet={bet_amount} winnings={winnings} net={net_profit} balance={pre_bal:.2f}→{post_bal:.2f}")
        deduct_house_balance(winnings - bet_amount)
        payout_display = f"+{format_balance_in_currency(net_profit, user_currency)}" + (f" ({multiplier}x)" if multiplier > 2 else "")
        add_match_history(user_id, 'rps', bet_amount, 'win', winnings)
        if query:
            try:
                await announce_win_to_channel(context, username, winnings, "Rock Paper Scissors", multiplier=multiplier, bet=bet_amount, user_id=user_id)
            except Exception as _ann_err:
                logger.warning(f"RPS announce_win_to_channel failed: {_ann_err}")

    elif result == 'tie':
        winnings = bet_amount
        ultra_secure_add_user_balance(user_id, winnings, "tie_refund")
        payout_display = "Bet returned"
        jackpot_tag = ""
    else:
        winnings = 0
        add_house_balance(bet_amount)
        add_loss_to_rakeback(user_id, bet_amount)
        payout_display = f"-{format_balance_in_currency(bet_amount, user_currency)}"
        add_match_history(user_id, 'rps', bet_amount, 'loss', 0)
        jackpot_tag = ""

    save_data_critical()

    curr_bal = get_user_balance(user_id)
    _won_em  = '<tg-emoji emoji-id="5442857362383714805">🏆</tg-emoji>'
    _mult_em = '<tg-emoji emoji-id="4983696199908328775">🔄</tg-emoji>'
    _bet_em  = '<tg-emoji emoji-id="5127902823542948533">💲</tg-emoji>'
    _bal_em  = '<tg-emoji emoji-id="6053003027793578665">🪙</tg-emoji>'
    result_icons = {
        'win':  f'{_won_em} YOU WIN!',
        'lose': '💀 YOU LOSE',
        'tie':  '🤝 TIE!'
    }
    _rps_plain = {'rock': '✊', 'scissors': '✌️', 'paper': '✋'}
    _you_plain = _rps_plain.get(choice, '✊')
    _bot_plain = _rps_plain.get(bot_choice, '✊')
    _mult_line = f"\n{_mult_em} Multiplier: <b>{int(multiplier)}x</b>" if result == 'win' else ""

    full_text = (
        f"{_you_plain} <b>You:</b>  {choice.title()}\n"
        f"{_bot_plain} <b>Bot:</b>  {bot_choice.title()}\n\n"
        f"{jackpot_tag + chr(10) if jackpot_tag else ''}"
        f"<b>{result_icons[result]}</b>{_mult_line}\n"
        f"{_bet_em} Bet: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
        f"{_bal_em} Balance: <b>{format_balance_in_currency(curr_bal, user_currency)}</b>\n"
        f"{payout_display}"
    )
    kb = [
        [InlineKeyboardButton("🔄 Play Again", callback_data=f"rps_again_{user_id}_{bet_amount_input}")],
        [InlineKeyboardButton("📝 Change bet", callback_data=f"rps_changbet_{user_id}_{bet_amount_input}")],
        [InlineKeyboardButton("⬅️ Back",       callback_data="back_to_menu")],
    ]
    # Dismiss the reply keyboard, show bot's emoji choice, then send outcome
    try:
        await context.bot.send_message(
            chat_id, "​",
            reply_markup=ReplyKeyboardRemove()
        )
    except Exception:
        pass
    # Send bot choice as plain emoji — Telegram auto-animates it
    try:
        await context.bot.send_message(chat_id=chat_id, text=_bot_plain)
    except Exception:
        pass
    await asyncio.sleep(1)
    try:
        _rps_result_msg = await context.bot.send_message(
            chat_id, full_text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(kb)
        )
        _register_game_msg(_rps_result_msg.message_id, user_id)
    except Exception:
        # Fallback: plain text without HTML parse mode
        plain_text = (
            f"{_you_plain} You: {choice.title()}\n"
            f"{_bot_plain} Bot: {bot_choice.title()}\n\n"
            f"{jackpot_tag + chr(10) if jackpot_tag else ''}"
            f"{result_icons[result]}\n"
            f"{payout_display}"
        )
        _rps_result_msg = await context.bot.send_message(
            chat_id, plain_text,
            reply_markup=InlineKeyboardMarkup(kb)
        )
        _register_game_msg(_rps_result_msg.message_id, user_id)


async def rps_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /rps command - Rock Paper Scissors with image output."""
    if not update.message or not update.message.from_user:
        return

    user_id       = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username      = update.message.from_user.username or update.message.from_user.first_name or "Player"
    balance       = get_user_balance(user_id)

    if not context.args or len(context.args) < 1:
        await update.message.reply_text(
            "✂️ <b>ROCK PAPER SCISSORS</b>\n\n"
            "<code>/rps [amount]</code>\n\n"
            "🏆 Win: <b>2x</b>  |  🤝 Tie: bet returned\n"
            f"Your balance: <b>{format_balance_in_currency(balance, user_currency)}</b>",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        bet_amount_input = float(context.args[0])

        # If a choice shortcut was given in the command, play directly
        if len(context.args) >= 2:
            raw_choice = context.args[1].lower()
            choice = {'r': 'rock', 'p': 'paper', 's': 'scissors'}.get(raw_choice, raw_choice)
            if choice not in ('rock', 'paper', 'scissors'):
                await update.message.reply_text("❌ Choose: rock / paper / scissors", parse_mode=ParseMode.HTML)
                return
            await _rps_play(context, update.message.chat_id, user_id, username,
                            bet_amount_input, choice)
            return

        # No choice given — show pick buttons
        bet_amount = convert_currency_to_usd(bet_amount_input, user_currency)
        if bet_amount < MIN_BET:
            await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}")
            return
        if not check_max_bet(bet_amount):
            await update.message.reply_text(f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, user_currency)}")
            return
        if bet_amount > balance:
            await update.message.reply_text("❌ Insufficient balance.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]))
            return

        _rps_active[user_id] = {'bet_input': bet_amount_input}
        await update.message.reply_text(
            f"📝 <b>Make your choice</b>\n\n"
            f'<tg-emoji emoji-id="5127902823542948533">💲</tg-emoji> Bet: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n'
            f'<tg-emoji emoji-id="4983696199908328775">🔄</tg-emoji> Multiplier ×1.92\n'
            f'<tg-emoji emoji-id="6053003027793578665">🪙</tg-emoji> Balance: <b>{format_balance_in_currency(balance, user_currency)}</b>\n\n'
            f"Tap ✊ ✌️ or ✋ on your keyboard 👇",
            parse_mode=ParseMode.HTML,
            reply_markup=_rps_reply_keyboard(user_id, bet_amount_input)
        )

    except ValueError:
        await update.message.reply_text("❌ Use: <code>/rps [amount]</code>", parse_mode=ParseMode.HTML)

