async def wheel_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /wheel command - Wheel of Fortune."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"
    telegram_username = update.message.from_user.username or username
    balance = get_user_balance(user_id)

    if not context.args:
        await update.message.reply_text(
            "🔥 <b>WHEEL OF FORTUNE</b>\n\n"
            f"Usage: /wheel [amount]\n"
            f"Example: /wheel 10\n\n"
            f"🔥 <b>Possible Wins:</b>\n"
            f"🔥 <b>MEGA WIN</b>: 50x\n"
            f"🔥 <b>BIG WIN</b>: 20x\n"
            f"🔥 <b>WIN</b>: 5x\n"
            f"💰 <b>SMALL WIN</b>: 2x\n"
            f"💸 <b>LOSE</b>: 0x\n\n"
            f"Minimum bet: {format_balance_in_currency(MIN_BET, get_user_currency(user_id))}\n"
            f"Your balance: {format_balance_in_currency(balance, user_currency)}",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        bet_amount_input = float(context.args[0])
        bet_amount = convert_currency_to_usd(bet_amount_input, user_currency)

        if bet_amount < MIN_BET:
            await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, get_user_currency(user_id))}")
            return

        if not check_max_bet(bet_amount):
            await update.message.reply_text(f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, get_user_currency(user_id))}")
            return

        if bet_amount > balance:
            keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
            reply_markup = InlineKeyboardMarkup(keyboard)
            await update.message.reply_text(
                "❌ Balance is too low",
                reply_markup=reply_markup
            )
            return

        # Deduct bet amount
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            await update.message.reply_text("❌ Insufficient balance!")
            return

        track_wagering(user_id, bet_amount, 2.0)  # Wheel has 2x+ multipliers

        # Track the bet
        track_bet(user_id, bet_amount)

        # Wheel emoji (custom animated wheel tg-emoji)
        _wheel_emoji = '<tg-emoji emoji-id="6328027839798975996">🎡</tg-emoji>'

        # ── Step 1: Send spinning animation sticker FIRST, before revealing result ──
        # Pick a random sticker from the combined pool to show "spinning"
        _all_wheel_stickers = _WHEEL_WIN_STICKERS + _WHEEL_LOSE_STICKERS
        _spin_sticker = random.choice(_all_wheel_stickers)
        _spin_msg = None
        try:
            _spin_msg = await update.message.reply_sticker(_spin_sticker)
        except Exception as _se:
            logger.warning(f"[WHEEL] Spin sticker send failed: {_se}")
            # Fallback: send an animated text "spinning" message
            try:
                _spin_msg = await update.message.reply_text(
                    f"{_wheel_emoji} <b>Wheel of Fortune</b>\n\n🎡 Spinning...",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass

        # ── Step 2: Wait for animation to play ──
        await asyncio.sleep(3.0)

        # ── Step 3: Determine result ──
        bot_win_chance = get_dynamic_bot_win_chance(user_id, 'wheel')
        if random.random() < bot_win_chance:
            multiplier = 0.0
            label = 'LOSE'
        else:
            wheel_results = [
                ('SMALL WIN', 1.2),
                ('WIN',       2.0),
                ('BIG WIN',   3.0),
                ('MEGA WIN',  5.0),
            ]
            weights = [60, 25, 12, 3]
            label, multiplier = random.choices(wheel_results, weights=weights)[0]

        global crypto_house_balances

        # ── Step 4: Credit/debit + send result sticker + result text ──
        if multiplier > 0:
            winnings = round(bet_amount * multiplier, 2)
            ultra_secure_add_user_balance(user_id, winnings, "win")
            deduct_house_balance(winnings - bet_amount)
            add_match_history(user_id, 'wheel', bet_amount, 'win', winnings)
            track_win(user_id, winnings)
            save_data_critical()
            await announce_win_to_channel(context, telegram_username, winnings, "Wheel of Fortune", multiplier=multiplier, bet=bet_amount, user_id=user_id)

            # Send result win sticker
            try:
                await update.message.reply_sticker(random.choice(_WHEEL_WIN_STICKERS))
            except Exception as _se:
                logger.warning(f"[WHEEL] Win sticker failed: {_se}")

            await update.message.reply_text(
                f"{_wheel_emoji} <b>{label}!</b>\n\n"
                f"🎯 Outcome: <b>{multiplier}x</b>\n"
                f"💰 Won: <b>{format_balance_in_currency(winnings, user_currency)}</b>\n"
                f"📊 Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>",
                parse_mode=ParseMode.HTML
            )
            await _send_player_win_sticker(context.bot, update.message.chat_id)
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            add_match_history(user_id, 'wheel', bet_amount, 'loss')
            save_data_critical()

            # Send result lose sticker
            try:
                await update.message.reply_sticker(random.choice(_WHEEL_LOSE_STICKERS))
            except Exception as _se:
                logger.warning(f"[WHEEL] Lose sticker failed: {_se}")

            await update.message.reply_text(
                f"{_wheel_emoji} <b>No luck this time!</b>\n\n"
                f"💸 Lost: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
                f"📊 Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>",
                parse_mode=ParseMode.HTML
            )

    except ValueError:
        await update.message.reply_text("❌ Please enter a valid amount")
    except Exception as _we:
        logger.error(f"[WHEEL] Unexpected error for {user_id}: {_we}", exc_info=True)
        try:
            await update.message.reply_text("❌ An error occurred. If your balance was deducted, contact support.")
        except Exception:
            pass

