# Command handlers for games
async def limbo_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /limbo command - Easy format: /limbo amount multiplier"""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    tg_user = update.message.from_user
    username = tg_user.username or tg_user.first_name or "Player"
    balance = get_user_balance(user_id)

    if not context.args or len(context.args) < 2:
        await update.message.reply_text(
            "🔥 <b>Limbo</b>\n\n"
            "Limbo is an exciting game where players aim to predict how high a randomly generated multiplier will go.\n"
            "To play, simply set your desired target multiplier and place your bet. The game then generates a random multiplier, and if it meets or exceeds your target, you win your bet multiplied by that target.\n"
            "If the multiplier falls short, you lose your bet.\n\n"
            "Usage: /limbo bet amount multiplier\n"
            "Example: /limbo 1 3x\n\n"
            f"Minimum bet: {format_balance_in_currency(MIN_BET, get_user_currency(user_id))}\n"
            f"Your balance: {format_balance_in_currency(balance, user_currency)}",
            parse_mode=ParseMode.HTML
        )
        return

    # ── Parse arguments ───────────────────────────────────────────────────────
    try:
        arg0 = context.args[0].lower().replace('x', '')
        arg1 = context.args[1].lower().replace('x', '')
        try:
            v0 = float(arg0)
            v1 = float(arg1)
        except Exception:
            v0, v1 = 0, 0

        if v0 > 1.5 and v1 <= v0 and v1 > 0 and v0 <= 1000 and v1 < 10000:
            target_multiplier = v0
            bet_amount_input  = v1
        else:
            raw = context.args[0].lower()
            if raw in ["all", "full"]:
                bet_amount_input = convert_usd_to_currency(balance, user_currency)
            elif raw == "half":
                bet_amount_input = convert_usd_to_currency(balance, user_currency) / 2
            else:
                bet_amount_input = float(context.args[0])
            target_multiplier = float(arg1)

        bet_amount = convert_currency_to_usd(bet_amount_input, user_currency)
    except Exception as e:
        logger.error(f"limbo_command parse error uid={user_id}: {e}")
        await update.message.reply_text("❌ Usage: /limbo <bet> <multiplier>  e.g. /limbo 1 3x")
        return

    # ── Validate ──────────────────────────────────────────────────────────────
    if bet_amount < MIN_BET:
        await update.message.reply_text(f"❌ Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}")
        return
    if bet_amount > balance:
        keyboard = [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]
        await update.message.reply_text("❌ Balance is too low", reply_markup=InlineKeyboardMarkup(keyboard))
        return
    if target_multiplier <= 1.0:
        await update.message.reply_text("❌ Multiplier must be more than 1x")
        return
    if target_multiplier > 100:
        await update.message.reply_text("❌ Maximum multiplier is 100x")
        return

    # ── Deduct bet ────────────────────────────────────────────────────────────
    if not deduct_user_balance(user_id, bet_amount):
        await update.message.reply_text("❌ Failed to place bet")
        return

    track_wagering(user_id, bet_amount, target_multiplier)

    # ── Provably Fair RNG — 65% house win ────────────────────────────────────
    server_seed = secrets.token_hex(32)
    client_seed = f"{user_id}_{random.randint(1000, 9999)}"
    nonce       = random.randint(1, 1000)
    hash_result = hashlib.sha256(f"{server_seed}:{client_seed}:{nonce}".encode()).hexdigest()
    hash_int    = int(hash_result[:8], 16)
    r           = (hash_int % 1000000) / 1000000.0

    # Provably fair crash formula — 1% natural house edge baked into 0.99 factor.
    # No forced losses: the distribution naturally gives the house its edge.
    # P(crash >= X) = 0.99/X for X >= 1.01 → realistic multiplier spread.
    crash_point = max(1.01, 0.99 / max(0.000001, 1.0 - r))
    if crash_point > 1000:
        crash_point = 1000.0
    # ─────────────────────────────────────────────────────────────────────────

    # ── Settle ────────────────────────────────────────────────────────────────
    if target_multiplier <= crash_point:
        winnings = bet_amount * target_multiplier
        ultra_secure_add_user_balance(user_id, winnings, "win")
        deduct_house_balance(max(0, winnings - bet_amount))
        add_match_history(user_id, 'limbo', bet_amount, 'win', winnings)
        await announce_win_to_channel(context, username, winnings, "Limbo", multiplier=target_multiplier, bet=bet_amount, user_id=user_id)
        won = True
    else:
        add_house_balance(bet_amount)
        add_loss_to_rakeback(user_id, bet_amount)
        add_match_history(user_id, 'limbo', bet_amount, 'loss', 0)
        winnings = 0
        won      = False

    save_data_critical()

    new_balance = get_user_balance(user_id)
    bet_d   = format_balance_in_currency(bet_amount, user_currency)
    win_d   = format_balance_in_currency(winnings, user_currency)
    bal_d   = format_balance_in_currency(new_balance, user_currency)
    tgt_str = f"{int(target_multiplier)}x" if target_multiplier == int(target_multiplier) else f"{target_multiplier:.2f}x"
    cp_str  = f"{crash_point:.2f}x"
    pf_url  = (f"{_pf_base}/limbo_verify?ss={server_seed}&cs={client_seed}&n={nonce}&h={hash_result}&t={target_multiplier}"
               if _pf_base else "")

    # ── Fetch profile photo ───────────────────────────────────────────────────
    avatar_bytes = None
    try:
        photos = await context.bot.get_user_profile_photos(tg_user.id, limit=1)
        if photos and photos.photos:
            pf = await context.bot.get_file(photos.photos[0][-1].file_id)
            avatar_bytes = bytes(await pf.download_as_bytearray())
    except Exception:
        pass

    # ── Result message — clean Telegram format ───────────────────────────────
    _pf_link = f' — <a href="{pf_url}">provably fair</a>' if pf_url else ""
    _outcome  = "✅" if won else "❌"
    # Format: "Limbo — provably fair\n\n💵 {bet} → {payout} ({target})\n\nMultiplier: {crash}x ✅/❌"
    caption = (
        f'Limbo{_pf_link}\n\n'
        f'💵 {bet_d} → <b>{win_d}</b> ({tgt_str})\n\n'
        f'Multiplier: <b>{crash_point:.2f}x</b> {_outcome}'
    )
    _limbo_pf_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔐 Provably Fair", url=pf_url)]]) if pf_url else None
    await update.message.reply_text(caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True, reply_markup=_limbo_pf_kb)

