async def start_mines_setup(update: Update, context: ContextTypes.DEFAULT_TYPE, bet_amount: float) -> None:
    """Start mines game setup matching IMG_6398."""
    if not update.message or not update.message.from_user:
        return
    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    user_balance = get_user_balance(user_id)
    
    # Default selection
    grid_size = 6
    mines_count = 3
    
    # Check for existing bet and active game
    if user_id in active_games and active_games[user_id].get('type') == 'mines_setup':
        grid_size = active_games[user_id].get('grid_size', 6)
        mines_count = active_games[user_id].get('mines_count', 3)
    
    active_games[user_id] = {
        '_created_at': time.time(),
        'type': 'mines_setup',
        'bet_amount': bet_amount,
        'grid_size': grid_size,
        'mines_count': mines_count,
        'created_at': time.time()
    }

    keyboard = [
        [InlineKeyboardButton("Grid Size", callback_data="mines_label_grid")],
        [
            InlineKeyboardButton(f"2 {'✅' if grid_size == 2 else ''}", callback_data="mines_setup_grid_2"),
            InlineKeyboardButton(f"3 {'✅' if grid_size == 3 else ''}", callback_data="mines_setup_grid_3"),
            InlineKeyboardButton(f"4 {'✅' if grid_size == 4 else ''}", callback_data="mines_setup_grid_4"),
            InlineKeyboardButton(f"5 {'✅' if grid_size == 5 else ''}", callback_data="mines_setup_grid_5"),
            InlineKeyboardButton(f"6 {'✅' if grid_size == 6 else ''}", callback_data="mines_setup_grid_6")
        ],
        [InlineKeyboardButton("Mines Count", callback_data="mines_label_count")]
    ]

    # Row 1 of mines count
    mines_row1 = []
    # If grid size 5 or 6, start from 3 to remove 1.2x multiplier
    if grid_size >= 5:
        start_count = 3
    else:
        start_count = 1
    
    for i in range(start_count, start_count + 5):
        mines_row1.append(InlineKeyboardButton(f"{i} {'✅' if mines_count == i else ''}", callback_data=f"mines_setup_count_{i}"))
    keyboard.append(mines_row1)

    # Row 2 of mines count
    mines_row2 = []
    for i in range(start_count + 5, start_count + 10):
        mines_row2.append(InlineKeyboardButton(f"{i} {'✅' if mines_count == i else ''}", callback_data=f"mines_setup_count_{i}"))
    keyboard.append(mines_row2)

    keyboard.append([InlineKeyboardButton("Start", callback_data="mines_start")])
    reply_markup = InlineKeyboardMarkup(keyboard)

    setup_message = (
        f"<b>Mines - provably fair [?]</b>\n\n"
        f"Multiplier increases until you find a mine, cashout at anytime!\n\n"
        f"Balance: <b>{format_balance_in_currency(user_balance, user_currency)}</b>"
    )

    await update.message.reply_text(setup_message, reply_markup=reply_markup, parse_mode=ParseMode.HTML)

async def handle_mines_setup_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle interactive mines setup callbacks."""
    query = update.callback_query
    if not query: return
    
    user_id = str(query.from_user.id)
    data = query.data
    
    # Ensure active game state exists
    if user_id not in active_games or active_games[user_id].get('type') != 'mines_setup':
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': 'mines_setup',
            'bet_amount': MIN_BET,
            'grid_size': 6,
            'mines_count': 3,
            'created_at': time.time()
        }

    game_data = active_games[user_id]
    
    # Handle grid size selection
    if "grid_" in data:
        grid_size = int(data.split("_")[-1])
        game_data['grid_size'] = grid_size
        if grid_size >= 5 and game_data.get('mines_count', 0) < 3:
            game_data['mines_count'] = 3
            
    # Handle mines count selection
    elif "count_" in data:
        mines_count = int(data.split("_")[-1])
        game_data['mines_count'] = mines_count
        if game_data.get('grid_size', 0) in [5, 6] and mines_count < 3:
             game_data['mines_count'] = 3
    
    # Handle start game transition
    if data in ["mines_setup_start", "mines_start"]:
        try:
            await query.answer("Starting Mines...")
        except Exception:
            pass
        await handle_mines_start(query, context)
        return

    # Update state and refresh UI
    active_games[user_id] = game_data
    save_data()
    
    try:
        await query.answer()
    except Exception:
        pass
    
    grid_size = game_data.get('grid_size', 6)
    mines_count = game_data.get('mines_count', 3)
    user_balance = get_user_balance(user_id)
    user_currency = get_user_currency(user_id)
    
    keyboard = [
        [InlineKeyboardButton("Grid Size", callback_data="mines_label_grid")],
        [
            InlineKeyboardButton(f"2 {'✅' if grid_size == 2 else ''}", callback_data="mines_grid_2"),
            InlineKeyboardButton(f"3 {'✅' if grid_size == 3 else ''}", callback_data="mines_grid_3"),
            InlineKeyboardButton(f"4 {'✅' if grid_size == 4 else ''}", callback_data="mines_grid_4"),
            InlineKeyboardButton(f"5 {'✅' if grid_size == 5 else ''}", callback_data="mines_grid_5"),
            InlineKeyboardButton(f"6 {'✅' if grid_size == 6 else ''}", callback_data="mines_grid_6")
        ],
        [InlineKeyboardButton("Mines Count", callback_data="mines_label_count")]
    ]

    start_count = 3 if grid_size >= 5 else 1
    row1 = [InlineKeyboardButton(f"{i} {'✅' if mines_count == i else ''}", callback_data=f"mines_count_{i}") for i in range(start_count, start_count + 5)]
    keyboard.append(row1)
    
    row2 = [InlineKeyboardButton(f"{i} {'✅' if mines_count == i else ''}", callback_data=f"mines_count_{i}") for i in range(start_count + 5, start_count + 10)]
    keyboard.append(row2)

    keyboard.append([InlineKeyboardButton("Start Game 🎮", callback_data="mines_start")])
    
    setup_message = (
        f"<b>Mines - Provably Fair</b>\n\n"
        f"Multiplier increases for every diamond found. Don't hit the mine!\n\n"
        f"Balance: <b>{format_balance_in_currency(user_balance, user_currency)}</b>\n"
        f"Current Setup: <b>{grid_size}x{grid_size} Grid</b> | <b>{mines_count} Mines</b>"
    )

    try:
        await query.edit_message_text(setup_message, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"Error updating mines setup: {e}")

async def handle_sticker(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle stickers sent by the owner to update the roulette sticker pack."""
    user_id = str(update.message.from_user.id)
    # Check if user is owner (assuming "[UPI REMOVED]" check or similar owner verification)
    # In this bot, owners are usually verified by ID. Let's look for owner check.
    
    if update.message.sticker:
        sticker = update.message.sticker
        file_id = sticker.file_id
        pack_name = sticker.set_name
        
        if pack_name == "roulete":
            if 'stickers' not in roulette_stickers:
                roulette_stickers['stickers'] = []
            
            # CRITICAL: Always use the raw file_id from the sticker object
            if file_id not in roulette_stickers['stickers']:
                roulette_stickers['stickers'].append(file_id)
                roulette_stickers['pack_name'] = pack_name
                # Persist to disk immediately
                save_data()
                await update.message.reply_text(f"✅ Sticker added to roulette pack! Total: {len(roulette_stickers['stickers'])}")
            else:
                await update.message.reply_text("ℹ️ Sticker already in pack.")

async def stickers_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner-only sticker settings help; normal sticker messages stay silent."""
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only.")
        return

    roulette_pack = roulette_stickers.get("pack_name") or "not set"
    roulette_count = len(roulette_stickers.get("stickers", []))
    rollers_pack = rollers_roulette_stickers.get("pack_name") or "not set"
    rollers_count = len(rollers_roulette_stickers.get("stickers", []))

    await update.message.reply_text(
        "🎨 <b>Sticker Settings</b>\n\n"
        "✅ You can send stickers normally — I will not ask anything.\n\n"
        "<b>Explicit setup commands:</b>\n"
        "• <code>/setsticker roulette PackName</code> — set the roulette pack\n"
        "• Reply to a sticker with <code>/setcf heads</code> or <code>/setcf tails</code> — coinflip stickers\n"
        "• Reply to a sticker with <code>/setlosesticker</code> — bot-loss sticker\n\n"
        f"🎰 Roulette: <code>{roulette_pack}</code> ({roulette_count} stickers)\n"
        f"🔫 Rollers Roulette: <code>{rollers_pack}</code> ({rollers_count} stickers)",
        parse_mode=ParseMode.HTML,
    )

async def setsticker_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner command: /setsticker roulette <packname>  — works in groups & DMs."""
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        return

    args = context.args  # e.g. ["roulette", "DicesByInfluence"]

    # No args — show status + usage
    if not args:
        pack = roulette_stickers.get('pack_name', 'not set')
        count = len(roulette_stickers.get('stickers', []))
        await update.message.reply_text(
            f"🎰 <b>Sticker Setup</b>\n\n"
            f"Current roulette pack: <code>{pack}</code>\n"
            f"Stickers loaded: <b>{count}</b>\n\n"
            f"<b>Usage:</b>\n"
            f"<code>/setsticker roulette PackName</code>\n\n"
            f"Example:\n"
            f"<code>/setsticker roulette DicesByInfluence</code>\n\n"
            f"ℹ️ The pack name is the last part of the sticker pack link "
            f"(e.g. t.me/addstickers/<b>PackName</b>)",
            parse_mode=ParseMode.HTML,
        )
        return

    if args[0].lower() == "roulette":
        if len(args) < 2:
            await update.message.reply_text(
                "❌ Please provide the pack name.\n"
                "Usage: <code>/setsticker roulette PackName</code>",
                parse_mode=ParseMode.HTML,
            )
            return

        pack_name = args[1]
        msg = await update.message.reply_text(
            f"🔄 Fetching sticker pack <code>{pack_name}</code>...",
            parse_mode=ParseMode.HTML,
        )

        pack_info = await fetch_sticker_pack_info(context, pack_name)
        if not pack_info:
            await msg.edit_text(
                f"❌ Could not find sticker pack <code>{pack_name}</code>.\n\n"
                f"Make sure the pack name is correct (case-sensitive).\n"
                f"Find it at: t.me/addstickers/{pack_name}",
                parse_mode=ParseMode.HTML,
            )
            return

        roulette_stickers['pack_name'] = pack_name
        roulette_stickers['title'] = pack_info.get('title', pack_name)
        roulette_stickers['is_animated'] = pack_info.get('is_animated', False)
        roulette_stickers['stickers'] = pack_info.get('stickers', [])
        save_data()

        count = len(roulette_stickers['stickers'])
        await msg.edit_text(
            f"✅ <b>Roulette sticker pack saved!</b>\n\n"
            f"📦 Pack: <code>{pack_name}</code>\n"
            f"🎬 Title: {pack_info.get('title', pack_name)}\n"
            f"🎞 Animated: {'Yes' if pack_info.get('is_animated') else 'No'}\n"
            f"🃏 Stickers loaded: <b>{count}</b>\n\n"
            f"The roulette game will now use these stickers on every spin!",
            parse_mode=ParseMode.HTML,
        )
    else:
        await update.message.reply_text(
            "❌ Unknown type. Use: <code>/setsticker roulette PackName</code>",
            parse_mode=ParseMode.HTML,
        )

async def handle_tower_callback(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle all tower game callbacks — routes to unified implementation."""
    user_id = str(query.from_user.id)
    data = query.data

    try:
        await query.answer()
    except Exception:
        pass

    # Difficulty selected — start the game
    if data in ["tower_easy", "tower_medium", "tower_hard"]:
        game_data = active_games.get(user_id)
        bet_amount = game_data.get('bet_amount', 0) if game_data and game_data.get('type') in ['tower_setup', 'tower'] else 0
        if bet_amount == 0:
            try:
                try:
                    await query.answer("❌ Bet session expired. Please try /tower again.", show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return
        difficulty = data.replace("tower_", "")
        _twr_pf_ss = secrets.token_hex(32)
        _twr_pf_nonce = random.randint(1, 999999)
        _twr_pf_cs = f"{user_id}_{_twr_pf_nonce}"
        _twr_pf_hash = hashlib.sha256(f"{_twr_pf_ss}:{_twr_pf_cs}:{_twr_pf_nonce}".encode()).hexdigest()
        tower_game = TowerGame(user_id=int(user_id), mode=difficulty, bet=float(bet_amount), seed=_twr_pf_hash)
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': 'tower',
            'bet_amount': bet_amount,
            'difficulty': difficulty,
            'game': tower_game,
            'status': 'playing',
            'created_at': time.time(),
            'msg_id': query.message.message_id,
            'chat_id': query.message.chat_id,
            'pf_server_seed': _twr_pf_ss,
            'pf_client_seed': _twr_pf_cs,
            'pf_nonce': _twr_pf_nonce,
        }
        save_data()
        await show_tower_grid(query, context)
        return

    # Difficulty cycling arrows
    if data in ["tower_prev_diff", "tower_next_diff"]:
        game_data = active_games.get(user_id)
        if not game_data or game_data.get('type') != 'tower_setup':
            return
        diffs = ["easy", "medium", "hard"]
        current = game_data.get('difficulty', 'medium')
        idx = diffs.index(current) if current in diffs else 1
        idx = (idx - 1) % 3 if data == "tower_prev_diff" else (idx + 1) % 3
        game_data['difficulty'] = diffs[idx]
        save_data()
        await _show_tower_setup_ui(query, context, game_data)
        return

    # Quick-bet selection from /tower menu
    if data.startswith("tower_quickbet_"):
        try:
            bet_amount = float(data.split("tower_quickbet_")[1])
        except (ValueError, IndexError):
            return
        balance = get_user_balance(user_id)
        user_currency = get_user_currency(user_id)
        if bet_amount > balance:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        if user_id in active_games and is_game_actively_playing(active_games[user_id]):
            gname = active_games[user_id].get('type', 'game').replace('_', ' ').title()
            try:
                await query.answer(f"❌ Finish your active {gname} game first!", show_alert=True)
            except Exception:
                pass
            return
        if not deduct_user_balance(user_id, bet_amount):
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        add_house_balance(bet_amount)
        track_wagering(user_id, bet_amount, 2.0)
        _qb_pf_ss = secrets.token_hex(32)
        _qb_pf_nonce = random.randint(1, 999999)
        _qb_pf_cs = f"{user_id}_{_qb_pf_nonce}"
        _qb_pf_hash = hashlib.sha256(f"{_qb_pf_ss}:{_qb_pf_cs}:{_qb_pf_nonce}".encode()).hexdigest()
        tower_game = TowerGame(user_id=int(user_id), mode="medium", bet=float(bet_amount), seed=_qb_pf_hash)
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': 'tower',
            'bet_amount': bet_amount,
            'difficulty': 'medium',
            'game': tower_game,
            'status': 'playing',
            'created_at': time.time(),
            'msg_id': query.message.message_id,
            'chat_id': query.message.chat_id,
            'pf_server_seed': _qb_pf_ss,
            'pf_client_seed': _qb_pf_cs,
            'pf_nonce': _qb_pf_nonce,
        }
        save_data()
        await show_tower_grid(query, context)
        return

    # Tile click
    if data.startswith("tower_tile_"):
        await handle_tower_tile_click(query, context)
        return

    # Cashout — delegate to guarded handler (concurrent-safe, try/finally)
    if data == "tower_cashout":
        await handle_tower_cashout(query, context)
        return

    # Rules
    if data == "tower_rules":
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=(
                "ℹ️ <b>Monkey Tower Rules</b>\n\n"
                "🍌 Banana = Safe — keep climbing!\n"
                "🐍 Snake = Game Over — you lose your bet\n\n"
                "<b>Difficulties:</b>\n"
                "🟢 Easy: 4 columns, 1 bomb per row\n"
                "🟡 Medium: 4 columns, 1 bomb per row\n"
                "🔴 Hard: 4 columns, 1 bomb per row\n\n"
                "Cash out at any time after climbing at least 1 floor."
            ),
            parse_mode=ParseMode.HTML
        )
        return

    # Quit
    if data == "tower_quit":
        if user_id in active_games:
            del active_games[user_id]
            save_data()
        await query.edit_message_text("❌ Tower game ended.")
        return

async def start_actual_tower_game(query, context, game_data):
    """Start actual tower game logic."""
    user_id = str(query.from_user.id)
    bet_amount = game_data['bet_amount']
    difficulty = game_data.get('difficulty', 'medium')
    
    # Initialize game state — generate PF seeds first so the seeded RNG drives layout
    _sta_pf_ss = secrets.token_hex(32)
    _sta_pf_nonce = random.randint(1, 999999)
    _sta_pf_cs = f"{user_id}_{_sta_pf_nonce}"
    _sta_pf_hash = hashlib.sha256(f"{_sta_pf_ss}:{_sta_pf_cs}:{_sta_pf_nonce}".encode()).hexdigest()
    tower_game = TowerGame(user_id=int(user_id), mode=difficulty, bet=float(bet_amount), seed=_sta_pf_hash)
    
    # Track the outcome of the user's choice to display it correctly
    tower_game.user_choices = {} 
    
    game_data.update({
        'type': 'tower',
        'game_instance': tower_game,
        'status': 'playing',
        'msg_id': query.message.message_id,
        'chat_id': query.message.chat_id,
        'pf_server_seed': _sta_pf_ss,
        'pf_client_seed': _sta_pf_cs,
        'pf_nonce': _sta_pf_nonce,
    })
    
    active_games[user_id] = game_data
    save_data()
    
    await show_tower_ui(query, context, tower_game)

async def show_tower_ui(query, context, tower_game):
    """Show the high-quality tower game UI matching reference images."""
    user_id = str(tower_game.user_id)
    user_currency = get_user_currency(user_id)
    
    # Header with premium styling
    current_payout = tower_game.current_payout()
    multiplier = tower_game.current_multiplier()
    
    # Calculate next payout
    next_multiplier = 1.28
    if tower_game.mode == "easy": next_multiplier = 1.18
    elif tower_game.mode == "hard": next_multiplier = 1.45
    next_payout = tower_game.bet * (next_multiplier ** (tower_game.floor + 1))

    # Build the vertical tower grid (10 rows, dynamic columns)
    keyboard = []
    for floor_idx in range(9, -1, -1):
        row = []
        for col_idx in range(tower_game.num_cols()):
            if floor_idx > tower_game.floor:
                # Future floors - locked
                row.append(InlineKeyboardButton("⬜", callback_data="none"))
            elif floor_idx == tower_game.floor and not tower_game.finished:
                # Active floor - playable
                row.append(InlineKeyboardButton("✨", callback_data=f"tower_tile_{col_idx}"))
            else:
                # Past floors - revealed or history
                # Check if this tile was the user's choice
                choice = getattr(tower_game, 'user_choices', {}).get(floor_idx)
                if choice == col_idx:
                    # Reveal what was here
                    val = tower_game.layout[floor_idx][col_idx]
                    row.append(InlineKeyboardButton("🐒" if val else "🐍", callback_data="none"))
                else:
                    row.append(InlineKeyboardButton("⬜", callback_data="none"))
        keyboard.append(row)
    
    # Premium Control Panel
    if not tower_game.finished:
        cashout_text = f"✅ Cash Out: {format_balance_in_currency(current_payout, user_currency)} ({multiplier:.2f}x)"
        keyboard.append([InlineKeyboardButton(cashout_text, callback_data="tower_cashout")])
    else:
        keyboard.append([success_btn("🔄 Play Again", callback_data="back_to_menu")])

    # Dynamic Message Header
    _tw_balance = get_user_balance(user_id)
    message = (
        f'<tg-emoji emoji-id="5472066460006239757">🐒</tg-emoji> <b>Monkey Tower</b>\n\n'
        f'<tg-emoji emoji-id="5127902823542948533">💵</tg-emoji> Bet: <b>{format_balance_in_currency(tower_game.bet, user_currency)}</b>\n'
        f"🏢 Floors: <b>{tower_game.floor}</b>\n"
        f'<tg-emoji emoji-id="5206415568743192168">🏆</tg-emoji> Win: <b>{format_balance_in_currency(current_payout, user_currency)}</b>\n'
        f'<tg-emoji emoji-id="6305046002374024896">💰</tg-emoji> Balance: <b>{format_balance_in_currency(_tw_balance, user_currency)}</b>'
    )
    
    await query.edit_message_text(
        message,
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )


async def start_tower_setup(update: Update, context: ContextTypes.DEFAULT_TYPE, bet_amount: float) -> None:
    """Start tower game setup — pick difficulty then climb 9 floors."""
    if not update.message or not update.message.from_user:
        return
    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)

    # Deduct first — then store setup game (deduct_user_balance clears stale games)
    if user_id in active_games and is_game_actively_playing(active_games[user_id]):
        gname = active_games[user_id].get('type', 'game').replace('_', ' ').title()
        await update.message.reply_text(f"❌ You already have an active <b>{gname}</b> game. Finish it first!", parse_mode=ParseMode.HTML)
        return
    if not deduct_user_balance(user_id, bet_amount):
        bal = get_user_balance(user_id)
        await update.message.reply_text(f"❌ Insufficient balance. You have <b>{format_balance_in_currency(bal, user_currency)}</b>.", parse_mode=ParseMode.HTML)
        return

    add_house_balance(bet_amount)
    track_wagering(user_id, bet_amount, 2.0)

    # Store AFTER deduction so the cleanup doesn't wipe it
    active_games[user_id] = {
        '_created_at': time.time(),
        'type': 'tower_setup',
        'bet_amount': bet_amount,
        'difficulty': 'medium',
        'created_at': time.time()
    }
    save_data()

    keyboard = [
        [
            success_btn("Easy", callback_data="tower_easy"),
            primary_btn("Medium", callback_data="tower_medium"),
            danger_btn("Hard", callback_data="tower_hard"),
        ],
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    await update.message.reply_text(
        "🎮 Choose game difficulty",
        reply_markup=reply_markup,
        parse_mode=ParseMode.HTML
    )

# Player-controlled animated emoji games
class EmojiGameState:
    WAITING_PLAYER_ROLL = "waiting_player_roll"
    WAITING_BOT_ROLL = "waiting_bot_roll"
    ROUND_COMPLETE = "round_complete"
    GAME_COMPLETED = "game_completed"

# New player-controlled dice game
async def show_emoji_game_setup(query, context: ContextTypes.DEFAULT_TYPE, game_type: str, first_to: int = 3, rolls_count: int = 1, bet_amount: float = 0) -> None:
    """Show the unified emoji game setup screen."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)

    game_info = {
        'dice':       {'name': 'Dice',     'emoji': '🎲'},
        'bowling':    {'name': 'Bowling',  'emoji': '🎳'},
        'darts':      {'name': 'Dart',     'emoji': '🎯'},
        'soccer':     {'name': 'Soccer',   'emoji': '⚽'},
        'basketball': {'name': 'Basket',   'emoji': '🏀'},
    }
    info = game_info.get(game_type, game_info['dice'])

    # Round bet to 2 dp to keep callback_data short
    bet_amount = round(float(bet_amount), 2)
    balance_usd = round(get_user_balance(user_id), 2)

    message = (
        f"{info['emoji']} <b>{info['name']}</b>\n"
        f"Match against the bot — highest roll wins each round.\n"
        f"First to <b>{first_to}</b> round(s) wins the match.\n"
        f"Multiplier: <b>1.92x</b> · Winning chance: <b>50%</b>\n\n"
        f"You're betting <b>{format_balance_in_currency(bet_amount, user_currency)}</b>.\n"
        f"{'▶️ Press <b>Start Game</b> to play!' if bet_amount > 0 else '⬇️ Select a bet amount below to start.'}"
    )

    # — Game row —
    game_row = []
    for g_type, g_info in game_info.items():
        label = f"{g_info['emoji']}✅" if g_type == game_type else g_info['emoji']
        cb = f"setup_eg_{g_type}_{first_to}_{rolls_count}_{bet_amount}"
        game_row.append(InlineKeyboardButton(label, callback_data=cb))

    # — First-to row —
    first_to_row = []
    for i in range(1, 6):
        label = f"{i}✅" if i == first_to else str(i)
        cb = f"setup_eg_{game_type}_{i}_{rolls_count}_{bet_amount}"
        first_to_row.append(InlineKeyboardButton(label, callback_data=cb))

    # — Rolls-count row —
    rolls_row = []
    for i in range(1, 4):
        label = f"{i}✅" if i == rolls_count else str(i)
        cb = f"setup_eg_{game_type}_{first_to}_{i}_{bet_amount}"
        rolls_row.append(InlineKeyboardButton(label, callback_data=cb))

    # — Bet-amount row (use raw USD amounts rounded to 2 dp) —
    bet25  = round(balance_usd * 0.25, 2)
    bet50  = round(balance_usd * 0.50, 2)
    bet100 = round(balance_usd, 2)
    bet_row = [
        InlineKeyboardButton("0",    callback_data=f"setup_eg_{game_type}_{first_to}_{rolls_count}_0"),
        InlineKeyboardButton("25%",  callback_data=f"setup_eg_{game_type}_{first_to}_{rolls_count}_{bet25}"),
        InlineKeyboardButton("50%",  callback_data=f"setup_eg_{game_type}_{first_to}_{rolls_count}_{bet50}"),
        InlineKeyboardButton("100%", callback_data=f"setup_eg_{game_type}_{first_to}_{rolls_count}_{bet100}"),
    ]

    keyboard = [
        [InlineKeyboardButton("— Game —", callback_data="noop")],
        game_row,
        [InlineKeyboardButton("— First to —", callback_data="noop")],
        first_to_row,
        [InlineKeyboardButton("— Rolls count —", callback_data="noop")],
        rolls_row,
        [InlineKeyboardButton("— Bet amount —", callback_data="noop")],
        bet_row,
    ]

    # Show Start button only when a bet is set
    if bet_amount > 0:
        start_cb = f"setup_eg_start_{game_type}_{first_to}_{rolls_count}_{bet_amount}"
        keyboard.append([InlineKeyboardButton(
            f"▶️ Start Game — {format_balance_in_currency(bet_amount, user_currency)}",
            callback_data=start_cb
        )])

    keyboard.append([InlineKeyboardButton("⬅️ Back", callback_data="emoji_games_menu")])

    await query.edit_message_text(message, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)

async def clear_all_games_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner command to clear all active games and stuck sessions."""
    if not update.message or not update.message.from_user:
        return
    
    owner_id = int(str(OWNER_ID))
    if update.message.from_user.id != owner_id:
        await update.message.reply_text("❌ Only the owner can use this command.")
        return
        
    global active_games, pending_challenges, active_pvp_games
    count = len(active_games) + len(active_pvp_games)
    active_games.clear()
    active_pvp_games.clear()
    pending_challenges.clear()
    save_data()
    
    await update.message.reply_text(f"✅ Cleared {count} active games and all pending challenges.")
