async def setup_sports_game_bot_mode_with_params(query, context, game_name: str, emoji: str, dice_emoji, params: list) -> None:
    """Handle sports game bot mode - send real animated emojis using dealer bot."""
    user_id = str(query.from_user.id)

    # Atomic duplicate-start guard. Python asyncio is single-threaded; the check
    # and add below have no `await` between them, so they are truly atomic —
    # a second coroutine cannot slip in between even with concurrent_updates=True.
    if user_id in _processing_game_starts:
        try:
            await query.answer("⏳ Already starting your game, please wait…", show_alert=True)
        except Exception:
            pass
        return
    _processing_game_starts.add(user_id)
    try:
        username = query.from_user.username or query.from_user.first_name or "Player"
        user_currency = get_user_currency(user_id)
        balance = get_user_balance(user_id)
        dice_format = params[0] if params else "1d2w"
        bet_amount_input = float(params[1]) if len(params) > 1 else 50
        bet_amount = bet_amount_input

        # Parse dice format
        rolls = 1
        wins_needed = 2
        try:
            if 'd' in dice_format and 'w' in dice_format:
                fp = dice_format.replace('w', '').split('d')
                rolls = int(fp[0])
                wins_needed = int(fp[1])
        except:
            pass

        # Block only genuinely mid-play games; clear stale/setup games
        if user_id in active_games:
            if is_game_actively_playing(active_games[user_id]):
                try:
                    await query.answer("❌ You already have an active game! Finish it first.", show_alert=True)
                except Exception:
                    pass
                return
            else:
                del active_games[user_id]

        if bet_amount < MIN_BET:
            try:
                await query.answer(f"❌ Minimum bet is ${MIN_BET:.2f}", show_alert=True)
            except Exception:
                pass
            return

        if bet_amount > balance:
            try:
                await query.answer("❌ Insufficient balance", show_alert=True)
            except Exception:
                pass
            return

        # Deduct balance — use ultra_secure directly (bypasses game-active block)
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        add_house_balance(bet_amount)

        _mode_char = params[2] if len(params) > 2 else 'n'
        _mode_line = "\nMode: Crazy" if _mode_char == 'c' else ""
        start_msg = (
            f"<b>Match accepted.</b>\n\n"
            f"Player 1: @{username}\n"
            f"Player 2: Bot{_mode_line}\n\n"
            f"<b>{username}, your turn — send {emoji} to roll.</b>\n"
            f"Or tap the button below to let the bot roll first."
        )
        keyboard = [
            [primary_btn("Bot rolls first", callback_data=f"{game_name}_order_bot_{dice_format}_{bet_amount_input}")]
        ]
        start_msg_id = None
        start_msg_chat_id = query.message.chat_id
        try:
            sent = await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=start_msg,
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )
            start_msg_id = sent.message_id
            try:
                await query.message.delete()
            except:
                pass
        except Exception as msg_err:
            logger.error(f"Bot mode start message error: {msg_err}")

        # Normalize dice_emoji
        if hasattr(dice_emoji, 'value'):
            dice_emoji_str = str(dice_emoji.value)
        elif isinstance(dice_emoji, str):
            dice_emoji_str = dice_emoji
        else:
            dice_emoji_str = '🎲'

        # Clean up stale PvP entries for this user
        for pid, gdata in list(active_games.items()):
            if pid != user_id and gdata.get('type') == 'sports_pvp':
                if gdata.get('player1_id') == user_id or gdata.get('player2_id') == user_id:
                    del active_games[pid]

        # Store game state
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': f'sports_{game_name}_bot',
            'game_name': game_name,
            'username': username,
            'emoji': emoji,
            'dice_emoji': dice_emoji_str,
            'bot_last_total': 0,
            'wins_needed': wins_needed,
            'rolls': rolls,
            'bet_amount': bet_amount,
            'player_wins': 0,
            'bot_wins': 0,
            'round': 1,
            'state': EmojiGameState.WAITING_PLAYER_ROLL,
            'player_round_rolls': 0,
            'player_round_total': 0,
            'bot_round_rolls': 0,
            'bot_round_total': 0,
            'chat_id': query.message.chat_id,
            'chat_type': query.message.chat.type,
            'last_active': time.time(),
            'created_at': time.time(),
            'start_msg_id': start_msg_id,
            'start_msg_chat_id': start_msg_chat_id,
        }
        save_data()

        if params and len(params) > 2 and params[2] == "bot":
            await handle_bot_roll_turn(query, context, user_id)

    except Exception as e:
        logger.error(f"Bot mode error: {e}", exc_info=True)
        try:
            await query.answer(f"❌ Error: {str(e)}", show_alert=True)
        except Exception:
            pass
    finally:
        # Always release the guard so the user can start a new game later
        _processing_game_starts.discard(user_id)

async def setup_sports_game_pvp_mode_with_params(query, context, game_name: str, emoji: str, dice_emoji, params: list) -> None:
    """Handle sports game PvP mode with format and bet parameters."""
    try:
        user_id = str(query.from_user.id)
        username = query.from_user.username or query.from_user.first_name or "Player"
        user_currency = get_user_currency(user_id)
        balance = get_user_balance(user_id)
        dice_format = params[0] if params else "1d2w"
        bet_amount = float(params[1]) if len(params) > 1 else 50
        
        if bet_amount > balance:
            try:
                await query.answer(f"❌ Insufficient balance", show_alert=True)
            except Exception:
                pass
            return
        
        # Create PvP challenge
        pending_challenges[f"{user_id}_{game_name}"] = {
            'challenger_id': user_id,
            'challenger_name': query.from_user.first_name or "Player",
            'game': game_name,
            'format': dice_format,
            'bet': bet_amount,
            'created_at': time.time()
        }
        save_data()
        
        await query.edit_message_text(f"<b>PvP Challenge Created!</b>\n\n{game_name.upper()}\nFormat: {dice_format}\nBet: {format_balance_in_currency(bet_amount, user_currency)}\n\nWaiting for opponent...", parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.error(f"PvP mode error: {e}")
        try:
            await query.answer(f"Error: {str(e)}", show_alert=True)
        except Exception:
            pass


# ──────────────────────────────────────────────────────────────────────────────
#  NEW SPORTS SETUP FLOW  (rolls picker → rounds picker → matchmaking)
# ──────────────────────────────────────────────────────────────────────────────
SP_EMOJI  = {'bowling': '🎳', 'darts': '🎯', 'soccer': '⚽', 'basketball': '🏀', 'dice': '🎲'}
SP_DICE   = {'bowling': DiceEmoji.BOWLING, 'darts': DiceEmoji.DARTS,
             'soccer': DiceEmoji.FOOTBALL, 'basketball': DiceEmoji.BASKETBALL, 'dice': DiceEmoji.DICE}

def _sp_mode_params(mode_key: str):
    """Return (rolls, is_crazy, mode_char, display_name, description) for a mode key."""
    if mode_key == 'double':
        return 2, False, 'n', 'Double Roll', (
            "Similar to <b>Normal</b>, but you are rolling 2 dice in a row. "
            "The winner of the round is the one who has the greater sum of the two dice's digits."
        )
    elif mode_key == 'triple':
        return 3, False, 'n', 'Triple Roll', (
            "Roll 3 dice in a row. The winner of the round is the one with the <b>greatest total sum</b> of all three dice."
        )
    elif mode_key == 'crazy':
        return 1, True, 'c', 'Crazy Mode', (
            "Take turns rolling once. The player who scores the <b>LOWEST</b> wins the round."
        )
    elif mode_key == 'crazydbl':
        return 2, True, 'c', 'Crazy Double Roll', (
            "Roll 2 dice in a row. The player with the <b>LOWER</b> total sum wins the round."
        )
    elif mode_key == 'crazytriple':
        return 3, True, 'c', 'Crazy Triple Roll', (
            "Roll 3 dice in a row. The player with the <b>LOWEST</b> total sum wins the round."
        )
    else:  # normal
        return 1, False, 'n', 'Normal Mode', (
            "Take turns rolling once. The player who scores the <b>highest</b> wins the round."
        )

async def handle_sp_mode(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """sp_mode_{sport}_{bet}_{mode_key}  →  show points-to-win picker."""
    try:
        await query.answer()
    except Exception:
        pass
    parts = query.data.split("_")
    sport = parts[2]; bet = parts[3]; mode_key = parts[4]
    emoji = SP_EMOJI.get(sport, '🎲')
    keyboard = [
        [InlineKeyboardButton("First to 3 points", callback_data=f"sp_pts_{sport}_{bet}_{mode_key}_3")],
        [InlineKeyboardButton("First to 2 points", callback_data=f"sp_pts_{sport}_{bet}_{mode_key}_2")],
        [InlineKeyboardButton("First to 1 point",  callback_data=f"sp_pts_{sport}_{bet}_{mode_key}_1")],
        [InlineKeyboardButton("Cancel",            callback_data="sp_cancel")],
    ]
    await query.edit_message_text(
        f"{emoji} Choose the number of points to win",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

async def handle_sp_pts(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """sp_pts_{sport}_{bet}_{mode_key}_{pts}  →  show game confirmation."""
    try:
        await query.answer()
    except Exception:
        pass
    parts = query.data.split("_")
    sport = parts[2]; bet = parts[3]; mode_key = parts[4]; pts = int(parts[5])
    emoji = SP_EMOJI.get(sport, '🎲')
    sport_name = {'bowling': 'Bowling', 'darts': 'Darts', 'soccer': 'Soccer',
                  'basketball': 'Basketball', 'dice': 'Dice'}.get(sport, sport.capitalize())
    user_currency = get_user_currency(str(query.from_user.id))
    bet_f = float(bet)
    rolls, is_crazy, mode_char, mode_display, mode_desc = _sp_mode_params(mode_key)
    pt_label = f"{pts} point{'s' if pts > 1 else ''}"
    keyboard = [
        [InlineKeyboardButton("Confirm", callback_data=f"sp_conf_{sport}_{bet}_{mode_key}_{pts}"),
         InlineKeyboardButton("Cancel",  callback_data="sp_cancel")],
    ]
    await query.edit_message_text(
        f"{emoji} <b>Game confirmation</b>\n\n"
        f"Game: <b>{sport_name} {emoji}</b>\n"
        f"<b>First to {pt_label}</b>\n"
        f"Mode: <b>{mode_display}</b>\n"
        f"Your bet: <b>{format_balance_in_currency(bet_f, user_currency)}</b> 🔥\n"
        f"Win multiplier: <b>1.92x</b>",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )

async def _sp_send_matchmaking(send_fn, context, sport, bet, mode_key, pts_str, user_id, username, user_currency):
    """Build and send the matchmaking message. send_fn is an async callable accepting (text, reply_markup, parse_mode)."""
    emoji = SP_EMOJI.get(sport, '🎲')
    sport_name = {'bowling': 'Bowling', 'darts': 'Darts', 'soccer': 'Soccer',
                  'basketball': 'Basketball', 'dice': 'Dice'}.get(sport, sport.capitalize())
    bet_f = float(bet)
    pts = int(pts_str)
    rolls, is_crazy, mode_char, mode_display, mode_desc = _sp_mode_params(mode_key)
    pt_label = f"{pts} point{'s' if pts > 1 else ''}"
    keyboard = [
        [InlineKeyboardButton("✅ Accept Match",     callback_data=f"sp_pvp_{sport}_{bet}_{rolls}_{pts}_{user_id}_{mode_char}"),
         InlineKeyboardButton("✅ Play against bot", callback_data=f"sp_vsbot_{sport}_{bet}_{rolls}_{pts}_{mode_char}")],
        [InlineKeyboardButton("Cancel",              callback_data="sp_cancel")],
    ]
    text = (
        f"{emoji} <b>{username} wants to play {sport_name}!</b>\n\n"
        f"Bet: <b>{format_balance_in_currency(bet_f, user_currency)}</b> 🔥\n"
        f"Win multiplier: <b>1.92x</b>\n"
        f"Mode: <b>First to {pt_label}</b>\n\n"
        f"<b>{mode_display}</b>\n"
        f"{mode_desc}\n\n"
        f"<i>If you want to play, click the <b>\"Accept Match\"</b> button</i>"
    )
    await send_fn(text=text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)

async def handle_sp_conf(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """sp_conf_{sport}_{bet}_{mode_key}_{pts}  →  show matchmaking screen."""
    try:
        await query.answer()
    except Exception:
        pass
    parts    = query.data.split("_")
    sport    = parts[2]; bet = parts[3]; mode_key = parts[4]; pts_str = parts[5]
    user_id  = str(query.from_user.id)
    username = query.from_user.username or query.from_user.first_name or "Player"
    user_currency = get_user_currency(user_id)
    async def send_fn(**kwargs): await query.edit_message_text(**kwargs)
    await _sp_send_matchmaking(send_fn, context, sport, bet, mode_key, pts_str, user_id, username, user_currency)

async def handle_sp_webapp_data(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle data sent back from game_confirm.html WebApp."""
    if not update.message or not update.message.web_app_data:
        return
    raw = update.message.web_app_data.data
    try:
        data = json.loads(raw)
    except Exception:
        return
    action   = data.get('action', '')
    sport    = data.get('sport', 'dice')
    bet      = data.get('bet', '0')
    mode_key = data.get('mode_key', 'normal')
    pts_str  = str(data.get('pts', '3'))
    if action == 'sp_cancel':
        await update.message.reply_text("❌ Game cancelled.")
        return
    if action == 'sp_conf':
        user_id  = str(update.message.from_user.id)
        username = update.message.from_user.username or update.message.from_user.first_name or "Player"
        user_currency = get_user_currency(user_id)
        async def send_fn(**kwargs): await update.message.reply_text(**kwargs)
        await _sp_send_matchmaking(send_fn, context, sport, bet, mode_key, pts_str, user_id, username, user_currency)

