async def handle_sp_vsbot(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """sp_vsbot_{sport}_{bet}_{rolls}_{rounds}[_{mode}]  →  start vs bot."""
    try:
        await query.answer()
    except Exception:
        pass
    parts   = query.data.split("_")
    sport   = parts[2]; bet = parts[3]; rolls = int(parts[4]); rounds = int(parts[5])
    mode = parts[6] if len(parts) > 6 else 'n'
    emoji   = SP_EMOJI.get(sport, '🎲')
    dice_em = SP_DICE.get(sport, DiceEmoji.DARTS)
    user_id = str(query.from_user.id)
    bet_f   = float(bet)
    fmt     = f"{rolls}d{rounds}w"

    if user_id in active_games:
        if is_game_actively_playing(active_games[user_id]):
            try:
                await query.answer("❌ You're already in a game! Finish it first.", show_alert=True)
            except Exception:
                pass
            return
        else:
            del active_games[user_id]

    await setup_sports_game_bot_mode_with_params(
        query, context, sport, emoji, dice_em, [fmt, str(bet_f), mode]
    )
    # ── Stamp crazy flag onto the freshly created game ──
    if user_id in active_games:
        active_games[user_id]['is_crazy'] = (mode == 'c')

async def handle_sp_pvp(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """sp_pvp_{sport}_{bet}_{rolls}_{rounds}_{challenger_id}  →  accept or create PvP."""
    try:
        await query.answer()
    except Exception:
        pass
    parts         = query.data.split("_")
    sport         = parts[2]; bet = parts[3]; rolls = int(parts[4])
    rounds        = int(parts[5]); challenger_id = parts[6]
    mode          = parts[7] if len(parts) > 7 else 'n'
    emoji         = SP_EMOJI.get(sport, '🎲')
    dice_em       = SP_DICE.get(sport, DiceEmoji.DICE)
    user_id       = str(query.from_user.id)
    username      = query.from_user.username or query.from_user.first_name or "Player"
    user_currency = get_user_currency(user_id)
    bet_f         = float(bet)

    # Challenger presses their own button — just wait
    if user_id == challenger_id:
        try:
            await query.answer("⏳ Waiting for another player to accept…", show_alert=True)
        except Exception:
            pass
        return

    # Double-tap / double-fire guard
    if user_id in _processing_game_starts:
        try:
            await query.answer("⏳ Already accepting, please wait…", show_alert=True)
        except Exception:
            pass
        return
    _processing_game_starts.add(user_id)
    try:
        # Check acceptor balance
        if get_user_balance(user_id) < bet_f:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return

        # Block if either player is mid-game
        for pid in [user_id, challenger_id]:
            if pid in active_games:
                if is_game_actively_playing(active_games[pid]):
                    try:
                        await query.answer("❌ A player is already in an active game!", show_alert=True)
                    except Exception:
                        pass
                    return
                del active_games[pid]

        # Deduct both bets
        if not ultra_secure_deduct_user_balance(user_id, bet_f, "bet"):
            try:
                await query.answer("❌ Failed to deduct your bet!", show_alert=True)
            except Exception:
                pass
            return
        if not ultra_secure_deduct_user_balance(challenger_id, bet_f, "bet"):
            ultra_secure_add_user_balance(user_id, bet_f, "pvp_refund")
            save_data_critical()  # Refund must not vanish on crash
            try:
                await query.answer("❌ Challenger has insufficient balance!", show_alert=True)
            except Exception:
                pass
            return

        add_house_balance(bet_f * 2)

        # Get challenger display name
        try:
            ch_info = await context.bot.get_chat(int(challenger_id))
            ch_name     = ch_info.username or ch_info.first_name or "Player1"
            ch_display  = f"@{ch_info.username}" if ch_info.username else ch_info.first_name
        except:
            ch_name    = "Player1"
            ch_display = "Player 1"

        # Normalise dice emoji to plain string
        dice_emoji_str = str(dice_em.value) if hasattr(dice_em, 'value') else str(dice_em)

        # Build shared PvP game state
        pvp_game = {
            'type': 'sports_pvp',
            'game_name': sport,
            'emoji': emoji,
            'dice_emoji': dice_emoji_str,
            'player1_id': challenger_id,
            'player2_id': user_id,
            'player1_name': ch_name,
            'player2_name': username,
            'rolls_count': rolls,
            'wins_needed': rounds,
            'bet_amount': bet_f,
            'player1_wins': 0,
            'player2_wins': 0,
            'round': 1,
            'current_player': 1,
            'player1_round_rolls': 0,
            'player1_round_total': 0,
            'player2_round_rolls': 0,
            'player2_round_total': 0,
            'chat_id': query.message.chat_id,
            'chat_type': query.message.chat.type,
            'state': EmojiGameState.WAITING_PLAYER_ROLL,
            'is_crazy': (mode == 'c'),
            'last_active': time.time(),
            '_created_at': time.time(),
        }

        # Register under both player IDs
        active_games[challenger_id] = pvp_game
        active_games[user_id]       = pvp_game
        save_data()

        mode_line = "\nMode: Crazy" if (mode == 'c') else ""
        match_text = (
            f"<b>PvP Match Started!</b>\n\n"
            f"Player 1: {ch_display}\n"
            f"Player 2: @{username}{mode_line}\n\n"
            f"Format: {rolls} roll(s) · First to {rounds} wins\n"
            f"Bet: {format_balance_in_currency(bet_f, user_currency)} each\n"
            f"\n"
            f"{ch_display}, your turn! Send {emoji} to roll."
        )
        await query.edit_message_text(match_text, parse_mode=ParseMode.HTML)
    finally:
        _processing_game_starts.discard(user_id)

