async def handle_accept_challenge(query, context: ContextTypes.DEFAULT_TYPE, challenge_id: str) -> None:
    """Handle accepting a PvP challenge."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    username = query.from_user.username or query.from_user.first_name or "Player"

    if challenge_id not in pending_challenges:
        try:
            await query.answer("❌ Challenge expired or not found!", show_alert=True)
        except Exception:
            pass
        return

    challenge = pending_challenges[challenge_id]
    challenger_id = challenge['challenger_id']

    if user_id == challenger_id:
        try:
            await query.answer("❌ You can't accept your own challenge!", show_alert=True)
        except Exception:
            pass
        return

    balance = get_user_balance(user_id)
    bet_amount = challenge['bet_amount']

    if balance < bet_amount:
        try:
            await query.answer(f"❌ Insufficient balance! Need {format_balance_in_currency(bet_amount, user_currency)}", show_alert=True)
        except Exception:
            pass
        return

    # Block if either player is mid-game
    for pid in [user_id, challenger_id]:
        if pid in active_games and is_game_actively_playing(active_games[pid]):
            try:
                await query.answer("❌ A player is already in an active game!", show_alert=True)
            except Exception:
                pass
            return

    # Deduct bets atomically
    if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
        try:
            await query.answer(f"❌ Insufficient balance!", show_alert=True)
        except Exception:
            pass
        return
    if not ultra_secure_deduct_user_balance(challenger_id, bet_amount, "bet"):
        ultra_secure_add_user_balance(user_id, bet_amount, "pvp_refund")
        save_data_critical()  # Refund must not vanish on crash
        try:
            await query.answer("❌ Challenger has insufficient balance!", show_alert=True)
        except Exception:
            pass
        return
    add_house_balance(bet_amount * 2)

    # Parse format
    emoji_map = {'darts': '🎯', 'soccer': '⚽', 'bowling': '🎳', 'basketball': '🏀'}
    dice_emoji_map = {'darts': '🎯', 'soccer': '⚽', 'bowling': '🎳', 'basketball': '🏀'}
    game_type = challenge.get('game_type', 'dice')
    emoji = emoji_map.get(game_type, '🎲')
    dice_emoji = dice_emoji_map.get(game_type, '🎲')

    try:
        fmt = challenge.get('format', '1d2w')
        fp = fmt.replace('w','').split('d')
        rolls_count = int(fp[0]); wins_needed = int(fp[1])
    except Exception:
        rolls_count = 1; wins_needed = 2

    # Build game using sports_pvp type (correct handler routing)
    pvp_game = {
        'type': 'sports_pvp',
        'game_name': game_type,
        'emoji': emoji,
        'dice_emoji': dice_emoji,
        'player1_id': challenger_id,
        'player2_id': user_id,
        'player1_name': challenge['challenger_name'],
        'player2_name': username,
        'rolls_count': rolls_count,
        'wins_needed': wins_needed,
        'bet_amount': bet_amount,
        'player1_wins': 0,
        'player2_wins': 0,
        'player1_round_rolls': 0,
        'player1_round_total': 0,
        'player2_round_rolls': 0,
        'player2_round_total': 0,
        'round': 1,
        'current_player': 1,
        'state': EmojiGameState.WAITING_PLAYER_ROLL,
        'last_active': time.time(),
        '_created_at': time.time(),
    }

    # Register under BOTH player IDs
    active_games[challenger_id] = pvp_game
    active_games[user_id]       = pvp_game

    # Remove challenge
    del pending_challenges[challenge_id]
    save_data()

    game_message = (
        f"<b>PvP Match Started!</b>\n\n"
        f"1️⃣ {challenge['challenger_name']}  vs  2️⃣ @{username}\n"
        f"Format: {rolls_count} roll(s) · First to {wins_needed} wins\n"
        f"Bet: {format_balance_in_currency(bet_amount, user_currency)} each\n\n"
        f"{challenge['challenger_name']}'s turn! Send {emoji}"
    )

    try:
        await context.bot.send_message(int(challenger_id), game_message, parse_mode=ParseMode.HTML)
        await context.bot.send_message(int(user_id),       game_message, parse_mode=ParseMode.HTML)
    except Exception:
        pass

    try:
        await query.answer("✅ Challenge accepted! Game started!", show_alert=True)
    except Exception:
        pass

async def handle_claim_weekly(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle weekly reward claim."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    import datetime
    import time
    
    now = datetime.datetime.now()
    # Weekly claim on Saturday 11 PM
    # weekday() is 0 for Monday, 5 for Saturday
    target_weekday = 5
    target_hour = 23
    
    # Calculate next claim time
    days_ahead = target_weekday - now.weekday()
    if days_ahead < 0 or (days_ahead == 0 and now.hour >= target_hour):
        days_ahead += 7
        
    next_claim = (now + datetime.timedelta(days=days_ahead)).replace(hour=target_hour, minute=0, second=0, microsecond=0)
    delta = next_claim - now
    
    if now.weekday() == target_weekday and now.hour >= target_hour:
        # It's currently claim time (or after) on Saturday
        # check if already claimed this week
        last_claim_time = user_last_weekly_claim.get(user_id, 0)
        last_claim_dt = datetime.datetime.fromtimestamp(last_claim_time)
        if last_claim_dt.date() == now.date():
             try:
                 await query.answer(f"✅ Already claimed today! Next in {delta.days}d {delta.seconds//3600}:{(delta.seconds//60)%60}:{delta.seconds%60}", show_alert=True)
             except Exception:
                 pass
             return
    else:
        try:
            await query.answer(f"❌ Next redeem available in {delta.days}d {delta.seconds//3600}:{(delta.seconds//60)%60}:{delta.seconds%60}", show_alert=True)
        except Exception:
            pass
        return

    weekly_reward_available = user_weekly_rewards.get(user_id, 0.0)
    if weekly_reward_available <= 0:
        try:
            await query.answer("❌ No weekly rewards to claim!", show_alert=True)
        except Exception:
            pass
        return

    ultra_secure_add_user_balance(user_id, weekly_reward_available, "weekly_claim")
    user_weekly_rewards[user_id] = 0.0
    user_last_weekly_claim[user_id] = time.time()
    save_data_critical()
    
    new_balance = get_user_balance(user_id)
    await query.edit_message_text(
        f"🔥 <b>Weekly Reward Claimed!</b>\n\n"
        f"💰 <b>Amount Claimed:</b> {format_balance_in_currency(weekly_reward_available, user_currency)}\n"
        f"📊 <b>New Balance:</b> {format_balance_in_currency(new_balance, user_currency)}\n\n"
        "Keep playing to earn more weekly rewards!",
        parse_mode=ParseMode.HTML
    )

async def handle_claim_rakeback(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle rakeback claim."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    # DOUBLE-CLAIM GUARD: block concurrent taps from both passing the > 0 check
    if user_id in _processing_rakeback:
        try:
            await query.answer("⏳ Processing your claim...", show_alert=True)
        except Exception:
            pass
        return
    _processing_rakeback.add(user_id)

    try:
        rakeback_available = user_losses_rakeback.get(user_id, 0.0)

        import time
        current_time = time.time()
        last_claim_time = user_last_rakeback_claim.get(user_id, 0)
        cooldown_seconds = RAKEBACK_COOLDOWN_HOURS * 3600

        if rakeback_available <= 0:
            try:
                await query.answer("❌ No rakeback to claim!", show_alert=True)
            except Exception:
                pass
            return

        if current_time - last_claim_time < cooldown_seconds:
            remaining_hours = (cooldown_seconds - (current_time - last_claim_time)) / 3600
            try:
                await query.answer(f"✅ Wait {remaining_hours:.1f} more hours", show_alert=True)
            except Exception:
                pass
            return

        ultra_secure_add_user_balance(user_id, rakeback_available, "rakeback_claim")
        user_losses_rakeback[user_id] = 0.0
        user_last_rakeback_claim[user_id] = current_time
        save_data_critical()
    finally:
        _processing_rakeback.discard(user_id)

    new_balance = get_user_balance(user_id)

    await query.edit_message_text(
        f"🔥 <b>Rakeback Claimed!</b>\n\n"
        f"💸 <b>Amount Claimed:</b> {format_balance_in_currency(rakeback_available, user_currency)}\n"
        f"💰 <b>New Balance:</b> {format_balance_in_currency(new_balance, user_currency)}\n\n"
        f"✅ <b>Next Claim:</b> Available in 24 hours\n\n"
        "Keep playing to earn more rakeback from losses!",
        parse_mode=ParseMode.HTML
    )

async def handle_claim_referral_commission(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle referral commission claim."""
    global crypto_house_balances
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    pending_commission = pending_referral_commissions.get(user_id, 0.0)

    if pending_commission <= 0:
        try:
            await query.answer("❌ No commission to claim!", show_alert=True)
        except Exception:
            pass
        return

    # Only pay commission if house has sufficient funds
    if house_balance < pending_commission:
        try:
            await query.answer("❌ Insufficient house balance. Try again later.", show_alert=True)
        except Exception:
            pass
        return

    # Deduct from house balance (marketing expense) and add to user balance
    deduct_house_balance(pending_commission)  # CRITICAL: Use function to ensure save_data()
    ultra_secure_add_user_balance(str(user_id), pending_commission, "referral_commission")

    # Track total referral earnings
    if user_id not in referral_earnings:
        referral_earnings[user_id] = 0.0
    referral_earnings[user_id] += pending_commission

    # Reset pending commission
    pending_referral_commissions[user_id] = 0.0
    save_data_critical()  # Commission credit must survive crash

    new_balance = get_user_balance(user_id)

    await query.edit_message_text(
        f"🔥 <b>Referral Commission Claimed!</b>\n\n"
        f"💰 <b>Amount Claimed:</b> {format_balance_in_currency(pending_commission, user_currency)}\n"
        f"📊 <b>New Balance:</b> {format_balance_in_currency(new_balance, user_currency)}\n\n"
        "Keep sharing your referral link to earn more!",
        parse_mode=ParseMode.HTML
    )

# PvP Dice Challenge Handler
async def handle_dice_pvp_challenge(query: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle PvP dice challenge selection with accept button."""
    data = query.data  # e.g., "dice_pvp_1d2w_50"
    parts = data.replace("dice_pvp_", "").split("_")
    
    if len(parts) < 2:
        return
    
    dice_format = parts[0]  # e.g., "1d2w"
    bet_amount = float(parts[1])  # e.g., "50"
    challenger_id = str(query.from_user.id)
    challenger_name = query.from_user.first_name or "Player"
    
    # Parse dice format
    try:
        format_parts = dice_format.replace('w', '').split('d')
        rolls = int(format_parts[0])
        wins = int(format_parts[1])
    except:
        return
    
    # Create accept button for other players
    accept_keyboard = [
        [InlineKeyboardButton("✅ Accept Challenge", callback_data=f"accept_dice_pvp_{challenger_id}_{dice_format}_{bet_amount}")]
    ]
    accept_markup = InlineKeyboardMarkup(accept_keyboard)
    
    # Post challenge message
    challenge_msg = (
        f"<b>PvP CHALLENGE</b>\n\n"
        f"<b>Challenger:</b> {challenger_name}\n"
        f"<b>Match:</b> {rolls}d{wins}w\n"
        f"<b>Bet:</b> {bet_amount}\n\n"
        f"<b>Prize:</b> Winner claims both bets!\n\n"
        f"Click to accept!"
    )
    
    await query.edit_message_text(
        challenge_msg,
        reply_markup=accept_markup,
        parse_mode=ParseMode.HTML
    )
    
    # Store challenge info
    pending_challenges[f"{challenger_id}_dice"] = {
        'challenger_id': challenger_id,
        'challenger_name': challenger_name,
        'dice_format': dice_format,
        'bet_amount': bet_amount,
        'created_at': time.time()
    }
    save_data()

# Callback handlers
async def handle_bot_roll_turn(update, context: ContextTypes.DEFAULT_TYPE, user_id: str) -> None:
    """Bot rolls for the current round, then tells player it's their turn."""
    if user_id not in active_games:
        logger.warning(f"[BOT_ROLL_DIAG] user {user_id} not in active_games on entry")
        return

    game_data = active_games[user_id]
    chat_id = game_data.get('chat_id')
    chat_type = game_data.get('chat_type', 'private')
    rolls_count = int(game_data.get('rolls', 1))
    bot_roll_emoji = game_data.get('dice_emoji', '🎲')
    username = game_data.get('username', 'Player')

    logger.info(
        f"[BOT_ROLL_DIAG] entry user={user_id} type={game_data.get('type')} "
        f"state={game_data.get('state')} chat_id={chat_id} chat_type={chat_type} "
        f"rolls={rolls_count} emoji={bot_roll_emoji!r} is_crazy={game_data.get('is_crazy')}"
    )

    # Set rolling lock BEFORE any await to prevent concurrent re-entry.
    # The guard at handle_order_selection checks bot_rolling_active; if it's
    # False during the asyncio.sleep(2.0) phase the guard misses re-entry.
    game_data['bot_rolling_active'] = True
    game_data['bot_round_total'] = 0
    game_data['bot_round_rolls'] = 0

    try:
        bot_total = 0
        for ridx in range(rolls_count):
            msg = None
            timed_out = False
            try:
                msg = await asyncio.wait_for(
                    dealer_send_dice(
                        chat_id=chat_id, emoji=bot_roll_emoji,
                        main_bot=context.bot, chat_type=chat_type,
                        user_id=int(user_id)
                    ),
                    timeout=20.0
                )
                logger.info(f"[BOT_ROLL_DIAG] dealer_send_dice #{ridx+1} returned msg={msg!r}")
            except asyncio.TimeoutError:
                # Telegram likely already accepted the dice send — DO NOT fallback,
                # otherwise the user sees a duplicate dice. Use a random value instead.
                timed_out = True
                logger.warning(f"[BOT_ROLL_DIAG] dealer_send_dice #{ridx+1} TIMEOUT")
            except Exception as e:
                logger.error(f"[BOT_ROLL_DIAG] dealer_send_dice #{ridx+1} EXCEPTION: {e}", exc_info=True)
            if msg and hasattr(msg, 'dice') and msg.dice:
                val = int(msg.dice.value)
            elif timed_out:
                val = random.randint(1, 6)
            else:
                # dealer_send_dice truly returned None — send a visible dice as fallback
                try:
                    fb = await asyncio.wait_for(
                        context.bot.send_dice(chat_id=chat_id, emoji=bot_roll_emoji),
                        timeout=20.0
                    )
                    val = int(fb.dice.value)
                    logger.info(f"[BOT_ROLL_DIAG] fallback context.bot.send_dice ok val={val}")
                except Exception as e:
                    val = random.randint(1, 6)
                    logger.error(f"[BOT_ROLL_DIAG] fallback context.bot.send_dice failed: {e}", exc_info=True)
            bot_total += val
            game_data['bot_round_rolls'] = game_data.get('bot_round_rolls', 0) + 1

        game_data['bot_round_total'] = bot_total
        game_data['bot_has_rolled'] = True
        game_data['state'] = EmojiGameState.WAITING_PLAYER_ROLL
        active_games[user_id] = game_data
        save_data()

        # Clear any stale auto-roll lock so player's manual dice is accepted
        game_data['auto_rolling_player'] = False
        active_games[user_id] = game_data
        save_data()
        logger.info(
            f"[BOT_ROLL_DIAG] bot rolls done user={user_id} bot_total={bot_total} "
            f"state set to WAITING_PLAYER_ROLL"
        )
        # Telegram already displays the animation in the chat. Prompt quickly
        # after the API response so the player can roll immediately.
        await asyncio.sleep(0.35)
        # Clear rolling lock AFTER the animation wait completes.  Clearing it
        # before the sleep would allow a button press during the 2-second wait
        # to start a second concurrent handle_bot_roll_turn.
        game_data['bot_rolling_active'] = False
        if user_id in active_games:
            active_games[user_id]['bot_rolling_active'] = False
        # Guard: game may have ended (player rolled during sleep) — only prompt if still active
        _gd_check = active_games.get(user_id)
        if _gd_check and _gd_check.get('state') == EmojiGameState.WAITING_PLAYER_ROLL:
            await context.bot.send_message(
                chat_id=chat_id,
                text=_rc_turn_text(game_data.get('game_name', 'dice'), user_id, username),
                parse_mode=ParseMode.HTML,
                reply_markup=_rc_player_turn_keyboard(game_data.get('game_name', 'dice'), user_id),
            )
            logger.info(f"[BOT_ROLL_DIAG] sent 'your turn' message to user={user_id}")
        else:
            logger.info(f"[BOT_ROLL_DIAG] skipped 'your turn' — game ended during sleep (user={user_id})")
    except Exception as e:
        logger.error(f"[BOT_ROLL_DIAG] handle_bot_roll_turn error: {e}", exc_info=True)
        # Even on failure, unlock and set WAITING_PLAYER_ROLL so game isn't stuck
        game_data['bot_has_rolled'] = True
        game_data['state'] = EmojiGameState.WAITING_PLAYER_ROLL
        game_data['bot_rolling_active'] = False
        game_data['auto_rolling_player'] = False
        if user_id in active_games:
            active_games[user_id] = game_data
            save_data()

async def auto_player_roll_and_process(context, user_id: str, chat_id: int) -> None:
    """Automatically roll player's dice via dealer bot and process game result — no manual send needed."""
    await asyncio.sleep(0.5)  # Brief pause so bot dice animation finishes first

    if user_id not in active_games:
        return
    game_data = active_games[user_id]
    if game_data.get('state') != EmojiGameState.WAITING_PLAYER_ROLL:
        return
    # Lock so manual dice messages are ignored during auto-roll
    game_data['auto_rolling_player'] = True
    active_games[user_id] = game_data

    rolls_count = int(game_data.get('rolls', 1))
    emoji = game_data.get('dice_emoji', '🎲')
    chat_type = game_data.get('chat_type', 'private')
    username = game_data.get('username', 'Player')
    game_name = game_data.get('game_name', 'dice')
    game_type = game_data.get('type', '')
    bet_amount = float(game_data.get('bet_amount', 0))
    wins_needed = int(game_data.get('wins_needed', 3))
    user_currency = get_user_currency(user_id)
    bot_total = int(game_data.get('bot_round_total', 0))

    # Roll player's dice automatically
    player_total = 0
    for _ in range(rolls_count):
        msg = None
        timed_out = False
        try:
            msg = await asyncio.wait_for(
                dealer_send_dice(
                    chat_id=chat_id, emoji=emoji,
                    main_bot=context.bot, chat_type=chat_type,
                    user_id=int(user_id)
                ),
                timeout=20.0
            )
        except asyncio.TimeoutError:
            timed_out = True
        except Exception:
            pass
        if msg and hasattr(msg, 'dice') and msg.dice:
            val = int(msg.dice.value)
        elif timed_out:
            val = random.randint(1, 6)
        else:
            try:
                fb = await asyncio.wait_for(
                    context.bot.send_dice(chat_id=chat_id, emoji=emoji),
                    timeout=20.0
                )
                val = int(fb.dice.value)
            except Exception:
                val = random.randint(1, 6)
        player_total += val
        await asyncio.sleep(0.15)

    # Wait for the last player dice animation to finish before showing result
    await asyncio.sleep(3.5)

    # Refresh game state (may have changed during awaits)
    if user_id not in active_games:
        return
    game_data = active_games[user_id]
    game_data['player_round_total'] = player_total
    game_data['player_round_rolls'] = rolls_count

    # Handle tie — replay round
    if player_total == bot_total:
        await context.bot.send_message(
            chat_id=chat_id,
            text=_rc_same_values_text(game_name, user_id, username, player_total),
            parse_mode=ParseMode.HTML
        )
        game_data['player_round_rolls'] = 0
        game_data['player_round_total'] = 0
        game_data['bot_round_total'] = 0
        game_data['bot_round_rolls'] = 0
        game_data['bot_has_rolled'] = False
        game_data['bot_rolling_active'] = False
        game_data['state'] = EmojiGameState.WAITING_BOT_ROLL
        active_games[user_id] = game_data
        save_data()
        await handle_bot_roll_turn_by_id(context, user_id, chat_id)
        return

    is_crazy = bool(game_data.get('is_crazy', False))
    player_won_round = (player_total < bot_total) if is_crazy else (player_total > bot_total)
    if player_won_round:
        game_data['player_wins'] = int(game_data.get('player_wins', 0)) + 1
    else:
        game_data['bot_wins'] = int(game_data.get('bot_wins', 0)) + 1

    player_wins = int(game_data.get('player_wins', 0))
    bot_wins = int(game_data.get('bot_wins', 0))
    score_line = (
        f"{_rc_tag('👤')} @{username}: <b>{player_wins}</b>\n"
        f"{_rc_tag('🤖')} Bot: <b>{bot_wins}</b>"
    )
    active_games[user_id] = game_data
    save_data()

    # Check match end
    if player_wins >= wins_needed or bot_wins >= wins_needed:
        # ── Atomically remove game FIRST, then pay — never save between the two ──
        active_games.pop(user_id, None)

        if player_wins >= wins_needed:
            payout = round(bet_amount * 1.92, 2)
            pre_bal = get_user_balance(user_id)
            ultra_secure_add_user_balance(user_id, payout, "win")
            save_data_critical()                       # ← persist balance immediately
            post_bal = get_user_balance(user_id)
            logger.info(f"✅ WIN PAID: {user_id} {pre_bal:.2f}→{post_bal:.2f} (+{payout:.2f}) game={game_name}")
            deduct_house_balance(payout - bet_amount)
            add_match_history(user_id, game_name, bet_amount, 'win', payout)
            track_wagering(user_id, bet_amount, 1.92)
            await announce_win_to_channel(context, username, payout, game_name.title(), multiplier=1.92, bet=bet_amount, user_id=user_id)

            try:
                await _send_bot_lose_sticker(context, update.effective_chat.id)
            except Exception:
                pass
            _r1_won = True; _r1_amt = payout; _r1_wpts = player_wins; _r1_lpts = bot_wins; _r1_uc = user_currency
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            add_match_history(user_id, game_name, bet_amount, 'loss', 0)
            track_wagering(user_id, bet_amount, 0)
            save_data_critical()
            _r1_won = False; _r1_amt = bet_amount; _r1_wpts = bot_wins; _r1_lpts = player_wins; _r1_uc = user_currency

        dice_format = f"{rolls_count}d{wins_needed}w"
        mode_char = 'c' if is_crazy else 'n'
        await _send_game_result_msg(
            context, chat_id,
            player_won=_r1_won,
            player_name=username, player_id=user_id,
            winner_pts=_r1_wpts, loser_pts=_r1_lpts,
            amount=_r1_amt, user_currency=_r1_uc,
            reply_markup=_rc_end_keyboard(game_name, dice_format, bet_amount, mode_char)
        )
        return

    # Game continues — show score and cashout option, then start next round
    if player_wins > bot_wins:
        cashout_ratio = 0.4 + (player_wins / wins_needed) * 0.7
    elif player_wins == bot_wins:
        total_rounds = player_wins + bot_wins
        cashout_ratio = 0.25 + (total_rounds / (wins_needed * 2)) * 0.3
    else:
        cashout_ratio = 0.1 + (player_wins / wins_needed) * 0.2
    cashout_amount = round(bet_amount * cashout_ratio, 2)
    game_data['current_cashout'] = cashout_amount
    active_games[user_id] = game_data
    save_data()

    co_kb = [[success_btn(
        f"Cashout {format_balance_in_currency(cashout_amount, user_currency)}",
        callback_data="cashout_animated"
    )]]
    await context.bot.send_message(
        chat_id=chat_id,
        text=f"{_rc_tag('📈')} <b>SCORE</b>\n\n{score_line}\n\n"
             f"{_rc_tag('🎲')} Next round starts now.",
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(co_kb)
    )

    # Reset for next round and auto-trigger bot roll
    game_data['player_round_rolls'] = 0
    game_data['player_round_total'] = 0
    game_data['bot_round_total'] = 0
    game_data['bot_round_rolls'] = 0
    game_data['bot_has_rolled'] = False
    game_data['bot_rolling_active'] = False
    game_data['state'] = EmojiGameState.WAITING_BOT_ROLL
    active_games[user_id] = game_data
    save_data()
    await asyncio.sleep(0.2)
    await handle_bot_roll_turn_by_id(context, user_id, chat_id)


