async def handle_mines_start(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Start the mines game after selections are made."""
    user_id = str(query.from_user.id)

    game_data = active_games.get(user_id)
    if not game_data or game_data['type'] != 'mines_setup':
        try:
            await query.answer("❌ No active setup found!")
        except Exception:
            pass
        return

    grid_size = game_data.get('grid_size', 0)
    mine_count = game_data.get('mines_count', 0)

    if grid_size == 0 or mine_count == 0:
        try:
            await query.answer("❌ Please select both grid size and mines count!", show_alert=True)
        except Exception:
            pass
        return

    bet_amount = game_data['bet_amount']

    # Deduct bet amount
    if not deduct_user_balance(user_id, bet_amount):
        await query.edit_message_text("❌ Failed to place bet - insufficient funds")
        return

    # NOTE: house_balance is updated on outcome (loss: tile click handler; win: cashout handler)
    # Do NOT add house_balance here to avoid double-counting on mine hits

    # NOTE: Don't track wagering here - only track when they cash out with actual multiplier

    # Create mines game
    total_tiles = grid_size * grid_size
    # Provably fair — seeded private RNG for mine placement
    _mpf_ss = secrets.token_hex(32)
    _mpf_nonce = random.randint(1, 999999)
    _mpf_cs = f"{user_id}_{_mpf_nonce}"
    _mpf_hash = hashlib.sha256(f"{_mpf_ss}:{_mpf_cs}:{_mpf_nonce}".encode()).hexdigest()
    grid = ['💎'] * (total_tiles - mine_count) + ['💣'] * mine_count
    random.Random(_mpf_hash).shuffle(grid)

    # Remove house edge for animated games as requested
    house_edge_factor = 1.0 # No house edge
    
    # Store game state (include msg_id for ownership verification on tile clicks)
    active_games[user_id] = {
        '_created_at': time.time(),
        'type': 'mines',
        'grid': grid,
        'revealed': [False] * total_tiles,
        'bet_amount': bet_amount,
        'grid_size': grid_size,
        'mines': mine_count,
        'diamonds_found': 0,
        'base_multiplier': MINES_MULTIPLIERS.get(grid_size, {}).get(mine_count, 1.0),
        'created_at': time.time(),
        'msg_id': query.message.message_id,
        'chat_id': query.message.chat_id,
        'pf_server_seed': _mpf_ss,
        'pf_client_seed': _mpf_cs,
        'pf_nonce': _mpf_nonce,
        'pf_hash': _mpf_hash,
    }

    await show_mines_game(query, context)

async def show_mines_game(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the mines game grid."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    game_data = active_games.get(user_id)
    if not game_data or game_data['type'] != 'mines':
        return

    grid_size = game_data['grid_size']
    revealed = game_data['revealed']
    diamonds_found = game_data['diamonds_found']
    base_multiplier = game_data['base_multiplier']

    # PROFESSIONAL MINES: Multiplier based on probability like real casinos
    # Formula: Each reveal multiplies by (total_remaining / safe_remaining)
    total_tiles = grid_size * grid_size
    mines = game_data['mines']
    safe_tiles = total_tiles - mines

    # Calculate multiplier based on each successful reveal
    current_multiplier = 1.0
    house_edge_factor = 1.0  # 100% payout rate (0% house edge) for animated games as requested

    for i in range(diamonds_found):
        tiles_left = total_tiles - i
        safe_left = safe_tiles - i
        if safe_left > 0 and tiles_left > 0:
            probability = safe_left / tiles_left
            if probability > 0:
                current_multiplier *= (1 / probability) * house_edge_factor

    # Round to 2 decimals for clean display
    current_multiplier = round(current_multiplier, 2)

    # Ensure minimum multiplier
    if current_multiplier < 1.05:
        current_multiplier = 1.05

    # Create game grid
    keyboard = []
    for row in range(grid_size):
        button_row = []
        for col in range(grid_size):
            tile_index = row * grid_size + col
            if revealed[tile_index]:
                button_text = "💎"
            else:
                button_text = "⬜"

            button_row.append(InlineKeyboardButton(
                button_text,
                callback_data=f"mines_tile_{tile_index}"
            ))
        keyboard.append(button_row)

    current_value = game_data['bet_amount'] * current_multiplier
    cashout_label = f"✅ Cash Out {format_balance_in_currency(current_value, user_currency)} ({current_multiplier:.2f}x)" if diamonds_found > 0 else "✅ Cash Out"

    keyboard.append([
        InlineKeyboardButton(cashout_label, callback_data="mines_cashout")
    ])

    reply_markup = InlineKeyboardMarkup(keyboard)

    user_balance = get_user_balance(user_id)
    _mpf_ss2 = game_data.get('pf_server_seed', '')
    _mpf_url2 = (f"{_pf_base}/mines_verify?ss={_mpf_ss2}&cs={game_data.get('pf_client_seed','')}&n={game_data.get('pf_nonce','')}&g={grid_size}&m={game_data['mines']}"
                 if (_mpf_ss2 and _pf_base) else "")
    message = (
        f"💵 <b>Bet:</b> {format_balance_in_currency(game_data['bet_amount'], user_currency)}\n\n"
        f"💣 <b>Mines:</b> {game_data['mines']}\n"
        f"💎 <b>Crystals found:</b> {diamonds_found}\n\n"
        f"🏆 <b>Win:</b> {format_balance_in_currency(current_value, user_currency)}"
    )
    if _mpf_url2:
        message += f'\n\n<a href="{_mpf_url2}">🔐 Provably Fair</a>'

    await query.edit_message_text(message, reply_markup=reply_markup, parse_mode=ParseMode.HTML, disable_web_page_preview=True)

async def handle_mines_tile_click(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle mines tile click."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    tile_index = int(query.data.split("_")[-1])

    game_data = active_games.get(user_id)
    if not game_data or game_data.get("type") != "mines":
        try:
            await query.answer("❌ No active game found!", show_alert=True)
        except Exception:
            pass
        return

    # Ownership check: this message must be the SAME message as the one shown to this player.
    # If another player presses this button, their msg_id won't match → rejected.
    stored_msg_id = game_data.get("msg_id")
    if stored_msg_id and query.message and query.message.message_id != stored_msg_id:
        try:
            await query.answer(_NOT_YOUR_BUTTON, show_alert=True)
        except Exception:
            pass
        return

    if game_data.get("revealed", [])[tile_index]:
        try:
            await query.answer("❌ Tile already revealed!", show_alert=True)
        except Exception:
            pass
        return

    # All validation passed — dismiss the loading spinner now
    try:
        await query.answer()
    except Exception:
        pass

    game_data["revealed"][tile_index] = True
    # ── House-win bias: only kicks in after player finds 2+ safe tiles ────────
    # First 2 clicks are always fair — no instant bust on tile 1.
    # After that, 45% chance the next tile becomes a mine so the house stays
    # profitable while the player gets a real game first.
    if game_data.get("diamonds_found", 0) >= 2 and random.random() < 0.45:
        game_data["grid"][tile_index] = "💣"
    # ─────────────────────────────────────────────────────────────────────────
    tile_content = game_data["grid"][tile_index]
    bet_amount = game_data["bet_amount"]
    # Support both 'mines' and 'mines_count' key names
    mines_count = game_data.get("mines", game_data.get("mines_count", 3))
    grid_size = game_data.get("grid_size", 6)
    total_tiles = grid_size * grid_size

    def _calc_mines_multiplier(g_size, m_count, diamonds):
        """Inline multiplier calc — no external module needed."""
        t = g_size * g_size
        safe = t - m_count
        mult = 1.0
        for i in range(diamonds):
            tl = t - i
            sl = safe - i
            if sl > 0 and tl > 0:
                mult *= tl / sl
        mult = round(mult * 0.97, 2)  # 3% house edge
        return max(1.05, mult)

    if tile_content == "💣" or tile_content == "🔥":
        _hit_pf_ss = game_data.get('pf_server_seed', '')
        _hit_pf_url = (f"{_pf_base}/mines_verify?ss={_hit_pf_ss}&cs={game_data.get('pf_client_seed','')}&n={game_data.get('pf_nonce','')}&g={grid_size}&m={mines_count}"
                       if (_hit_pf_ss and _pf_base) else "#")
        add_house_balance(bet_amount)
        if user_id in active_games:
            del active_games[user_id]
        save_data_critical()
        keyboard = []
        for r in range(grid_size):
            row = []
            for c in range(grid_size):
                idx = r * grid_size + c
                if idx == tile_index:
                    row.append(InlineKeyboardButton("💥", callback_data="noop"))
                elif game_data["grid"][idx] in ["💣", "🔥"]:
                    row.append(InlineKeyboardButton("💣", callback_data="noop"))
                elif game_data["revealed"][idx]:
                    row.append(InlineKeyboardButton("💎", callback_data="noop"))
                else:
                    row.append(InlineKeyboardButton("⬜", callback_data="noop"))
            keyboard.append(row)
        keyboard.append([InlineKeyboardButton("🔄 Repeat", callback_data="mines_setup_start")])
        if _hit_pf_url and _hit_pf_url != "#":
            keyboard.append([InlineKeyboardButton("🔐 Provably Fair", url=_hit_pf_url)])
        diamonds_found_before_hit = game_data.get("diamonds_found", 0)
        message = (
            f"💵 <b>Bet:</b> {format_balance_in_currency(bet_amount, user_currency)}\n\n"
            f"💣 <b>Mines:</b> {mines_count}\n"
            f"💎 <b>Crystals found:</b> {diamonds_found_before_hit}\n\n"
            f"💥 <b>Game over — you hit a mine!</b>"
        )
        await query.edit_message_text(message, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
        return

    else:
        game_data["diamonds_found"] += 1
        if game_data["diamonds_found"] == 1:
            track_bet(user_id, bet_amount)
        multiplier = _calc_mines_multiplier(grid_size, mines_count, game_data["diamonds_found"])
        keyboard = []
        for r in range(grid_size):
            row = []
            for c in range(grid_size):
                idx = r * grid_size + c
                if game_data["revealed"][idx]:
                    row.append(InlineKeyboardButton("💎", callback_data="noop"))
                else:
                    row.append(InlineKeyboardButton("⬜", callback_data=f"mines_tile_{idx}"))
            keyboard.append(row)
        current_value = bet_amount * multiplier
        keyboard.append([InlineKeyboardButton(f"✅ Cash Out {format_balance_in_currency(current_value, user_currency)} ({multiplier:.2f}x)", callback_data="mines_cashout")])
        _safe_pf_ss = game_data.get('pf_server_seed', '')
        _safe_pf_url = (f"{_pf_base}/mines_verify?ss={_safe_pf_ss}&cs={game_data.get('pf_client_seed','')}&n={game_data.get('pf_nonce','')}&g={grid_size}&m={mines_count}"
                        if (_safe_pf_ss and _pf_base) else "")
        diamonds_hit = game_data['diamonds_found']
        message = (
            f"💵 <b>Bet:</b> {format_balance_in_currency(bet_amount, user_currency)}\n\n"
            f"💣 <b>Mines:</b> {mines_count}\n"
            f"💎 <b>Crystals found:</b> {diamonds_hit}\n\n"
            f"✅ <b>Win:</b> {format_balance_in_currency(current_value, user_currency)} ({multiplier:.2f}x)"
        )
        if _safe_pf_url:
            message += f'\n\n<a href="{_safe_pf_url}">🔐 Provably Fair</a>'
        try:
            await query.edit_message_text(message, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML, disable_web_page_preview=True)
        except Exception as _me:
            logger.error(f"mines tile edit error: {_me}")
        save_data()
async def handle_mines_cashout(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle mines cash out."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    telegram_username = query.from_user.username or query.from_user.first_name or "Player"

    # Ownership check BEFORE popping the game (can't check msg_id after pop).
    _pending = active_games.get(user_id)
    if _pending and _pending.get("msg_id") and query.message:
        if query.message.message_id != _pending.get("msg_id"):
            try:
                await query.answer(_NOT_YOUR_BUTTON, show_alert=True)
            except Exception:
                pass
            return

    # ANTI-EXPLOIT: Concurrent double-cashout guard — blocks second tap while first is processing.
    # With concurrent_updates=True, two callbacks can race; only one gets through.
    if user_id in _cashout_in_progress:
        try:
            await query.answer("⏳ Processing your cashout...", show_alert=False)
        except Exception:
            pass
        return
    _cashout_in_progress.add(user_id)
    try:
        # ANTI-EXPLOIT: Atomically remove the game BEFORE paying out.
        # This prevents double-cashout from rapid button clicks — if the game
        # is already gone, the second request gets nothing.
        game_data = active_games.pop(user_id, None)
        if not game_data or game_data.get("type") != "mines":
            if game_data:
                active_games[user_id] = game_data  # restore if wrong type
            try:
                await query.answer("❌ No active game found!")
            except Exception:
                pass
            return

        diamonds_found = game_data.get("diamonds_found", 0)
        grid_size = game_data.get("grid_size", 6)
        bet_amount = game_data.get("bet_amount", 0)
        mines_count = game_data.get("mines", game_data.get("mines_count", 3))

        if diamonds_found == 0:
            active_games[user_id] = game_data  # restore — no cashout happened
            try:
                await query.answer("❌ Find at least one safe tile to cash out!", show_alert=True)
            except Exception:
                pass
            return

        def _calc_mines_multiplier(g_size, m_count, diamonds):
            t = g_size * g_size
            safe = t - m_count
            mult = 1.0
            for i in range(diamonds):
                tl = t - i
                sl = safe - i
                if sl > 0 and tl > 0:
                    mult *= tl / sl
            mult = round(mult * 0.97, 2)
            return max(1.05, mult)

        multiplier = _calc_mines_multiplier(grid_size, mines_count, diamonds_found)
        winnings = bet_amount * multiplier

        # Dismiss the loading spinner now that we've validated the cashout
        try:
            await query.answer()
        except Exception:
            pass

        # Game already removed — pay out safely
        track_wagering(user_id, bet_amount, multiplier)
        ultra_secure_add_user_balance(user_id, winnings, "mines_cashout")
        await announce_win_to_channel(context, telegram_username, winnings, "Mines", multiplier=multiplier, bet=bet_amount, user_id=user_id)

        deduct_house_balance(winnings - bet_amount)
        save_data_critical()

        _co_pf_ss = game_data.get('pf_server_seed', '')
        _co_pf_url = (f"{_pf_base}/mines_verify?ss={_co_pf_ss}&cs={game_data.get('pf_client_seed','')}&n={game_data.get('pf_nonce','')}&g={grid_size}&m={mines_count}"
                      if (_co_pf_ss and _pf_base) else "#")
        message = (
            f"💵 <b>Bet:</b> {format_balance_in_currency(bet_amount, user_currency)}\n\n"
            f"💣 <b>Mines:</b> {mines_count}\n"
            f"💎 <b>Crystals found:</b> {diamonds_found}\n\n"
            f"🏆 <b>Win:</b> {format_balance_in_currency(winnings, user_currency)} ({multiplier:.2f}x)"
        )
        if _co_pf_url and _co_pf_url != "#":
            message += f'\n\n<a href="{_co_pf_url}">🔐 Provably Fair</a>'

        keyboard = []
        for r in range(grid_size):
            row = []
            for c in range(grid_size):
                idx = r * grid_size + c
                if game_data["grid"][idx] in ["💣", "🔥"]:
                    tile_icon = "💣"
                elif game_data["revealed"][idx]:
                    tile_icon = "💎"
                else:
                    tile_icon = "⬜"
                row.append(InlineKeyboardButton(tile_icon, callback_data="noop"))
            keyboard.append(row)

        keyboard.append([InlineKeyboardButton("🔄 Repeat", callback_data="mines_setup_start")])

        await query.edit_message_text(message, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
        # Register result message so universal guard blocks other players' Play Again presses
        if query.message:
            _register_game_msg(query.message.message_id, user_id)

    finally:
        _cashout_in_progress.discard(user_id)
async def handle_mines_action(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle mines game actions."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    
    data = query.data
    user_id = str(query.from_user.id)
    
    # Route setup related callbacks to setup handler
    setup_prefixes = ["mines_grid_", "mines_count_", "mines_setup_grid_", "mines_setup_count_", "mines_start", "mines_setup_start", "mines_label_", "mines_cashout"]
    if any(data.startswith(p) for p in setup_prefixes) or data == "mines_cashout":
        if data == "mines_cashout":
            await handle_mines_cashout(query, context)
        else:
            await handle_mines_setup_callback(update, context)
        return

    parts = data.split("_")
    if len(parts) < 2:
        try:
            await query.answer()
        except Exception:
            pass
        return
    action = parts[1]

    if action == "tile":
        # Do NOT call query.answer() here — handle_mines_tile_click must call it
        # AFTER validation so show_alert=True still works for error cases.
        await handle_mines_tile_click(query, context)
    elif action == "cashout":
        await handle_mines_cashout(query, context)
    else:
        try:
            await query.answer()
        except Exception:
            pass

async def handle_tower_action(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle tower game actions."""
    query = update.callback_query
    if not query or not query.from_user:
        return

    user_id = str(query.from_user.id)
    data = query.data  # e.g. "tower_easy", "tower_tile_0", "tower_cashout", etc.

    # ── All alert-showing guards BEFORE query.answer() ──────────────────────
    _tmsg_id = query.message.message_id if query.message else None
    if _tmsg_id:
        for _uid, _game in list(active_games.items()):
            if _uid != user_id and _game.get("msg_id") == _tmsg_id:
                try:
                    try:
                        await query.answer(_NOT_YOUR_BUTTON, show_alert=True)
                    except Exception:
                        pass
                except Exception:
                    pass
                return

    # Tile ownership guard (needs alert — must run before query.answer())
    if data.startswith("tower_tile_"):
        _gs = active_games.get(user_id, {})
        _smid = _gs.get('msg_id')
        if _smid and query.message and query.message.message_id != _smid:
            try:
                try:
                    await query.answer(_NOT_YOUR_BUTTON, show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return

    # Quick-bet pre-checks (alert before answer)
    if data.startswith("tower_quickbet_"):
        try:
            _qb_bet = float(data.split("tower_quickbet_")[1])
        except (ValueError, IndexError):
            try:
                await query.answer("❌ Invalid bet.", show_alert=True)
            except Exception:
                pass
            return
        if user_id in active_games and is_game_actively_playing(active_games[user_id]):
            _gname = active_games[user_id].get('type', 'game').replace('_', ' ').title()
            try:
                await query.answer(f"❌ Finish your active {_gname} game first!", show_alert=True)
            except Exception:
                pass
            return
        if get_user_balance(user_id) < _qb_bet:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return

    # Difficulty session-expired alert (must run before query.answer())
    if data in ["tower_easy", "tower_medium", "tower_hard"]:
        _gd_pre = active_games.get(user_id)
        _ba_pre = _gd_pre.get('bet_amount', 0) if _gd_pre and _gd_pre.get('type') in ['tower_setup', 'tower'] else 0
        if _ba_pre == 0:
            try:
                try:
                    await query.answer("❌ Bet session expired. Please try /tower again.", show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return

    # Play Again pre-checks — alerts must fire before query.answer()
    if data.startswith("tower_play_again_"):
        # Format: tower_play_again_{owner_id}_{bet}  — 5 parts (e.g. tower_play_again_123456789_5.0)
        # Legacy: tower_play_again_{bet}              — 4 parts (e.g. tower_play_again_5.0)
        _pa_parts = data.split("_")
        try:
            if len(_pa_parts) >= 5:
                # parts[3] = owner_id (always digits), parts[4] = bet
                _pa_owner = _pa_parts[3]
                _pa_bet   = float(_pa_parts[4])
            else:
                _pa_owner = ""
                _pa_bet   = float(_pa_parts[3])
        except (IndexError, ValueError):
            try:
                try:
                    await query.answer("❌ Couldn't restart. Please use /tower again.", show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return
        if _pa_owner and _pa_owner != user_id:
            try:
                try:
                    await query.answer(_NOT_YOUR_BUTTON, show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return
        _pa_bal = get_user_balance(user_id)
        if _pa_bal < _pa_bet:
            try:
                try:
                    await query.answer("❌ Insufficient balance!", show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return
        if user_id in active_games and is_game_actively_playing(active_games[user_id]):
            try:
                try:
                    await query.answer("❌ You still have an active game!", show_alert=True)
                except Exception:
                    pass
            except Exception:
                pass
            return

    # Single answer point — dismiss loader, no popup
    try:
        try:
            await query.answer()
        except Exception:
            pass
    except Exception:
        pass

    # Quick-bet: deduct balance, store setup, show difficulty screen
    if data.startswith("tower_quickbet_"):
        try:
            _qb_bet = float(data.split("tower_quickbet_")[1])
        except (ValueError, IndexError):
            return
        _qb_uid = user_id
        _qb_currency = get_user_currency(_qb_uid)
        if not deduct_user_balance(_qb_uid, _qb_bet):
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        add_house_balance(_qb_bet)
        track_wagering(_qb_uid, _qb_bet, 2.0)
        active_games[_qb_uid] = {
            '_created_at': time.time(),
            'type': 'tower_setup',
            'bet_amount': _qb_bet,
            'difficulty': 'medium',
            'created_at': time.time(),
        }
        save_data()
        _diff_kb = InlineKeyboardMarkup([
            [
                success_btn("🟢 Easy", callback_data="tower_easy"),
                InlineKeyboardButton("🟡 Medium", callback_data="tower_medium"),
                danger_btn("🔴 Hard", callback_data="tower_hard"),
            ],
            [danger_btn("⬅️ Back", callback_data="tower_quickbet_cancel")],
        ])
        try:
            await query.edit_message_text(
                "🎮 Choose game difficulty",
                reply_markup=_diff_kb,
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            logger.error(f"tower_quickbet difficulty screen error: {e}")
        return

    # Cancel quickbet — refund and go back to menu
    if data == "tower_quickbet_cancel":
        _gd = active_games.pop(user_id, None)
        if _gd and _gd.get('type') == 'tower_setup':
            ultra_secure_add_user_balance(user_id, _gd['bet_amount'], "refund")
            deduct_house_balance(_gd['bet_amount'])
            save_data()
        try:
            await query.edit_message_text("❌ Bet cancelled — balance refunded.")
        except Exception:
            pass
        return

    # Difficulty selection — start the actual game
    if data in ["tower_easy", "tower_medium", "tower_hard"]:
        game_data = active_games.get(user_id)
        bet_amount = game_data.get('bet_amount', 0) if game_data and game_data.get('type') in ['tower_setup', 'tower'] else 0
        difficulty = data.replace("tower_", "")
        _twr_pf_ss = secrets.token_hex(32)
        _twr_pf_nonce = random.randint(1, 999999)
        _twr_pf_cs = f"{user_id}_{_twr_pf_nonce}"
        _twr_pf_hash = hashlib.sha256(f"{_twr_pf_ss}:{_twr_pf_cs}:{_twr_pf_nonce}".encode()).hexdigest()
        tower_game = TowerGame(user_id=int(user_id), mode=difficulty, bet=float(bet_amount), seed=_twr_pf_hash)
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': 'tower',
            'bet_amount': bet_amount,
            'difficulty': difficulty,
            'game': tower_game,
            'status': 'playing',
            'created_at': time.time(),
            'msg_id': query.message.message_id,
            'chat_id': query.message.chat_id,
            'pf_server_seed': _twr_pf_ss,
            'pf_client_seed': _twr_pf_cs,
            'pf_nonce': _twr_pf_nonce,
        }
        save_data()
        await show_tower_grid(query, context)
        return

    # Difficulty cycling arrows
    if data in ["tower_prev_diff", "tower_next_diff"]:
        game_data = active_games.get(user_id)
        if not game_data or game_data.get('type') != 'tower_setup':
            return
        diffs = ["easy", "medium", "hard"]
        current = game_data.get('difficulty', 'medium')
        idx = diffs.index(current) if current in diffs else 1
        if data == "tower_prev_diff":
            idx = (idx - 1) % 3
        else:
            idx = (idx + 1) % 3
        game_data['difficulty'] = diffs[idx]
        save_data()
        # Show updated setup
        await _show_tower_setup_ui(query, context, game_data)
        return

    # Tile click: tower_tile_{col}
    if data.startswith("tower_tile_"):
        await handle_tower_tile_click(query, context)
        return

    # Cashout — delegate to guarded handler (concurrent-safe, try/finally)
    if data == "tower_cashout":
        await handle_tower_cashout(query, context)
        return

    # Quit
    if data == "tower_quit":
        if user_id in active_games:
            del active_games[user_id]
            save_data_critical()
        await query.edit_message_text("❌ Tower game ended.")
        return

    # Rules
    if data == "tower_rules":
        await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=(
                "ℹ️ <b>Monkey Tower Rules</b>\n\n"
                "✅ Green tile = Safe — keep climbing!\n"
                "💀 Skeleton = Game Over — you lose your bet\n"
                "🍌 Banana = You climbed to the TOP — you win!\n\n"
                "<b>Difficulties:</b>\n"
                "🟢 Easy: 4 columns, 1 bomb per row\n"
                "🟡 Medium: 4 columns, 1 bomb per row\n"
                "🔴 Hard: 4 columns, 1 bomb per row\n\n"
                "You can cash out at any time after climbing at least 1 row."
            ),
            parse_mode="HTML"
        )
        return

    # Play Again — restart with same bet amount (pre-checks already done above)
    if data.startswith("tower_play_again_"):
        _tpa_parts = data.split("_")
        # 5 parts: tower_play_again_{owner_id}_{bet}
        # 4 parts (legacy): tower_play_again_{bet}
        if len(_tpa_parts) >= 5:
            bet_amount = float(_tpa_parts[4])
        else:
            bet_amount = float(_tpa_parts[3])
        user_currency = get_user_currency(user_id)
        if not deduct_user_balance(user_id, bet_amount):
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        add_house_balance(bet_amount)
        track_wagering(user_id, bet_amount, 2.0)
        prev_difficulty = active_games.get(user_id, {}).get('difficulty', 'medium')
        # Skip difficulty screen — launch game immediately with same difficulty
        _tpa_pf_ss = secrets.token_hex(32)
        _tpa_pf_nonce = random.randint(1, 999999)
        _tpa_pf_cs = f"{user_id}_{_tpa_pf_nonce}"
        _tpa_pf_hash = hashlib.sha256(f"{_tpa_pf_ss}:{_tpa_pf_cs}:{_tpa_pf_nonce}".encode()).hexdigest()
        tower_game = TowerGame(user_id=int(user_id), mode=prev_difficulty, bet=float(bet_amount), seed=_tpa_pf_hash)
        active_games[user_id] = {
            '_created_at': time.time(),
            'type': 'tower',
            'bet_amount': bet_amount,
            'difficulty': prev_difficulty,
            'game': tower_game,
            'status': 'playing',
            'created_at': time.time(),
            'msg_id': query.message.message_id,
            'chat_id': query.message.chat_id,
            'pf_server_seed': _tpa_pf_ss,
            'pf_client_seed': _tpa_pf_cs,
            'pf_nonce': _tpa_pf_nonce,
        }
        save_data()
        await show_tower_grid(query, context)
        return

    # Noop (non-clickable tiles)
    if data == "tower_noop":
        return

async def show_tower_grid(query, context: ContextTypes.DEFAULT_TYPE, result_text: str = "") -> None:
    """Show the monkey tower grid — compact UI matching reference design."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    game_data = active_games.get(user_id)
    if not game_data or game_data['type'] != 'tower':
        return
    if query.message:
        _register_game_msg(query.message.message_id, user_id)

    tower_game = game_data.get('game')
    if not tower_game:
        return

    cols = tower_game.num_cols()
    current_floor = tower_game.floor
    current_payout = tower_game.current_payout()

    # Build grid top-to-bottom (row 8 = top, row 0 = first floor)
    keyboard = []
    for floor_idx in range(8, -1, -1):
        row = []
        for col_idx in range(cols):
            choice = tower_game.user_choices.get(floor_idx)
            if floor_idx > current_floor:
                # Future floor — plain dark, locked tile.
                row.append(InlineKeyboardButton(_TOWER_EMPTY_TILE, callback_data="tower_noop"))
            elif floor_idx == current_floor and not tower_game.finished:
                # Active floor — only a successfully opened tile turns green.
                if choice == col_idx:
                    row.append(success_btn(
                        _TOWER_EMPTY_TILE,
                        callback_data="tower_noop",
                        icon_custom_emoji_id=TOWER_SAFE_EMOJI_ID,
                    ))
                else:
                    row.append(InlineKeyboardButton(_TOWER_EMPTY_TILE, callback_data=f"tower_tile_{col_idx}"))
            else:
                # Completed floors stay visually quiet. The selected safe tile
                # remains green; every other tile keeps the normal dark style.
                val = tower_game.layout[floor_idx][col_idx]
                if choice == col_idx and val:
                    row.append(success_btn(
                        _TOWER_EMPTY_TILE,
                        callback_data="tower_noop",
                        icon_custom_emoji_id=TOWER_SAFE_EMOJI_ID,
                    ))
                else:
                    row.append(InlineKeyboardButton(_TOWER_EMPTY_TILE, callback_data="tower_noop"))
        keyboard.append(row)

    # Cashout button (green) — only if player has climbed at least 1 floor
    if current_floor > 0 and not tower_game.finished:
        cashout_label = f"✅ Cashout {format_balance_in_currency(current_payout, user_currency)}"
        keyboard.append([success_btn(cashout_label, callback_data="tower_cashout")])

    # Compact message — no extra text
    win_display = format_balance_in_currency(current_payout if current_floor > 0 else 0, user_currency)
    balance = get_user_balance(str(tower_game.user_id))
    message = (
        f'<tg-emoji emoji-id="5127902823542948533">💵</tg-emoji> Bet: <b>{format_balance_in_currency(tower_game.bet, user_currency)}</b>\n'
        f"🏢 Floors: <b>{current_floor}</b>\n"
        f'<tg-emoji emoji-id="5206415568743192168">🏆</tg-emoji> Win: <b>{win_display}</b>\n'
        f'<tg-emoji emoji-id="6305046002374024896">💰</tg-emoji> Balance: <b>{format_balance_in_currency(balance, user_currency)}</b>'
    )

    try:
        await query.edit_message_text(
            message,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML,
            disable_web_page_preview=True
        )
    except Exception as e:
        logger.error(f"show_tower_grid error: {e}")

