async def handle_tower_cashout(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle tower cash out — atomic pop + concurrent guard prevents double-cashout."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)

    # ANTI-EXPLOIT: Concurrent double-cashout guard
    if user_id in _cashout_in_progress:
        try:
            await query.answer("⏳ Processing your cashout...", show_alert=False)
        except Exception:
            pass
        return
    _cashout_in_progress.add(user_id)
    try:
        # ── ANTI-EXPLOIT: atomically claim game before touching balance ───────────
        game_data = active_games.pop(user_id, None)
        if not game_data or game_data.get('type') != 'tower':
            if game_data:
                active_games[user_id] = game_data   # restore if wrong type
            try:
                await query.answer("❌ No active tower game!")
            except Exception:
                pass
            return

        tower_game = game_data.get('game')
        bet_amount = float(game_data.get('bet_amount', 0))

        if not tower_game or tower_game.floor <= 0:
            # Put game back — player hasn't climbed yet
            active_games[user_id] = game_data
            try:
                await query.answer("❌ Climb at least 1 row before cashing out!", show_alert=True)
            except Exception:
                pass
            return

        multiplier = tower_game.current_multiplier()
        winnings = tower_game.current_payout()

        pre_bal = get_user_balance(user_id)
        ultra_secure_add_user_balance(user_id, winnings, "win")
        save_data_critical()
        post_bal = get_user_balance(user_id)
        logger.info(f"✅ TOWER CASHOUT: {user_id} {pre_bal:.2f}→{post_bal:.2f} (+{winnings:.2f}) floors={tower_game.floor}")
        deduct_house_balance(winnings - bet_amount)
        track_wagering(user_id, bet_amount)
        add_match_history(user_id, 'tower', bet_amount, 'win', winnings)

        # Show fully-revealed board with cashout result
        cols = tower_game.num_cols()
        keyboard = []
        for floor_idx in range(8, -1, -1):
            row = []
            choice = tower_game.user_choices.get(floor_idx)
            for col_idx in range(cols):
                val = tower_game.layout[floor_idx][col_idx]
                if val:
                    # Cashout reveals safe tiles without green styling.
                    row.append(InlineKeyboardButton(_TOWER_EMPTY_TILE, callback_data="tower_noop"))
                else:
                    # Cashout reveals every danger tile in red.
                    row.append(danger_btn(
                        _TOWER_EMPTY_TILE,
                        callback_data="tower_noop",
                        icon_custom_emoji_id=TOWER_BOMB_EMOJI_ID,
                    ))
            keyboard.append(row)
        keyboard.append([
            success_btn("↩️ Repeat", callback_data=f"tower_play_again_{user_id}_{tower_game.bet}"),
            InlineKeyboardButton("📝 Change bet", callback_data="play_tower"),
        ])
        msg = (
            f'<tg-emoji emoji-id="5127902823542948533">💵</tg-emoji> Bet: <b>{format_balance_in_currency(tower_game.bet, user_currency)}</b>\n'
            f"🏢 Floors: <b>{tower_game.floor}</b>\n"
            f'<tg-emoji emoji-id="5206415568743192168">🏆</tg-emoji> Win: <b>{format_balance_in_currency(winnings, user_currency)}</b>\n'
            f'<tg-emoji emoji-id="6305046002374024896">💰</tg-emoji> Balance: <b>{format_balance_in_currency(post_bal, user_currency)}</b>'
        )
        await query.edit_message_text(msg, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)

    finally:
        _cashout_in_progress.discard(user_id)

async def handle_tower_quit(query, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle tower quit - house keeps the bet."""
    user_id = str(query.from_user.id)
    user_currency = get_user_currency(user_id)
    game_data = active_games.get(user_id)
    if not game_data or game_data['type'] != 'tower':
        try:
            await query.answer("❌ No active game!")
        except Exception:
            pass
        return

    add_house_balance(game_data['bet_amount'])
    del active_games[user_id]
    save_data_critical()
    
    msg = f"❌ QUIT!\n\n💰 {format_balance_in_currency(get_user_balance(user_id), user_currency)}"
    await query.edit_message_text(msg, parse_mode=ParseMode.HTML)

