    """Detect if player is calling the games rigged."""
    message_lower = message.lower()
    rigged_words = ['rigged', 'rig', 'scam', 'cheating', 'cheat', 'fixed', 'fake', 'fraud', 'dhoka', 'fraud', 'scam casino', 'loot', 'chor', 'thug', 'bekaar', 'bakwaas']
