    # ── 4. ADD BALANCE ──────────────────────────────────────────────────────
    addbal_kws = ["add balance", "add money", "give balance", "give money", "add funds",
                  "credit user", "credit balance", "top up user", "add $", "give $",
                  "add bal", "addbal", "give bal"]
    if any(kw in msg_l for kw in addbal_kws):
        # find amount
        amount = None
