async def handle_limbo_multiplier(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle limbo multiplier input (interactive flow)."""
    if not update.message or not update.message.text:
        return

    tg_user  = update.message.from_user
    user_id  = str(tg_user.id)
    username = tg_user.username or tg_user.first_name or "Player"
    user_currency = get_user_currency(user_id)
    game_data = active_games.get(user_id)
    if not game_data or game_data['type'] != 'limbo':
        return

    try:
        target_multiplier = float(update.message.text.strip())
    except ValueError:
        await update.message.reply_text("❌ Please enter a valid multiplier (e.g., 2.5)")
        return

    if target_multiplier < 1.1 or target_multiplier > 100:
        await update.message.reply_text("❌ Multiplier must be between 1.1x - 100x")
        return

    bet_amount = game_data['bet_amount']

    if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
        await update.message.reply_text("❌ Insufficient balance!")
        return

    track_wagering(user_id, bet_amount, target_multiplier)

    # ── Provably Fair RNG — 65% house win ────────────────────────────────────
    pf_server_seed = secrets.token_hex(32)
    pf_client_seed = f"{user_id}_{random.randint(1000, 9999)}"
    pf_nonce       = random.randint(1, 1000)
    pf_hash        = hashlib.sha256(f"{pf_server_seed}:{pf_client_seed}:{pf_nonce}".encode()).hexdigest()
    pf_hash_int    = int(pf_hash[:8], 16)
    r              = (pf_hash_int % 1000000) / 1000000.0

    # Provably fair crash formula — same as limbo_command handler.
    crash_point = max(1.01, 0.99 / max(0.000001, 1.0 - r))
    if crash_point > 1000:
        crash_point = 1000.0
    # ─────────────────────────────────────────────────────────────────────────

    if crash_point >= target_multiplier:
        winnings = bet_amount * target_multiplier
        ultra_secure_add_user_balance(user_id, winnings, "win")
        deduct_house_balance(max(0, winnings - bet_amount))
        add_match_history(user_id, 'limbo', bet_amount, 'win', winnings)
        await announce_win_to_channel(context, username, winnings, "Limbo", multiplier=target_multiplier, bet=bet_amount, user_id=user_id)
        won = True
    else:
        add_house_balance(bet_amount)
        add_loss_to_rakeback(user_id, bet_amount)
        add_match_history(user_id, 'limbo', bet_amount, 'loss', 0)
        winnings = 0
        won      = False

    save_data_critical()

    # Clean up session
    user_states.pop(user_id, None)
    active_games.pop(user_id, None)

    new_balance = get_user_balance(user_id)
    bet_d   = format_balance_in_currency(bet_amount, user_currency)
    win_d   = format_balance_in_currency(winnings, user_currency)
    bal_d   = format_balance_in_currency(new_balance, user_currency)
    tgt_str = f"{int(target_multiplier)}x" if target_multiplier == int(target_multiplier) else f"{target_multiplier:.2f}x"
    cp_str  = f"{crash_point:.2f}x"
    pf_url  = (f"{_pf_base}/limbo_verify?ss={pf_server_seed}&cs={pf_client_seed}&n={pf_nonce}&h={pf_hash}&t={target_multiplier}"
               if _pf_base else "")

    # ── Fetch profile photo ───────────────────────────────────────────────────
    avatar_bytes = None
    try:
        photos = await context.bot.get_user_profile_photos(tg_user.id, limit=1)
        if photos and photos.photos:
            pf_file = await context.bot.get_file(photos.photos[0][-1].file_id)
            avatar_bytes = bytes(await pf_file.download_as_bytearray())
    except Exception:
        pass

    # ── Result message — clean Telegram format ───────────────────────────────
    _pf_link2  = f' — <a href="{pf_url}">provably fair</a>' if pf_url else ""
    _outcome2  = "✅" if won else "❌"
    caption = (
        f'Limbo{_pf_link2}\n\n'
        f'💵 {bet_d} → <b>{win_d}</b> ({tgt_str})\n\n'
        f'Multiplier: <b>{crash_point:.2f}x</b> {_outcome2}'
    )
    _limbo2_pf_kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔐 Provably Fair", url=pf_url)]]) if pf_url else None
    await update.message.reply_text(caption, parse_mode=ParseMode.HTML, disable_web_page_preview=True, reply_markup=_limbo2_pf_kb)

# ── Telegram Stars deposit ────────────────────────────────────────────────────
# These are the Star amounts shown in the supplied Telegram checkout examples.
# The final fiat price for buying Stars is always displayed by Telegram for the
# user's region; the invoice itself is denominated in XTR.
TELEGRAM_STARS_PACKAGES = (
    (84, 1.00),
    (167, 2.00),
    (417, 5.00),
    (834, 10.00),
    (1667, 20.00),
    (4167, 50.00),
)

TELEGRAM_STAR_BUTTON_EMOJI_ID = "6305280073796689362"
TELEGRAM_GIFT_BUTTON_EMOJI_ID = "6303251320224622462"
TELEGRAM_WARNING_EMOJI_ID = "5368454557288391017"
TELEGRAM_GIFT_OWNER_USERNAME = "arshxy"
TELEGRAM_GIFT_USD_PER_STAR = 1.0 / 84.0


def _telegram_warning_emoji() -> str:
    return f'<tg-emoji emoji-id="{TELEGRAM_WARNING_EMOJI_ID}">⚠️</tg-emoji>'


def _gift_current_star_value(owned_gift) -> int:
    """Use the current conversion/transfer value, not the original gift price."""
    for field in ("convert_star_count", "transfer_star_count"):
        value = getattr(owned_gift, field, None)
        if value:
            return max(0, int(value))
    gift = getattr(owned_gift, "gift", None)
    return max(0, int(getattr(gift, "star_count", 0) or 0))


def _gift_key(owned_gift) -> str:
    """Build a stable key for regular and unique owned gifts."""
    owned_id = getattr(owned_gift, "owned_gift_id", None)
    if owned_id:
        return f"owned:{owned_id}"
    gift = getattr(owned_gift, "gift", None)
    gift_id = getattr(gift, "id", "unknown")
    sender = getattr(getattr(owned_gift, "sender_user", None), "id", "")
    send_date = getattr(owned_gift, "send_date", None)
    send_key = send_date.isoformat() if hasattr(send_date, "isoformat") else str(send_date or "")
    return f"{getattr(owned_gift, 'type', 'gift')}:{gift_id}:{sender}:{send_key}"


def _gift_snapshot(owned_gift) -> dict:
    gift = getattr(owned_gift, "gift", None)
    gift_id = str(getattr(gift, "id", "Telegram Gift"))
    sender = getattr(owned_gift, "sender_user", None)
    send_date = getattr(owned_gift, "send_date", None)
    stars = _gift_current_star_value(owned_gift)
    return {
        "gift_id": gift_id,
        "type": str(getattr(owned_gift, "type", "regular")),
        "stars": stars,
        "usd": round(stars * TELEGRAM_GIFT_USD_PER_STAR, 2),
        "sender_id": str(getattr(sender, "id", "")) if sender else "",
        "sender_username": getattr(sender, "username", "") if sender else "",
        "send_date": send_date.isoformat() if hasattr(send_date, "isoformat") else str(send_date or ""),
    }


async def _fetch_and_store_user_gifts(bot, user_id: str):
    """Read the user's owned-gift profile and persist its current values."""
    owned = await bot.get_user_gifts(
        user_id=int(user_id),
        sort_by_price=True,
        limit=100,
    )
    snapshots = [_gift_snapshot(item) for item in (owned.gifts or [])]
    total_stars = sum(item["stars"] for item in snapshots)
    user_gift_profiles[str(user_id)] = {
        "updated_at": time.time(),
        "total_stars": total_stars,
        "current_usd": round(total_stars * TELEGRAM_GIFT_USD_PER_STAR, 2),
        "gifts": snapshots,
    }
    save_data_critical()
    return snapshots


def _gift_profile_text(user_id: str, snapshots: list[dict] | None = None) -> str:
    profile = user_gift_profiles.get(str(user_id), {})
    gifts = snapshots if snapshots is not None else profile.get("gifts", [])
    total_stars = sum(int(item.get("stars", 0) or 0) for item in gifts)
    total_usd = round(total_stars * TELEGRAM_GIFT_USD_PER_STAR, 2)
    if not gifts:
        detail = "No owned gifts were found in your Telegram profile yet."
    else:
        lines = []
        for item in gifts[:12]:
            label = item.get("gift_id", "Telegram Gift")
            lines.append(f"• <b>{label}</b> — {item.get('stars', 0):,} Stars (${item.get('usd', 0):.2f})")
        if len(gifts) > 12:
            lines.append(f"• And {len(gifts) - 12} more gifts")
        detail = "\n".join(lines)
    return (
        "🎁 <b>Your Telegram Gift Value</b>\n\n"
        f"Current value: <b>{total_stars:,} Stars</b> "
        f"(<b>${total_usd:.2f}</b>)\n\n"
        f"{detail}\n\n"
        "This uses each gift's current conversion or transfer value, not its original purchase price."
    )


