async def _credit_telegram_gift(user_id: str, gift_key: str, snapshot: dict) -> bool:
    """Credit one gift exactly once through the normal deposit accounting path."""
    if not user_id or not snapshot.get("stars"):
        return False
    with _gift_sync_lock:
        if gift_key in processed_telegram_gifts:
            return False
        processed_telegram_gifts.add(gift_key)
    credited_usd = float(snapshot["stars"]) * TELEGRAM_GIFT_USD_PER_STAR
    processed = _process_confirmed_deposit(
        user_id=str(user_id),
        usd_amount=credited_usd,
        credited_amount=credited_usd,
        fee_amount=0.0,
        pay_currency="TELEGRAM_GIFT",
        payment_id=f"gift_{gift_key}",
        source="telegram_gift",
        coin_amount=float(snapshot["stars"]),
    )
    if not processed:
        with _gift_sync_lock:
            processed_telegram_gifts.discard(gift_key)
    return processed


async def handle_telegram_gift_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Credit gifts sent directly to the bot when Telegram includes the sender."""
    message = update.message
    gift_info = getattr(message, "gift", None) if message else None
    sender = message.from_user if message else None
    if not gift_info or not sender:
        return
    snapshot = {
        "gift_id": str(getattr(getattr(gift_info, "gift", None), "id", "Telegram Gift")),
        "type": "regular",
        "stars": _gift_current_star_value(gift_info),
        "usd": round(_gift_current_star_value(gift_info) * TELEGRAM_GIFT_USD_PER_STAR, 2),
        "sender_id": str(sender.id),
        "sender_username": sender.username or "",
        "send_date": str(getattr(message, "date", "") or ""),
    }
    gift_key = f"message:{message.chat_id}:{message.message_id}"
    if await _credit_telegram_gift(str(sender.id), gift_key, snapshot):
        await message.reply_text(
            f"🎁 <b>Gift deposit credited</b>\n\n"
            f"Current value: <b>{snapshot['stars']:,} Stars (${snapshot['usd']:.2f})</b>",
            parse_mode=ParseMode.HTML,
        )


async def _poll_owner_gifts_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """Poll the owner's gift profile and credit newly received identifiable gifts."""
    global gift_tracking_initialized
    try:
        owned = await context.bot.get_user_gifts(
            user_id=int(OWNER_ID),
            sort_by_price=False,
            limit=100,
        )
    except Exception as exc:
        logger.info("[GIFTS] Owner gift profile is unavailable: %s", exc)
        return

    gifts = list(owned.gifts or [])
    keys = {_gift_key(item) for item in gifts}
    with _gift_sync_lock:
        if not gift_tracking_initialized:
            processed_telegram_gifts.update(keys)
            gift_tracking_initialized = True
            save_data()
            return

    for item in gifts:
        key = _gift_key(item)
        if key in processed_telegram_gifts:
            continue
        snapshot = _gift_snapshot(item)
        sender_id = snapshot.get("sender_id", "")
        if not sender_id or sender_id == str(OWNER_ID):
            if key not in unattributed_telegram_gifts:
                unattributed_telegram_gifts[key] = snapshot
                save_data()
            continue
        if await _credit_telegram_gift(sender_id, key, snapshot):
            unattributed_telegram_gifts.pop(key, None)
            try:
                await context.bot.send_message(
                    chat_id=int(sender_id),
                    text=(
                        "🎁 <b>Telegram Gift deposit credited</b>\n\n"
                        f"Current value: <b>{snapshot['stars']:,} Stars (${snapshot['usd']:.2f})</b>"
                    ),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
    save_data()


