async def _edit_callback_text_or_send(
    query,
    context: ContextTypes.DEFAULT_TYPE,
    text: str,
    *,
    reply_markup=None,
    parse_mode=None,
) -> None:
    """Edit callback text screens, replacing a photo message when necessary."""
    message = query.message
    if message and getattr(message, "photo", None):
        try:
            await message.delete()
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=message.chat_id,
            text=text,
            reply_markup=reply_markup,
            parse_mode=parse_mode,
        )
        return

    try:
        await query.edit_message_text(
            text=text,
            reply_markup=reply_markup,
            parse_mode=parse_mode,
        )
    except Exception as exc:
        logger.info("Callback message could not be edited; sending replacement: %s", exc)
        try:
            if message:
                await message.delete()
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=message.chat_id if message else query.from_user.id,
            text=text,
            reply_markup=reply_markup,
            parse_mode=parse_mode,
        )


