async def handle_set_language(query, context: ContextTypes.DEFAULT_TYPE, lang_code: str) -> None:
    """Handle language selection and save to player data."""
    if not query.from_user:
        return
    user_id = str(query.from_user.id)

    LANG_NAMES = {
        "en": "English", "zh": "中文", "tr": "Türkçe", "it": "Italiano",
        "de": "Deutsch", "hi": "हिन्दी", "ru": "Русский", "es": "Español",
        "pt": "Português", "ar": "العربية", "fr": "Français", "ja": "日本語",
        "ko": "한국어", "id": "Indonesia", "vi": "Tiếng Việt", "th": "ภาษาไทย",
        "pl": "Polski", "uk": "Українська", "nl": "Nederlands", "sv": "Svenska",
    }

    if lang_code not in SUPPORTED_LANGUAGE_CODES:
        await query.answer("⚠️ Unsupported language.", show_alert=True)
        return

    if user_id not in player_data or not isinstance(player_data[user_id], dict):
        player_data[user_id] = {}
    player_data[user_id]['language'] = lang_code
    # Keep the in-memory translation source and cache synchronized immediately.
    # Without this, the selection only appeared in saved data and all calls to
    # translations.t() continued using English until a later reload.
    set_user_lang(user_id, lang_code)
    save_data()

    lang_name = LANG_NAMES.get(lang_code, lang_code)
    try:
        await query.answer(_tr(user_id, "lang_set_confirm", name=lang_name))
    except Exception:
        pass
    # Return to settings menu after language selection
    await handle_settings_menu(query, context)

