async def handle_animated_game_turn(query, context, user_id):
    """Core logic for multi-round animated games."""
    game_data = active_games.get(user_id)
    if not game_data:
        return

    chat_id = game_data['chat_id']
    username = query.from_user.username or query.from_user.first_name or "Player"
    user_currency = get_user_currency(user_id)
    bet_amount = game_data['bet_amount']
    dice_emoji = game_data['emoji']
    state = game_data['state']
    rolls_count = game_data['rolls']
    wins_needed = game_data['wins_needed']
    game_format = game_data.get('format', '1d1w')

    if state == 'bot_turn':
        # Bot rolls
        round_score = 0
        chat_type = query.message.chat.type
        is_group = chat_type in ["group", "supergroup"]
        
        for i in range(rolls_count):
            if is_group:
                b_dice = await dealer_send_dice(chat_id=chat_id, emoji=dice_emoji, main_bot=context.bot, chat_type=chat_type, user_id=int(user_id))
            else:
                b_dice = await context.bot.send_dice(chat_id=chat_id, emoji=dice_emoji)
            
            if b_dice:
                round_score += b_dice.dice.value
            if i < rolls_count - 1:
                await asyncio.sleep(0.1)
        
        # Wait for animation
        await asyncio.sleep(0.3)

        game_data['bot_round_total'] = round_score
        game_data['state'] = 'player_turn'
        save_data()

        # Race-condition guard: game may have ended while bot was rolling async dice
        if user_id not in active_games:
            return

        # Notify player's turn
        await query.message.reply_text(
            _rc_turn_text(game_data.get('game_name', 'dice'), user_id, username),
            parse_mode=ParseMode.HTML,
            reply_markup=ReplyKeyboardRemove(),
        )
        return

    elif state == 'player_turn':
        # Player needs to roll their dice manually — handled by the dice message handler
        # Only prompt if game is still active (prevents stale-button "your turn" spam)
        if user_id not in active_games:
            return
        await query.message.reply_text(
            f"<b>Your turn!</b> Please send a {dice_emoji} dice now.",
            parse_mode=ParseMode.HTML
        )
        return

    # Check if match is over
    if game_data['player_wins'] >= wins_needed or game_data['bot_wins'] >= wins_needed:
        winner = username if game_data['player_wins'] >= wins_needed else "Bot"
        game_name = game_data.get('game_name', 'Dice')
        emoji = game_data.get('emoji', '🎲')

        # ANTI-GLITCH: Mark game as won BEFORE paying out, then remove from active_games
        # This prevents the stuck-game cleanup from also refunding the bet
        game_data['won'] = True
        if user_id in active_games:
            del active_games[user_id]

        if winner == username:
            # Player wins
            winnings = bet_amount * 1.92
            ultra_secure_add_user_balance(user_id, winnings, "dice_match_win")
            deduct_house_balance(winnings - bet_amount)
            add_match_history(user_id, game_name.lower(), bet_amount, 'win', winnings)
            final_msg = f"🏆 <b>{username} WINS!</b>\n\n{emoji} {game_name} match is OVER!\n\n👤 {username}: {game_data['player_wins']}\n🤖 Bot: {game_data['bot_wins']}\n\n💰 Won: {format_balance_in_currency(winnings, user_currency)}\n📊 Balance: {format_balance_in_currency(get_user_balance(user_id), user_currency)}"
        else:
            # Bot wins
            add_match_history(user_id, game_name.lower(), bet_amount, 'loss', 0)
            final_msg = f"❌ <b>Bot WINS!</b>\n\n{emoji} {game_name} match is OVER!\n\n👤 {username}: {game_data['player_wins']}\n🤖 Bot: {game_data['bot_wins']}\n\n💔 Lost: {format_balance_in_currency(bet_amount, user_currency)}\n📊 Balance: {format_balance_in_currency(get_user_balance(user_id), user_currency)}"
        
        save_data_critical()
        await query.message.reply_text(final_msg, parse_mode=ParseMode.HTML)
        if winner == username:
            await _send_player_win_sticker(context.bot, query.message.chat_id)
        return
    
    # If match not ended, set state for bot to roll next round
    game_data['state'] = 'bot_turn'
    save_data()

    # Score and turn message
    score_msg = (
        f"<b>Score</b>\n\n"
        f"{username}: {game_data['player_wins']}\n"
        f"Bot: {game_data['bot_wins']}"
    )

    # Cashout logic - show if not in final round
    total_rounds = game_data['player_wins'] + game_data['bot_wins']
    show_cashout = total_rounds < (wins_needed * 2 - 1)

    reply_markup = None
    if show_cashout:
        # Multiplier logic based on progress
        win_ratio = (game_data['player_wins'] + 1) / (total_rounds + 2)
        cashout_val = bet_amount * win_ratio * 1.84
        multiplier = cashout_val / bet_amount if bet_amount > 0 else 0
        reply_markup = InlineKeyboardMarkup([[InlineKeyboardButton(f"✅ Cashout {format_balance_in_currency(cashout_val, user_currency)} (x{multiplier:.2f})", callback_data=f"dice_cashout_active")]])

    await query.message.reply_text(score_msg, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    
    # Start bot's next turn automatically
    await handle_animated_game_turn(query, context, user_id)

def extract_emojis(text: str) -> list:
    """Extract all emojis from text."""
    import re
    emoji_pattern = re.compile(
        "["
        "\U0001F600-\U0001F64F"  # emoticons
        "\U0001F300-\U0001F5FF"  # symbols & pictographs
        "\U0001F680-\U0001F6FF"  # transport & map symbols
        "\U0001F700-\U0001F77F"  # alchemical symbols
        "\U0001F780-\U0001F7FF"  # Geometric Shapes Extended
        "\U0001F800-\U0001F8FF"  # Supplemental Arrows-C
        "\U0001F900-\U0001F9FF"  # Supplemental Symbols and Pictographs
        "\U0001FA00-\U0001FA6F"  # Chess Symbols
        "\U0001FA70-\U0001FAFF"  # Symbols and Pictographs Extended-A
        "\U00002702-\U000027B0"
        "\U000024C2-\U0001F251"
        "\U0001f926-\U0001f937"
        "\U00010000-\U0010ffff"
        "\u2640-\u2642"
        "\u2600-\u2B55"
        "\u200d"
        "\u23cf"
        "\u23e9"
        "\u231a"
        "\ufe0f"  # dingbats
        "\u3030"
        "]+"
    )
    return emoji_pattern.findall(text)

async def owner_set_emojis(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner command to set emoji collection."""
    if not update.message or not update.message.from_user:
        return
    
    user_id = str(update.message.from_user.id)
