# Owner approval handlers (simplified)
async def handle_deposit_approval(query, context: ContextTypes.DEFAULT_TYPE, deposit_id: str) -> None:
    """Handle deposit approval — routes through _process_confirmed_deposit for full consistency."""
    deposit = pending_deposits.get(deposit_id)
    if not deposit:
        try:
            await query.answer("Deposit not found!")
        except Exception:
            pass
        return

    amount = float(deposit['amount'])
    user_id = str(deposit['user_id'])
    pay_currency = str(deposit.get('crypto', deposit.get('currency', 'USDT'))).upper()

    # Remove from pending first (idempotency guard)
    del pending_deposits[deposit_id]

    # Delegate ALL side-effects (balance, history, wagering, rain eligibility,
    # bonus activation, critical save, DM notification) to the single authority.
    ok = await asyncio.to_thread(
        _process_confirmed_deposit,
        user_id, amount, amount, 0.0,
        pay_currency, f"manual_{deposit_id}", 'manual_deposit_approval',
    )

    if ok:
        try:
            await query.edit_message_text(
                f"✅ <b>Deposit Confirmed</b>\n\n"
                f"ID: `{deposit_id}`\n"
                f"User: {deposit.get('user_name', user_id)}\n"
                f"Amount: ${amount:.2f}\n"
                f"Status: Completed",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            try:
                await query.answer("✅ Deposit approved and player notified!")
            except Exception:
                pass
    else:
        try:
            await query.answer("⚠️ Approval error — check logs.", show_alert=True)
        except Exception:
            pass

async def handle_deposit_rejection(query, context: ContextTypes.DEFAULT_TYPE, deposit_id: str) -> None:
    """Handle deposit rejection."""
    deposit = pending_deposits.get(deposit_id)
    if not deposit:
        try:
            await query.answer("Deposit not found!")
        except Exception:
            pass
        return

    try:
        # Notify user of rejection
        await context.bot.send_message(
            chat_id=int(deposit['user_id']),
            text=f"❌ <b>Deposit Rejected</b>\n\n"
                 f"Request ID: `{deposit_id}`\n"
                 f"Amount: {format_balance_in_currency(deposit['amount'], user_currency)}\n\n"
                 f"Please check your payment details and submit a new request.",
            parse_mode=ParseMode.HTML
        )

        await query.edit_message_text(
            f"❌ <b>Deposit Rejected</b>\n\n"
            f"ID: `{deposit_id}`\n"
            f"User: {deposit['user_name']}\n"
            f"Amount: {format_balance_in_currency(deposit['amount'], user_currency)}\n"
            f"Status: Rejected",
            parse_mode=ParseMode.HTML
        )

        del pending_deposits[deposit_id]
        save_data()

    except Exception as e:
        logger.error(f"Error rejecting deposit: {e}")
        try:
            await query.answer("Error rejecting deposit!")
        except Exception:
            pass

async def handle_withdrawal_approval(query, context: ContextTypes.DEFAULT_TYPE, withdrawal_id: str) -> None:
    """Handle withdrawal approval."""
    withdrawal = pending_withdrawals.get(withdrawal_id)
    if not withdrawal:
        try:
            await query.answer("Withdrawal not found!")
        except Exception:
            pass
        return

    amount = withdrawal['amount']
    user_id = str(withdrawal['user_id'])
    user_currency = get_user_currency(user_id)
    
    # Deduct balance only if sufficient funds - CRITICAL FIX
    if not deduct_user_balance(user_id, amount):
        try:
            await query.answer(f"❌ Insufficient balance for withdrawal!", show_alert=True)
        except Exception:
            pass
        logger.error(f"Withdrawal approval failed - insufficient balance for user {user_id}")
        return

    try:
        new_balance = get_user_balance(user_id)
        await context.bot.send_message(
            chat_id=int(user_id),
            text=f"🔥 <b>Withdrawal Successful!</b>\n\n"
                 f"Request ID: `{withdrawal_id}`\n"
                 f"Amount: {format_balance_in_currency(amount, user_currency)}\n"
                 f"Your new balance: {format_balance_in_currency(new_balance, user_currency)}\n\n"
                 f"Your withdrawal has been processed.",
            parse_mode=ParseMode.HTML
        )

        await query.edit_message_text(
            f"✅ <b>Withdrawal Processed</b>\n\n"
            f"ID: `{withdrawal_id}`\n"
            f"User: {withdrawal['user_name']}\n"
            f"Amount: {format_balance_in_currency(amount, user_currency)}\n"
            f"Status: Completed",
            parse_mode=ParseMode.HTML
        )

        del pending_withdrawals[withdrawal_id]
        save_data()
        logger.info(f"✅ Withdrawal processed for user {user_id}: ${amount:.2f} USD, new balance: {new_balance}")

    except Exception as e:
        logger.error(f"Error processing withdrawal: {e}", exc_info=True)
        # Refund the deducted amount on error
        ultra_secure_add_user_balance(user_id, amount, "withdrawal_error_refund")
        save_data_critical()
        try:
            await query.answer("❌ Error processing withdrawal! Balance refunded.", show_alert=True)
        except Exception:
            pass

