async def smartgiveaway_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """AI-powered smart giveaway - just provide basic details and AI writes professional text."""
    if not update.message or not update.message.from_user:
        return
    
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    if not context.args or len(context.args) < 3:
        await update.message.reply_text(
            "🤖 <b>Smart Giveaway Command</b>\n\n"
            "The bot will automatically write a professional announcement!\n\n"
            "Usage: `/smartgiveaway [amount] [duration] [reason]`\n\n"
            "<b>Duration formats:</b>\n"
            "• `5m` - 5 minutes\n"
            "• `2h` - 2 hours\n"
            "• `3d` - 3 days\n"
            "• `1w` - 1 week\n\n"
            "<b>Examples:</b>\n"
            "• `/smartgiveaway 500 30m lucky guy referred 50 people`\n"
            "• `/smartgiveaway 1000 2h wagered 700 in slots`\n"
            "• `/smartgiveaway 2000 1d new year celebration`\n"
            "• `/smartgiveaway 5000 3h top referrer of the week`\n"
            "• `/smartgiveaway 20 1h random lucky winner`\n\n"
            "Just tell me the reason and I'll write a professional announcement! ✨",
            parse_mode=ParseMode.HTML
        )
        return
    
    try:
        amount = float(context.args[0])
        duration_str = context.args[1]
        reason = " ".join(context.args[2:])
        
        if amount < 10:
            await update.message.reply_text("❌ Minimum giveaway amount is $10")
            return
        
        duration_seconds, duration_display = parse_duration(duration_str)
        
        if duration_seconds is None:
            await update.message.reply_text("❌ Invalid duration format. Use: 5m, 2h, 3d, 1w, 1mo")
            return
        
        if duration_seconds < 60:
            await update.message.reply_text("❌ Minimum duration is 1 minute")
            return
        
        await update.message.reply_text("✨ Generating professional giveaway announcement...")
        
        professional_text = await generate_professional_giveaway_text(amount, duration_display, reason)
        
        giveaway_id = str(int(time.time()))
        end_time = time.time() + duration_seconds
        
        active_giveaways[giveaway_id] = {
            'amount': amount,
            'duration_seconds': duration_seconds,
            'duration_display': duration_display,
            'description': reason,
            'end_time': end_time,
            'participants': [],
            'chat_id': update.message.chat_id,
            'message_id': None,
            'winner': None,
            'ai_generated': True,
            'original_text': professional_text
        }
        
        keyboard = [[InlineKeyboardButton("🎁 JOIN GIVEAWAY", callback_data=f"join_giveaway_{giveaway_id}")]]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        giveaway_msg = await update.message.reply_text(
            professional_text,
            parse_mode=ParseMode.HTML,
            reply_markup=reply_markup
        )
        
        active_giveaways[giveaway_id]['message_id'] = giveaway_msg.message_id
        
        asyncio.create_task(end_giveaway_timer(context, giveaway_id))
        
    except ValueError:
        await update.message.reply_text("❌ Invalid format. Use: /smartgiveaway [amount] [duration] [reason]")
    except Exception as e:
        logger.error(f"Smart giveaway error: {e}")
        await update.message.reply_text(f"❌ Error creating giveaway. Please try again.")


async def end_giveaway_timer(context: ContextTypes.DEFAULT_TYPE, giveaway_id: str):
    """Timer to end giveaway automatically."""
    if giveaway_id not in active_giveaways:
        return
    
    giveaway = active_giveaways[giveaway_id]
    wait_time = giveaway['end_time'] - time.time()
    
    if wait_time > 0:
        await asyncio.sleep(wait_time)
    
    await finish_giveaway(context, giveaway_id)

