    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    games_count = len(active_games)
    
    if games_count == 0:
        await update.message.reply_text("✅ No active games to clear.")
        return
    
    # Clear all games — no refunds (inactivity = forfeit)
    cleared_count = 0

    for user_id, game_data in list(active_games.items()):
        cleared_count += 1
        try:
            await context.bot.send_message(
                chat_id=int(user_id),
                text="⚠️ <b>Game Cleared</b>\n\nYour game was closed by the administrator due to inactivity. No refund is issued.",
                parse_mode=ParseMode.HTML
            )
        except:
            pass

    active_games.clear()

    # Also clear related user states
    for uid in list(user_states.keys()):
        if user_states[uid] and str(user_states[uid]).startswith("waiting_"):
            user_states[uid] = None

    save_data_critical()
    await update.message.reply_text(f"✅ Successfully cleared {games_count} games. No refunds issued.")

