async def removewithdrawreq_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner/manager: /removewithdrawreq <user_id> — remove ALL withdrawal restrictions for a player.

    Clears:
      • Tip restriction  ($10 deposit / $5 wager in 30 days)
      • Wagering requirement  (3× deposit rule)
    """
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner/manager only.")
        return
    if not context.args:
        await update.message.reply_text(
            "<b>Usage:</b> /removewithdrawreq &lt;user_id&gt;\n\n"
            "Removes <b>all</b> withdrawal restrictions for that player:\n"
            "• Tip restriction ($10 deposit / $5 wager requirement)\n"
            "• Wagering requirement (3× deposit rule)\n\n"
            "The player will be able to withdraw immediately after this.",
            parse_mode=ParseMode.HTML
        )
        return

    target_id = str(context.args[0])

    removed = []

    # 1. Tip restriction
    had_tip = user_tip_received.pop(target_id, None)
    if had_tip:
        removed.append("tip restriction ($10 deposit / $5 wager rule)")

    # 2. Wagering requirement — clear both stores (kept in sync per architecture)
    had_wager_req = user_wagering_requirements.pop(target_id, None)
    if player_data.get(target_id):
        player_data[target_id]['wager_requirement'] = 0.0
    if had_wager_req and float(had_wager_req) > 0:
        removed.append(f"wagering requirement (was {format_balance_in_currency(float(had_wager_req), get_user_currency(target_id))})")

    save_data_critical()

    if removed:
        lines_txt = "\n".join(f"  ✅ Removed: {r}" for r in removed)
        await update.message.reply_text(
            f"✅ <b>Withdrawal restrictions cleared for</b> <code>{target_id}</code>\n\n"
            f"{lines_txt}\n\n"
            f"They can now withdraw freely.",
            parse_mode=ParseMode.HTML
        )
    else:
        await update.message.reply_text(
            f"ℹ️ User <code>{target_id}</code> had no withdrawal restrictions to remove.",
            parse_mode=ParseMode.HTML
        )


