async def clearstuck_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Clear all stuck transactions - Owner only."""
    if not update.message or not update.message.from_user:
        return
    
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    cleared_deposits = len(pending_deposits)
    cleared_withdrawals = 0
    refunded_amount = 0
    
    # Refund and clear stuck withdrawals
    for wid, data in list(pending_withdrawals.items()):
        uid = data.get('user_id')
        amount = data.get('amount_usd', data.get('amount_inr', data.get('amount', 0)))
        if uid and amount > 0:
            ultra_secure_add_user_balance(str(uid), amount, "stuck_withdrawal_refund")
            refunded_amount += amount
            cleared_withdrawals += 1
    
    pending_deposits.clear()
    pending_withdrawals.clear()
    save_data_critical()
    
    await update.message.reply_text(
        f"✅ <b>STUCK TRANSACTIONS CLEARED</b>\n\n"
        f"📥 Deposits cleared: {cleared_deposits}\n"
        f"📤 Withdrawals cleared: {cleared_withdrawals}\n"
        f"💰 Total refunded: ${refunded_amount:.2f}",
        parse_mode=ParseMode.HTML
    )

async def announce_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Send announcement to all users - with retry logic."""
    if not update.message or not update.message.from_user:
        return
    
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    if not context.args:
        await update.message.reply_text("Usage: /announce [message]")
        return
    
    message = " ".join(context.args)
    sent = 0
    failed = 0
    total = len(user_balances)
    
    await update.message.reply_text(f"📢 Sending announcement to {total} users...")
    
    for user_id in list(user_balances.keys()):
        try:
            chat_id = int(user_id) if isinstance(user_id, str) else user_id
            await asyncio.wait_for(
                context.bot.send_message(
                    chat_id=chat_id,
                    text=f"📢 <b>CASINO ANNOUNCEMENT</b> 📢\n\n{message}\n\n👑 From: Rollers Casino",
                    parse_mode=ParseMode.HTML,
                    request_timeout=10
                ),
                timeout=10
            )
            sent += 1
        except Exception as e:
            failed += 1
        
        await asyncio.sleep(0.05)
    
    await update.message.reply_text(f"✅ Complete!\n✅ Sent: {sent} | ❌ Failed: {failed} | 📊 Total: {total}")

