def _format_race_time_left(end_time: float) -> str:
    """Return human-readable countdown to race end. Never frozen — always computed live."""
    secs = int(end_time - time.time())
    if secs <= 0:
        return "⌛ Ended"
    d, rem = divmod(secs, 86400)
    h, rem = divmod(rem, 3600)
    m = rem // 60
    if d:
        return f"{d}d {h}h {m}m"
    if h:
        return f"{h}h {m}m"
    return f"{m}m"

