async def checkdeposit_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Owner/manager command: /checkdeposit [payment_id]
    Manually trigger deposit check. Without payment_id: scans ALL recent NowPayments
    confirmed payments and credits any that weren't auto-credited yet.
    With payment_id: checks that specific payment and credits it if confirmed.
    """
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        return

    msg = update.message
    args = context.args or []

    if args:
        # Specific payment_id check
        payment_id = args[0].strip()
        await msg.reply_text(f"🔍 Checking payment `{payment_id}`...", parse_mode='Markdown')
        status_data, err = await asyncio.to_thread(nowpayments_get_payment_status, payment_id)
        if err or not status_data:
            await msg.reply_text(f"❌ Could not fetch payment `{payment_id}`: {err}", parse_mode='Markdown')
            return
        ps = status_data.get('payment_status', 'unknown')
        order_id = str(status_data.get('order_id', ''))
        price_amount = float(status_data.get('price_amount') or 0)
        pay_currency = str(status_data.get('pay_currency', 'USDT')).upper()
        await msg.reply_text(
            f"💳 *Payment {payment_id}*\n"
            f"Status: `{ps}`\n"
            f"Amount: `${price_amount:.2f}` via `{pay_currency}`\n"
            f"Order ID: `{order_id}`",
            parse_mode='Markdown'
        )
        if ps in ('finished', 'confirmed'):
            if payment_id in processed_payment_ids:
                await msg.reply_text("✅ Already credited to player.")
                return
            # Extract user_id from order_id
            user_id = None
            for prefix in ('dep_', 'deposit_'):
                if order_id.startswith(prefix):
                    parts = order_id[len(prefix):].split('_')
                    user_id = parts[0]
                    break
            if not user_id:
                parts = order_id.split('_')
                if len(parts) >= 2 and parts[0].isdigit():
                    user_id = parts[0]
            if not user_id:
                await msg.reply_text("❌ Cannot extract user_id from order_id. Manual action needed.")
                return
            processed_payment_ids.add(payment_id)
            _cd_fee      = round(price_amount * DEPOSIT_FEE_RATE, 2)
            _cd_credited = round(price_amount - _cd_fee, 2)
            ok = await asyncio.to_thread(
                _process_confirmed_deposit,
                user_id, price_amount, _cd_credited, _cd_fee,
                pay_currency, payment_id, 'manual_checkdeposit',
            )
            if ok:
                await msg.reply_text(
                    f"✅ Credited *${_cd_credited:.2f}* (fee ${_cd_fee:.2f}) to user `{user_id}` and notified them!",
                    parse_mode='Markdown'
                )
            else:
                await msg.reply_text(f"⚠️ Processing error — check logs for user `{user_id}`.", parse_mode='Markdown')
        else:
            await msg.reply_text(f"⏳ Payment is `{ps}` — not confirmed yet, cannot credit.")
    else:
        # Full scan mode
        await msg.reply_text("🔍 Scanning ALL recent NowPayments confirmed payments...")
        try:
            new_credits = await asyncio.to_thread(nowpayments_fetch_and_credit_confirmed, BOT_TOKEN)
            if new_credits:
                await msg.reply_text(f"✅ Auto-credited *{new_credits}* new deposit(s)!", parse_mode='Markdown')
            else:
                await msg.reply_text("✅ Scan complete — no new confirmed deposits to credit.")
        except Exception as e:
            await msg.reply_text(f"❌ Scan error: {e}")

