async def _endreffle_inner(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Inner raffle draw logic — only called via endreffle_command after race guard."""
    global _active_raffle, user_raffle_tickets
    if not _active_raffle:
        await update.message.reply_text("❌ No active raffle to end.")
        return

    title            = _active_raffle.get('title', 'Raffle')
    prize_per_winner = _active_raffle.get('prize_per_winner', 100)
    num_winners      = _active_raffle.get('num_winners', 1)

    # Build weighted ticket pool
    ticket_pool = []
    for uid, tickets in user_raffle_tickets.items():
        ticket_pool.extend([uid] * max(0, int(tickets)))

    if not ticket_pool:
        await update.message.reply_text("❌ No tickets sold — raffle cancelled (no participants).")
        _active_raffle.clear()
        user_raffle_tickets.clear()
        save_data_critical()
        return

    import random as _rand
    winners = []
    remaining_pool = list(ticket_pool)
    for _ in range(min(num_winners, len(set(ticket_pool)))):
        if not remaining_pool:
            break
        winner_id = _rand.choice(remaining_pool)
        winners.append(winner_id)
        remaining_pool = [x for x in remaining_pool if x != winner_id]

    result_msg = f"🎟️ <b>{title} — Results!</b>\n\n<b>🏆 Winners:</b>\n\n"
    for i, uid in enumerate(winners):
        profile = user_profiles.get(uid, {})
        name    = profile.get('username') or profile.get('first_name') or f"Player_{uid[-4:]}"
        tickets = user_raffle_tickets.get(uid, 0)
        result_msg += (
            f"{'🥇' if i==0 else '🥈' if i==1 else '🥉' if i==2 else f'#{i+1}'} "
            f"{name} — <b>{tickets}</b> tickets → <b>${prize_per_winner:,.0f}</b>\n"
        )
        ultra_secure_add_user_balance(uid, prize_per_winner, "raffle_prize")

    # Clear raffle state AFTER paying out — so a crash before clear = safe retry
    _active_raffle.clear()
    user_raffle_tickets.clear()
    _raffle_start_wager.clear()
    save_data_critical()   # raffle prizes MUST NOT vanish on crash
    await update.message.reply_text(result_msg, parse_mode=ParseMode.HTML)


async def endreffle_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Owner: /endreffle — draw raffle winners and pay out."""
    global _endraffle_in_progress
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only.")
        return
    # ANTI-EXPLOIT: Concurrent double-draw guard.
    # With concurrent_updates=True two /endreffle messages can both pass the
    # `if not _active_raffle` check before either clears it — every winner
    # would be paid twice.  This flag blocks the second call while first is live.
    if _endraffle_in_progress:
        await update.message.reply_text("⏳ Raffle draw already in progress. Please wait.")
        return
    _endraffle_in_progress = True
    try:
        await _endreffle_inner(update, context)
    finally:
        _endraffle_in_progress = False

