async def toplosers_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """View users who lost the most (deposited but low balance)."""
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    losses = []
    for uid, deposit_total in user_deposit_totals.items():
        current_balance = get_user_balance(uid)
        loss = deposit_total - current_balance
        if loss > 0:
            losses.append((uid, loss, deposit_total, current_balance))
    
    sorted_losers = sorted(losses, key=lambda x: x[1], reverse=True)[:20]
    
    msg = "📉 <b>TOP LOSERS (Deposit - Balance)</b>\n\n"
    for i, (uid, loss, deposited, balance) in enumerate(sorted_losers, 1):
        profile = user_profiles.get(uid, {})
        name = profile.get('first_name', 'Unknown')
        msg += f"{i}. {name}: -${loss:.2f}\n   (Deposited: ${deposited:.2f}, Balance: ${balance:.2f})\n"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def setmindeposit_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Set minimum deposit amount. Usage: /setmindeposit [amount]"""
    global MIN_DEPOSIT
    if not update.message or not update.message.from_user:
        return
    if not is_owner_or_manager(update.message.from_user.id):
        await update.message.reply_text("❌ Owner only command.")
        return
    
    if not context.args:
        await update.message.reply_text(f"Current minimum deposit: ${MIN_DEPOSIT}\nUsage: /setmindeposit [amount]")
        return
    
    try:
        new_min = float(context.args[0])
        if new_min <= 0:
            await update.message.reply_text("❌ Amount must be greater than 0.")
            return
        old_min = MIN_DEPOSIT
        MIN_DEPOSIT = new_min
        save_data_critical()
        logger.info(f"[OWNER] MIN_DEPOSIT changed from ${old_min} → ${MIN_DEPOSIT} by {update.message.from_user.id}")
        await update.message.reply_text(
            f"✅ Minimum deposit updated!\n"
            f"Old: ${old_min:.2f}\n"
            f"New: ${MIN_DEPOSIT:.2f}\n\n"
            f"Change saved and will survive bot restarts."
        )
    except ValueError:
        await update.message.reply_text("❌ Invalid amount. Example: /setmindeposit 5")

