REPLY_COOLDOWN_SECONDS = 1.0


async def handle_group_deposit_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Group-wide handler: any player can ask for a crypto deposit address/QR code
    without needing to @mention the bot. Detects natural language like:
      - 'create me a sol address to deposit'
      - 'give me a usdt address'
      - 'generate btc qr code'
    """
    if not update.message or not update.message.text or not update.message.from_user:
        return
    chat_type = update.message.chat.type
    if chat_type not in ('group', 'supergroup'):
        return

    text = update.message.text
    msg_l = text.lower()
    user_id = str(update.message.from_user.id)
    chat_id = update.message.chat_id

    # Must mention a known coin AND a deposit/address intent keyword
    coin_mentioned = any(coin_kw in msg_l for coin_kw in _COIN_MAP.keys())
    if not coin_mentioned:
        return

    group_deposit_kws = [
        "create me a", "give me a", "generate me a", "make me a", "get me a", "send me a",
        "create me an", "give me an", "generate me an", "make me an", "get me an",
        "create a", "generate a", "make a", "get a",
        "address to deposit", "address for deposit", "deposit address", "wallet address",
        "crypto address", "coin address", "deposit qr", "qr code", "generate qr",
        "create address", "generate address", "create deposit", "generate deposit",
        "make deposit", "send deposit", "btc address", "eth address", "usdt address",
        "sol address", "trx address", "ton address", "bnb address", "ltc address",
        "doge address", "xrp address"
    ]
    if not any(kw in msg_l for kw in group_deposit_kws):
        return

    # Detect coin from message
    np_code = "usdttrc20"
    display_name = "USDT (TRC20)"
    for keyword, code in sorted(_COIN_MAP.items(), key=lambda x: -len(x[0])):
        if keyword in msg_l:
            np_code = code
            for name, c in DEPOSIT_OPTIONS:
                if c == code:
                    display_name = name
                    break
            break

    await context.bot.send_chat_action(chat_id=chat_id, action="typing")

    payment_data = create_nowpayments_payment(20.0, np_code, user_id=user_id)

    if not payment_data:
        await update.message.reply_text(
            f"❌ Could not generate deposit address for {display_name}.\n\n"
            f"Please try /deposit directly.",
            parse_mode=ParseMode.HTML
        )
        return

    pay_address = payment_data.get('pay_address', '')
    pay_amount = payment_data.get('pay_amount', 0)
    payment_id = payment_data.get('payment_id', '')
    user_name = update.message.from_user.first_name or "Player"

    nowpayments_pending_deposits[str(payment_id)] = {
        "user_id": user_id,
        "username": user_name,
        "crypto": np_code,
        "order_id": f"dep_{user_id}_{int(time.time())}",
        "payment_id": payment_id,
        "pay_address": pay_address,
        "created_at": time.time(),
        "status": "waiting"
    }
    save_data()

    deposit_caption = (
        f"💚 <b>Top-up {display_name}</b>\n\n"
        f"📥 <b>Deposit address:</b>\n"
        f"<code>{pay_address}</code>\n\n"
        f"✅ <b>Minimum amount:</b> ${pay_amount:.2f} worth of {display_name}\n\n"
        f"💎 Send the desired amount to the address above.\n"
        f"Your balance will be credited automatically after 1 confirmation.\n\n"
        f"⚠️ <i>If deposit doesn't arrive in 10 minutes, use /reportdeposit</i>"
    )

    keyboard = [[InlineKeyboardButton("🔗 Report Stuck Deposit", callback_data=f"stuck_deposit_{payment_id}")]]

    try:
        qr_img = make_qr_with_logo(pay_address, np_code)
        await update.message.reply_photo(
            photo=qr_img,
            caption=deposit_caption,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode=ParseMode.HTML
        )
    except Exception as qr_err:
        logger.warning(f"QR gen error in group deposit: {qr_err}")
        qr_url = f"https://api.qrserver.com/v1/create-qr-code/?size=400x400&data={pay_address}&margin=2"
        try:
            await update.message.reply_photo(
                photo=qr_url,
                caption=deposit_caption,
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )
        except Exception:
            await update.message.reply_text(
                deposit_caption,
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode=ParseMode.HTML
            )


async def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Central message handler for all user inputs (states)."""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    # Set ContextVar so any bot reply auto-registers ownership
    _handler_user_cv.set(user_id)
    text = update.message.text
    if not text: return

    # ── RPS guard ── ✊/✌️/✋ belong exclusively to the RPS handler.
    # ApplicationHandlerStop is unreliable with concurrent_updates=True so we
    # hard-block those emoji here to prevent double-processing or silent drops.
    _rps_base = text.replace('\ufe0f', '').replace('\ufe0e', '').strip()
    if _rps_base and _rps_base[0] in {'✊', '✌', '✋'}:
        # If there IS an active session the wrapper already handled it;
        # if there ISN'T (backlog/stale) just silently drop — do NOT fall through.
        if user_id in _rps_active:
            await handle_rps_text_choice(update, context)
        return

    chat_type = update.message.chat.type
    is_group = chat_type in ('group', 'supergroup')

    bot_username = context.bot.username or ""
    mention_tag = f"@{bot_username}".lower()
    is_mentioned = mention_tag in text.lower()
    replied_to_bot = (
        update.message.reply_to_message is not None
        and update.message.reply_to_message.from_user is not None
        and update.message.reply_to_message.from_user.id == context.bot.id
    )

    if is_group:
        # In groups: only handle active states OR when tagged/replied to
        if user_id not in user_states and not is_mentioned and not replied_to_bot:
            return  # Ignore unrelated group messages
    else:
        # In private chats: only trigger AI when tagged or replied to bot's message
        # Game states still work normally via the state routing below
        if user_id not in user_states and not is_mentioned and not replied_to_bot:
            return

    # Strip the @mention from text so AI gets clean input
    if is_mentioned and bot_username:
        import re as _re
        text = _re.sub(rf"@{_re.escape(bot_username)}", "", text, flags=_re.IGNORECASE).strip()

    logger.info(f"📨 Message from {user_id} in state {user_states.get(user_id)}: {text[:50]}")

    if user_id in user_states:
        state = user_states[user_id]
        
        logger.info(f"📨 Processing state {state} for user {user_id}")

        # Slot Emoji accepts a custom real-money bet after /se or
        # /slotmachine.  Keep this before the generic financial-state routing
        # so a plain number cannot be interpreted as a deposit/withdrawal.
        if state == "slot_emoji_waiting_bet":
            bet_usd, error = _se_parse_bet(text, user_id)
            if error:
                await update.message.reply_text(error, parse_mode=ParseMode.HTML)
                return
            user_states.pop(user_id, None)
            await _se_send_game_screen(update.message, user_id, bet_usd)
            return

        # Owner broadcast content collection
        if state == UserState.WAITING_BROADCAST_CONTENT:
            await handle_broadcast_content(update, context)
            return

        # Owner panel setting prompts
        if state in (UserState.OWNER_MIN_BET, UserState.OWNER_MIN_WITHDRAWAL):
            if not is_owner_or_manager(update.message.from_user.id):
                user_states[user_id] = UserState.NONE
                await update.message.reply_text("❌ Owner only command.")
                raise ApplicationHandlerStop

            try:
                new_value = float(text.strip().replace("$", "").replace(",", ""))
                if state == UserState.OWNER_MIN_BET:
                    if new_value < 1:
                        await update.message.reply_text("❌ Minimum bet must be at least $1.00. Try again.")
                        raise ApplicationHandlerStop
                    global MIN_BET
                    old_value = MIN_BET
                    MIN_BET = new_value
                    setting_name = "minimum bet"
                else:
                    if new_value <= 0:
                        await update.message.reply_text("❌ Minimum withdrawal must be greater than $0.00. Try again.")
                        raise ApplicationHandlerStop
                    global MIN_WITHDRAWAL
                    old_value = MIN_WITHDRAWAL
                    MIN_WITHDRAWAL = new_value
                    setting_name = "minimum withdrawal"

                user_states[user_id] = UserState.NONE
                save_data_critical()
                await update.message.reply_text(
                    f"✅ <b>{setting_name.title()} updated</b>\n\n"
                    f"Old: ${old_value:.2f}\n"
                    f"New: ${new_value:.2f}\n\n"
                    "The new value is active immediately and saved for future restarts.",
                    parse_mode=ParseMode.HTML,
                )
                await owner_panel(update, context)
            except ValueError:
                await update.message.reply_text("❌ Please send a valid number, for example <code>10</code> or <code>25.50</code>.", parse_mode=ParseMode.HTML)
            raise ApplicationHandlerStop

        # Owner bonus code creation wizard
        if state == UserState.OWNER_BONUS_CREATE:
            handled = await handle_bonus_wizard_message(update, context)
            if handled:
                raise ApplicationHandlerStop
        
        # Financial States - High Priority
        if state in [UserState.NP_WITHDRAWAL_AMOUNT, UserState.CRYPTO_WITHDRAWAL_AMOUNT, UserState.WAITING_WITHDRAW_CRYPTO_AMOUNT]:
            logger.info(f"💰 Routing financial amount state {state} for user {user_id}")
            await handle_np_withdrawal_amount(update, context)
            raise ApplicationHandlerStop
        elif state in [UserState.NP_WITHDRAWAL_ADDRESS, UserState.CRYPTO_WITHDRAWAL_ADDRESS, UserState.WAITING_WITHDRAW_CRYPTO_ADDRESS]:
            logger.info(f"💰 Routing financial address state {state} for user {user_id}")
            await handle_np_withdrawal_address(update, context)
            raise ApplicationHandlerStop
        elif state == UserState.CRYPTO_WAITING_AMOUNT:
            await handle_crypto_deposit_amount(update, context)
            raise ApplicationHandlerStop
        elif state == UserState.CRYPTO_WAITING_PROOF:
            await handle_crypto_deposit_proof_message(update, context)
            raise ApplicationHandlerStop
        elif state in (UserState.INR_WAITING_AMOUNT, "inr_waiting_amount"):
            await handle_inr_amount(update, context)
            raise ApplicationHandlerStop
        elif state in (UserState.INR_WAITING_PROOF, "inr_waiting_proof"):
            await handle_inr_proof_message(update, context)
            raise ApplicationHandlerStop
        elif state == "waiting_for_amount":
            raise ApplicationHandlerStop
        elif state == UserState.WAITING_WITHDRAWAL_AMOUNT:
            await process_withdrawal_amount(update, context)
            raise ApplicationHandlerStop
        elif state == UserState.WAITING_WITHDRAWAL_UPI:
            user_states[str(update.message.from_user.id)] = UserState.NONE
            keyboard = [[InlineKeyboardButton("💎 Withdraw Crypto", callback_data="crypto_withdrawals")]]
            await update.message.reply_text(
                "💎 Please use the crypto withdrawal option.",
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
            raise ApplicationHandlerStop
        elif state == UserState.WAITING_WITHDRAWAL_SCREENSHOT:
            await handle_owner_withdrawal_screenshot(update, context)
            raise ApplicationHandlerStop

    # AI only responds when bot is tagged or someone replies to its message
    if not is_mentioned and not replied_to_bot:
        return

    if not text or len(text.strip()) < 1:
        return

    user_name = update.message.from_user.first_name or "Player"

    # Show typing indicator while AI thinks
    try:
        await context.bot.send_chat_action(
            chat_id=update.message.chat_id,
            action="typing"
        )
    except Exception:
        pass

    if await try_manager_action(update, context, user_id, text.strip()):
        return

async def handle_sticker_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle sticker messages - owner can send coinflip, roulette, or other stickers."""
    if not update.message or not update.message.from_user or not update.message.sticker:
        return

    user_id = str(update.message.from_user.id)

    if not is_owner_or_manager(user_id):
        return

    sticker = update.message.sticker
    sticker_id = sticker.file_id
    sticker_set_name = sticker.set_name if sticker.set_name else None

    if not sticker_set_name:
        await update.message.reply_text("❌ This sticker doesn't belong to any sticker pack")
        return

    # Check if this is a roulette sticker pack
    user_states[f"{user_id}_pending_sticker"] = sticker_id
    user_states[f"{user_id}_pending_sticker_set"] = sticker_set_name

    keyboard = [
        [InlineKeyboardButton("🎰 Roulette Sticker Pack", callback_data="setsticker_roulette")],
        [InlineKeyboardButton("🔫 Rollers Roulette Sticker Pack", callback_data="setsticker_rollers_roulette")],
        [InlineKeyboardButton("🔄 Coinflip Stickers", callback_data="setsticker_coinflip")],
        [InlineKeyboardButton("❌ Cancel", callback_data="cancel_sticker")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    await update.message.reply_text(
        f"🎲 <b>Sticker Pack Detected</b>\n\n"
        f"Pack name: `{sticker_set_name}`\n"
        f"Sticker ID: `{sticker_id}`\n\n"
        f"What type of sticker pack is this?",
        reply_markup=reply_markup,
        parse_mode=ParseMode.HTML
    )

async def handle_dice_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle dice messages from users to process game turns."""
    if not update.message or not update.message.from_user or not update.message.dice:
        return

    # Block forwarded dice — prevents replay attacks with old outcomes
    if getattr(update.message, 'forward_date', None) or getattr(update.message, 'forward_origin', None):
        await update.message.reply_text("❌ Forwarded dice are not valid. Please send a fresh live roll.")
        return

    user_id = str(update.message.from_user.id)
    dice_value = update.message.dice.value

    # ── Stale session guard ──────────────────────────────────────────────
    # Any active_games entry older than STALE_GAME_TIMEOUT_SECS is treated as
    # abandoned/leaked state (e.g. left behind by an error path) and purged so
    # a random dice sticker the user sends later doesn't get silently
    # absorbed into a long-dead game and keep "continuing" forever.
    if user_id in active_games and is_active_game_stale(active_games[user_id]):
        logger.warning(f"[STALE_GAME] Purging stale active_games entry for user={user_id}")
        del active_games[user_id]
        try:
            await update.message.reply_text(
                "⚠️ Your previous game session expired. Start a new game with a command like /dr, /dice, or /darts."
            )
        except Exception:
            pass
        return

    if user_id in active_games:
        game_data = active_games[user_id]

        # ── If bot is still rolling, tell player to wait instead of ignoring ──
        if game_data.get('state') == 'bot_turn':
            try:
                await update.message.reply_text(
                    "⏳ <b>Bot is still rolling — please wait for the bot to finish before sending your dice!</b>",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
            return

        if game_data.get('state') == 'player_turn':
            # ── Anti-spam: only one dice processed at a time per user ───────────
            if user_id in _player_roll_processing:
                try:
                    await update.message.reply_text(
                        "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                        parse_mode=ParseMode.HTML
                    )
                except Exception:
                    pass
                return
            _player_roll_processing.add(user_id)
            try:
                # Add to round total
                game_data['player_round_total'] = game_data.get('player_round_total', 0) + dice_value
                game_data['round_rolls'] = game_data.get('round_rolls', 0) + 1
                
                rolls_needed = game_data.get('rolls', 1)
                
                if game_data['round_rolls'] >= rolls_needed:
                    # Player finished their rolls for this round — release lock before async work
                    _player_roll_processing.discard(user_id)
                    game_data['round_rolls'] = 0
                    
                    # Determine round winner
                    p_round_score = game_data['player_round_total']
                    b_round_score = game_data['bot_round_total']
                    
                    if p_round_score > b_round_score:
                        game_data['player_wins'] += 1
                    elif b_round_score > p_round_score:
                        game_data['bot_wins'] += 1
                    
                    # Reset round totals
                    game_data['player_round_total'] = 0
                    game_data['bot_round_total'] = 0
                    
                    # Check match end
                    wins_needed = game_data['wins_needed']
                    if game_data['player_wins'] >= wins_needed or game_data['bot_wins'] >= wins_needed:
                        username = update.message.from_user.username or update.message.from_user.first_name or "Player"
                        winner = username if game_data['player_wins'] >= wins_needed else "Bot"
                        bet_amount = game_data['bet_amount']
                        win_amount = bet_amount * 1.92
                        user_currency = get_user_currency(user_id)
                        
                        final_msg = (
                            f"<b>Game over!</b>\n\n"
                            f"<b>Score:</b>\n"
                            f"{username} • {game_data['player_wins']}\n"
                            f"Bot • {game_data['bot_wins']}\n\n"
                        )
                        
                        # ANTI-GLITCH: Mark as won/refunded BEFORE payout, then remove
                        game_data['won'] = True
                        if user_id in active_games:
                            del active_games[user_id]

                        if winner == username:
                            ultra_secure_add_user_balance(user_id, win_amount, "win")
                            deduct_house_balance(win_amount - bet_amount)
                            add_match_history(user_id, game_data.get('game_name', 'dice'), bet_amount, 'win', win_amount)
                            final_msg += f"<b>{username} wins {format_balance_in_currency(win_amount, user_currency)}!</b>"
                        else:
                            add_match_history(user_id, game_data.get('game_name', 'dice'), bet_amount, 'loss', 0)
                            final_msg += f"<b>Bot wins!</b>"
                        
                        track_wagering(user_id, bet_amount, 1.92)
                        await asyncio.to_thread(save_data_critical)  # non-blocking — don't stall event loop
                        game_format = game_data.get('format', '1d1w')
                        kb = [[success_btn("🔄 Play Again", callback_data=f"dice_start_bot_{game_format}_{bet_amount}")]]
                        await update.message.reply_text(final_msg, reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML)
                        if winner == username:
                            await _send_player_win_sticker(context.bot, update.message.chat_id)
                        return

                    game_data['state'] = 'bot_turn'
                    save_data()
                    
                    # Show score and bot's turn
                    username = update.message.from_user.username or update.message.from_user.first_name or "Player"
                    score_msg = (
                        f"<b>Score</b>\n\n"
                        f"{username}: {game_data['player_wins']}\n"
                        f"Bot: {game_data['bot_wins']}"
                    )
                    await update.message.reply_text(score_msg, parse_mode=ParseMode.HTML)
                    
                    # Trigger bot roll
                    class PseudoQuery:
                        def __init__(self, message):
                            self.message = message
                            self.from_user = message.from_user
                        async def answer(self, *args, **kwargs): pass
                    
                    await handle_animated_game_turn(PseudoQuery(update.message), context, user_id)
                else:
                    # Need more rolls — hold lock while sending "one more roll" so rapid
                    # dice are blocked until the player sees the prompt.
                    remaining = rolls_needed - game_data['round_rolls']
                    save_data()
                    try:
                        _nm = update.message.from_user.first_name or "Player"
                        roll_word = "roll" if remaining == 1 else "rolls"
                        await update.message.reply_text(
                            f"🎲 <b>{_nm}</b>, {remaining} more {roll_word}!",
                            parse_mode=ParseMode.HTML
                        )
                    except Exception:
                        pass
                    # Lock released here (finally block) — player may now send next dice
            finally:
                _player_roll_processing.discard(user_id)
            return  # only return if we actually handled a 'player_turn' state game
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    if user_id not in active_games:
        return

    game_data = active_games[user_id]
    game_type = game_data.get('type', '')
    username = update.message.from_user.username or update.message.from_user.first_name or "Player"

    # ── Emoji setup transition (player sends emoji to START game) ──────────
    if game_type and game_type.startswith('sports_') and game_type.endswith('_setup'):
        await start_emoji_game_from_setup(update, context, user_id, game_data)
        return

    # ── PvP games: two human players rolling against each other ──────────────
    if game_type == 'sports_pvp':
        await handle_pvp_dice_game(update, context, user_id, username, game_data)
        return

    # ── Sports games: route directly — handle_sports_dice_game owns ALL accumulation ──
    if game_type and (game_type.startswith('sports_') or any(g in game_type for g in ['darts', 'soccer', 'bowling', 'basketball'])):
        logger.info(
            f"[DICE_DIAG] sports dispatch user={user_id} type={game_type} "
            f"state={game_data.get('state')} auto_rolling={game_data.get('auto_rolling_player')} "
            f"is_crazy={game_data.get('is_crazy')} dice_value={update.message.dice.value} "
            f"dice_emoji={update.message.dice.emoji!r}"
        )
        if game_data.get('state') != EmojiGameState.WAITING_PLAYER_ROLL:
            logger.warning(
                f"[DICE_DIAG] REJECTED — state {game_data.get('state')!r} != WAITING_PLAYER_ROLL "
                f"({EmojiGameState.WAITING_PLAYER_ROLL!r})"
            )
            try:
                await update.message.reply_text(
                    "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
            return
        if game_data.get('auto_rolling_player'):
            logger.warning(f"[DICE_DIAG] REJECTED — auto_rolling_player flag is set")
            try:
                await update.message.reply_text(
                    "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
            return
        await handle_sports_dice_game(update, context, user_id, username, game_data)
        return

    # ── Everything below is for regular dice / PvP only ───────────────────
    if game_data.get('state') != EmojiGameState.WAITING_PLAYER_ROLL:
        try:
            await update.message.reply_text(
                "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return
    if game_data.get('auto_rolling_player'):
        try:
            await update.message.reply_text(
                "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    # Rate limiting — only on the FIRST roll of each round
    # STRICT: reject any dice sent beyond the chosen roll count
    rolls_allowed = int(game_data.get('rolls', 1))
    if game_data.get('player_round_rolls', 0) >= rolls_allowed:
        try:
            await update.message.reply_text(
                "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    if game_data.get('player_round_rolls', 0) == 0:
        last_roll_time = context.user_data.get('last_roll_time', 0)
        current_time = time.time()
        if current_time - last_roll_time < 2:
            await update.message.reply_text(
                "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                parse_mode=ParseMode.HTML
            )
            return
        context.user_data['last_roll_time'] = current_time

    if not update.message.dice:
        return
    dice_value = update.message.dice.value
    dice_emoji = update.message.dice.emoji

    expected_emoji = game_data.get('dice_emoji')
    if expected_emoji:
        expected_str = str(expected_emoji.value) if hasattr(expected_emoji, 'value') else str(expected_emoji)
        if dice_emoji != expected_str:
            return

    game_data['player_round_rolls'] = game_data.get('player_round_rolls', 0) + 1
    game_data['player_round_total'] = game_data.get('player_round_total', 0) + dice_value
    logger.info(f"🎲 User {user_id} rolled {dice_value}. Total: {game_data['player_round_total']}/{game_data['rolls']}")

    rolls_left = rolls_allowed - game_data['player_round_rolls']

    # Lock immediately when last roll is in — prevents any extra dice slipping through
    if rolls_left <= 0:
        game_data['auto_rolling_player'] = True
        active_games[user_id] = game_data

    if rolls_left > 0:
        save_data()
        return

    if user_id not in active_games:
        return

    game_data = active_games[user_id]
    game_type = game_data.get('type')

    if game_type == 'player_dice' or (game_type and game_type.startswith('dice_')):
        if not update.message.dice: return
        await handle_regular_dice_game(update, context, user_id, username, game_data)

async def start_emoji_game_from_setup(update: Update, context: ContextTypes.DEFAULT_TYPE, user_id: str, setup_data: dict) -> None:
    """Initialize the emoji game: Player rolls first, then bot."""
    game_name = setup_data['game_name']
    bet_amount = setup_data['bet_amount']
    rolls_count = setup_data['rolls_count']
    wins_needed = setup_data['first_to']
    emoji = setup_data['emoji']
    
    # If it's a new game, the user sent the emoji to START the game.
    # We set up the state but we DO NOT process it as a game roll yet.
    # We send a "Your turn" message and wait for the NEXT roll which will be the first round.
    
    # 1. Deduct balance
    if not deduct_user_balance(user_id, bet_amount):
        await update.message.reply_text("❌ Failed to place bet. Check your balance.")
        return

    # 2. Setup active game state
    uname = update.message.from_user.username or update.message.from_user.first_name or "Player"
    game_data = {
        'type': f'sports_{game_name}_bot',
        'game_name': game_name,
        'game_type': game_name,
        'emoji': emoji,
        'dice_emoji': emoji,
        'username': uname,
        'wins_needed': wins_needed,
        'rolls': rolls_count,
        'bet_amount': bet_amount,
        'player_wins': 0,
        'bot_wins': 0,
        'round': 1,
        'turn_order': 'bot_first',
        'state': EmojiGameState.WAITING_BOT_ROLL,
        'player_round_rolls': 0,
        'player_round_total': 0,
        'bot_round_total': 0,
        'bot_round_rolls': 0,
        'bot_has_rolled': False,
        'bot_last_total': 0,
        'chat_id': update.message.chat_id,
        'chat_type': update.message.chat.type
    }
    active_games[user_id] = game_data
    save_data()

    # Bot always rolls first — trigger immediately
    await handle_bot_roll_turn(update, context, user_id)
    return

async def handle_pvp_dice_game(update: Update, context: ContextTypes.DEFAULT_TYPE, user_id: str, username: str, game_data: dict) -> None:
    """Handle PvP animated dice game between two human players."""
    chat_id       = game_data.get('chat_id') or update.message.chat_id
    emoji         = game_data.get('emoji', '🎲')
    dice_emoji_str = game_data.get('dice_emoji', '🎲')
    player1_id    = game_data.get('player1_id')
    player2_id    = game_data.get('player2_id')
    player1_name  = game_data.get('player1_name', 'Player 1')
    player2_name  = game_data.get('player2_name', 'Player 2')
    # HTML-safe versions for all formatted messages
    p1_safe       = _html.escape(str(player1_name))
    p2_safe       = _html.escape(str(player2_name))
    rolls_count   = int(game_data.get('rolls_count', 1))
    wins_needed   = int(game_data.get('wins_needed', 3))
    current_player = int(game_data.get('current_player', 1))
    bet_amount    = float(game_data.get('bet_amount', 0))
    sport         = game_data.get('game_name', 'dice')
    user_currency = get_user_currency(player1_id)

    # Validate emoji type
    if update.message.dice.emoji != dice_emoji_str:
        return

    # Validate this user is actually a participant in this PvP game
    if user_id not in [player1_id, player2_id]:
        return  # Ignore rolls from non-participants silently

    # Validate it's this player's turn — silently ignore out-of-turn rolls
    if current_player == 1 and user_id != player1_id:
        try:
            await update.message.reply_text("⏳ It's not your turn yet! Wait for the other player.")
        except Exception:
            pass
        return
    if current_player == 2 and user_id != player2_id:
        try:
            await update.message.reply_text("⏳ It's not your turn yet! Wait for the other player.")
        except Exception:
            pass
        return

    roll_value = int(update.message.dice.value)

    # Accumulate roll for current player
    if current_player == 1:
        game_data['player1_round_rolls'] = int(game_data.get('player1_round_rolls', 0)) + 1
        game_data['player1_round_total'] = int(game_data.get('player1_round_total', 0)) + roll_value
        rolls_done = game_data['player1_round_rolls']
    else:
        game_data['player2_round_rolls'] = int(game_data.get('player2_round_rolls', 0)) + 1
        game_data['player2_round_total'] = int(game_data.get('player2_round_total', 0)) + roll_value
        rolls_done = game_data['player2_round_rolls']

    # Sync state to both players
    active_games[player1_id] = game_data
    active_games[player2_id] = game_data
    save_data()

    # Player hasn't finished all their rolls yet — prompt for more
    if rolls_done < rolls_count:
        remaining = rolls_count - rolls_done
        cur_safe  = p1_safe if current_player == 1 else p2_safe
        try:
            await update.message.reply_text(
                f"🎲 <b>{cur_safe}</b>, {remaining} more roll(s)!",
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    # Player 1 just finished — ask Player 2 to roll
    if current_player == 1:
        p1_total = game_data['player1_round_total']
        game_data['current_player'] = 2
        game_data['player2_round_rolls'] = 0
        game_data['player2_round_total'] = 0
        active_games[player1_id] = game_data
        active_games[player2_id] = game_data
        save_data()
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"1️⃣ <b>{p1_safe}</b> rolled <b>{p1_total}</b>\n\n2️⃣ {p2_safe}, your turn! Send {emoji}",
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"[PVP] Failed to send p1-rolled message: {e}")
        return

    # Both players have rolled — determine round result
    p1_total = int(game_data.get('player1_round_total', 0))
    p2_total = int(game_data.get('player2_round_total', 0))

    if p1_total == p2_total:
        # Tie — replay round
        game_data['current_player'] = 1
        game_data['player1_round_rolls'] = 0
        game_data['player1_round_total'] = 0
        game_data['player2_round_rolls'] = 0
        game_data['player2_round_total'] = 0
        active_games[player1_id] = game_data
        active_games[player2_id] = game_data
        save_data()
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"🤝 <b>Tie! Both scored {p1_total}. Replaying round!</b>\n\n1️⃣ {p1_safe}, send {emoji}",
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"[PVP] Failed to send tie message: {e}")
        return

    is_crazy = bool(game_data.get('is_crazy', False))
    p1_won_round = (p1_total < p2_total) if is_crazy else (p1_total > p2_total)
    if p1_won_round:
        game_data['player1_wins'] = int(game_data.get('player1_wins', 0)) + 1
    else:
        game_data['player2_wins'] = int(game_data.get('player2_wins', 0)) + 1

    p1_wins = int(game_data.get('player1_wins', 0))
    p2_wins = int(game_data.get('player2_wins', 0))
    score_line = f"1️⃣ {p1_safe}: {p1_wins}\n2️⃣ {p2_safe}: {p2_wins}"

    # ── Game over? ────────────────────────────────────────────────────────────
    if p1_wins >= wins_needed or p2_wins >= wins_needed:
        for pid in [player1_id, player2_id]:
            if pid in active_games:
                del active_games[pid]
        save_data()

        total_pot = bet_amount * 2
        payout    = round(total_pot * 0.96, 2)

        if p1_wins >= wins_needed:
            winner_id   = player1_id
            loser_id    = player2_id
            winner_disp = f"🏆 {p1_safe}"
        else:
            winner_id   = player2_id
            loser_id    = player1_id
            winner_disp = f"🏆 {p2_safe}"

        ultra_secure_add_user_balance(winner_id, payout, "pvp_win")
        await asyncio.to_thread(save_data_critical)  # non-blocking — don't stall event loop
        deduct_house_balance(total_pot * 0.04)

        # Record match history and wagering for BOTH players
        add_match_history(winner_id, f"{sport}_pvp", bet_amount, 'win', payout)
        add_match_history(loser_id,  f"{sport}_pvp", bet_amount, 'loss', 0)
        track_wagering(winner_id, bet_amount, payout / bet_amount if bet_amount else 1.92)
        track_wagering(loser_id,  bet_amount, 0)

        won_str = format_balance_in_currency(payout, user_currency)
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=(
                    f"🏆 <b>Match Over!</b>\n\n"
                    f"<b>Score</b>\n\n{score_line}\n\n"
                    f"🎉 <b>{winner_disp} wins {won_str}!</b>"
                ),
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"[PVP] Failed to send game-over message: {e}")
        return

    # ── Game continues — next round ───────────────────────────────────────────
    game_data['round']              = int(game_data.get('round', 1)) + 1
    game_data['current_player']     = 1
    game_data['player1_round_rolls'] = 0
    game_data['player1_round_total'] = 0
    game_data['player2_round_rolls'] = 0
    game_data['player2_round_total'] = 0
    active_games[player1_id] = game_data
    active_games[player2_id] = game_data
    save_data()

    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(
                f"<b>Score</b>\n\n{score_line}\n\n"
                f"Round {game_data['round']} — 1️⃣ {p1_safe}, send {emoji}"
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.error(f"[PVP] Failed to send next-round message: {e}")


async def handle_sports_dice_game(update: Update, context: ContextTypes.DEFAULT_TYPE, user_id: str, username: str, game_data: dict) -> None:
    """Handle sports dice game: bot rolls first each round, then player rolls, then score shown."""
    global crypto_house_balances

    # Always resolve chat_id up front so every code path has it
    chat_id = game_data.get('chat_id') or update.message.chat_id
    chat_type = game_data.get('chat_type') or update.message.chat.type
    user_currency = get_user_currency(user_id)
    game_name = game_data.get('game_name', 'dice')
    username_val = game_data.get('username', username)
    rolls_count = int(game_data.get('rolls', 1))
    wins_needed = int(game_data.get('wins_needed', 3))
    bet_amount = float(game_data.get('bet_amount', 0))

    # ── Validate incoming dice message ─────────────────────────────────────
    if not update.message or not update.message.dice:
        return

    expected_emoji = game_data.get('dice_emoji')
    if expected_emoji:
        expected_str = str(expected_emoji.value) if hasattr(expected_emoji, 'value') else str(expected_emoji)
        if update.message.dice.emoji != expected_str:
            return

    # STRICT: reject any dice beyond the chosen roll count before touching state
    if int(game_data.get('player_round_rolls', 0)) >= rolls_count:
        return

    # ── Rate-limit: only on the very first roll of each round ──────────────
    if game_data.get('player_round_rolls', 0) == 0:
        now = time.time()
        if now - game_data.get('last_roll_time', 0) < 1.5:
            await update.message.reply_text(
                "<b>Please don't send dice too quickly. Wait for bot to respond.</b>",
                parse_mode=ParseMode.HTML
            )
            return
        game_data['last_roll_time'] = now
        game_data['player_round_total'] = 0  # reset total on first roll of round

    # ── Accumulate player roll ──────────────────────────────────────────────
    game_data['player_round_rolls'] = int(game_data.get('player_round_rolls', 0)) + 1
    rolled_val = int(update.message.dice.value)
    game_data['player_round_total'] = int(game_data.get('player_round_total', 0)) + rolled_val

    logger.info(
        f"🎲 Player roll {game_data['player_round_rolls']}/{rolls_count}: "
        f"{rolled_val} → total {game_data['player_round_total']}"
    )

    # Lock immediately on the last roll so no extra dice can slip through
    if game_data['player_round_rolls'] >= rolls_count:
        game_data['auto_rolling_player'] = True

    active_games[user_id] = game_data
    save_data()

    # Still waiting for more rolls from the player this round
    if game_data['player_round_rolls'] < rolls_count:
        _rolls_done = int(game_data.get('player_round_rolls', 0))
        _rolls_left = rolls_count - _rolls_done
        _player_first = update.message.from_user.first_name or username_val or "Player"
        if _rolls_left == 1:
            try:
                await update.message.reply_text(
                    f"🎲 <b>{_player_first}</b>, one more roll!",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
        return

    # ── Player finished all rolls for this round ───────────────────────────
    player_total = int(game_data.get('player_round_total', 0))
    bot_has_rolled = game_data.get('bot_has_rolled', False)
    bot_total = int(game_data.get('bot_round_total', 0))

    # If bot hasn't rolled yet (player-first mode), bot rolls now
    if not bot_has_rolled:
        bot_roll_emoji = game_data.get('dice_emoji', '🎲')
        bot_values = []
        for _ in range(rolls_count):
            msg = None
            timed_out = False
            try:
                msg = await asyncio.wait_for(
                    dealer_send_dice(
                        chat_id=chat_id, emoji=bot_roll_emoji,
                        main_bot=context.bot, chat_type=chat_type, user_id=int(user_id)
                    ),
                    timeout=20.0
                )
            except asyncio.TimeoutError:
                timed_out = True
            except Exception as e:
                logger.warning(f"Bot roll error: {e}")
            if msg and hasattr(msg, 'dice') and msg.dice:
                bot_values.append(int(msg.dice.value))
            elif timed_out:
                bot_values.append(random.randint(1, 6))
            else:
                try:
                    fb = await asyncio.wait_for(
                        context.bot.send_dice(chat_id=chat_id, emoji=bot_roll_emoji),
                        timeout=20.0
                    )
                    bot_values.append(int(fb.dice.value))
                except Exception:
                    bot_values.append(random.randint(1, 6))
        bot_total = sum(bot_values)
        game_data['bot_round_total'] = bot_total
        game_data['bot_has_rolled'] = True
        active_games[user_id] = game_data
        save_data()

    # ── Determine round winner ─────────────────────────────────────────────
    if player_total == bot_total:
        # Tie → replay the round
        await context.bot.send_message(
            chat_id=chat_id,
            text=_rc_same_values_text(game_name, user_id, username_val, player_total),
            parse_mode=ParseMode.HTML
        )
        game_data['player_round_rolls'] = 0
        game_data['player_round_total'] = 0
        game_data['bot_round_total'] = 0
        game_data['bot_round_rolls'] = 0
        game_data['bot_has_rolled'] = False
        game_data['bot_rolling_active'] = False
        game_data['auto_rolling_player'] = False  # unlock player for replay
        game_data['last_roll_time'] = 0
        game_data['state'] = EmojiGameState.WAITING_BOT_ROLL
        active_games[user_id] = game_data
        save_data()
        await handle_bot_roll_turn(update, context, user_id)
        return

    is_crazy = bool(game_data.get('is_crazy', False))
    player_won_round = (player_total < bot_total) if is_crazy else (player_total > bot_total)
    if player_won_round:
        game_data['player_wins'] = int(game_data.get('player_wins', 0)) + 1
    else:
        game_data['bot_wins'] = int(game_data.get('bot_wins', 0)) + 1

    player_wins = int(game_data.get('player_wins', 0))
    bot_wins    = int(game_data.get('bot_wins', 0))
    active_games[user_id] = game_data
    save_data()

    score_line = f"{username_val}: {player_wins}\nBot: {bot_wins}"

    # ── Game over? ──────────────────────────────────────────────────────────
    if player_wins >= wins_needed or bot_wins >= wins_needed:
        bet_internal = float(game_data.get('bet_amount', 0))
        dice_format = f"{rolls_count}d{wins_needed}w"

        game_data['won'] = True
        if user_id in active_games:
            del active_games[user_id]

        if player_wins >= wins_needed:
            payout = round(bet_internal * 1.92, 2)
            logger.info(f"💰 WIN PAYOUT: user={user_id} bet={bet_internal} payout={payout} game={game_name}")
            pre_bal = get_user_balance(user_id)
            ultra_secure_add_user_balance(user_id, payout, "win")
            post_bal = get_user_balance(user_id)
            logger.info(f"✅ BALANCE UPDATED: {user_id} {pre_bal:.2f} → {post_bal:.2f} (+{payout:.2f})")
            deduct_house_balance(payout - bet_internal)
            add_match_history(user_id, game_name, bet_internal, 'win', payout)
            track_wagering(user_id, bet_internal, 1.92)
            await asyncio.to_thread(save_data_critical)  # non-blocking — don't stall event loop
            try:
                await _send_bot_lose_sticker(context, chat_id)
            except Exception:
                pass
            _r2_won = True; _r2_amt = payout; _r2_wpts = player_wins; _r2_lpts = bot_wins
        else:
            add_house_balance(bet_internal)
            add_loss_to_rakeback(user_id, bet_internal)
            add_match_history(user_id, game_name, bet_internal, 'loss', 0)
            track_wagering(user_id, bet_internal, 0)
            await asyncio.to_thread(save_data_critical)  # non-blocking — don't stall event loop
            _r2_won = False; _r2_amt = bet_internal; _r2_wpts = bot_wins; _r2_lpts = player_wins

        mode_char = 'c' if is_crazy else 'n'
        await _send_game_result_msg(
            context, chat_id,
            player_won=_r2_won,
            player_name=username_val, player_id=user_id,
            winner_pts=_r2_wpts, loser_pts=_r2_lpts,
            amount=_r2_amt, user_currency=user_currency,
            reply_markup=_rc_end_keyboard(game_name, dice_format, bet_internal, mode_char)
        )
        if _r2_won:
            await _send_player_win_sticker(context.bot, chat_id)
        return

    # ── Game continues — show score, then start next round ─────────────────
    bet_internal = float(game_data.get('bet_amount', 0))
    total_rounds = player_wins + bot_wins
    if player_wins > bot_wins:
        cashout_ratio = 0.4 + (player_wins / wins_needed) * 0.7
    elif player_wins == bot_wins:
        cashout_ratio = 0.25 + (total_rounds / (wins_needed * 2)) * 0.3
    else:
        cashout_ratio = 0.1 + (player_wins / wins_needed) * 0.2
    cashout_amount = round(bet_internal * cashout_ratio, 2)
    game_data['current_cashout'] = cashout_amount

    co_kb = [[success_btn(
        f"Cashout {format_balance_in_currency(cashout_amount, user_currency)}",
        callback_data="cashout_animated"
    )]]
    await context.bot.send_message(
        chat_id=chat_id,
        text=(
            f"{_rc_tag('📈')} <b>SCORE</b>\n\n"
            f"{_rc_tag('👤')} @{username_val}: <b>{player_wins}</b>\n"
            f"{_rc_tag('🤖')} Bot: <b>{bot_wins}</b>\n\n"
            f"{_rc_tag(_rc_game_emoji(game_name))} Next round starts now."
        ),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(co_kb)
    )

    # ── Reset ALL round state cleanly for next round ─────────────────────
    game_data['round'] = int(game_data.get('round', 1)) + 1
    game_data['state'] = EmojiGameState.WAITING_BOT_ROLL
    game_data['player_round_rolls'] = 0
    game_data['player_round_total'] = 0
    game_data['bot_round_total'] = 0
    game_data['bot_round_rolls'] = 0
    game_data['bot_has_rolled'] = False
    game_data['bot_rolling_active'] = False
    game_data['auto_rolling_player'] = False  # unlock player for next round
    game_data['last_roll_time'] = 0           # reset rate limit for next round
    active_games[user_id] = game_data
    save_data()

    # ── Bot always rolls first at the start of every new round ────────────
    try:
        await handle_bot_roll_turn(update, context, user_id)
    except Exception as e:
        logger.error(f"Next round bot roll failed: {e}", exc_info=True)
        # Recovery: manually set state so player can still roll
        if user_id in active_games:
            active_games[user_id]['state'] = EmojiGameState.WAITING_PLAYER_ROLL
            active_games[user_id]['bot_has_rolled'] = True
            active_games[user_id]['bot_rolling_active'] = False
            active_games[user_id]['auto_rolling_player'] = False
            active_games[user_id]['player_round_rolls'] = 0
            save_data()
        await context.bot.send_message(
            chat_id=chat_id,
            text=_rc_turn_text(game_name, user_id, username_val),
            parse_mode=ParseMode.HTML,
            reply_markup=_rc_player_turn_keyboard(game_name, user_id),
        )
    return

async def handle_regular_dice_game(update: Update, context: ContextTypes.DEFAULT_TYPE, user_id: str, username: str, game_data: dict) -> None:
    """Handle regular dice game logic - Bot rolled first, player responds."""
    global crypto_house_balances
    user_currency = get_user_currency(user_id)

    # CRITICAL FIX: Always get fresh game state from active_games to avoid stale data
    if user_id not in active_games:
        return
    game_data = active_games[user_id]
    
    # Initialize state if not set (prevents game from getting stuck)
    if 'state' not in game_data:
        game_data['state'] = EmojiGameState.WAITING_PLAYER_ROLL
        active_games[user_id] = game_data
        save_data()
    
    if game_data.get('state') != EmojiGameState.WAITING_PLAYER_ROLL:
        logger.info(f"🎲 DICE: Game not in WAITING state (state={game_data.get('state')}), skipping")
        return
    
    logger.info(f"🎲 DICE: Processing roll for {username}")

    # Get game settings
    rolls_count = game_data.get('rolls', 1)
    wins_needed = game_data.get('wins_needed', 3)
    bet_amount = game_data.get('bet_amount', 45)

    # Track player's roll count for this round
    if 'player_round_rolls' not in game_data:
        game_data['player_round_rolls'] = 0
        game_data['player_round_total'] = 0

    # FORCE RESET ON FIRST ROLL OF ROUND
    if game_data['player_round_rolls'] == 0:
        game_data['player_round_total'] = 0
        logger.info(f"🔄 ROUND RESET: Starting fresh round for {username}")

    # Add user's actual dice roll to round total (no rigging on dice itself)
    game_data['player_round_rolls'] = int(game_data.get('player_round_rolls', 0)) + 1
    game_data['player_round_total'] = int(game_data.get('player_round_total', 0)) + int(update.message.dice.value)
    
    logger.info(f"🎲 PLAYER ROLL {game_data['player_round_rolls']}/{rolls_count}: {update.message.dice.value} (Total: {game_data['player_round_total']})")
    
    # CRITICAL: Save after each roll to prevent state loss
    active_games[user_id] = game_data
    save_data()

    # Check if player has completed all rolls for this round
    if game_data['player_round_rolls'] < rolls_count:
        # Silently collect emojis - no message
        return

    # Player finished their rolls - Check if bot already rolled first
    player_total = game_data['player_round_total']
    
    chat_id = game_data.get('chat_id', update.message.chat_id)
    chat_type = game_data.get('chat_type', update.message.chat.type)
    bot_roll_emoji = game_data.get('dice_emoji', '🎲')

    # CHECK IF BOT ALREADY ROLLED FIRST - use stored value
    if 'bot_last_total' in game_data and game_data['bot_last_total'] > 0:
        bot_total = game_data['bot_last_total']
        logger.info(f"🤖 Using stored bot total: {bot_total} (bot rolled first)")
        # Clear for next round
        game_data['bot_last_total'] = 0
    else:
        # Bot needs to roll now (player rolled first scenario)
        bot_total = 0
        dice_values = []
        for i in range(rolls_count):
            try:
                bot_dice_msg = await asyncio.wait_for(
                    dealer_send_dice(
                        chat_id=chat_id,
                        emoji=bot_roll_emoji,
                        main_bot=context.bot,
                        chat_type=chat_type,
                        user_id=int(user_id)
                    ),
                    timeout=15.0
                )
            except asyncio.TimeoutError:
                logger.error(f"⌛ Dealer Bot timeout for {username}.")
                bot_dice_msg = None

            if bot_dice_msg and hasattr(bot_dice_msg, 'dice') and bot_dice_msg.dice:
                dice_value = bot_dice_msg.dice.value
                dice_values.append(dice_value)
                bot_total += dice_value
            else:
                dice_value = random.randint(1, 6)
                dice_values.append(dice_value)
                bot_total += dice_value
            await asyncio.sleep(0.5)

    # DETERMINING ROUND WINNER - NO HOUSE EDGE
    bot_total_val = int(bot_total)
    player_total_val = int(game_data.get('player_round_total', 0))
    
    if player_total_val > bot_total_val:
        game_data['player_wins'] = int(game_data.get('player_wins', 0)) + 1
        result_text = f"✅ <b>You won this round!</b> ({player_total_val} vs {bot_total_val})"
    elif bot_total_val > player_total_val:
        game_data['bot_wins'] = int(game_data.get('bot_wins', 0)) + 1
        result_text = f"💀 <b>Bot won this round!</b> ({bot_total_val} vs {player_total_val})"
    else:
        # Tie handling
        await context.bot.send_message(
            chat_id=chat_id, 
            text=_rc_same_values_text(
                game_data.get('game_name', 'dice'),
                user_id,
                game_data.get('username', username),
                player_total_val,
            ),
            parse_mode=ParseMode.HTML
        )
        game_data['player_round_rolls'] = 0
        game_data['player_round_total'] = 0
        game_data['state'] = EmojiGameState.WAITING_PLAYER_ROLL
        active_games[user_id] = game_data # Save the reset state
        save_data()
        
        # Trigger bot roll again for the tie-break
        game_type = game_data.get('type', '')
        if game_type == 'sports_predict':
             # Re-trigger bot roll for predict
             bot_total = 0
             dice_emoji = game_data.get('dice_emoji', '🎲')
             for i in range(rolls_count):
                 bot_dice_msg = await context.bot.send_dice(chat_id=chat_id, emoji=dice_emoji)
                 if bot_dice_msg:
                     bot_total += bot_dice_msg.dice.value
                 if i < rolls_count - 1:
                     await asyncio.sleep(0.5)
             game_data['bot_last_total'] = bot_total
             game_data['bot_round_total'] = bot_total
             active_games[user_id] = game_data
             save_data()
             await context.bot.send_message(
                 chat_id=chat_id,
                 text=f"<b>Bot rolled: {bot_total}</b>\n\n<b>{username_val}, your turn!</b>",
                 parse_mode=ParseMode.HTML
             )
        else:
            await handle_bot_roll_turn(update, context, user_id)
        return

    # UPDATED: Get the latest win counts AFTER incrementing
    player_wins_val = int(game_data.get('player_wins', 0))
    bot_wins_val = int(game_data.get('bot_wins', 0))
    wins_needed_val = int(wins_needed)
    
    # minimalism score
    username_val = game_data.get('username', 'Player')
    score_msg = f"{result_text}\n\n<b>Score:</b>\n<b>{username_val}</b> • {player_wins_val}\nBot • {bot_wins_val}"
    
    # Wait for the bot's animation to finish
    await asyncio.sleep(0.3)

    if player_wins_val >= wins_needed_val or bot_wins_val >= wins_needed_val:
        # Game Over
        if player_wins_val >= wins_needed_val:
            bet_internal = float(game_data.get('bet_amount', 0))
            winnings = round(bet_internal * 1.92, 2)
            ultra_secure_add_user_balance(user_id, winnings, "win")
            deduct_house_balance(winnings - bet_internal)
            save_data_critical()
            _uc3 = get_user_currency(user_id)
            _r3_won = True; _r3_amt = winnings; _r3_wpts = player_wins_val; _r3_lpts = bot_wins_val; _r3_uc = _uc3
        else:
            # Bot wins — bet was already deducted from player and added to house at game start
            bet_internal = float(game_data.get('bet_amount', 0))
            save_data_critical()
            _uc3b = get_user_currency(user_id)
            _r3_won = False; _r3_amt = bet_internal; _r3_wpts = bot_wins_val; _r3_lpts = player_wins_val; _r3_uc = _uc3b

        _game_name_3 = game_data.get('game_name', 'dice')
        _rolls_3 = int(game_data.get('rolls', 1))
        _wins_3 = int(wins_needed)
        _bet_3 = float(game_data.get('bet_amount', 0))
        _crazy_3 = bool(game_data.get('is_crazy', False))
        _dice_fmt_3 = f"{_rolls_3}d{_wins_3}w"
        _mode_3 = 'c' if _crazy_3 else 'n'
        _uname3 = game_data.get('username', 'Player')
        await _send_game_result_msg(
            context, chat_id,
            player_won=_r3_won,
            player_name=_uname3, player_id=user_id,
            winner_pts=_r3_wpts, loser_pts=_r3_lpts,
            amount=_r3_amt, user_currency=_r3_uc,
            reply_markup=_rc_end_keyboard(_game_name_3, _dice_fmt_3, _bet_3, _mode_3)
        )
        if _r3_won:
            await _send_player_win_sticker(context.bot, chat_id)
        if user_id in active_games:
            del active_games[user_id]
        save_data()
        return
    
    # Reset for next round
    game_data['round'] = game_data.get('round', 1) + 1
    game_data['state'] = EmojiGameState.WAITING_BOT_ROLL
    game_data['player_round_rolls'] = 0
    game_data['player_round_total'] = 0
    game_data['bot_round_rolls'] = 0
    game_data['bot_round_total'] = 0
    game_data['bot_last_total'] = 0
    active_games[user_id] = game_data
    save_data()
    
    # BOT ROLLS AGAIN IMMEDIATELY
    game_type = game_data.get('type', '')
    if game_type == 'sports_predict':
        bot_total = 0
        dice_emoji = game_data.get('dice_emoji', '🎲')
        for i in range(rolls_count):
            bot_dice_msg = await context.bot.send_dice(chat_id=chat_id, emoji=dice_emoji)
            if bot_dice_msg:
                bot_total += bot_dice_msg.dice.value
            if i < rolls_count - 1:
                await asyncio.sleep(0.5)
        
        # FRESH STATE RETRIEVAL
        game_data = active_games.get(user_id, game_data)
        game_data['bot_last_total'] = bot_total
        game_data['bot_round_total'] = bot_total
        game_data['state'] = EmojiGameState.WAITING_PLAYER_ROLL
        active_games[user_id] = game_data
        save_data()
        await context.bot.send_message(
            chat_id=chat_id,
            text=f"<b>Bot rolled: {bot_total}</b>\n\n<b>{username_val}, your turn!</b>",
            parse_mode=ParseMode.HTML
        )
    else:
        # Use handle_bot_roll_turn for other animated games
        await handle_bot_roll_turn(update, context, user_id)
    return
