async def handle_roulette_callbacks(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle all roulette_* callback queries."""
    query = update.callback_query
    user_id = str(query.from_user.id)
    data = query.data
    user_currency = get_user_currency(user_id)

    # ── Bet selection ─────────────────────────────────────────────────────────
    if data.startswith("roulette_bet:"):
        if 'user_games' not in context.user_data or 'roulette' not in context.user_data['user_games']:
            try:
                await query.answer("Session expired. Use /roulette again.", show_alert=True)
            except Exception:
                pass
            return

        selection = data.split(":", 1)[1]
        game_state = context.user_data['user_games']['roulette']
        game_state['selection'] = selection
        sel_display = selection.replace("-", " to ").title()
        try:
            await query.answer(f"Selected: {sel_display}")
        except Exception:
            pass

        bet_amount = float(game_state['bet_amount'])
        balance = get_user_balance(user_id)
        caption = _roulette_caption(bet_amount, balance, user_currency, selection)
        keyboard = _roulette_build_keyboard(selection)

        try:
            await query.edit_message_caption(caption=caption, reply_markup=keyboard, parse_mode=ParseMode.HTML)
        except Exception:
            pass

    # ── Bet on specific number hint ───────────────────────────────────────────
    elif data == "roulette_number_hint":
        await query.answer(
            "To bet on a specific number (0-36), type:\n/roulette [amount] [number]\n\nExample: /roulette 10 7",
            show_alert=True
        )

    # ── Start game ────────────────────────────────────────────────────────────
    elif data == "roulette_start":
        if 'user_games' not in context.user_data or 'roulette' not in context.user_data['user_games']:
            try:
                await query.answer("Session expired. Use /roulette again.", show_alert=True)
            except Exception:
                pass
            return

        game_state = context.user_data['user_games']['roulette']
        selection = game_state.get('selection', '')
        if not selection:
            try:
                await query.answer("⚠️ Please select a bet type first!", show_alert=True)
            except Exception:
                pass
            return

        bet_amount = float(game_state['bet_amount'])
        balance = get_user_balance(user_id)

        if bet_amount < MIN_BET:
            try:
                await query.answer(f"Minimum bet is {format_balance_in_currency(MIN_BET, user_currency)}", show_alert=True)
            except Exception:
                pass
            return
        if bet_amount > balance:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        if not ultra_secure_deduct_user_balance(user_id, bet_amount, "bet"):
            try:
                await query.answer("❌ Could not deduct balance!", show_alert=True)
            except Exception:
                pass
            return

        try:
            await query.answer("🎰 Spinning...")
        except Exception:
            pass

        # Delete the betting message so chat is clean before spin
        try:
            await query.message.delete()
        except Exception:
            try:
                await query.edit_message_caption(caption="🎰 Spinning...", reply_markup=None, parse_mode=ParseMode.HTML)
            except Exception:
                pass

        # ── Roulette spin logic ───────────────────────────────────────────────
        # Numbers capped at 33 to match the 35-sticker pack (intro + numbers 0-33).
        # sticker[0]=intro spin, sticker[n+1]=number n, n in 0..33 — exact 1:1 match.
        RED_NUMS   = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32]
        BLACK_NUMS = [2,4,6,8,10,11,13,15,17,20,22,24,26,28,29,31,33]

        sel = selection
        if random.random() < 0.40:
            # 40% — forced WIN (land on player's selection)
            if sel.isdigit():   result_number = int(sel)
            elif sel == 'red':  result_number = random.choice(RED_NUMS)
            elif sel == 'black':result_number = random.choice(BLACK_NUMS)
            elif sel == 'even': result_number = random.choice([n for n in range(2, 34, 2)])
            elif sel == 'odd':  result_number = random.choice([n for n in range(1, 34, 2)])
            elif sel == '1-12': result_number = random.randint(1, 12)
            elif sel == '13-24':result_number = random.randint(13, 24)
            elif sel == '25-36':result_number = random.randint(25, 33)
            elif sel == '1-18': result_number = random.randint(1, 18)
            elif sel == '19-36':result_number = random.randint(19, 33)
            else:               result_number = random.randint(0, 33)
        else:
            # 60% — forced LOSS (land opposite of player's selection)
            if sel.isdigit():
                losing_nums = [n for n in range(0, 34) if n != int(sel)]
                result_number = random.choice(losing_nums)
            elif sel == 'red':
                result_number = random.choice(BLACK_NUMS + [0])
            elif sel == 'black':
                result_number = random.choice(RED_NUMS + [0])
            elif sel == 'even':
                result_number = random.choice([n for n in range(1, 34, 2)] + [0])
            elif sel == 'odd':
                result_number = random.choice([n for n in range(2, 34, 2)] + [0])
            elif sel == '1-12':
                result_number = random.randint(13, 33)
            elif sel == '13-24':
                result_number = random.choice(list(range(1, 13)) + list(range(25, 34)))
            elif sel == '25-36':
                result_number = random.randint(0, 24)
            elif sel == '1-18':
                result_number = random.randint(19, 33)
            elif sel == '19-36':
                result_number = random.randint(0, 18)
            else:
                result_number = random.randint(0, 33)

        if result_number == 0:
            color_label = "🟢 Green"; color_simple = "green"
        elif result_number in RED_NUMS:
            color_label = "🔴 Red";   color_simple = "red"
        else:
            color_label = "⚫ Black"; color_simple = "black"

        # ── Determine win ────────────────────────────────────────────────────
        won = False
        multiplier = 0.0
        sel = selection
        if   sel == 'red'   and color_simple == 'red':                          won = True; multiplier = 2.0
        elif sel == 'black' and color_simple == 'black':                         won = True; multiplier = 2.0
        elif sel == 'even'  and result_number != 0 and result_number % 2 == 0:  won = True; multiplier = 2.0
        elif sel == 'odd'   and result_number % 2 == 1:                          won = True; multiplier = 2.0
        elif sel == '1-18'  and 1 <= result_number <= 18:                        won = True; multiplier = 2.0
        elif sel == '19-36' and 19 <= result_number <= 36:                       won = True; multiplier = 2.0
        elif sel == '1-12'  and 1 <= result_number <= 12:                        won = True; multiplier = 3.0
        elif sel == '13-24' and 13 <= result_number <= 24:                       won = True; multiplier = 3.0
        elif sel == '25-36' and 25 <= result_number <= 36:                       won = True; multiplier = 3.0
        elif sel.isdigit()  and int(sel) == result_number:                       won = True; multiplier = 36.0

        chat_id   = query.message.chat_id
        thread_id = game_state.get('thread_id')

        # ── Send roulette sticker (spin animation) ───────────────────────────
        # PERMANENT pack: ROULETTE_STICKER_IDS[0]=intro, [n+1]=number n (0-33).
        # result_number is always in 0-33 so sticker_idx is always in range 1-34.
        spin_wait = 4  # default wait for sticker animation to finish
        try:
            stickers = roulette_stickers.get('stickers', [])
            if stickers:
                # stickers[n] = number n directly (no intro offset — sticker[0]=0, sticker[1]=1 …)
                sticker_idx = result_number
                sticker_obj = stickers[sticker_idx] if sticker_idx < len(stickers) else stickers[0]
                sticker_id  = sticker_obj.get('file_id') if isinstance(sticker_obj, dict) else str(sticker_obj)
                await context.bot.send_sticker(chat_id=chat_id, sticker=sticker_id,
                                               message_thread_id=thread_id)
                spin_wait = 4  # wait for animated sticker to finish
            else:
                await context.bot.send_dice(chat_id=chat_id, emoji='🎰',
                                            message_thread_id=thread_id)
                spin_wait = 3
            await asyncio.sleep(spin_wait)
        except Exception as e:
            logger.error(f"Roulette sticker error: {e}")
            await asyncio.sleep(2)

        username = query.from_user.username or query.from_user.first_name or "Player"

        # ── Build result caption ─────────────────────────────────────────────
        if won:
            winnings = bet_amount * multiplier
            # Capture the balance BEFORE crediting, so we can compute and verify
            # the post-credit balance deterministically (defends against any
            # race that might briefly show a stale value via get_user_balance).
            balance_before_credit = get_user_balance(user_id)
            ultra_secure_add_user_balance(user_id, winnings, "win")
            # Force-flush so the credit is on disk before we render anything.
            try:
                save_data_critical()
            except Exception:
                pass
            expected_balance = round(balance_before_credit + winnings, 2)
            actual_balance = get_user_balance(user_id)
            # If a stale background save somehow rolled the credit back, restore.
            if actual_balance < expected_balance - 0.01:
                logger.error(f"⚠️ ROULETTE WIN BALANCE REGRESSION user={user_id} expected={expected_balance} actual={actual_balance} — restoring")
                user_balances[str(user_id)] = expected_balance
                try:
                    save_data_critical()
                except Exception:
                    pass
                actual_balance = expected_balance
            deduct_house_balance(winnings - bet_amount)
            track_wagering(user_id, bet_amount)
            add_match_history(user_id, 'roulette', bet_amount, 'win', winnings)
            try:
                await announce_win_to_channel(context, username, winnings, "Roulette", user_id=user_id)

            except Exception as _ann_e:
                logger.warning(f"announce_win_to_channel failed (non-fatal): {_ann_e}")
            result_caption = (
                f"🎡 <b>Roulette</b>\n\n"
                f"Bet: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
                f"Balance: <b>{format_balance_in_currency(actual_balance, user_currency)}</b>\n"
                f"Multiplier: <b>{multiplier:.2f}x</b>\n\n"
                f"🎉 You won <b>{format_balance_in_currency(winnings, user_currency)}</b>!\n"
                f"Ball landed on: <b>{result_number} {color_label}</b>"
            )
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            add_match_history(user_id, 'roulette', bet_amount, 'loss')
            result_caption = (
                f"🎡 <b>Roulette</b>\n\n"
                f"Bet: <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
                f"Balance: <b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}</b>\n"
                f"Multiplier: <b>0.00x</b>\n\n"
                f"💀 You lost <b>{format_balance_in_currency(bet_amount, user_currency)}</b>\n"
                f"Ball landed on: <b>{result_number} {color_label}</b>"
            )

        # Clear selection and send result as a NEW message at the bottom
        game_state['selection'] = ''
        place_bet_keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🎰 Place Bet", callback_data="roulette_play_again")],
        ])
        await context.bot.send_message(
            chat_id=chat_id,
            text=result_caption,
            reply_markup=place_bet_keyboard,
            message_thread_id=thread_id,
            parse_mode=ParseMode.HTML
        )
        if won:
            await _send_player_win_sticker(context.bot, chat_id)

        save_data()

    # ── Place Bet / Play again ─────────────────────────────────────────────────
    elif data == "roulette_play_again":
        if 'user_games' not in context.user_data or 'roulette' not in context.user_data['user_games']:
            try:
                await query.answer("Use /roulette [amount] to play again.", show_alert=True)
            except Exception:
                pass
            return
        game_state = context.user_data['user_games']['roulette']
        bet_amount = float(game_state['bet_amount'])
        balance    = get_user_balance(user_id)
        if bet_amount > balance:
            try:
                await query.answer("❌ Insufficient balance!", show_alert=True)
            except Exception:
                pass
            return
        game_state['selection'] = ''
        caption  = _roulette_caption(bet_amount, balance, user_currency)
        keyboard = _roulette_build_keyboard()
        try:
            await query.answer()
        except Exception:
            pass
        chat_id  = query.message.chat_id
        thread_id = game_state.get('thread_id')
        # Delete the result message, send fresh betting photo
        try:
            await query.message.delete()
        except Exception:
            pass
        try:
            with open("roulette_table.jpeg", "rb") as f:
                await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=f,
                    caption=caption,
                    reply_markup=keyboard,
                    message_thread_id=thread_id,
                    parse_mode=ParseMode.HTML
                )
        except Exception:
            await context.bot.send_message(
                chat_id=chat_id, text=caption,
                reply_markup=keyboard,
                message_thread_id=thread_id,
                parse_mode=ParseMode.HTML
            )

    # ── Verify ────────────────────────────────────────────────────────────────
    elif data == "roulette_verify":
        try:
            await query.answer("✅ Game is provably fair. Results are randomly generated server-side.", show_alert=True)
        except Exception:
            pass

def generate_rupee_coin_frames(result: str, size: int = 220) -> list:
    """Generate physics-based coin flip animation with Rollers badge on landing."""
    from PIL import Image, ImageDraw, ImageFont, ImageFilter
    import math, os

    FONT_BOLD = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
    FONT_REG  = "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"

    canvas_w = size + 40
    canvas_h = size + 60   # extra space for shadow
    cx = canvas_w // 2
    cy = canvas_h // 2

    # --- Preload fonts ---
    def get_font(path, sz):
        try: return ImageFont.truetype(path, sz)
        except: return ImageFont.load_default()

    # --- Preload Rollers logo ---
    logo_path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                             'public', 'crypto_icons', 'rollers_logo.png')
    rollers_logo = None
    try:
        rollers_logo = Image.open(logo_path).convert('RGBA')
    except Exception:
        pass

    def draw_shadow(draw, cx, cy, coin_d, alpha=80):
        """Draw elliptical shadow under the coin."""
        sw = int(coin_d * 0.85)
        sh = int(coin_d * 0.12)
        sx, sy = cx - sw//2, cy + coin_d//2 + 6
        for i in range(4, 0, -1):
            a = int(alpha * i / 4)
            draw.ellipse([sx+i, sy+i//2, sx+sw-i, sy+sh-i//2], fill=(0,0,0,a))

    def draw_coin(side, squish, coin_d, logo_scale=0.0):
        """
        Draw one coin frame.
        squish: 1.0 = full face, 0.0 = edge
        logo_scale: 0.0-1.0 = Rollers badge size (0=hidden)
        """
        img = Image.new('RGBA', (canvas_w, canvas_h), (0,0,0,0))
        draw = ImageDraw.Draw(img)

        w = max(3, int(coin_d * abs(squish)))
        h = coin_d
        x0 = cx - w//2
        y0 = cy - h//2
        x1 = cx + w//2
        y1 = cy + h//2

        # Shadow (flattens as coin lands)
        shadow_alpha = int(60 * (1.0 - squish * 0.5))
        draw_shadow(draw, cx, cy, coin_d, shadow_alpha)

        if w < 5:
            draw.ellipse([cx-2, y0, cx+2, y1], fill=(160,120,0,255))
            return img

        # ---- Coin body ----
        # Rim (dark gold)
        draw.ellipse([x0, y0, x1, y1], fill=(140, 100, 0, 255))
        # Bevelled inner face
        bevel = max(2, int(w * 0.06))
        face_color = (235, 185, 25, 255) if side == 'heads' else (200, 155, 12, 255)
        draw.ellipse([x0+bevel, y0+bevel, x1-bevel, y1-bevel], fill=face_color)

        # Inner decorative ring
        ring = max(3, int(w * 0.14))
        draw.ellipse([x0+ring, y0+ring, x1-ring, y1-ring],
                     outline=(255, 220, 60, 180), width=max(1, int(w * 0.025)))

        # ---- Text content (only when wide enough) ----
        if w > coin_d * 0.3:
            fsz_big = max(12, int(w * 0.40))
            fsz_sm  = max(7,  int(w * 0.14))
            f_big = get_font(FONT_BOLD, fsz_big)
            f_sm  = get_font(FONT_REG,  fsz_sm)

            if side == 'heads':
                symbol, label = "₹", "HEADS"
                s_col = (110, 70, 0, 255)
                l_col = (90, 55, 0, 220)
            else:
                symbol, label = "✦", "TAILS"
                s_col = (90, 60, 0, 255)
                l_col = (80, 50, 0, 220)

            # Main symbol (centred, slightly above middle)
            try:
                bb = draw.textbbox((0,0), symbol, font=f_big)
                tw, th = bb[2]-bb[0], bb[3]-bb[1]
            except Exception:
                tw = th = fsz_big
            draw.text((cx - tw//2, cy - th//2 - max(3, int(h*0.07))),
                      symbol, font=f_big, fill=s_col)

            # Label at bottom of coin face
            try:
                bb2 = draw.textbbox((0,0), label, font=f_sm)
                lw = bb2[2]-bb2[0]
            except Exception:
                lw = fsz_sm * len(label) // 2
            draw.text((cx - lw//2, y1 - max(10, int(h*0.24))),
                      label, font=f_sm, fill=l_col)

        # ---- Specular highlight ----
        if w > 12:
            hl_w = max(3, w//4)
            hl_h = max(3, h//5)
            hl_x = x0 + max(3, w//7)
            hl_y = y0 + max(3, h//10)
            # soft white oval
            hl = Image.new('RGBA', (hl_w, hl_h), (0,0,0,0))
            hl_d = ImageDraw.Draw(hl)
            hl_d.ellipse([0,0,hl_w-1,hl_h-1], fill=(255,255,220,70))
            img.paste(hl, (hl_x, hl_y), hl)

        # ---- Rollers badge (pops in after landing) ----
        if logo_scale > 0.05 and rollers_logo is not None:
            badge_sz = int(coin_d * 0.42 * logo_scale)
            if badge_sz > 10:
                badge = rollers_logo.resize((badge_sz, badge_sz), Image.Resampling.LANCZOS)
                # Position: top-right of coin area
                bx = cx + coin_d//2 - badge_sz//2 - 4
                by = cy - coin_d//2 - badge_sz//2 + 4
                img.paste(badge, (bx, by), badge)

        return img

    # ================================================================
    # Build animation frames with physics-based deceleration
    # Target: ~4-5 seconds total, snappy start, smooth landing
    # ================================================================
    frames = []

    # half-turn = 180°. We start showing 'heads'.
    # Result 'heads' = even half-turns, 'tails' = odd half-turns.
    total_half_turns = 8   # 4 full spins fast
    if result == 'tails' and total_half_turns % 2 == 0:
        total_half_turns += 1
    elif result == 'heads' and total_half_turns % 2 != 0:
        total_half_turns += 1
    total_half_turns += 2  # 1 slow + 1 landing

    T = total_half_turns
    base_frames_fast = 3   # frames per half-turn at top speed
    base_frames_slow = 8   # frames per half-turn when landing

    sides = ['heads', 'tails']
    current_side_idx = 0

    for ht in range(total_half_turns):
        t_norm = ht / T
        ease = (1 - t_norm) ** 1.8   # ease-out curve
        n_frames = max(base_frames_fast, int(base_frames_fast + (base_frames_slow - base_frames_fast) * (1 - ease)))
        is_last = (ht == total_half_turns - 1)
        is_second_last = (ht == total_half_turns - 2)

        if is_last:
            dur_ms, n_frames = 90, base_frames_slow
        elif is_second_last:
            dur_ms, n_frames = 55, base_frames_slow - 2
        else:
            dur_ms = max(20, int(20 + 40 * (1 - ease)))

        side = sides[current_side_idx % 2]
        next_side = sides[(current_side_idx + 1) % 2]

        # Half-turn OUT: current face → edge (cos: 1→0)
        for fi in range(n_frames):
            squish = math.cos(fi / n_frames * math.pi / 2)
            logo_sc = 0.0
            frames.append((draw_coin(side, squish, size, logo_sc), dur_ms))

        # Half-turn IN: edge → next face (sin: 0→1)
        for fi in range(n_frames):
            squish = math.sin(fi / n_frames * math.pi / 2)
            logo_sc = 0.0
            # Badge starts fading in during last few frames of landing
            if is_last and fi >= n_frames - 3:
                logo_sc = (fi - (n_frames - 3)) / 3 * 0.9
            frames.append((draw_coin(next_side, squish, size, logo_sc), dur_ms))

        current_side_idx += 1

    # Hold: final face + Rollers badge pops in fully
    for i in range(5):
        badge_sc = min(1.0, 0.6 + 0.4 * (i / 2))
        dur = 100 if i < 2 else 250
        frames.append((draw_coin(result, 1.0, size, badge_sc), dur))

    return frames  # list of (Image, duration_ms)


def create_rupee_coinflip_gif(result: str) -> BytesIO:
    """Return a BytesIO GIF of the rupee coin flip landing on result."""
    from PIL import Image as PilImage
    frames_data = generate_rupee_coin_frames(result, size=200)

    # Convert RGBA frames to palette mode for GIF
    pil_frames = []
    durations = []
    bg_color = (30, 30, 30)

    for (img, dur) in frames_data:
        bg = PilImage.new('RGBA', img.size, bg_color + (255,))
        bg.paste(img, mask=img.split()[3])
        pil_frames.append(bg.convert('P', palette=PilImage.ADAPTIVE, colors=128))
        durations.append(dur)

    bio = BytesIO()
    bio.name = "rupee_flip.gif"
    pil_frames[0].save(
        bio,
        format='GIF',
        save_all=True,
        append_images=pil_frames[1:],
        duration=durations,
        loop=0,
        optimize=False,
        disposal=2,
    )
    bio.seek(0)
    return bio


async def rupeecoin_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Indian Rupee animated coin flip game — /rupeecoin [amount] [heads/tails]"""
    if not update.message or not update.message.from_user:
        return

    user_id   = str(update.message.from_user.id)
    username  = update.message.from_user.first_name or "Player"
    args      = context.args or []

    # --- Parse args ---
    if len(args) < 2:
        await update.message.reply_text(
            "🪙 <b>Indian Rupee Coin Flip</b>\n\n"
            "Usage: <code>/rupeecoin [amount] [heads/tails]</code>\n\n"
            "Example: <code>/rupeecoin 5 heads</code>",
            parse_mode=ParseMode.HTML
        )
        return

    # Amount
    try:
        bet_amount = float(args[0].replace('$','').strip())
    except ValueError:
        await update.message.reply_text("❌ Invalid amount. Example: /rupeecoin 5 heads")
        return

    # Choice
    choice = args[1].lower().strip()
    if choice not in ('heads', 'tails', 'h', 't'):
        await update.message.reply_text("❌ Choose <b>heads</b> or <b>tails</b>.", parse_mode=ParseMode.HTML)
        return
    choice = 'heads' if choice in ('heads', 'h') else 'tails'

    # Validate bet
    min_bet = 0.5
    if bet_amount < min_bet:
        await update.message.reply_text(f"❌ Minimum bet is ${min_bet:.2f}")
        return

    balance = get_user_balance(user_id)
    if balance < bet_amount:
        await update.message.reply_text(
            f"❌ Insufficient balance!\n"
            f"💰 Your balance: ${balance:.2f}\n"
            f"🎰 Bet: ${bet_amount:.2f}"
        )
        return

    if not deduct_user_balance(user_id, bet_amount):
        await update.message.reply_text("❌ Failed to deduct balance. Please try again.")
        return

    track_wagering(user_id, bet_amount, 1.95)

    # Decide result
    import random
    result = random.choice(['heads', 'tails'])
    won = (result == choice)

    # Winnings
    if won:
        winnings = bet_amount * 1.95   # 2x minus 5% house edge
        ultra_secure_add_user_balance(user_id, winnings, "credit")
        add_match_history(user_id, 'rupeecoin', bet_amount, 'win', winnings)
        deduct_house_balance(winnings - bet_amount)
    else:
        winnings = 0.0
        add_loss_to_rakeback(user_id, bet_amount)
        add_match_history(user_id, 'rupeecoin', bet_amount, 'loss', 0)
        add_house_balance(bet_amount)
    save_data_critical()

    # Send "flipping…" message
    flip_msg = await update.message.reply_text(
        f"🪙 <b>Flipping the Rupee coin...</b>\n\n"
        f"You chose: <b>{'HEADS (₹)' if choice == 'heads' else 'TAILS (✦)'}</b>",
        parse_mode=ParseMode.HTML
    )

    # Generate GIF in thread to not block event loop
    loop = asyncio.get_event_loop()
    try:
        gif_bio = await loop.run_in_executor(None, create_rupee_coinflip_gif, result)
    except Exception as e:
        logger.error(f"Rupee coin GIF error: {e}")
        gif_bio = None

    # Build result text
    new_bal = get_user_balance(user_id)
    if won:
        result_text = (
            f"🪙 <b>RUPEE COIN FLIP</b> 🪙\n\n"
            f"🎯 Landed on: <b>{'HEADS ₹' if result == 'heads' else 'TAILS ✦'}</b>\n\n"
            f"✅ <b>YOU WON!</b> +${winnings:.2f}\n"
            f"💰 Balance: ${new_bal:.2f}"
        )
    else:
        result_text = (
            f"🪙 <b>RUPEE COIN FLIP</b> 🪙\n\n"
            f"🎯 Landed on: <b>{'HEADS ₹' if result == 'heads' else 'TAILS ✦'}</b>\n\n"
            f"❌ <b>YOU LOST!</b> -${bet_amount:.2f}\n"
            f"💰 Balance: ${new_bal:.2f}"
        )

    # Delete the flipping message and send GIF + result
    try:
        await flip_msg.delete()
    except Exception:
        pass

    if gif_bio:
        try:
            await update.message.reply_animation(
                animation=gif_bio,
                caption=result_text,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"Failed to send GIF: {e}")
            await update.message.reply_text(result_text, parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(result_text, parse_mode=ParseMode.HTML)


