# ── Detection helpers ─────────────────────────────────────────────────────────

_SLANDER_WORDS = [
    'scam', 'rigged', 'rig', 'fake', 'fraud', 'cheat', 'cheating', 'fixed',
    'loot', 'chor', 'dhoka', 'thug', 'bekaar', 'bakwaas', 'faltu',
    'not legit', 'not trusted', 'beware', 'avoid', 'stay away',
    'dont trust', "don't trust", 'loss fix', 'sab fixed', 'sab rigged',
]
_PROMO_WORDS = [
    'join our', 'join my', 'join this', 't.me/', 'telegram.me/',
    'other casino', 'new casino', 'better casino', 'earning app',
    'instant withdraw', 'refer and earn', 'free bonus', 'free usdt',
    'dm me', 'contact me for', 'make money fast',
]
_SPAM_THRESHOLD = 5   # same message repeated N times triggers spam flag

_user_recent_msgs: dict = {}   # {user_id: [timestamps]}  for rate-limit spam


def detect_casino_slander(text: str) -> bool:
    t = text.lower()
    return any(w in t for w in _SLANDER_WORDS)


def detect_other_casino_promo(text: str) -> bool:
    t = text.lower()
    return any(w in t for w in _PROMO_WORDS)


def detect_spam(user_id: str, text: str) -> bool:
    """True if user sent 5+ messages in under 10 seconds."""
    now = time.time()
    history = _user_recent_msgs.setdefault(user_id, [])
    history.append(now)
    _user_recent_msgs[user_id] = [t for t in history if now - t < 10]
    return len(_user_recent_msgs[user_id]) >= _SPAM_THRESHOLD


# ── User intelligence ─────────────────────────────────────────────────────────

def get_user_intel(user_id: str, name: str = "Player") -> dict:
    if user_id not in user_intel:
        user_intel[user_id] = {
            'name': name, 'messages': 0, 'risk_score': 0,
            'mute_count': 0, 'last_active': time.time(),
            'flagged': [], 'user_type': 'new',
        }
    return user_intel[user_id]


def update_user_intel(user_id: str, name: str, risk_delta: int = 0, flagged_msg: str = None):
    rec = get_user_intel(user_id, name)
    rec['name'] = name
    rec['messages'] += 1
    rec['last_active'] = time.time()
    rec['risk_score'] = max(0, rec['risk_score'] + risk_delta)
    if flagged_msg:
        rec['flagged'].append({'ts': time.time(), 'msg': flagged_msg[:200]})
        rec['flagged'] = rec['flagged'][-50:]
    # classify
    msgs = rec['messages']
    wagered = user_wagering_totals.get(user_id, 0)
    if rec['risk_score'] >= RISK_BAN_THRESHOLD:
        rec['user_type'] = 'risky'
    elif msgs < 5:
        rec['user_type'] = 'new'
    elif wagered > 0:
        rec['user_type'] = 'active'
    else:
        rec['user_type'] = 'passive'


def record_mute(user_id: str) -> str:
    """Track mute count. Returns next action: 'warn', 'mute_24h', 'ban'."""
    rec = get_user_intel(user_id)
    rec['mute_count'] = rec.get('mute_count', 0) + 1
    cnt = rec['mute_count']
    if cnt >= 3:
        return 'ban'
    if cnt >= 2:
        return 'mute_24h'
    return 'mute'


# ── Mute helper ───────────────────────────────────────────────────────────────

async def mute_user_in_group(context, chat_id: int, user_id: int, duration_seconds: int = 3600):
    """Mute a user in a group for duration_seconds (default 1h)."""
    until = int(time.time()) + duration_seconds
    try:
        await context.bot.restrict_chat_member(
            chat_id=chat_id,
            user_id=user_id,
            permissions=ChatPermissions(can_send_messages=False),
            until_date=until,
        )
        mod_actions_log.append({
            'ts': time.time(), 'user_id': str(user_id),
            'action': 'mute', 'duration': duration_seconds,
        })
        return True
    except Exception as e:
        logger.warning(f"Mute failed for {user_id}: {e}")
        return False


async def ban_user_in_group(context, chat_id: int, user_id: int):
    try:
        await context.bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
        banned_users[str(user_id)] = {
            'reason': 'Auto-ban: repeat offender',
            'banned_at': time.time(), 'banned_by': 'system',
        }
        mod_actions_log.append({
            'ts': time.time(), 'user_id': str(user_id), 'action': 'ban',
        })
        return True
    except Exception as e:
        logger.warning(f"Ban failed for {user_id}: {e}")
        return False


# ── Group moderation handler (ALL replies via AI) ─────────────────────────────

async def handle_group_moderation(update, context) -> bool:
    """
    Called on every group message BEFORE normal flow.
    Returns True if message was handled (caller should stop processing).
    ALL warning/mute messages come from AI — zero pre-saved strings.
    """
    if not update.message or not update.message.from_user:
        return False
    msg = update.message
    user_id = str(msg.from_user.id)
    user_name = msg.from_user.first_name or "Player"
    text = msg.text or msg.caption or ""
    chat_id = msg.chat_id
    uid_int = msg.from_user.id

    # Whitelisted users bypass all moderation
    if user_id in mod_whitelist:
        update_user_intel(user_id, user_name)
        return False

    update_user_intel(user_id, user_name)
    group_last_activity[str(chat_id)] = time.time()

    if not text:
        return False

    action_taken = None
    context_hint = ""
    duration = 3600  # 1h default

    # 1. Casino slander detection
    if detect_casino_slander(text):
        update_user_intel(user_id, user_name, risk_delta=3, flagged_msg=text)
        next_action = record_mute(user_id)
        if next_action == 'ban':
            await ban_user_in_group(context, chat_id, uid_int)
            action_taken = 'ban'
            context_hint = (
                f"[MODERATION CONTEXT: This player (@{msg.from_user.username or user_name}) "
                f"just said '{text[:100]}' which is false info calling Rollers Casino a scam/rigged. "
                f"They are a repeat offender and have now been BANNED from the group. "
                f"Write 1-2 sentences: defend Rollers, say they were banned for spreading false info.]"
            )
        else:
            duration = 86400 if next_action == 'mute_24h' else 3600
            await mute_user_in_group(context, chat_id, uid_int, duration)
            action_taken = 'mute'
            context_hint = (
                f"[MODERATION CONTEXT: This player (@{msg.from_user.username or user_name}) "
                f"just said '{text[:100]}' which is false — Rollers Casino is legit and fair. "
                f"They have been muted for {duration//3600}h for spreading misinformation. "
                f"Write 1-2 sentences: defend Rollers firmly, say they are muted for false info.]"
            )

    # 2. Other casino promotion
    elif detect_other_casino_promo(text):
        update_user_intel(user_id, user_name, risk_delta=2, flagged_msg=text)
        next_action = record_mute(user_id)
        duration = 86400 if next_action in ('mute_24h', 'ban') else 3600
        await mute_user_in_group(context, chat_id, uid_int, duration)
        action_taken = 'mute'
        context_hint = (
            f"[MODERATION CONTEXT: User @{msg.from_user.username or user_name} "
            f"tried to promote another casino/platform in this Rollers group. "
            f"They have been muted for {duration//3600}h. "
            f"Write 1-2 sentences: say this is Rollers-only, promoting others is not allowed, they are muted.]"
        )

    # 3. Spam detection
    elif detect_spam(user_id, text):
        update_user_intel(user_id, user_name, risk_delta=1, flagged_msg=text)
        await mute_user_in_group(context, chat_id, uid_int, 600)  # 10 min
        action_taken = 'spam_mute'
        context_hint = (
            f"[MODERATION CONTEXT: User @{msg.from_user.username or user_name} is spamming the group. "
            f"They have been muted for 10 minutes. "
            f"Write 1 sentence warning them to stop spamming.]"
        )

    if action_taken and context_hint:
        try:
            await context.bot.send_chat_action(chat_id=chat_id, action="typing")
        except Exception as e:
            logger.warning(f"Mod AI reply failed: {e}")
        return True  # handled

    return False


