async def modstats_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show intelligence/moderation analytics."""
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    total = len(user_intel)
    active = sum(1 for u in user_intel.values() if time.time() - u.get('last_active', 0) < 3600)
    risky = sum(1 for u in user_intel.values() if u.get('user_type') == 'risky')
    flagged = sum(1 for u in user_intel.values() if u.get('flagged'))
    muted = sum(1 for u in user_intel.values() if u.get('mute_count', 0) > 0)
    total_actions = len(mod_actions_log)
    bans = sum(1 for a in mod_actions_log if a.get('action') == 'ban')
    wl = len(mod_whitelist)
    await update.message.reply_text(
        f"📊 <b>Casino Intelligence Report</b>\n\n"
        f"👥 Total tracked users: {total}\n"
        f"🟢 Active (last 1h): {active}\n"
        f"⚠️ Risky users: {risky}\n"
        f"🚩 Flagged users: {flagged}\n"
        f"🔇 Muted (ever): {muted}\n"
        f"🚫 Total bans: {bans}\n"
        f"✅ Whitelist: {wl}\n"
        f"📝 Total mod actions: {total_actions}",
        parse_mode=ParseMode.HTML
    )


async def force_mute_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Force-mute a user. Usage: /force_mute [user_id] [hours=1]"""
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    args = context.args
    if not args:
        await update.message.reply_text("Usage: /force_mute [user_id] [hours=1]")
        return
    target_id = int(args[0])
    hours = int(args[1]) if len(args) > 1 else 1
    ok = await mute_user_in_group(context, update.message.chat_id, target_id, hours * 3600)
    record_mute(str(target_id))
    await update.message.reply_text(f"{'✅ Muted' if ok else '❌ Failed'} user {target_id} for {hours}h")


async def force_unmute_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Unmute a user. Usage: /force_unmute [user_id]"""
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    args = context.args
    if not args:
        await update.message.reply_text("Usage: /force_unmute [user_id]")
        return
    target_id = int(args[0])
    try:
        await context.bot.restrict_chat_member(
            chat_id=update.message.chat_id,
            user_id=target_id,
            permissions=ChatPermissions(
                can_send_messages=True, can_send_polls=True,
                can_send_other_messages=True, can_add_web_page_previews=True,
            ),
        )
        await update.message.reply_text(f"✅ Unmuted user {target_id}")
    except Exception as e:
        await update.message.reply_text(f"❌ Failed: {e}")


async def reset_user_score_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Reset a user's risk score. Usage: /reset_user_score [user_id]"""
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    args = context.args
    if not args:
        await update.message.reply_text("Usage: /reset_user_score [user_id]")
        return
    uid = args[0]
    if uid in user_intel:
        user_intel[uid]['risk_score'] = 0
        user_intel[uid]['mute_count'] = 0
        user_intel[uid]['flagged'] = []
        user_intel[uid]['user_type'] = 'active'
    await update.message.reply_text(f"✅ Risk score reset for {uid}")


async def whitelist_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Whitelist a trusted user. Usage: /whitelist [user_id]"""
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    args = context.args
    if not args:
        await update.message.reply_text("Usage: /whitelist [user_id]")
        return
    uid = args[0]
    if uid in mod_whitelist:
        mod_whitelist.discard(uid)
        await update.message.reply_text(f"✅ Removed {uid} from whitelist")
    else:
        mod_whitelist.add(uid)
        await update.message.reply_text(f"✅ Added {uid} to whitelist")


async def weeklyunlock_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Toggle weekly bonus availability for all players. Owner only."""
    global _weekly_bonus_unlocked
    if str(update.effective_user.id) != str(OWNER_ID):
        return
    _weekly_bonus_unlocked = not _weekly_bonus_unlocked
