async def depo_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle /depo [coin] [network] — with arg generates address directly, without shows keyboard."""
    if not update.message:
        return

    if update.effective_user and payments_blocked_for(update.effective_user.id):
        await update.message.reply_text(PAYMENT_MAINTENANCE_MESSAGE, parse_mode=ParseMode.HTML)
        return

    # If no args → show full coin keyboard as before
    if not context.args:
        await crypto_deposit_start(update, context)
        return

    # Join all args into a single lowercase string for lookup
    query_str = " ".join(context.args).lower().strip()

    coin_key = DEPO_KEYWORD_MAP.get(query_str)

    if not coin_key:
        # Show a helpful list of networks for that coin if possible
        base = query_str.split()[0]
        networks = [
            COINS[v]["name"] for k, v in DEPO_KEYWORD_MAP.items()
            if k.startswith(base) and v in COINS
        ]
        networks = list(dict.fromkeys(networks))  # deduplicate
        if networks:
            network_list = "\n".join(f"  • <code>/depo {k}</code> — {COINS[v]['name']}"
                                     for k, v in DEPO_KEYWORD_MAP.items()
                                     if k.startswith(base) and v in COINS)
            await update.message.reply_text(
                f"❓ Multiple networks available for <b>{base.upper()}</b>. Choose one:\n\n{network_list}",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                f"❌ Unknown coin <b>{query_str.upper()}</b>.\n\n"
                f"Use <code>/depo</code> to see all supported coins.",
                parse_mode=ParseMode.HTML
            )
        return

    # Generate deposit address directly
    await deposit_screen_from_command(update, context, coin_key)


async def cryptodeposit_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Alias for crypto_deposit_start."""
    await crypto_deposit_start(update, context)

async def deposit_screen_from_command(update: Update, context: ContextTypes.DEFAULT_TYPE, code: str):
    """Helper to show deposit screen from a command instead of callback."""
    coin = COINS.get(code)
    if not coin: return

    # Generate deposit info — ALWAYS pass user_id so order_id can be parsed back to user on IPN
    user_id_str = str(update.effective_user.id) if update.effective_user else None
    payment = create_nowpayments_payment(10, coin["pay_currency"], user_id=user_id_str)
    if not payment:
        order_id = f"dep_{update.effective_user.id}_{int(time.time())}"
        payment_data, error = nowpayments_create_payment(10.0, coin["pay_currency"], order_id, f"Deposit - {coin['name']}")
        payment = payment_data

    if not payment or (not payment.get("pay_address") and not payment.get("address")):
        error_detail = locals().get("error") or "NOWPayments did not return a payment address."
        await update.message.reply_text(
            "❌ <b>Deposit address could not be generated.</b>\n\n"
            f"<code>{html.escape(str(error_detail)[:300])}</code>\n\n"
            "Please try again in a moment.",
            parse_mode=ParseMode.HTML,
        )
        return

    address = payment.get("pay_address") or payment.get("address")
    payment_id = payment.get("payment_id") or payment.get("id")
    _cmd_username = user_profiles.get(user_id_str, {}).get('username', '') if user_id_str else ''
    cap_plain2, cap_ents2 = _make_dep_caption(code, address, EXP_SECONDS, _cmd_username)
    _cmd_pay_curr = coin.get('pay_currency', code).lower()
    qr_photo = make_qr_with_logo(address, _cmd_pay_curr)
    dep_msg = await context.bot.send_photo(
        chat_id=update.effective_chat.id,
        photo=qr_photo,
        caption=cap_plain2,
        caption_entities=cap_ents2,
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🔄", callback_data=f"refresh:{code}:{payment_id}")],
            [InlineKeyboardButton("⬅️ BACK", callback_data="back_to_deposit")]
        ])
    )
    import asyncio as _asyncio2
    _asyncio2.create_task(_run_deposit_countdown(
        context=context,
        chat_id=dep_msg.chat_id,
        message_id=dep_msg.message_id,
        user_id=user_id_str or '',
        code=code,
        address=address,
        payment_id=str(payment_id) if payment_id else '',
        expires_at=int(time.time()) + EXP_SECONDS,
        username=_cmd_username,
    ))

async def rummy_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Rummy - Card matching game"""
    if not update.message or not update.message.from_user:
        return

    user_id = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    balance = get_user_balance(user_id)

    if not context.args:
        await update.message.reply_text(
            "🔥 <b>RUMMY</b>\n\n"
            "Match sets and runs!\n"
            "Complete hand for big win\n\n"
            f"Usage: /rummy [amount]\n"
            f"Your balance: {format_balance_in_currency(balance, user_currency)}",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        bet_amount_input = float(context.args[0]); bet_amount = convert_currency_to_usd(bet_amount_input, user_currency)

        if bet_amount < MIN_BET or bet_amount > balance:
            await update.message.reply_text(f"❌ Invalid bet amount")
            return

        if not deduct_user_balance(user_id, bet_amount):
            return

        track_wagering(user_id, bet_amount, 5.0)

        outcomes = ['No sets', 'One set', 'Two sets', 'Full hand']
        multipliers = [0, 1, 3, 5]

        if random.random() < BOT_WIN_CHANCES['rummy']:
            outcome = random.choice(outcomes[:2])
        else:
            outcome = random.choice(outcomes[2:])

        mult = multipliers[outcomes.index(outcome)]

        if mult > 0:
            winnings = bet_amount * mult
            ultra_secure_add_user_balance(user_id, winnings, "win")
            deduct_house_balance(winnings - bet_amount)
            add_match_history(user_id, 'rummy', bet_amount, 'win', winnings)
            result_msg = f"🔥 <b>RUMMY WIN!</b>\n\n🔥 Result: {outcome}\n💰 Won: <b>{format_balance_in_currency(winnings, user_currency)} ({mult}x)\n📊 Balance: </b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}"
            save_data_critical()
        else:
            add_house_balance(bet_amount)
            add_loss_to_rakeback(user_id, bet_amount)
            add_match_history(user_id, 'rummy', bet_amount, 'loss', 0)
            result_msg = f"🔥 <b>RUMMY</b>\n\n🔥 Result: {outcome}\n❌ Lost: <b>{format_balance_in_currency(bet_amount, user_currency)}\n📊 Balance: </b>{format_balance_in_currency(get_user_balance(user_id), user_currency)}"
            save_data_critical()
        await update.message.reply_text(result_msg, parse_mode=ParseMode.HTML)
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Usage: /rummy [amount]")


