# ROLLERS CRASH GAME — provably fair, multi-player, real-time
# ═══════════════════════════════════════════════════════════════════════════════
import threading as _cth
import hashlib as _chash
import time as _ctime
import random as _crand

_CRASH_MIN_BET        = 1.0
_CRASH_MAX_BET        = 300.0
_CRASH_HOUSE_EDGE     = 0.03   # 3%
_CRASH_BET_WINDOW     = 7.0    # seconds of betting phase
_CRASH_CRASH_PAUSE    = 4.0    # seconds to show crashed screen

_crash_state = {
    'phase':       'betting',   # 'betting' | 'flying' | 'crashed'
    'multiplier':  1.00,
    'crash_at':    None,
    'bets':        {},          # {uid: {amount, cashedout, cashout_mult, lost, auto_cashout, username, display_name, photo_url}}
    'history':     [],          # list of last 20 crash points
    'countdown':   _CRASH_BET_WINDOW,
    'server_seed': '',
    'nonce':       0,
    'round_id':    0,
}
_crash_lock = _cth.Lock()

def _crash_point(server_seed: str, client_seed: str, nonce: int) -> float:
    """Provably-fair crash point — same algorithm as limbo."""
    combined  = f"{server_seed}:{client_seed}:{nonce}"
    h         = _chash.sha256(combined.encode()).hexdigest()
    hash_int  = int(h[:8], 16)
    r         = (hash_int % 1_000_000) / 1_000_000.0
    if r < _CRASH_HOUSE_EDGE:
        return 1.00
    return min(max(1.01, 0.99 / max(1e-6, 1.0 - r)), 1000.0)

def _crash_new_seed() -> str:
    raw = f"{_ctime.time()}-{_crand.random()}-crash"
    return _chash.sha256(raw.encode()).hexdigest()[:32]

def _crash_credit(user_id: str, bet: float, winnings: float, mult: float):
    """Credit winnings to player — runs in a daemon thread."""
    try:
        ultra_secure_add_user_balance(user_id, winnings, "win")
        save_data_critical()
        add_match_history(user_id, 'crash', bet, 'win', winnings)
    except Exception as _ce:
        logger.error(f"crash credit error uid={user_id}: {_ce}")

def _crash_game_loop():
    """Infinite background loop running crash rounds."""
    server_seed  = _crash_new_seed()
    client_seed  = "rollers_crash_v1"
    nonce        = 0

    while True:
        # ── BETTING PHASE ────────────────────────────────────────────────
        crash_at = _crash_point(server_seed, client_seed, nonce)

        with _crash_lock:
            _crash_state['phase']       = 'betting'
            _crash_state['multiplier']  = 1.00
            _crash_state['crash_at']    = crash_at
            _crash_state['bets']        = {}
            _crash_state['countdown']   = _CRASH_BET_WINDOW
            _crash_state['server_seed'] = server_seed
            _crash_state['nonce']       = nonce
            _crash_state['round_id']   += 1

        t0 = _ctime.time()
        while _ctime.time() - t0 < _CRASH_BET_WINDOW:
            with _crash_lock:
                _crash_state['countdown'] = max(0.0, _CRASH_BET_WINDOW - (_ctime.time() - t0))
            _ctime.sleep(0.1)

        # ── FLYING PHASE ─────────────────────────────────────────────────
        with _crash_lock:
            _crash_state['phase']      = 'flying'
            _crash_state['multiplier'] = 1.00

        fly_start = _ctime.time()
        while True:
            elapsed = _ctime.time() - fly_start
            mult    = round(1.0 * (1.0022 ** (elapsed * 100)), 2)

            with _crash_lock:
                _crash_state['multiplier'] = mult
                bets_snap = dict(_crash_state['bets'])

            # Server-side auto-cashout
            for uid, bd in bets_snap.items():
                if bd.get('cashedout'):
                    continue
                ac = bd.get('auto_cashout')
                if ac and mult >= ac:
                    wins = round(bd['amount'] * ac, 2)
                    _did_co = False
                    with _crash_lock:
                        if not _crash_state['bets'].get(uid, {}).get('cashedout'):
                            _crash_state['bets'][uid]['cashedout']    = True
                            _crash_state['bets'][uid]['cashout_mult'] = ac
                            _did_co = True
                    # Only credit if WE performed the state transition (prevents double-credit)
                    if _did_co:
                        _cth.Thread(target=_crash_credit, args=(uid, bd['amount'], wins, ac), daemon=True).start()

            if mult >= crash_at:
                with _crash_lock:
                    _crash_state['phase']      = 'crashed'
                    _crash_state['multiplier'] = round(crash_at, 2)
                break
            _ctime.sleep(0.05)

        # ── CRASHED PHASE ────────────────────────────────────────────────
        with _crash_lock:
            hist = _crash_state.get('history', [])
            hist.append(round(crash_at, 2))
            _crash_state['history'] = hist[-20:]
            for uid, bd in _crash_state['bets'].items():
                if not bd.get('cashedout'):
                    _crash_state['bets'][uid]['lost'] = True
                    try:
                        add_match_history(uid, 'crash', bd['amount'], 'loss', 0)
                    except Exception:
                        pass

        _ctime.sleep(_CRASH_CRASH_PAUSE)

        # Prep next round
        server_seed = _crash_new_seed()
        nonce      += 1

# Start the crash game loop on first import
_crash_thread = _cth.Thread(target=_crash_game_loop, daemon=True, name="CrashGameLoop")
_crash_thread.start()
logger.info("🚀 Crash game loop started")

