@app.route('/crash-api/state')
def api_crash_state():
    with _crash_lock:
        snap = {
            'phase':      _crash_state['phase'],
            'multiplier': _crash_state['multiplier'],
            'bets':       dict(_crash_state['bets']),
            'history':    list(_crash_state['history']),
            'countdown':  _crash_state['countdown'],
            'round_id':   _crash_state['round_id'],
        }
        # Only reveal crash_at after crash (provably fair)
        if _crash_state['phase'] == 'crashed':
            snap['crash_at']    = _crash_state['crash_at']
            snap['server_seed'] = _crash_state['server_seed']
            snap['nonce']       = _crash_state['nonce']
    return jsonify(snap)

@app.route('/crash-api/bet', methods=['POST'])
def api_crash_bet():
    data    = request.get_json(silent=True) or {}
    user_id = str(data.get('user_id', '')).strip()
    try:
        amount = float(data.get('amount', 0))
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'error': 'Invalid amount'})
    auto_co = data.get('auto_cashout')
    try:
        auto_co = float(auto_co) if auto_co else None
    except (TypeError, ValueError):
        auto_co = None

    if not user_id:
        return jsonify({'ok': False, 'error': 'Missing user_id'})
    if amount < _CRASH_MIN_BET:
        return jsonify({'ok': False, 'error': f'Minimum bet is ${_CRASH_MIN_BET:.2f}'})
    if amount > _CRASH_MAX_BET:
        return jsonify({'ok': False, 'error': f'Maximum bet is ${_CRASH_MAX_BET:.2f}'})

    # Build display info before acquiring lock (no I/O inside lock)
    prof         = user_profiles.get(user_id, {})
    uname        = prof.get('username', '')
    fname        = prof.get('first_name', '')
    display_name = f"@{uname}" if uname else fname or f'Player{user_id[-4:]}'
    photo_url    = prof.get('photo_url', '')

    # Atomically reserve a bet slot so concurrent requests can't both slip through.
    # We insert a sentinel entry while still holding the lock, then deduct balance,
    # then either confirm or roll back the reservation.
    SENTINEL = {'_pending': True, 'amount': amount}
    with _crash_lock:
        if _crash_state['phase'] != 'betting':
            return jsonify({'ok': False, 'error': 'Betting phase is over'})
        if user_id in _crash_state['bets']:
            return jsonify({'ok': False, 'error': 'You already have a bet this round'})
        # Reserve slot — prevents a concurrent request from claiming it while we deduct
        _crash_state['bets'][user_id] = SENTINEL

    # Deduct balance (outside lock — can block)
    bal = get_user_balance(user_id)
    if bal < amount:
        with _crash_lock:
            if _crash_state['bets'].get(user_id) is SENTINEL:
                del _crash_state['bets'][user_id]
        return jsonify({'ok': False, 'error': 'Insufficient balance'})

    if not deduct_user_balance(user_id, amount):
        with _crash_lock:
            if _crash_state['bets'].get(user_id) is SENTINEL:
                del _crash_state['bets'][user_id]
        return jsonify({'ok': False, 'error': 'Balance deduction failed — try again'})

    # Confirm the reservation with full bet data
    with _crash_lock:
        if _crash_state['phase'] != 'betting':
            # Round ended while we were deducting — refund and remove sentinel
            if _crash_state['bets'].get(user_id) is SENTINEL:
                del _crash_state['bets'][user_id]
            ultra_secure_add_user_balance(user_id, amount, "crash_bet_refund")
            return jsonify({'ok': False, 'error': 'Round started while placing bet — bet refunded'})
        _crash_state['bets'][user_id] = {
            'amount':       amount,
            'cashedout':    False,
            'cashout_mult': None,
            'lost':         False,
            'auto_cashout': auto_co,
            'username':     uname,
            'display_name': display_name,
            'photo_url':    photo_url,
        }

    return jsonify({'ok': True})

@app.route('/crash-api/cashout', methods=['POST'])
def api_crash_cashout():
    data    = request.get_json(silent=True) or {}
    user_id = str(data.get('user_id', '')).strip()

    if not user_id:
        return jsonify({'ok': False, 'error': 'Missing user_id'})

    with _crash_lock:
        if _crash_state['phase'] != 'flying':
            return jsonify({'ok': False, 'error': 'Not in flying phase'})
        bd = _crash_state['bets'].get(user_id)
        if not bd:
            return jsonify({'ok': False, 'error': 'No active bet'})
        if bd.get('cashedout'):
            return jsonify({'ok': False, 'error': 'Already cashed out'})

        mult     = _crash_state['multiplier']
        amount   = bd['amount']
        winnings = round(amount * mult, 2)
        _crash_state['bets'][user_id]['cashedout']    = True
        _crash_state['bets'][user_id]['cashout_mult'] = mult

    _cth.Thread(target=_crash_credit, args=(user_id, amount, winnings, mult), daemon=True).start()
    return jsonify({'ok': True, 'multiplier': mult, 'winnings': winnings})

