    # RPS emoji text choice handler — highest priority so ✊/✌️/✋ are never passed to handle_message
    _RPS_EMOJI_SET = {'✊', '✌', '✋'}  # base chars (no variation selectors)
    async def _rps_text_handler_wrapper(update, context):
        raw = (update.message.text or '') if update.message else ''
        normalised = raw.replace('️', '').replace('︎', '').strip()
        # Check FIRST character only — iOS sends skin-tone variants like ✊🏼 (2+ chars)
        if normalised and normalised[0] in _RPS_EMOJI_SET:
            await handle_rps_text_choice(update, context)
            raise ApplicationHandlerStop  # always stop — ✊/✌️/✋ belong to RPS, not handle_message
    application.add_handler(MessageHandler(
        filters.TEXT & ~filters.COMMAND,
        _rps_text_handler_wrapper
    ), group=-3)

