    # Add error handler for Conflict errors (multiple instances)
    async def error_handler(update, context):
        if isinstance(context.error, Exception):
            error_str = str(context.error)
            # Conflict from old bot instance — harmless, just warn
            if 'Conflict' in error_str or 'getUpdates' in error_str:
                logger.warning(f"Conflict error (probably old instance): {error_str}")
                return
            # Telegram rejects edit when content is identical — harmless, ignore silently
            if 'Message is not modified' in error_str or 'message is not modified' in error_str:
                return
            # User blocked the bot or chat not found — harmless
            if 'bot was blocked' in error_str or 'chat not found' in error_str.lower():
                return
            # Query too old (user pressed button on stale message) — harmless
            if 'query is too old' in error_str or 'QUERY_ID_INVALID' in error_str:
                return
            logger.error(f"Unexpected error: {error_str}")
    
    application.add_error_handler(error_handler)

