    # Import threading to run Flask and Telegram bot concurrently

    # Start Flask server in a separate thread
    def run_flask_server():
        # Prefer the platform-provided port so VPS panels and Replit route to
        # the same public Flask app. Keep fallbacks for local development.
        configured_port = os.environ.get("PORT", "").strip()
        ports = []
        if configured_port:
            try:
                ports.append(int(configured_port))
            except ValueError:
                print(f"⚠️ Ignoring invalid PORT value: {configured_port!r}")
        ports.extend([5000, 8000, 8099, 6000, 6800])
        for _port in dict.fromkeys(ports):
            try:
                print(f"🔥 Starting Flask web server on port {_port}...")
                app.run(host='0.0.0.0', port=_port, debug=False, use_reloader=False)
                break
            except Exception as _e:
                print(f"Port {_port} unavailable: {_e}")

    flask_thread = threading.Thread(target=run_flask_server, daemon=True)
    flask_thread.start()

    print(f"🔗 NowPayments IPN webhook URL: {IPN_CALLBACK_URL}")
