# Sticker pack to pull outcome stickers from
_SS67_PACK        = "ST_eRctED4StiW8jKnAOLa0pVmx_QszrcOUd9xfUjno_by_StickersPackRobot"
_SS67_STICKERS: list = []           # cached file_ids – filled on first play
_SS67_MIN_BET     = 10.0            # minimum bet (in user's displayed currency)

# Outcome table – weights must sum to 100
_SS67_NUMBERS  = [67,     68,    69   ]
_SS67_WEIGHTS  = [3,      46,    51   ]   # % chance each outcome occurs
_SS67_MULTI    = {67: 10.80, 68: 2.40, 69: 2.15}

async def _ss67_load_stickers(bot) -> None:
    """Fetch sticker file_ids from the pack once and cache them."""
    global _SS67_STICKERS
    if _SS67_STICKERS:
        return
    try:
        pack = await bot.get_sticker_set(_SS67_PACK)
        _SS67_STICKERS = [s.file_id for s in pack.stickers]
        logger.info(f"[SixSeven] Loaded {len(_SS67_STICKERS)} stickers from pack")
    except Exception as exc:
        logger.warning(f"[SixSeven] Could not load sticker pack: {exc}")

def _ss67_random_sticker() -> str | None:
    return random.choice(_SS67_STICKERS) if _SS67_STICKERS else None

def _ss67_sticker_for(outcome: int) -> str | None:
    """Return the sticker matching the rolled outcome.
    Pack order confirmed from live observation: idx0=67, idx1=69, idx2=68.
    """
    idx_map = {67: 0, 68: 2, 69: 1}
    idx = idx_map.get(outcome)
    if idx is not None and len(_SS67_STICKERS) > idx:
        return _SS67_STICKERS[idx]
    return _ss67_random_sticker()

def _ss67_bet_screen(balance_usd: float, user_id: str, user_currency: str) -> tuple:
    """Return (text, markup) for the bet-selection screen (Screen 1)."""
    fmt = lambda x: format_balance_in_currency(x, user_currency)
    pcts    = [0.01, 0.05, 0.10, 0.25, 0.50]
    amounts = []
    seen    = set()
    for p in pcts:
        a = round(max(_SS67_MIN_BET, balance_usd * p), 2)
        if a not in seen:
            seen.add(a)
            amounts.append(a)

    rows = []
    row  = []
    for a in amounts:
        label = f"💰 {fmt(a)}"
        row.append(InlineKeyboardButton(label, callback_data=f"ss67_b_{a}_{user_id}"))
        if len(row) == 2:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("⬅️ Back", callback_data=f"ss67_back_{user_id}")])

    text = (
        f'<tg-emoji emoji-id="5235957629410353710">🎰</tg-emoji><tg-emoji emoji-id="5978977350891606342">🎰</tg-emoji> <b>SixSeven</b>\n\n'
        f"⬆️ Choose a bet or enter your own\n"
        f"Minimum bet — {fmt(_SS67_MIN_BET)}\n\n"
        f'<tg-emoji emoji-id="6305046002374024896">💰</tg-emoji> Current balance: <b>{fmt(balance_usd)}</b>'
    )
    return text, InlineKeyboardMarkup(rows)

def _ss67_game_screen(bet: float, selected: int | None, balance_usd: float,
                      user_id: str, user_currency: str) -> tuple:
    """Return (text, markup) for the game screen (Screen 2)."""
    fmt = lambda x: format_balance_in_currency(x, user_currency)

    info_lines = [f'<tg-emoji emoji-id="5127902823542948533">💵</tg-emoji> Bet: <b>{fmt(bet)}</b>']
    if selected is not None:
        m = _SS67_MULTI[selected]
        info_lines.append(f'<tg-emoji emoji-id="5447262491295892594">🎯</tg-emoji> Selected: <b>{selected}</b> (×{m:.2f})')
    info_lines.append(f'<tg-emoji emoji-id="6305046002374024896">💰</tg-emoji> Current balance: <b>{fmt(balance_usd)}</b>')

    text = '<tg-emoji emoji-id="5235957629410353710">🎰</tg-emoji><tg-emoji emoji-id="5978977350891606342">🎰</tg-emoji> <b>SixSeven</b>\n\n' + "\n".join(info_lines)

    play_row  = []
    if selected is not None:
        play_row = [success_btn("Play", callback_data=f"ss67_p_{bet}_{selected}_{user_id}",
                                icon_custom_emoji_id="5291925842165781791")]

    num_row = []
    for n in _SS67_NUMBERS:
        if selected == n:
            num_row.append(success_btn(f"✅ {n}", callback_data=f"ss67_n_{bet}_{n}_{user_id}"))
        else:
            num_row.append(InlineKeyboardButton(str(n), callback_data=f"ss67_n_{bet}_{n}_{user_id}"))

    bottom_row = [
        danger_btn("Back", callback_data=f"ss67_bs_{user_id}",
                   icon_custom_emoji_id="5354834116481143712"),
        InlineKeyboardButton("📝 Change bet", callback_data=f"ss67_bs_{user_id}"),
    ]

    rows = []
    if play_row:
        rows.append(play_row)
    rows.append(num_row)
    rows.append(bottom_row)
    return text, InlineKeyboardMarkup(rows)


async def sixseven_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/67 or /sixseven — Rollers SixSeven pick-a-number game."""
    if not update.message or not update.message.from_user:
        return

    user_id      = str(update.message.from_user.id)
    user_currency = get_user_currency(user_id)
    balance      = get_user_balance(user_id)

    await _ss67_load_stickers(context.bot)

    # If a bet amount was passed directly (/67 50) jump straight to game screen
    if context.args:
        try:
            raw = float(context.args[0])
            bet = convert_currency_to_usd(raw, user_currency)
            if bet < MIN_BET:
                await update.message.reply_text(
                    f"❌ Minimum bet is {format_balance_in_currency(_SS67_MIN_BET, user_currency)}")
                return
            if bet > MAX_BET:
                await update.message.reply_text(
                    f"❌ Maximum bet is {format_balance_in_currency(MAX_BET, user_currency)}")
                return
            if bet > balance:
                await update.message.reply_text(
                    "❌ Insufficient balance.",
                    reply_markup=InlineKeyboardMarkup(
                        [[InlineKeyboardButton("📥 Deposit", callback_data="crypto_deposit")]]))
                return
            text, markup = _ss67_game_screen(bet, None, balance, user_id, user_currency)
            await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
            return
        except ValueError:
            pass

    # No args – show bet selection screen
    text, markup = _ss67_bet_screen(balance, user_id, user_currency)
    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)


async def handle_sixseven_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle all ss67_* callback queries."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    await query.answer()

    data    = query.data or ""
    caller  = str(query.from_user.id)

    # ── Back to bet-selection screen ────────────────────────────────────────
    if data.startswith("ss67_bs_") or data.startswith("ss67_back_"):
        owner = data.split("_")[-1]
        if caller != owner:
            await query.answer(_NOT_YOUR_BUTTON, show_alert=True); return
        balance      = get_user_balance(owner)
        user_currency = get_user_currency(owner)
        text, markup = _ss67_bet_screen(balance, owner, user_currency)
        try:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except Exception:
            pass
        return

    # ── Bet amount selected → show game screen ──────────────────────────────
    if data.startswith("ss67_b_"):
        # format: ss67_b_{amt}_{uid}
        parts = data.split("_")
        # parts: ['ss67','b', amt, uid]  (uid may contain nothing unusual)
        uid   = parts[-1]
        amt   = float(parts[2])
        if caller != uid:
            await query.answer(_NOT_YOUR_BUTTON, show_alert=True); return
        balance      = get_user_balance(uid)
        user_currency = get_user_currency(uid)
        bet           = convert_currency_to_usd(amt, user_currency)
        if bet > balance:
            await query.answer("❌ Insufficient balance!", show_alert=True); return
        text, markup = _ss67_game_screen(bet, None, balance, uid, user_currency)
        try:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except Exception:
            pass
        return

    # ── Number selected → update game screen with highlight ────────────────
    if data.startswith("ss67_n_"):
        # format: ss67_n_{bet}_{number}_{uid}
        parts  = data.split("_")
        uid    = parts[-1]
        number = int(parts[-2])
        bet    = float(parts[2])
        if caller != uid:
            await query.answer(_NOT_YOUR_BUTTON, show_alert=True); return
        balance      = get_user_balance(uid)
        user_currency = get_user_currency(uid)
        text, markup = _ss67_game_screen(bet, number, balance, uid, user_currency)
        try:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except Exception:
            pass
        return

    # ── Play ────────────────────────────────────────────────────────────────
    if data.startswith("ss67_p_"):
        # format: ss67_p_{bet}_{number}_{uid}
        parts  = data.split("_")
        uid    = parts[-1]
        number = int(parts[-2])
        bet    = float(parts[2])
        if caller != uid:
            await query.answer(_NOT_YOUR_BUTTON, show_alert=True); return

        user_currency = get_user_currency(uid)
        balance       = get_user_balance(uid)

        if bet > balance:
            await query.answer("❌ Insufficient balance!", show_alert=True); return

        if not ultra_secure_deduct_user_balance(uid, bet, "bet"):
            await query.answer("❌ Insufficient balance!", show_alert=True); return

        track_wagering(uid, bet, 2.0)

        # ── Roll outcome ────────────────────────────────────────────────────
        outcome = random.choices(_SS67_NUMBERS, weights=_SS67_WEIGHTS, k=1)[0]
        won     = outcome == number
        multi   = _SS67_MULTI[number]

        if won:
            winnings = round(bet * multi, 2)
            ultra_secure_add_user_balance(uid, winnings, "win")
            add_match_history(uid, 'sixseven', bet, 'win', winnings)
        else:
            winnings = 0.0
            add_match_history(uid, 'sixseven', bet, 'loss', 0)

        new_balance   = get_user_balance(uid)
        fmt           = lambda x: format_balance_in_currency(x, user_currency)
        win_display   = fmt(winnings - bet) if won else fmt(0)

        # ── Send sticker ────────────────────────────────────────────────────
        chat_id = query.message.chat_id
        sticker = _ss67_sticker_for(outcome)
        if sticker:
            try:
                await context.bot.send_sticker(chat_id=chat_id, sticker=sticker)
            except Exception as exc:
                logger.warning(f"[SixSeven] Sticker send failed: {exc}")

        # ── Result message ──────────────────────────────────────────────────
        result_text = (
            f'<tg-emoji emoji-id="5235957629410353710">🎰</tg-emoji><tg-emoji emoji-id="5978977350891606342">🎰</tg-emoji> <b>SixSeven</b>\n\n'
            f'<tg-emoji emoji-id="5206415568743192168">🏆</tg-emoji> {"WIN!" if won else "LOSS"}\n\n'
            f'<tg-emoji emoji-id="5436276282780299973">💎</tg-emoji> Result:   <b>{outcome}</b>\n'
            f'<tg-emoji emoji-id="5447262491295892594">🎯</tg-emoji> Selected: <b>{number}</b>\n'
            f'{"🏆" if won else "📉"} Winnings: <b>{fmt(winnings)}</b>'
        )
        await context.bot.send_message(
            chat_id=chat_id,
            text=result_text,
            parse_mode=ParseMode.HTML,
        )
        if won:
            await _send_player_win_sticker(context.bot, chat_id)

        # ── Refresh game screen (same bet, same number selected) ────────────
        text, markup = _ss67_game_screen(bet, number, new_balance, uid, user_currency)
        await context.bot.send_message(
            chat_id=chat_id,
            text=text,
            parse_mode=ParseMode.HTML,
            reply_markup=markup,
        )
        return


